import type {
  GameplayRegistry,
  GameplayRegistryIssue,
} from '../definitions/GameplayRegistry';
import type {
  GoodType,
  RouteConditionStatus,
  RouteWidthClass,
} from '../definitions/GameplayTypes';
import {
  validateWorldTargetRef,
  worldTarget,
  worldTargetKey,
  type WorldTargetRef,
} from '../world/WorldTarget';
import type { WorldContributionEvent } from './WorldContributionEvent';
import type { WorldEventBase } from './WorldEventBase';
import type {
  AccessConditionStatus,
  ServiceAvailability,
  TravelStatus,
  WorldIncidentStatus,
  WorldIncidentType,
  StoryQuestStatus,
} from '../emergence/EmergentWorldTypes';

export type ShipEscortPauseReason =
  | 'UNSAFE_ROUTE'
  | 'PLAYER_TOO_FAR'
  | 'PLAYER_OFF_CORRIDOR'
  | 'WAITING_FOR_LEAD';

export type WorldOperationalEvent =
  | (WorldEventBase & {
      type: 'ROUTE_CONDITION_CHANGED';
      routeId: string;
      previousStatus: RouteConditionStatus;
      status: RouteConditionStatus;
      worstPoint?: { x: number; y: number; z: number };
    })
  | (WorldEventBase & {
      type: 'ROUTE_CAPACITY_CHANGED';
      routeId: string;
      previousWidthClass: RouteWidthClass;
      widthClass: RouteWidthClass;
    })
  | (WorldEventBase & {
      type: 'SHIP_DEPARTED';
      shipId: string;
      routeId: string;
      originPortId: string;
      destinationPortId: string;
      tripId: string;
    })
  | (WorldEventBase & {
      type: 'SHIP_WAITING';
      shipId: string;
      routeId: string;
      incidentId: string;
    })
  | (WorldEventBase & {
      type: 'SHIP_STUCK';
      shipId: string;
      routeId: string;
      incidentId: string;
    })
  | (WorldEventBase & {
      type: 'SHIP_RESUMED';
      shipId: string;
      routeId: string;
      incidentId: string;
    })
  | (WorldEventBase & {
      type: 'SHIP_ESCORT_STARTED';
      shipId: string;
      routeId: string;
      incidentId: string;
      escortId: string;
    })
  | (WorldEventBase & {
      type: 'SHIP_ESCORT_PAUSED';
      shipId: string;
      routeId: string;
      incidentId: string;
      escortId: string;
      reason: ShipEscortPauseReason;
    })
  | (WorldEventBase & {
      type: 'SHIP_ESCORT_RESUMED';
      shipId: string;
      routeId: string;
      incidentId: string;
      escortId: string;
    })
  | (WorldEventBase & {
      type: 'SHIP_ARRIVED';
      shipId: string;
      routeId: string;
      portId: string;
      tripId: string;
    })
  | (WorldEventBase & {
      type: 'PORT_CARGO_DELIVERED';
      portId: string;
      shipId: string;
      tripId: string;
      goodType: GoodType;
      amount: number;
    })
  | (WorldEventBase & {
      type: 'WEATHER_REPORT_UPDATED';
      regionId: string;
      weatherKind:
        | 'clear'
        | 'overcast'
        | 'light-snow'
        | 'fog'
        | 'strong-wind'
        | 'snowstorm';
      windMultiplier: number;
      fogDensity: number;
      snowIntensity: number;
      refreezeMultiplier: number;
    })
  | (WorldEventBase & {
      type: 'LOCAL_PORT_NOTICE';
      portId: string;
      noticeCode:
        | 'SUPPLY_LOW'
        | 'PORT_BUSY'
        | 'PORT_GROWING'
        | 'OPERATIONS_NORMAL';
      supplySatisfaction: number;
      traffic: number;
      developmentProgress: number;
    })
  | (WorldEventBase & {
      type: 'OPEN_BAND_TRAFFIC';
      shipId: string;
      routeId: string;
      destinationPortId: string;
      navigationStatus:
        | 'TRAVELLING_FAR'
        | 'WAITING_FOR_CHANNEL'
        | 'STUCK_ASSISTANCE'
        | 'ARRIVING';
    })
  | (WorldEventBase & {
      type: 'MYSTERY_BROADCAST_AVAILABLE';
      broadcastId: string;
      clueCode: string;
      musicTrackId: string;
    })
  | (WorldEventBase & {
      type: 'BOTTLE_DISCOVERED';
      bottleId: string;
      discoveryOrder: number;
    })
  | (WorldEventBase & {
      type:
        | 'MISSION_OFFERED'
        | 'MISSION_ACCEPTED'
        | 'MISSION_EXPIRED'
        | 'MISSION_CANCELLED';
      missionId: string;
    })
  | (WorldEventBase & {
      type: 'WORLD_OUTCOME_CHANGED';
      outcomeId: string;
      previousState: string;
      state: string;
      sourceEventId?: string;
    })
  | (WorldEventBase & {
      type: 'LAND_ROAD_CONDITION_CHANGED';
      segmentId: string;
      previousStatus: AccessConditionStatus;
      status: AccessConditionStatus;
      averageDepth: number;
      maximumDepth: number;
      revision: number;
    })
  | (WorldEventBase & {
      type: 'NPC_TRAVEL_STATE_CHANGED';
      npcId: string;
      previousStatus: TravelStatus;
      status: TravelStatus;
      reason: string;
      tripId?: string;
      segmentId?: string;
      locationId?: string;
    })
  | (WorldEventBase & {
      type: 'SERVICE_AVAILABILITY_CHANGED';
      serviceId: string;
      previousAvailability: ServiceAvailability;
      availability: ServiceAvailability;
      reason: string;
    })
  | (WorldEventBase & {
      type: 'WORLD_INCIDENT_CHANGED';
      incidentId: string;
      incidentType: WorldIncidentType;
      previousStatus?: WorldIncidentStatus;
      status: WorldIncidentStatus;
      subjectId: string;
      reason: string;
    })
  | (WorldEventBase & {
      type: 'STORY_QUEST_STATE_CHANGED';
      questId: string;
      previousStatus: StoryQuestStatus;
      status: StoryQuestStatus;
      previousStageId?: string;
      stageId?: string;
      reason: string;
    });

export type WorldDomainEvent =
  | WorldContributionEvent
  | WorldOperationalEvent;

const CONTRIBUTION_EVENT_TYPES = new Set<
  WorldContributionEvent['type']
>([
  'ROUTE_OPENED',
  'ROUTE_SERVICED',
  'SHIP_RESCUED',
  'SHIP_ESCORTED',
  'POI_DISCOVERED',
  'UPGRADE_PART_RECOVERED',
  'SPECIAL_COMPONENT_DELIVERED',
  'PORT_ACCESS_IMPROVED',
  'PORT_CLEARED',
  'MISSION_COMPLETED',
]);

export const isWorldContributionEvent = (
  event: Readonly<WorldDomainEvent>,
): event is WorldContributionEvent =>
  CONTRIBUTION_EVENT_TYPES.has(
    event.type as WorldContributionEvent['type'],
  );

const deriveWorldEventTargets = (
  event: Readonly<WorldDomainEvent>,
): readonly WorldTargetRef[] => {
  switch (event.type) {
    case 'ROUTE_OPENED':
    case 'ROUTE_SERVICED':
    case 'ROUTE_CONDITION_CHANGED':
    case 'ROUTE_CAPACITY_CHANGED':
      return [worldTarget.route(event.routeId)];
    case 'SHIP_ESCORTED':
      return [worldTarget.ship(event.shipId)];
    case 'SHIP_RESCUED':
      return [
        worldTarget.ship(event.shipId),
        ...(event.routeId
          ? [worldTarget.route(event.routeId)]
          : []),
      ];
    case 'POI_DISCOVERED':
      return [worldTarget.poi(event.poiId)];
    case 'SPECIAL_COMPONENT_DELIVERED':
    case 'PORT_ACCESS_IMPROVED':
    case 'PORT_CLEARED':
      return [worldTarget.port(event.portId)];
    case 'SHIP_DEPARTED':
      return [
        worldTarget.ship(event.shipId),
        worldTarget.route(event.routeId),
        worldTarget.port(event.originPortId),
        worldTarget.port(event.destinationPortId),
      ];
    case 'SHIP_WAITING':
    case 'SHIP_STUCK':
    case 'SHIP_RESUMED':
    case 'SHIP_ESCORT_STARTED':
    case 'SHIP_ESCORT_PAUSED':
    case 'SHIP_ESCORT_RESUMED':
      return [
        worldTarget.ship(event.shipId),
        worldTarget.route(event.routeId),
      ];
    case 'SHIP_ARRIVED':
      return [
        worldTarget.ship(event.shipId),
        worldTarget.route(event.routeId),
        worldTarget.port(event.portId),
      ];
    case 'PORT_CARGO_DELIVERED':
      return [
        worldTarget.ship(event.shipId),
        worldTarget.port(event.portId),
      ];
    case 'LOCAL_PORT_NOTICE':
      return [worldTarget.port(event.portId)];
    case 'OPEN_BAND_TRAFFIC':
      return [
        worldTarget.ship(event.shipId),
        worldTarget.route(event.routeId),
        worldTarget.port(event.destinationPortId),
      ];
    case 'WEATHER_REPORT_UPDATED':
    case 'MYSTERY_BROADCAST_AVAILABLE':
      return [];
    case 'LAND_ROAD_CONDITION_CHANGED':
      return [worldTarget.roadSegment(event.segmentId)];
    case 'NPC_TRAVEL_STATE_CHANGED':
      return [
        worldTarget.npc(event.npcId),
        ...(event.segmentId ? [worldTarget.roadSegment(event.segmentId)] : []),
        ...(event.locationId ? [worldTarget.location(event.locationId)] : []),
      ];
    case 'SERVICE_AVAILABILITY_CHANGED':
      return [worldTarget.service(event.serviceId)];
    case 'WORLD_INCIDENT_CHANGED':
      return [worldTarget.incident(event.incidentId), worldTarget.npc(event.subjectId)];
    case 'STORY_QUEST_STATE_CHANGED':
      return [worldTarget.object(`story-quest:${event.questId}`)];
    case 'BOTTLE_DISCOVERED':
      return [worldTarget.object(`bottle:${event.bottleId}`)];
    case 'UPGRADE_PART_RECOVERED':
    case 'MISSION_COMPLETED':
    case 'MISSION_OFFERED':
    case 'MISSION_ACCEPTED':
    case 'MISSION_EXPIRED':
    case 'MISSION_CANCELLED':
    case 'WORLD_OUTCOME_CHANGED':
      return [];
  }
};

export const inferWorldEventTargets = (
  event: Readonly<WorldDomainEvent>,
): readonly WorldTargetRef[] =>
  event.targetRefs && event.targetRefs.length > 0
    ? event.targetRefs
    : deriveWorldEventTargets(event);

export const validateWorldDomainEvent = (
  event: Readonly<WorldDomainEvent>,
  registry: GameplayRegistry,
  path = 'event',
): readonly GameplayRegistryIssue[] => {
  const issues: GameplayRegistryIssue[] = [];
  if (!event.eventId.trim()) {
    issues.push({
      path: `${path}.eventId`,
      message: 'Event ID must be a non-empty string',
    });
  }
  if (!Number.isFinite(event.occurredAt) || event.occurredAt < 0) {
    issues.push({
      path: `${path}.occurredAt`,
      message: 'Event time must be finite and non-negative',
    });
  }
  const targets = [
    ...(event.targetRefs ?? []),
    ...deriveWorldEventTargets(event),
  ].filter((target, index, values) => {
    const key = worldTargetKey(target);
    return (
      values.findIndex(
        (candidate) => worldTargetKey(candidate) === key,
      ) === index
    );
  });
  for (const [index, target] of targets.entries()) {
    issues.push(
      ...validateWorldTargetRef(
        target,
        registry,
        `${path}.targetRefs[${index}]`,
      ),
    );
  }
  if (
    event.type === 'PORT_CARGO_DELIVERED' &&
    (!Number.isFinite(event.amount) || event.amount <= 0)
  ) {
    issues.push({
      path: `${path}.amount`,
      message: 'Cargo amount must be positive',
    });
  }
  if (
    event.type === 'PORT_CARGO_DELIVERED' &&
    !registry.getGood(event.goodType)
  ) {
    issues.push({
      path: `${path}.goodType`,
      message: `Missing good "${event.goodType}"`,
    });
  }
  if (
    event.type === 'MISSION_COMPLETED' &&
    !registry.getMission(event.missionId)
  ) {
    issues.push({
      path: `${path}.missionId`,
      message: `Missing mission "${event.missionId}"`,
    });
  }
  if (
    [
      'MISSION_OFFERED',
      'MISSION_ACCEPTED',
      'MISSION_EXPIRED',
      'MISSION_CANCELLED',
    ].includes(event.type) &&
    !registry.getMission(
      (event as { missionId: string }).missionId,
    )
  ) {
    const missionId = (event as { missionId: string })
      .missionId;
    issues.push({
      path: `${path}.missionId`,
      message: `Missing mission "${missionId}"`,
    });
  }
  return issues;
};
