import { cloneGlobalPosition } from '../../world/GlobalPosition';
import type { EmergentWorldDirector } from './EmergentWorldDirector';
import type { TravelSystem } from './TravelSystem';
import type { WorldIncidentState, WorldIncidentStatus } from './EmergentWorldTypes';

export interface IncidentTransition {
  incident: WorldIncidentState;
  previousStatus?: WorldIncidentStatus;
  status: WorldIncidentStatus;
  occurredAt: number;
  reason: string;
}

interface IncidentSaveData { version: 1; incidents: WorldIncidentState[]; nextSequenceBySubject: Record<string, number>; }

const cloneIncident = (state: Readonly<WorldIncidentState>): WorldIncidentState => ({
  ...state,
  location: cloneGlobalPosition(state.location),
  evidence: state.evidence.map((value) => ({ ...value })),
});

export class IncidentSystem {
  private readonly incidents = new Map<string, WorldIncidentState>();
  private readonly nextSequenceBySubject = new Map<string, number>();

  public constructor(
    private readonly travel: TravelSystem,
    private readonly director: EmergentWorldDirector,
    saved?: unknown,
  ) {
    this.importState(saved);
  }

  public update(
    simulationTime: number,
    hasCommunicationCoverage: (subjectId: string, position: WorldIncidentState['location']) => boolean,
  ): readonly IncidentTransition[] {
    const transitions: IncidentTransition[] = [];
    const activeBySubject = new Map(
      [...this.incidents.values()]
        .filter((incident) => incident.status !== 'RESOLVED')
        .map((incident) => [incident.subjectId, incident]),
    );
    for (const traveller of this.travel.getStates()) {
      const active = activeBySubject.get(traveller.agentId);
      if (traveller.status === 'STRANDED' && !active) {
        const sequence = (this.nextSequenceBySubject.get(traveller.agentId) ?? 0) + 1;
        this.nextSequenceBySubject.set(traveller.agentId, sequence);
        const incident: WorldIncidentState = {
          incidentId: `incident:traveller-stranded:${traveller.agentId}:${sequence}`,
          type: 'TRAVELLER_STRANDED',
          status: 'ACTIVE_UNREPORTED',
          subjectId: traveller.agentId,
          location: cloneGlobalPosition(traveller.worldPosition),
          detectedAt: simulationTime,
          stateChangedAt: simulationTime,
          reportSequence: 0,
          ruleId: 'travel.stranded.creates-incident',
          evidence: [
            { fact: 'travel.status', subjectId: traveller.agentId, value: traveller.status },
            ...(traveller.currentSegmentId
              ? [{ fact: 'travel.currentSegmentId', subjectId: traveller.agentId, value: traveller.currentSegmentId }]
              : []),
            { fact: 'travel.lastDecision', subjectId: traveller.agentId, value: traveller.lastDecision },
          ],
        };
        this.incidents.set(incident.incidentId, incident);
        activeBySubject.set(traveller.agentId, incident);
        transitions.push({ incident: cloneIncident(incident), status: incident.status, occurredAt: simulationTime, reason: 'STRANDED_STATE_DETECTED' });
      } else if (traveller.status !== 'STRANDED' && active) {
        const previousStatus = active.status;
        active.status = 'RESOLVED';
        active.resolvedAt = simulationTime;
        active.stateChangedAt = simulationTime;
        transitions.push({ incident: cloneIncident(active), previousStatus, status: active.status, occurredAt: simulationTime, reason: 'SUBJECT_NO_LONGER_STRANDED' });
      }
    }
    let reportedCount = [...this.incidents.values()].filter((incident) => incident.status === 'REPORTED').length;
    for (const incident of [...this.incidents.values()].sort((a, b) => a.incidentId.localeCompare(b.incidentId))) {
      if (incident.status !== 'ACTIVE_UNREPORTED') continue;
      if (!hasCommunicationCoverage(incident.subjectId, incident.location)) continue;
      const decision = this.director.decide(incident.incidentId, simulationTime, reportedCount);
      if (!decision.allowed) continue;
      const previousStatus = incident.status;
      incident.status = 'REPORTED';
      incident.reportedAt = simulationTime;
      incident.stateChangedAt = simulationTime;
      incident.reportSequence += 1;
      this.director.markSurfaced(incident.incidentId, simulationTime);
      reportedCount += 1;
      transitions.push({ incident: cloneIncident(incident), previousStatus, status: incident.status, occurredAt: simulationTime, reason: `COVERAGE_AND_DIRECTOR_${decision.reason}` });
    }
    return transitions;
  }

  public getState(incidentId: string): WorldIncidentState | undefined {
    const state = this.incidents.get(incidentId);
    return state ? cloneIncident(state) : undefined;
  }

  public getStates(): readonly WorldIncidentState[] {
    return [...this.incidents.values()].sort((a, b) => a.incidentId.localeCompare(b.incidentId)).map(cloneIncident);
  }

  public getActiveCount(): number {
    let count = 0;
    for (const incident of this.incidents.values()) {
      if (incident.status !== 'RESOLVED') count += 1;
    }
    return count;
  }

  public exportState(): IncidentSaveData {
    return { version: 1, incidents: this.getStates().map(cloneIncident), nextSequenceBySubject: Object.fromEntries(this.nextSequenceBySubject) };
  }

  private importState(saved: unknown): boolean {
    const candidate = saved as Partial<IncidentSaveData> | undefined;
    if (candidate?.version !== 1 || !Array.isArray(candidate.incidents)) return false;
    for (const incident of candidate.incidents) {
      if (!incident?.incidentId || !['ACTIVE_UNREPORTED', 'REPORTED', 'RESOLVED'].includes(incident.status)) continue;
      this.incidents.set(incident.incidentId, cloneIncident(incident));
    }
    for (const [subjectId, sequence] of Object.entries(candidate.nextSequenceBySubject ?? {})) {
      if (Number.isInteger(sequence) && sequence >= 0) this.nextSequenceBySubject.set(subjectId, sequence);
    }
    return true;
  }
}
