import type { WorldPoint } from '../world/WorldPoint';

export type IceClass = 'open' | 'channel' | 'thin' | 'medium' | 'thick';

export interface VesselHullSample {
  length: number;
  width: number;
}

export interface VesselIceContact {
  averageThickness: number;
  peakThickness: number;
  openness: number;
  concentration: number;
  pressure: number;
  bowCoverage: number;
  bowResistance: number;
  bowLeftResistance: number;
  bowRightResistance: number;
  bowIceClass: IceClass;
  bowStaticPackCoverage: number;
  bowMovableFloeCoverage: number;
  bowBlockingFloeCoverage: number;
  bowCenterBlockingCoverage: number;
  bowShoulderBlockingCoverage: number;
  sideCoverage: number;
  sideLeftCoverage: number;
  sideRightCoverage: number;
  resistance: number;
  breakableFraction: number;
  iceClass: IceClass;
}

export interface BreakStroke {
  previousBow: WorldPoint;
  currentBow: WorldPoint;
  previousHeading: number;
  currentHeading: number;
  bowWidth: number;
  vesselMass: number;
  impactSpeed: number;
  compression: number;
  breakingPower: number;
  canBreakIce?: boolean;
  worldTick: number;
}

export interface BreakResult {
  changedCells: number;
  averageOpened: number;
  releasedStress: number;
  peakResistance: number;
  iceClass: IceClass;
}

export interface IceWorld {
  sampleVesselContact(
    position: Readonly<WorldPoint>,
    heading: number,
    hull: Readonly<VesselHullSample>,
  ): VesselIceContact;
  applyBreakStroke(stroke: Readonly<BreakStroke>): BreakResult;
}

export const EMPTY_BREAK_RESULT: BreakResult = {
  changedCells: 0,
  averageOpened: 0,
  releasedStress: 0,
  peakResistance: 0,
  iceClass: 'open',
};
