import { clamp } from '../utils/math';
import type { LandMachineState, LandMachineType } from './LandMachineSystem';
import type { BulldozerState } from './BulldozerSimulation';
import type { PenguinState } from './PenguinSimulation';
import { resolveBorealisWorkshopProgress } from './BorealisLand';
import {
  BULLDOZER_BLADE_PROFILES,
  DEFAULT_BULLDOZER_CAPABILITIES,
  type BulldozerCapabilities,
} from './BulldozerUpgrades';
import type { LandOperationsViewModel } from './LandOperationsSystem';
import { ICEWAY_PLAYTEST_MODE } from '../core/RuntimeBuildFlags';

export interface LandExpeditionUIActions {
  onSetBladeMotion: (motion: -1 | 0 | 1) => void;
  onCycleBladeMode: () => void;
  onToggleBeacon: () => void;
  onToggleLights: () => void;
  onSetBlower: (active: boolean) => void;
  onInteract: () => void;
  onDevResetFleet: () => void;
  onDevForceSnow: () => void;
  onDevInstallProtection: () => void;
}

export class LandExpeditionUI {
  private readonly element: HTMLElement;
  private readonly lowerBladeButton: HTMLButtonElement;
  private readonly raiseBladeButton: HTMLButtonElement;
  private readonly bladeModeButton: HTMLButtonElement;
  private readonly beaconButton: HTMLButtonElement;
  private readonly lightsButton: HTMLButtonElement;
  private readonly blowerButton: HTMLButtonElement;
  private readonly interactButton: HTMLButtonElement;
  private readonly speed: HTMLElement;
  private readonly snow: HTMLElement;
  private readonly blade: HTMLElement;
  private readonly load: HTMLElement;
  private readonly progress: HTMLElement;
  private readonly objectiveTitle: HTMLElement;
  private readonly objectiveDescription: HTMLElement;
  private readonly forecast: HTMLElement;
  private readonly hint: HTMLElement;
  private readonly devButtons: HTMLButtonElement[];
  private activeBladePointerId?: number;
  private activeBlowerPointerId?: number;
  private capabilities: BulldozerCapabilities = {
    ...DEFAULT_BULLDOZER_CAPABILITIES,
  };
  private machine?: LandMachineType;

  public constructor(
    root: HTMLElement,
    private readonly actions: LandExpeditionUIActions,
  ) {
    this.element = document.createElement('section');
    this.element.id = 'land-expedition-hud';
    this.element.className = 'land-expedition-hud is-hidden';
    this.element.setAttribute('aria-label', 'Harbor exploration controls');
    this.element.innerHTML = `
      <div class="land-expedition-objective">
        <small>BOREALIS SURROUNDINGS</small>
        <strong data-land-output="objective-title">CLEAR THE WORKSHOP APPROACH</strong>
        <span data-land-output="objective-description">Drive west along the causeway and clear the marked snowfield.</span>
        <span data-land-output="forecast">FORECAST · CHECKING</span>
        <div class="land-expedition-progress"><i></i></div>
        <output data-land-output="progress">0% CLEAR</output>
      </div>
      <div class="land-expedition-telemetry">
        <div><small>SPEED</small><strong data-land-output="speed">0.0</strong></div>
        <div><small>SNOW / ALT</small><strong data-land-output="snow">0.0</strong></div>
        <div><small>TOOL</small><strong data-land-output="blade">0%</strong></div>
        <div><small>LOAD</small><strong data-land-output="load">0%</strong></div>
      </div>
      <div class="land-expedition-actions">
        <button data-land-action="lower-blade">Q · LOWER TOOL</button>
        <button data-land-action="raise-blade">E · RAISE TOOL</button>
        <button data-land-action="blade-mode">C · STRAIGHT BLADE</button>
        <button data-land-action="beacon">B · BEACON UPGRADE</button>
        <button data-land-action="lights">G · WORK LIGHTS ON</button>
        <button data-land-action="blower">SPACE (HOLD) · LEAF BLOWER</button>
        <button data-land-action="interact">F · INTERACT</button>
        <button data-land-action="dev-fleet" data-land-dev>DEV · RESET / UNLOCK FLEET</button>
        <button data-land-action="dev-snow" data-land-dev>DEV · FORCE SNOW FORECAST</button>
        <button data-land-action="dev-protection" data-land-dev>DEV · INSTALL SNOW PROTECTION</button>
      </div>
      <div class="land-expedition-hint" data-land-output="hint">W/S DRIVE · A/D STEER · Q/E TOOL · F CONTEXT ACTION · DRAG INSPECT</div>
    `;
    root.appendChild(this.element);
    this.lowerBladeButton = this.require('[data-land-action="lower-blade"]');
    this.raiseBladeButton = this.require('[data-land-action="raise-blade"]');
    this.bladeModeButton = this.require('[data-land-action="blade-mode"]');
    this.beaconButton = this.require('[data-land-action="beacon"]');
    this.lightsButton = this.require('[data-land-action="lights"]');
    this.blowerButton = this.require('[data-land-action="blower"]');
    this.interactButton = this.require('[data-land-action="interact"]');
    this.speed = this.require('[data-land-output="speed"]');
    this.snow = this.require('[data-land-output="snow"]');
    this.blade = this.require('[data-land-output="blade"]');
    this.load = this.require('[data-land-output="load"]');
    this.progress = this.require('[data-land-output="progress"]');
    this.objectiveTitle = this.require('[data-land-output="objective-title"]');
    this.objectiveDescription = this.require('[data-land-output="objective-description"]');
    this.forecast = this.require('[data-land-output="forecast"]');
    this.hint = this.require('[data-land-output="hint"]');
    this.devButtons = [...this.element.querySelectorAll<HTMLButtonElement>('[data-land-dev]')];
    this.setDevMode(ICEWAY_PLAYTEST_MODE);
    this.setControlMode('vehicle');
    this.element.addEventListener('click', this.onClick);
    this.element.addEventListener('pointerdown', this.onPointerDown);
    this.element.addEventListener('pointerup', this.onPointerEnd);
    this.element.addEventListener('pointercancel', this.onPointerEnd);
  }

  public setVisible(visible: boolean): void {
    this.element.classList.toggle('is-hidden', !visible);
    if (!visible) {
      this.releaseBladePointer();
      this.releaseBlowerPointer();
    }
  }

  public setDevMode(enabled: boolean): void {
    for (const button of this.devButtons) button.hidden = !enabled;
  }

  public setContextAction(label: string, enabled = true): void {
    this.interactButton.textContent = `F · ${label.toUpperCase()}`;
    this.interactButton.disabled = !enabled;
  }

  public setControlMode(
    mode: 'vehicle' | 'on-foot',
    machine?: LandMachineType,
  ): void {
    const onFoot = mode === 'on-foot';
    this.machine = machine;
    this.element.classList.toggle('is-on-foot', onFoot);
    const starter = !onFoot && !machine;
    const heavy = machine === 'HEAVY_DOZER';
    const loader = machine === 'WHEEL_LOADER';
    this.lowerBladeButton.hidden = !(starter || heavy || loader);
    this.raiseBladeButton.hidden = !(starter || heavy || loader);
    this.bladeModeButton.hidden = !starter;
    this.beaconButton.hidden = !starter;
    this.lightsButton.hidden = !starter;
    this.blowerButton.hidden = !onFoot;
    this.hint.textContent = onFoot
      ? 'WASD / ARROWS MOVE · MOUSE AIM · HOLD SPACE BLOW · F CONTEXT ACTION · DRAG INSPECT'
      : machine === 'HELICOPTER'
        ? 'WASD TILT · Q/E ALTITUDE · LEFT/RIGHT ARROWS YAW · F EXIT / UNLOAD · DRAG INSPECT'
        : machine === 'SNOW_TRUCK'
          ? 'W/S DRIVE · A/D STEER · F EXIT / UNLOAD · DRAG INSPECT'
          : loader
            ? 'W/S DRIVE · A/D STEER · Q/E BUCKET HEIGHT · Z CURL · C TIP · F EXIT · DRAG INSPECT'
          : heavy
            ? 'W/S DRIVE · A/D STEER · Q/E BLADE HEIGHT · F EXIT · DRAG INSPECT'
            : 'W/S DRIVE · A/D STEER · Q/E TOOL HEIGHT · C BLADE SHAPE / BUCKET TIP · F CONTEXT ACTION · DRAG INSPECT';
    if (onFoot) this.releaseBladePointer();
    else this.releaseBlowerPointer();
  }

  public setCapabilities(capabilities: Readonly<BulldozerCapabilities>): void {
    this.capabilities = { ...capabilities };
    this.bladeModeButton.disabled = !capabilities.adjustableWingPlow;
    this.beaconButton.disabled = !capabilities.amberBeacon;
  }

  public updateOperations(operations: Readonly<LandOperationsViewModel>): void {
    this.element.dataset.npcPlow = operations.npcActive ? 'active' : 'parked';
    this.element.dataset.snowForecast = operations.snowForecast ? 'snow' : 'clear';
    this.forecast.textContent = operations.snowForecast
      ? operations.npcActive
        ? 'FORECAST · SNOW · NPC PLOW ACTIVE'
        : operations.npcPermissionGranted
          ? 'FORECAST · SNOW · NPC WAITING FOR TRACTOR'
          : 'FORECAST · SNOW · TALK TO PLOW NPC'
      : operations.npcPermissionGranted
        ? 'FORECAST · CLEAR · NPC PARKED'
        : 'FORECAST · CLEAR';
  }

  public update(
    state: Readonly<BulldozerState>,
    clearedRatio: number,
    objectiveComplete = false,
    workLightsEnabled = true,
  ): void {
    this.speed.textContent = `${Math.abs(state.speed * 3.6).toFixed(1)} km/h`;
    this.snow.textContent = `${state.snowDepth.toFixed(2)} m · STARTER`;
    this.blade.textContent = state.attachment === 'BUCKET'
      ? `${Math.round((1 - state.bucketTilt) * 100)}% TIP`
      : `${Math.round(state.bladePosition * 100)}%`;
    this.load.textContent = state.attachment === 'BUCKET'
      ? `${state.bucketMass.toFixed(2)}/0.72 m³`
      : state.snowDepth > this.capabilities.maximumPushDepth && state.bladeDown
        ? `OVER ${this.capabilities.maximumPushDepth.toFixed(1)} m LIMIT`
        : `${Math.round(state.bladeLoad * 100)}%`;
    this.setBladeButtonLimit(this.lowerBladeButton, state.bladePosition >= 0.995);
    this.setBladeButtonLimit(this.raiseBladeButton, state.bladePosition <= 0.005);
    const mode = BULLDOZER_BLADE_PROFILES[state.bladeMode].displayName;
    this.bladeModeButton.textContent = state.attachment === 'BUCKET'
      ? 'C / Z · TIP / CURL BUCKET'
      : this.capabilities.adjustableWingPlow
        ? `C · ${mode.toUpperCase()}`
        : 'C · WING PLOW UPGRADE';
    this.beaconButton.textContent = this.capabilities.amberBeacon
      ? `B · BEACON ${state.beaconOn ? 'ON' : 'OFF'}`
      : 'B · BEACON UPGRADE';
    this.beaconButton.classList.toggle('is-active', state.beaconOn);
    this.lightsButton.textContent = `G · WORK LIGHTS ${workLightsEnabled ? 'ON' : 'OFF'}`;
    this.lightsButton.classList.toggle('is-active', workLightsEnabled);
    this.updateWorkshopObjective(clearedRatio, objectiveComplete);
  }

  public updateMachine(
    state: Readonly<LandMachineState>,
    clearedRatio: number,
    objectiveComplete = false,
  ): void {
    this.speed.textContent = `${Math.abs(state.speed * 3.6).toFixed(1)} km/h`;
    this.snow.textContent = state.type === 'HELICOPTER'
      ? `${state.altitude.toFixed(1)} m ALT`
      : 'HEAVY FLEET';
    this.blade.textContent = state.type === 'HEAVY_DOZER'
      ? `${Math.round(state.bladePosition * 100)}%`
      : state.type === 'WHEEL_LOADER'
        ? `${Math.round(state.bladePosition * 100)}% DOWN / ${Math.round((1 - state.bucketTilt) * 100)}% TIP`
      : state.type === 'HELICOPTER'
        ? `${Math.round(state.pitch * 180 / Math.PI)}° / ${Math.round(state.roll * 180 / Math.PI)}°`
        : 'HAUL';
    const capacity = state.type === 'SNOW_TRUCK'
      ? 22
      : state.type === 'HELICOPTER'
        ? 12
        : state.type === 'WHEEL_LOADER'
          ? 2.4
          : 0;
    this.load.textContent = capacity > 0
      ? `${state.cargoMass.toFixed(1)}/${capacity.toFixed(0)} m³`
      : '4–6 m PILES';
    this.updateWorkshopObjective(clearedRatio, objectiveComplete);
  }

  public updateOnFoot(
    state: Readonly<PenguinState>,
    cleanRatio: number,
    _nearVehicle: boolean,
    objectiveComplete = false,
  ): void {
    this.speed.textContent = `${Math.abs(state.speed * 3.6).toFixed(1)} km/h`;
    this.snow.textContent = `${state.snowDepth.toFixed(2)} m`;
    this.blade.textContent = `${Math.round(cleanRatio * 100)}%`;
    this.load.textContent = state.blowerActive ? 'BLOWING' : 'READY';
    this.blowerButton.classList.toggle('is-active', state.blowerActive);
    this.objectiveTitle.textContent = objectiveComplete ? 'OLD PARK DETAILS UNCOVERED' : 'UNCOVER THE OLD PARK';
    this.objectiveDescription.textContent = objectiveComplete
      ? 'Detail pass complete. The old park is visible again.'
      : 'Use the leaf blower for benches, the statue, bin and frozen fountain.';
    const percentage = Math.round(clamp(cleanRatio, 0, 1) * 100);
    this.progress.textContent = objectiveComplete
      ? `DETAIL PASS COMPLETE · ${percentage}% CLEAN`
      : `${percentage}% DETAILS CLEAN`;
    this.element.style.setProperty('--land-progress', `${percentage}%`);
    this.element.classList.toggle('is-complete', objectiveComplete);
  }

  public dispose(): void {
    this.releaseBladePointer(); this.releaseBlowerPointer();
    this.element.removeEventListener('click', this.onClick);
    this.element.removeEventListener('pointerdown', this.onPointerDown);
    this.element.removeEventListener('pointerup', this.onPointerEnd);
    this.element.removeEventListener('pointercancel', this.onPointerEnd);
    this.element.remove();
  }

  private updateWorkshopObjective(clearedRatio: number, complete: boolean): void {
    const percentage = complete ? 100 : Math.round(resolveBorealisWorkshopProgress(clearedRatio) * 100);
    this.objectiveTitle.textContent = complete ? 'WORKSHOP APPROACH CLEARED' : 'CLEAR THE WORKSHOP APPROACH';
    this.objectiveDescription.textContent = complete
      ? 'Work order complete. Keep working freely or return to the ship.'
      : 'Clear 90% of the marked snowfield; the meter then reads 100%.';
    this.progress.textContent = complete ? `JOB COMPLETE · ${percentage}% CLEAR` : `${percentage}% CLEAR`;
    this.element.style.setProperty('--land-progress', `${percentage}%`);
    this.element.classList.toggle('is-complete', complete);
  }

  private onClick = (event: MouseEvent): void => {
    const action = (event.target as HTMLElement).closest<HTMLElement>('[data-land-action]')?.dataset.landAction;
    if (action === 'blade-mode') this.actions.onCycleBladeMode();
    else if (action === 'beacon') this.actions.onToggleBeacon();
    else if (action === 'lights') this.actions.onToggleLights();
    else if (action === 'interact') this.actions.onInteract();
    else if (action === 'dev-fleet') this.actions.onDevResetFleet();
    else if (action === 'dev-snow') this.actions.onDevForceSnow();
    else if (action === 'dev-protection') this.actions.onDevInstallProtection();
  };

  private onPointerDown = (event: PointerEvent): void => {
    if (event.button !== 0 || this.activeBladePointerId !== undefined || this.activeBlowerPointerId !== undefined) return;
    const blower = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-land-action="blower"]');
    if (blower) {
      event.preventDefault(); this.activeBlowerPointerId = event.pointerId;
      blower.setPointerCapture?.(event.pointerId); this.actions.onSetBlower(true); return;
    }
    const button = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-land-action="lower-blade"], [data-land-action="raise-blade"]');
    if (!button) return;
    event.preventDefault(); this.activeBladePointerId = event.pointerId;
    button.setPointerCapture?.(event.pointerId);
    this.actions.onSetBladeMotion(button.dataset.landAction === 'lower-blade' ? 1 : -1);
  };

  private onPointerEnd = (event: PointerEvent): void => {
    if (event.pointerId === this.activeBladePointerId) this.releaseBladePointer();
    if (event.pointerId === this.activeBlowerPointerId) this.releaseBlowerPointer();
  };

  private releaseBladePointer(): void {
    if (this.activeBladePointerId === undefined) return;
    this.activeBladePointerId = undefined; this.actions.onSetBladeMotion(0);
  }

  private releaseBlowerPointer(): void {
    if (this.activeBlowerPointerId === undefined) return;
    this.activeBlowerPointerId = undefined; this.actions.onSetBlower(false);
  }

  private setBladeButtonLimit(button: HTMLButtonElement, limited: boolean): void {
    button.classList.toggle('is-unavailable', limited);
    button.setAttribute('aria-disabled', limited ? 'true' : 'false');
  }

  private require<T extends HTMLElement = HTMLElement>(selector: string): T {
    const element = this.element.querySelector<T>(selector);
    if (!element) throw new Error(`ICE-A-WAY land UI element missing: ${selector}`);
    return element;
  }
}
