export const BULLDOZER_UPGRADE_IDS = {
  adjustableWingPlow: 'bulldozer-adjustable-wing-plow',
  wideTracks: 'bulldozer-wide-snow-tracks',
  polarWorkLights: 'bulldozer-polar-work-lights',
  amberBeacon: 'bulldozer-amber-beacon',
  heavyChassis: 'bulldozer-heavy-chassis',
  highCapacityBlade: 'bulldozer-high-capacity-blade',
  heavyPowertrain: 'bulldozer-heavy-powertrain',
} as const;

export type BulldozerBladeMode = 'STRAIGHT' | 'SCOOP' | 'V_PLOW';

export interface BulldozerCapabilities {
  adjustableWingPlow: boolean;
  wideTracks: boolean;
  polarWorkLights: boolean;
  amberBeacon: boolean;
  heavyChassis: boolean;
  highCapacityBlade: boolean;
  heavyPowertrain: boolean;
  maximumPushDepth: number;
  maximumPileDepth: number;
  massCapacityMultiplier: number;
  displayTier: 'STARTER' | 'HEAVY' | 'POLAR HEAVY';
}

export interface BulldozerBladeProfile {
  displayName: string;
  speedMultiplier: number;
  resistanceMultiplier: number;
  retainedFraction: number;
  frontCarryFraction: number;
  frontPileDepth: number;
  frontWaveSpread: number;
  depositForward: number;
  depositLateral: number;
  depositSpread: number;
  wingAngleRadians: number;
}

