export type FloeClass = 'debris' | 'small' | 'medium' | 'large';

export interface FloeMotionProfile {
  floeClass: FloeClass;
  windInfluence: number;
  currentInfluence: number;
  rotationInfluence: number;
  maximumSpeed: number;
}

export const classifyFloe = (cellCount: number): FloeClass => {
  if (cellCount <= 2) return 'debris';
  if (cellCount <= 12) return 'small';
  if (cellCount <= 64) return 'medium';
  return 'large';
};

const PROFILES: Record<FloeClass, Readonly<FloeMotionProfile>> = {
  debris: Object.freeze({
    floeClass: 'debris',
    windInfluence: 0.068,
    currentInfluence: 0.18,
    rotationInfluence: 0.9,
    maximumSpeed: 0.105,
  }),
  small: Object.freeze({
    floeClass: 'small',
    windInfluence: 0.048,
    currentInfluence: 0.28,
    rotationInfluence: 0.62,
    maximumSpeed: 0.078,
  }),
  medium: Object.freeze({
    floeClass: 'medium',
    windInfluence: 0.025,
    currentInfluence: 0.38,
    rotationInfluence: 0.32,
    maximumSpeed: 0.05,
  }),
  large: Object.freeze({
    floeClass: 'large',
    windInfluence: 0.009,
    currentInfluence: 0.48,
    rotationInfluence: 0.12,
    maximumSpeed: 0.024,
  }),
};

export const getFloeMotionProfile = (
  cellCount: number,
): Readonly<FloeMotionProfile> => PROFILES[classifyFloe(cellCount)];
