import { clamp } from '../utils/math';
import type { IceClass } from '../ice/IceWorldTypes';
import {
  AUTOMATIC_MUSIC_TRACK_ID,
  DEFAULT_AUDIO_SETTINGS,
  type AudioSettings,
} from './AudioSettings';
import type { RadioVoicePlaybackPlan } from './RadioVoiceSystem';

export interface MusicTrack {
  id: string;
  title: string;
  url: string;
}

export const MUSIC_TRACKS: readonly MusicTrack[] = [
  {
    id: 'dream-of-ice',
    title: 'Dream of Ice',
    url: './assets/music/dream-of-ice.mp3',
  },
  {
    id: 'waltzing-on-ice',
    title: 'Waltzing on Ice',
    url: './assets/music/waltzing-on-ice.mp3',
  },
  {
    id: 'where-penguins-dwell',
    title: 'Where Penguins Dwell',
    url: './assets/music/where-penguins-dwell.mp3',
  },
  {
    id: 'breaking-ice',
    title: 'Breaking Ice',
    url: './assets/music/breaking-ice.mp3',
  },
];

export class AudioSystem {
  private context: AudioContext | null = null;
  private master: GainNode | null = null;
  private effectsBus: GainNode | null = null;
  private musicBus: GainNode | null = null;
  private engineGain: GainNode | null = null;
  private engineFilter: BiquadFilterNode | null = null;
  private engineOscillator: OscillatorNode | null = null;
  private engineSubOscillator: OscillatorNode | null = null;
  private blowerGain: GainNode | null = null;
  private blowerFilter: BiquadFilterNode | null = null;
  private blowerOscillator: OscillatorNode | null = null;
  private blowerNoise: AudioBufferSourceNode | null = null;
  private windGain: GainNode | null = null;
  private waterGain: GainNode | null = null;
  private snowGain: GainNode | null = null;
  private riggingGain: GainNode | null = null;
  private riggingOscillator: OscillatorNode | null = null;
  private muted = false;
  private lastCrackAt = 0;
  private lastGroanAt = 0;
  private lastCompressionAt = 0;
  private lastSnowPlowAt = 0;
  private activeOneShots = 0;
  private weatherWind = 0;
  private weatherSnow = 0;
  private weatherVisibility = 1;
  private effectsVolume: number;
  private musicVolume: number;
  private musicElement: HTMLAudioElement | null = null;
  private musicSource: MediaElementAudioSourceNode | null = null;
  private musicTrackIndex = 0;
  private musicTrackId = AUTOMATIC_MUSIC_TRACK_ID;
  private musicPaused: boolean;
  private musicRepeat: boolean;
  private musicStateListener?: () => void;
  private musicRequested = false;
  private pageVisible = true;
  private musicDuckTimer = 0;
  private readonly activeRadioVoices =
    new Map<HTMLAudioElement, AudioNode[]>();

  public constructor(
    settings: Readonly<AudioSettings> = DEFAULT_AUDIO_SETTINGS,
  ) {
    this.effectsVolume = clamp(settings.effectsVolume, 0, 1);
    this.musicVolume = clamp(settings.musicVolume, 0, 1);
    this.musicPaused = settings.musicPaused;
    this.musicRepeat = settings.musicRepeat;
    const selectedTrackIndex = MUSIC_TRACKS.findIndex(
      (track) => track.id === settings.musicTrackId,
    );
    if (selectedTrackIndex >= 0) {
      this.musicTrackIndex = selectedTrackIndex;
      this.musicTrackId = MUSIC_TRACKS[selectedTrackIndex]!.id;
    }
  }

  public async unlock(): Promise<void> {
    if (!this.context) this.createGraph();
    if (this.context?.state === 'suspended') await this.context.resume();
    this.musicRequested = true;
    if (!this.musicPaused) await this.playMusic();
  }

  public setMuted(muted: boolean): void {
    this.muted = muted;
    if (!this.master || !this.context) return;
    this.master.gain.setTargetAtTime(muted ? 0 : 0.62, this.context.currentTime, 0.035);
  }

  public isMuted(): boolean {
    return this.muted;
  }

  public setEffectsVolume(volume: number): void {
    this.effectsVolume = clamp(volume, 0, 1);
    if (!this.effectsBus || !this.context) return;
    this.effectsBus.gain.setTargetAtTime(
      this.effectsVolume,
      this.context.currentTime,
      0.035,
    );
  }

  public setMusicVolume(volume: number): void {
    this.musicVolume = clamp(volume, 0, 1);
    if (this.musicBus && this.context) {
      this.musicBus.gain.setTargetAtTime(
        this.musicVolume,
        this.context.currentTime,
        0.06,
      );
    }
    if (
      this.musicVolume > 0 &&
      this.musicRequested &&
      this.pageVisible &&
      !this.musicPaused
    ) {
      void this.playMusic();
    }
  }

  public getSettings(): AudioSettings {
    return {
      effectsVolume: this.effectsVolume,
      musicVolume: this.musicVolume,
      musicTrackId: this.musicTrackId,
      musicPaused: this.musicPaused,
      musicRepeat: this.musicRepeat,
    };
  }

  public setPageVisible(visible: boolean): void {
    this.pageVisible = visible;
    if (!visible) {
      this.musicElement?.pause();
      return;
    }
    if (this.musicRequested && !this.musicPaused) {
      void this.playMusic();
    }
  }

  public setMusicStateListener(listener?: () => void): void {
    this.musicStateListener = listener;
  }

  public getMusicPlayerState(): {
    trackId: string;
    trackTitle: string;
    paused: boolean;
    repeat: boolean;
  } {
    const track = MUSIC_TRACKS[this.musicTrackIndex];
    return {
      trackId: track?.id ?? '',
      trackTitle: track?.title ?? 'No track',
      paused: this.musicPaused,
      repeat: this.musicRepeat,
    };
  }

  public selectMusicTrack(trackId: string): boolean {
    const index = MUSIC_TRACKS.findIndex(
      (track) => track.id === trackId,
    );
    if (index < 0) return false;
    if (index !== this.musicTrackIndex) {
      this.musicTrackIndex = index;
      this.loadMusicTrack();
    }
    if (
      this.musicRequested &&
      this.pageVisible &&
      !this.musicPaused
    ) {
      void this.playMusic();
    }
    this.notifyMusicStateChanged();
    return true;
  }

  public setMusicSelection(trackId: string): boolean {
    if (trackId === AUTOMATIC_MUSIC_TRACK_ID) {
      this.musicTrackId = AUTOMATIC_MUSIC_TRACK_ID;
      this.notifyMusicStateChanged();
      return true;
    }
    if (!MUSIC_TRACKS.some((track) => track.id === trackId)) {
      return false;
    }
    this.musicTrackId = trackId;
    return this.selectMusicTrack(trackId);
  }

  public previousMusicTrack(): void {
    const length = MUSIC_TRACKS.length;
    if (length === 0) return;
    this.musicTrackIndex =
      (this.musicTrackIndex - 1 + length) % length;
    this.musicTrackId =
      MUSIC_TRACKS[this.musicTrackIndex]?.id ??
      AUTOMATIC_MUSIC_TRACK_ID;
    this.loadMusicTrack();
    if (this.musicRequested && this.pageVisible && !this.musicPaused) {
      void this.playMusic();
    }
    this.notifyMusicStateChanged();
  }

  public nextMusicTrack(): void {
    const length = MUSIC_TRACKS.length;
    if (length === 0) return;
    this.musicTrackIndex = (this.musicTrackIndex + 1) % length;
    this.musicTrackId =
      MUSIC_TRACKS[this.musicTrackIndex]?.id ??
      AUTOMATIC_MUSIC_TRACK_ID;
    this.loadMusicTrack();
    if (this.musicRequested && this.pageVisible && !this.musicPaused) {
      void this.playMusic();
    }
    this.notifyMusicStateChanged();
  }

  public toggleMusicPlayback(): boolean {
    this.musicPaused = !this.musicPaused;
    if (this.musicPaused) {
      this.musicElement?.pause();
    } else {
      this.musicRequested = true;
      if (this.pageVisible) void this.playMusic();
    }
    this.notifyMusicStateChanged();
    return !this.musicPaused;
  }

  public toggleMusicRepeat(): boolean {
    this.musicRepeat = !this.musicRepeat;
    this.notifyMusicStateChanged();
    return this.musicRepeat;
  }

  public duckMusic(
    durationSeconds = 2.4,
    level = 0.24,
  ): void {
    if (!this.context || !this.musicBus) return;
    window.clearTimeout(this.musicDuckTimer);
    const now = this.context.currentTime;
    this.musicBus.gain.setTargetAtTime(
      this.musicVolume * clamp(level, 0, 1),
      now,
      0.06,
    );
    this.musicDuckTimer = window.setTimeout(() => {
      if (!this.context || !this.musicBus) return;
      this.musicBus.gain.setTargetAtTime(
        this.musicVolume,
        this.context.currentTime,
        0.18,
      );
    }, Math.max(0, durationSeconds) * 1000);
  }

  public playRadioVoice(
    plan: Extract<RadioVoicePlaybackPlan, { mode: 'AUDIO' }>,
  ): boolean {
    if (
      !this.context ||
      !this.effectsBus ||
      !this.pageVisible ||
      this.muted
    ) {
      return false;
    }
    const element = new Audio(plan.url);
    element.preload = 'auto';
    element.playbackRate = clamp(
      plan.playbackRate *
        2 ** (plan.pitchSemitones / 12),
      0.65,
      1.5,
    );
    const source =
      this.context.createMediaElementSource(element);
    const filter = this.context.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 1_250;
    filter.Q.value = 0.48;
    const compressor = this.context.createDynamicsCompressor();
    compressor.threshold.value = -26;
    compressor.knee.value = 18;
    compressor.ratio.value = 5;
    compressor.attack.value = 0.008;
    compressor.release.value = 0.16;
    const gain = this.context.createGain();
    gain.gain.value = 0.76;
    source
      .connect(filter)
      .connect(compressor)
      .connect(gain)
      .connect(this.effectsBus);
    const nodes: AudioNode[] = [
      source,
      filter,
      compressor,
      gain,
    ];
    const cleanup = (): void => {
      element.removeEventListener('ended', cleanup);
      element.removeEventListener('error', cleanup);
      for (const node of nodes) node.disconnect();
      this.activeRadioVoices.delete(element);
    };
    element.addEventListener('ended', cleanup, { once: true });
    element.addEventListener('error', cleanup, { once: true });
    this.activeRadioVoices.set(element, nodes);
    void element.play().catch(cleanup);
    return true;
  }

  public setEngine(active: boolean, normalizedSpeed: number, resistance: number): void {
    if (!this.context || !this.engineGain || !this.engineFilter || !this.engineOscillator || !this.engineSubOscillator) {
      return;
    }
    const now = this.context.currentTime;
    const speed = clamp(normalizedSpeed, 0, 1.5);
    const load = clamp(resistance, 0, 1);
    this.engineGain.gain.setTargetAtTime(active ? 0.045 + speed * 0.035 : 0.012, now, 0.12);
    this.engineOscillator.frequency.setTargetAtTime(48 + speed * 25 - load * 5, now, 0.14);
    this.engineSubOscillator.frequency.setTargetAtTime(24 + speed * 12.5, now, 0.14);
    this.engineFilter.frequency.setTargetAtTime(230 + speed * 240 + load * 80, now, 0.12);
  }

  public setVesselEngine(
    active: boolean,
    normalizedRpm: number,
    engineLoad: number,
  ): void {
    this.setEngine(active, normalizedRpm, engineLoad);
  }

  public setOceanAmbience(
    waveEnergy: number,
    vesselSpeed: number,
    openness: number,
  ): void {
    if (!this.context || !this.windGain || !this.waterGain) return;
    const now = this.context.currentTime;
    const waves = clamp(waveEnergy, 0, 1.5);
    const speed = clamp(vesselSpeed, 0, 1.5);
    const openWater = clamp(openness, 0, 1);
    this.windGain.gain.setTargetAtTime(
      0.006 +
        waves * 0.011 +
        (1 - openWater) * 0.004 +
        this.weatherWind * 0.012,
      now,
      0.5,
    );
    this.waterGain.gain.setTargetAtTime(
      openWater *
        (0.006 + waves * 0.018 + speed * 0.006) *
        (0.72 + this.weatherVisibility * 0.28),
      now,
      0.32,
    );
  }

  public setWeatherAmbience(
    windStrength: number,
    snowIntensity: number,
    visibility: number,
  ): void {
    this.weatherWind = clamp((windStrength - 0.7) / 0.85, 0, 1);
    this.weatherSnow = clamp(snowIntensity, 0, 1);
    this.weatherVisibility = clamp(visibility, 0, 1);
    if (
      !this.context ||
      !this.snowGain ||
      !this.riggingGain
    ) {
      return;
    }
    const now = this.context.currentTime;
    this.snowGain.gain.setTargetAtTime(
      this.weatherSnow * 0.011,
      now,
      0.8,
    );
    this.riggingGain.gain.setTargetAtTime(
      this.weatherWind * 0.008,
      now,
      0.65,
    );
  }

  public getVoiceStats(): {
    continuous: number;
    oneShots: number;
    total: number;
    effectsVolume: number;
    musicVolume: number;
    musicPlaying: boolean;
    musicTrack: string;
  } {
    const continuous = this.context ? 8 : 0;
    const musicPlaying =
      this.musicElement !== null && !this.musicElement.paused;
    return {
      continuous,
      oneShots: this.activeOneShots,
      total:
        continuous +
        this.activeOneShots +
        this.activeRadioVoices.size +
        (musicPlaying ? 1 : 0),
      effectsVolume: this.effectsVolume,
      musicVolume: this.musicVolume,
      musicPlaying,
      musicTrack: MUSIC_TRACKS[this.musicTrackIndex]?.title ?? 'None',
    };
  }

  public horn(): void {
    if (!this.context || !this.effectsBus) return;
    this.tone(185, 0.42, 0.055, 'sawtooth', 168);
    window.setTimeout(() => this.tone(155, 0.5, 0.045, 'sawtooth', 142), 115);
  }

  public iceImpact(iceClass: IceClass, intensity: number): void {
    const strength = clamp(intensity, 0, 1);
    this.iceCrack(strength);
    if (!this.context || iceClass === 'open' || iceClass === 'channel') return;
    const now = this.context.currentTime;
    const cooldown = iceClass === 'thick' ? 0.48 : 0.7;
    if (now - this.lastGroanAt < cooldown || strength < 0.28) return;
    this.lastGroanAt = now;
    if (iceClass === 'thick') {
      this.tone(78 + Math.random() * 14, 0.34, 0.026 + strength * 0.025, 'sawtooth', 62);
    } else if (iceClass === 'medium') {
      this.tone(128 + Math.random() * 24, 0.18, 0.018 + strength * 0.018, 'triangle', 96);
    }
  }

  public floeCompression(intensity: number): void {
    if (!this.context || intensity < 0.18) return;
    const now = this.context.currentTime;
    if (now - this.lastCompressionAt < 1.8) return;
    this.lastCompressionAt = now;
    const strength = clamp(intensity, 0, 1);
    this.tone(
      64 + Math.random() * 10,
      0.42 + strength * 0.32,
      0.012 + strength * 0.022,
      'sawtooth',
      48,
    );
  }

  public snowPlow(displacedSnow: number): void {
    if (!this.context || displacedSnow <= 0.02) return;
    const now = this.context.currentTime;
    if (now - this.lastSnowPlowAt < 0.16) return;
    this.lastSnowPlowAt = now;
    const strength = clamp(displacedSnow / 1.2, 0, 1);
    this.tone(
      96 + strength * 26,
      0.09 + strength * 0.08,
      0.008 + strength * 0.012,
      'triangle',
      72 + strength * 14,
    );
  }

  public setSnowBlower(active: boolean, snowDepth: number): void {
    if (
      !this.context ||
      !this.blowerGain ||
      !this.blowerFilter ||
      !this.blowerOscillator
    ) {
      return;
    }
    const now = this.context.currentTime;
    const load = clamp(snowDepth / 0.8, 0, 1);
    this.blowerGain.gain.setTargetAtTime(
      active ? 0.016 + load * 0.006 : 0.0001,
      now,
      active ? 0.06 : 0.12,
    );
    this.blowerOscillator.frequency.setTargetAtTime(
      152 - load * 12,
      now,
      0.08,
    );
    this.blowerFilter.frequency.setTargetAtTime(
      1_050 + load * 260,
      now,
      0.09,
    );
  }

  public ambientIceGroan(intensity: number): void {
    if (!this.context || !this.effectsBus) return;
    const now = this.context.currentTime;
    if (now - this.lastGroanAt < 4.5) return;
    this.lastGroanAt = now;
    const strength = clamp(intensity, 0, 1);
    this.tone(
      48 + strength * 18,
      1.1 + strength * 0.8,
      0.009 + strength * 0.018,
      'sawtooth',
      39 + strength * 8,
    );
  }

  public click(): void {
    this.tone(520, 0.035, 0.018, 'sine', 740);
  }

  public purchase(): void {
    if (!this.context || !this.effectsBus) return;
    const now = this.context.currentTime;
    [392, 523, 659].forEach((frequency, index) => {
      const oscillator = this.context!.createOscillator();
      const gain = this.context!.createGain();
      oscillator.type = 'sine';
      oscillator.frequency.value = frequency;
      gain.gain.setValueAtTime(0, now + index * 0.045);
      gain.gain.linearRampToValueAtTime(0.055, now + index * 0.045 + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + index * 0.045 + 0.22);
      oscillator.connect(gain).connect(this.effectsBus!);
      this.trackOneShot(oscillator);
      oscillator.start(now + index * 0.045);
      oscillator.stop(now + index * 0.045 + 0.24);
    });
  }

  public success(): void {
    if (!this.context || !this.effectsBus) return;
    const now = this.context.currentTime;
    const notes = [261.63, 329.63, 392, 523.25];
    notes.forEach((frequency, index) => {
      const oscillator = this.context!.createOscillator();
      const gain = this.context!.createGain();
      oscillator.type = index < 3 ? 'triangle' : 'sine';
      oscillator.frequency.value = frequency;
      const start = now + index * 0.09;
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(0.07, start + 0.025);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.55);
      oscillator.connect(gain).connect(this.effectsBus!);
      this.trackOneShot(oscillator);
      oscillator.start(start);
      oscillator.stop(start + 0.58);
    });
  }

  public radioTowerOnline(): void {
    if (!this.context || !this.effectsBus) return;
    const now = this.context.currentTime;
    const notes = [196, 293.66, 392, 587.33];
    notes.forEach((frequency, index) => {
      const oscillator = this.context!.createOscillator();
      const gain = this.context!.createGain();
      const filter = this.context!.createBiquadFilter();
      oscillator.type = index < 2 ? 'triangle' : 'sine';
      oscillator.frequency.value = frequency;
      filter.type = 'bandpass';
      filter.frequency.value = 680 + index * 180;
      filter.Q.value = 0.65;
      const start = now + index * 0.085;
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(
        0.05,
        start + 0.018,
      );
      gain.gain.exponentialRampToValueAtTime(
        0.0001,
        start + 0.42,
      );
      oscillator
        .connect(filter)
        .connect(gain)
        .connect(this.effectsBus!);
      this.trackOneShot(oscillator);
      oscillator.start(start);
      oscillator.stop(start + 0.45);
    });
  }

  public lighthouseLit(): void {
    if (!this.context || !this.effectsBus) return;
    const now = this.context.currentTime;
    [329.63, 493.88, 659.25].forEach(
      (frequency, index) => {
        const oscillator = this.context!.createOscillator();
        const gain = this.context!.createGain();
        oscillator.type = 'sine';
        oscillator.frequency.value = frequency;
        const start = now + index * 0.16;
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(
          0.055,
          start + 0.025,
        );
        gain.gain.exponentialRampToValueAtTime(
          0.0001,
          start + 0.82,
        );
        oscillator.connect(gain).connect(this.effectsBus!);
        this.trackOneShot(oscillator);
        oscillator.start(start);
        oscillator.stop(start + 0.86);
      },
    );
  }

  public iceCrack(intensity: number): void {
    if (!this.context || !this.effectsBus) return;
    const now = this.context.currentTime;
    if (now - this.lastCrackAt < 0.075) return;
    this.lastCrackAt = now;

    const duration = 0.055 + clamp(intensity, 0, 1) * 0.11;
    const buffer = this.context.createBuffer(1, Math.ceil(this.context.sampleRate * duration), this.context.sampleRate);
    const data = buffer.getChannelData(0);
    for (let index = 0; index < data.length; index += 1) {
      const envelope = 1 - index / data.length;
      data[index] = (Math.random() * 2 - 1) * envelope * envelope;
    }

    const source = this.context.createBufferSource();
    const filter = this.context.createBiquadFilter();
    const gain = this.context.createGain();
    source.buffer = buffer;
    filter.type = 'bandpass';
    filter.frequency.value = 700 + Math.random() * 1150;
    filter.Q.value = 0.65;
    gain.gain.setValueAtTime(0.035 + intensity * 0.065, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    source.connect(filter).connect(gain).connect(this.effectsBus);
    this.trackOneShot(source);
    source.start(now);
  }

  public dispose(): void {
    window.clearTimeout(this.musicDuckTimer);
    this.musicStateListener = undefined;
    this.musicElement?.pause();
    for (const [voice, nodes] of this.activeRadioVoices) {
      voice.pause();
      for (const node of nodes) node.disconnect();
    }
    this.activeRadioVoices.clear();
    if (this.musicElement) {
      this.musicElement.removeEventListener('ended', this.onMusicEnded);
      this.musicElement.removeAttribute('src');
      this.musicElement.load();
    }
    this.musicSource?.disconnect();
    this.engineOscillator?.stop();
    this.engineSubOscillator?.stop();
    this.blowerOscillator?.stop();
    this.blowerNoise?.stop();
    this.riggingOscillator?.stop();
    void this.context?.close();
    this.context = null;
    this.musicElement = null;
    this.musicSource = null;
    this.activeOneShots = 0;
  }

  private createGraph(): void {
    this.context = new AudioContext();
    const master = this.context.createGain();
    master.gain.value = this.muted ? 0 : 0.62;
    master.connect(this.context.destination);
    this.master = master;

    const effectsBus = this.context.createGain();
    effectsBus.gain.value = this.effectsVolume;
    effectsBus.connect(master);
    this.effectsBus = effectsBus;

    const musicBus = this.context.createGain();
    musicBus.gain.value = this.musicVolume;
    musicBus.connect(master);
    this.musicBus = musicBus;

    const windGain = this.context.createGain();
    windGain.gain.value = 0.018;
    const windFilter = this.context.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 520;
    const windBuffer = this.context.createBuffer(1, this.context.sampleRate * 3, this.context.sampleRate);
    const windData = windBuffer.getChannelData(0);
    let previous = 0;
    for (let index = 0; index < windData.length; index += 1) {
      const white = Math.random() * 2 - 1;
      previous = previous * 0.985 + white * 0.015;
      windData[index] = previous * 4.4;
    }
    const windSource = this.context.createBufferSource();
    windSource.buffer = windBuffer;
    windSource.loop = true;
    windSource
      .connect(windFilter)
      .connect(windGain)
      .connect(effectsBus);
    windSource.start();
    this.windGain = windGain;

    const waterGain = this.context.createGain();
    waterGain.gain.value = 0.008;
    const waterFilter = this.context.createBiquadFilter();
    waterFilter.type = 'bandpass';
    waterFilter.frequency.value = 860;
    waterFilter.Q.value = 0.52;
    const waterBuffer = this.context.createBuffer(
      1,
      this.context.sampleRate * 4,
      this.context.sampleRate,
    );
    const waterData = waterBuffer.getChannelData(0);
    let waterEnvelope = 0;
    for (let index = 0; index < waterData.length; index += 1) {
      const white = Math.random() * 2 - 1;
      const pulse = Math.sin(index / this.context.sampleRate * 2.8) * 0.18;
      waterEnvelope = waterEnvelope * 0.965 + white * 0.035;
      waterData[index] = waterEnvelope * 2.3 + white * (0.12 + pulse);
    }
    const waterSource = this.context.createBufferSource();
    waterSource.buffer = waterBuffer;
    waterSource.loop = true;
    waterSource
      .connect(waterFilter)
      .connect(waterGain)
      .connect(effectsBus);
    waterSource.start();
    this.waterGain = waterGain;

    const snowGain = this.context.createGain();
    snowGain.gain.value = 0;
    const snowFilter = this.context.createBiquadFilter();
    snowFilter.type = 'highpass';
    snowFilter.frequency.value = 1900;
    const snowBuffer = this.context.createBuffer(
      1,
      this.context.sampleRate * 3,
      this.context.sampleRate,
    );
    const snowData = snowBuffer.getChannelData(0);
    for (let index = 0; index < snowData.length; index += 1) {
      snowData[index] = (Math.random() * 2 - 1) * 0.34;
    }
    const snowSource = this.context.createBufferSource();
    snowSource.buffer = snowBuffer;
    snowSource.loop = true;
    snowSource
      .connect(snowFilter)
      .connect(snowGain)
      .connect(effectsBus);
    snowSource.start();
    this.snowGain = snowGain;

    const riggingGain = this.context.createGain();
    riggingGain.gain.value = 0;
    const riggingFilter = this.context.createBiquadFilter();
    riggingFilter.type = 'bandpass';
    riggingFilter.frequency.value = 380;
    riggingFilter.Q.value = 2.8;
    const riggingOscillator = this.context.createOscillator();
    riggingOscillator.type = 'triangle';
    riggingOscillator.frequency.value = 96;
    riggingOscillator
      .connect(riggingFilter)
      .connect(riggingGain)
      .connect(effectsBus);
    riggingOscillator.start();
    this.riggingGain = riggingGain;
    this.riggingOscillator = riggingOscillator;

    const engineGain = this.context.createGain();
    engineGain.gain.value = 0.012;
    const engineFilter = this.context.createBiquadFilter();
    engineFilter.type = 'lowpass';
    engineFilter.frequency.value = 260;
    engineFilter.Q.value = 1.1;

    const engineOscillator = this.context.createOscillator();
    engineOscillator.type = 'sawtooth';
    engineOscillator.frequency.value = 48;
    const engineSubOscillator = this.context.createOscillator();
    engineSubOscillator.type = 'sine';
    engineSubOscillator.frequency.value = 24;
    const subGain = this.context.createGain();
    subGain.gain.value = 0.58;

    engineOscillator.connect(engineFilter);
    engineSubOscillator.connect(subGain).connect(engineFilter);
    engineFilter.connect(engineGain).connect(effectsBus);
    engineOscillator.start();
    engineSubOscillator.start();

    this.engineGain = engineGain;
    this.engineFilter = engineFilter;
    this.engineOscillator = engineOscillator;
    this.engineSubOscillator = engineSubOscillator;

    const blowerGain = this.context.createGain();
    blowerGain.gain.value = 0.0001;
    const blowerFilter = this.context.createBiquadFilter();
    blowerFilter.type = 'bandpass';
    blowerFilter.frequency.value = 1_050;
    blowerFilter.Q.value = 0.34;
    const blowerBuffer = this.context.createBuffer(
      1,
      this.context.sampleRate * 2,
      this.context.sampleRate,
    );
    const blowerData = blowerBuffer.getChannelData(0);
    for (let index = 0; index < blowerData.length; index += 1) {
      blowerData[index] = (Math.random() * 2 - 1) * 0.46;
    }
    const blowerNoise = this.context.createBufferSource();
    blowerNoise.buffer = blowerBuffer;
    blowerNoise.loop = true;
    const blowerOscillator = this.context.createOscillator();
    blowerOscillator.type = 'sawtooth';
    blowerOscillator.frequency.value = 152;
    blowerNoise.connect(blowerFilter).connect(blowerGain);
    blowerOscillator.connect(blowerGain);
    blowerGain.connect(effectsBus);
    blowerNoise.start();
    blowerOscillator.start();
    this.blowerGain = blowerGain;
    this.blowerFilter = blowerFilter;
    this.blowerNoise = blowerNoise;
    this.blowerOscillator = blowerOscillator;

    const musicElement = new Audio();
    musicElement.preload = 'auto';
    musicElement.addEventListener('ended', this.onMusicEnded);
    this.musicElement = musicElement;
    this.musicSource =
      this.context.createMediaElementSource(musicElement);
    this.musicSource.connect(musicBus);
    this.loadMusicTrack();
  }

  private tone(
    frequency: number,
    duration: number,
    volume: number,
    type: OscillatorType,
    endFrequency?: number,
  ): void {
    if (!this.context || !this.effectsBus) return;
    const now = this.context.currentTime;
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    oscillator.type = type;
    oscillator.frequency.setValueAtTime(frequency, now);
    if (endFrequency) oscillator.frequency.exponentialRampToValueAtTime(endFrequency, now + duration);
    gain.gain.setValueAtTime(volume, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    oscillator.connect(gain).connect(this.effectsBus);
    this.trackOneShot(oscillator);
    oscillator.start(now);
    oscillator.stop(now + duration + 0.01);
  }

  private trackOneShot(source: AudioScheduledSourceNode): void {
    this.activeOneShots += 1;
    source.addEventListener(
      'ended',
      () => {
        this.activeOneShots = Math.max(0, this.activeOneShots - 1);
      },
      { once: true },
    );
  }

  private readonly onMusicEnded = (): void => {
    if (!this.musicRepeat) {
      this.musicTrackIndex =
        (this.musicTrackIndex + 1) % MUSIC_TRACKS.length;
      if (this.musicTrackId !== AUTOMATIC_MUSIC_TRACK_ID) {
        this.musicTrackId =
          MUSIC_TRACKS[this.musicTrackIndex]?.id ??
          AUTOMATIC_MUSIC_TRACK_ID;
      }
    }
    this.loadMusicTrack();
    if (
      this.musicRequested &&
      this.pageVisible &&
      !this.musicPaused
    ) {
      void this.playMusic();
    }
    this.notifyMusicStateChanged();
  };

  private loadMusicTrack(): void {
    const track = MUSIC_TRACKS[this.musicTrackIndex];
    if (!this.musicElement || !track) return;
    this.musicElement.src = track.url;
    this.musicElement.load();
  }

  private async playMusic(): Promise<void> {
    if (!this.musicElement || !this.pageVisible || this.musicPaused) {
      return;
    }
    try {
      await this.musicElement.play();
    } catch {
      // The next user gesture retries playback if the browser blocks it.
    }
  }

  private notifyMusicStateChanged(): void {
    this.musicStateListener?.();
  }
}
