import type { VesselObstacle } from '../vessels/VesselConfig';
import {
  initializeBorealisCoastRaster,
  sampleBorealisRasterCoastX,
} from './BorealisCoastRaster';

export const BOREALIS_GROUND_HEIGHT = 0.31;
export const BOREALIS_DEPLOYMENT = Object.freeze({
  x: -27.4,
  z: 8.4,
  heading: -Math.PI / 2,
});
export const BOREALIS_HARBOR_LUOTO = Object.freeze({
  x: -20.8,
  z: 8.4,
  radius: 4.2,
});
export const BOREALIS_WORKSHOP_SNOWFIELD = Object.freeze({
  centerX: -43,
  centerZ: 8.4,
  halfWidth: 4.2,
  halfHeight: 3.2,
});
export const BOREALIS_WORKSHOP_CLEAR_REQUIREMENT = 0.9;

export const resolveBorealisWorkshopProgress = (
  clearedRatio: number,
): number =>
  Math.max(
    0,
    Math.min(1, clearedRatio / BOREALIS_WORKSHOP_CLEAR_REQUIREMENT),
  );

export const isBorealisWorkshopComplete = (
  clearedRatio: number,
): boolean => clearedRatio >= BOREALIS_WORKSHOP_CLEAR_REQUIREMENT;

export const borealisCoastX = (z: number): number => {
  const rasterCoast = sampleBorealisRasterCoastX(z);
  if (rasterCoast !== undefined) return rasterCoast;
  const broadCoast =
    -31.5 +
    Math.sin(z * 0.105 + 0.8) * 1.65 +
    Math.sin(z * 0.037 - 1.2) * 1.1;
  const harborPromontory =
    Math.exp(-((z - 8.4) * (z - 8.4)) / 38) * 8.6;
  const northernCove =
    Math.exp(-((z + 19) * (z + 19)) / 70) * -2.2;
  return broadCoast + harborPromontory + northernCove;
};

export const isBorealisLand = (x: number, z: number): boolean => {
  if (!Number.isFinite(x) || !Number.isFinite(z)) return false;
  const mainland = x <= borealisCoastX(z);
  const borealisIsland =
    Math.hypot(
      x - BOREALIS_HARBOR_LUOTO.x,
      z - BOREALIS_HARBOR_LUOTO.z,
    ) <= BOREALIS_HARBOR_LUOTO.radius;
  return mainland || borealisIsland;
};

export const distanceInsideBorealisLand = (
  x: number,
  z: number,
): number => {
  const mainlandDistance = borealisCoastX(z) - x;
  const islandDistance =
    BOREALIS_HARBOR_LUOTO.radius -
    Math.hypot(
      x - BOREALIS_HARBOR_LUOTO.x,
      z - BOREALIS_HARBOR_LUOTO.z,
    );
  return Math.max(mainlandDistance, islandDistance);
};

const coastObstacles: VesselObstacle[] = [];
const refreshCoastObstacles = (): void => {
  let index = 0;
  for (let z = -30; z <= 30; z += 5.5) {
    if (Math.abs(z - 8.4) < 5.2) continue;
    const existing = coastObstacles[index];
    if (existing) {
      existing.x = borealisCoastX(z) - 2.4;
      existing.z = z;
      existing.radius = 3.5;
    } else {
      coastObstacles.push({
        x: borealisCoastX(z) - 2.4,
        z,
        radius: 3.5,
      });
    }
    index += 1;
  }
  coastObstacles.length = index;
};
refreshCoastObstacles();

export const initializeBorealisLandRaster = async (): Promise<void> => {
  await initializeBorealisCoastRaster();
  refreshCoastObstacles();
};

export const BOREALIS_MAINLAND_VESSEL_OBSTACLES:
  readonly VesselObstacle[] = coastObstacles;
