import {
  BoxGeometry,
  CanvasTexture,
  Color,
  ConeGeometry,
  CylinderGeometry,
  Group,
  InstancedMesh,
  MeshStandardMaterial,
  Object3D,
  PointLight,
  Sprite,
  SpriteMaterial,
  SRGBColorSpace,
  SphereGeometry,
  type BufferGeometry,
  type Scene,
} from 'three';
import type {
  RuntimeWorldChunkDescriptor,
  RuntimeWorldChunkListener,
} from '../world/RuntimeWorldChunks';
import { clamp } from '../utils/math';
import { BOREALIS_GROUND_HEIGHT } from './BorealisLand';
import { prototypeBoundsForChunk } from './BorealisMainlandRenderer';
import {
  BOREALIS_TOWN_BOUNDS,
  BOREALIS_TOWN_BUILDINGS,
  BOREALIS_TOWN_EMPTY_LOTS,
  BOREALIS_FLEET_YARD,
  BOREALIS_TOWN_ROADS,
  type BorealisTownBuildingLot,
} from './BorealisTownLayout';

interface TownInstance {
  x: number;
  y: number;
  z: number;
  scaleX: number;
  scaleY: number;
  scaleZ: number;
  rotationY?: number;
  color?: number;
}

interface ActiveTownChunk {
  root: Group;
  lampPositions: readonly { x: number; z: number }[];
  drawGroups: number;
  buildings: number;
  disposables: Array<{ dispose(): void }>;
}

const ACTIVE_TOWN_LIGHT_COUNT = 6;

const chunkKey = (chunk: Readonly<RuntimeWorldChunkDescriptor>): string =>
  `${chunk.address.x},${chunk.address.z}`;

export class BorealisTownSystem implements RuntimeWorldChunkListener {
  private readonly root = new Group();
  private readonly chunks = new Map<string, ActiveTownChunk>();
  private readonly geometries = new Set<BufferGeometry>();
  private readonly materials = new Set<MeshStandardMaterial>();
  private readonly transform = new Object3D();
  private readonly wallMaterial = this.material(0xffffff, 0.88, 0.01);
  private readonly roofMaterial = this.material(0x38525a, 0.82, 0.06);
  private readonly snowMaterial = this.material(0xe8f4f2, 0.96, 0);
  private readonly trimMaterial = this.material(0xe5dfc8, 0.82, 0.02);
  private readonly glassMaterial = this.material(0x8fc6ce, 0.34, 0.08);
  private readonly doorMaterial = this.material(0x533f35, 0.82, 0.03);
  private readonly signMaterial = this.material(0xe5a948, 0.7, 0.04);
  private readonly metalMaterial = this.material(0x2f454b, 0.72, 0.28);
  private readonly lampMaterial = this.material(0xffd991, 0.28, 0.04);
  private readonly foliageMaterial = this.material(0x315f55, 0.94, 0);
  private readonly yardMaterial = this.material(0x617175, 0.9, 0.04);
  private readonly wallGeometry = this.geometry(new BoxGeometry(1, 1, 1));
  private readonly roofGeometry = this.geometry(new ConeGeometry(1, 1, 4));
  private readonly cylinderGeometry = this.geometry(
    new CylinderGeometry(1, 1, 1, 8),
  );
  private readonly globeGeometry = this.geometry(new SphereGeometry(1, 8, 6));
  private readonly treeGeometry = this.geometry(new ConeGeometry(1, 1, 7));
  private readonly lightPool: PointLight[] = [];
  private night = 0;
  private lightFocusX = Number.NaN;
  private lightFocusZ = Number.NaN;
  private lightsDirty = true;

  public constructor(scene: Scene) {
    this.root.name = 'Chunked Borealis town beyond the harbor';
    this.lampMaterial.emissive.setHex(0xffc96f);
    this.lampMaterial.emissiveIntensity = 0.08;
    for (let index = 0; index < ACTIVE_TOWN_LIGHT_COUNT; index += 1) {
      const light = new PointLight(0xffd48d, 0, 11, 2);
      light.name = `Nearest Borealis town light ${index + 1}`;
      light.visible = false;
      this.lightPool.push(light);
      this.root.add(light);
    }
    scene.add(this.root);
  }

  public onChunkActivated(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void {
    if (chunk.kind !== 'BOREALIS_COAST' && chunk.kind !== 'WESTERN_MAINLAND') {
      return;
    }
    const key = chunkKey(chunk);
    if (this.chunks.has(key)) return;
    const bounds = prototypeBoundsForChunk(chunk.address.x, chunk.address.z);
    if (
      bounds.maxX < BOREALIS_TOWN_BOUNDS.minX ||
      bounds.minX > BOREALIS_TOWN_BOUNDS.maxX ||
      bounds.maxZ < BOREALIS_TOWN_BOUNDS.minZ ||
      bounds.minZ > BOREALIS_TOWN_BOUNDS.maxZ
    ) {
      return;
    }
    const active = this.createChunk(bounds);
    this.chunks.set(key, active);
    this.root.add(active.root);
    this.lightsDirty = true;
  }

  public onChunkDeactivated(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void {
    const key = chunkKey(chunk);
    const active = this.chunks.get(key);
    if (!active) return;
    for (const disposable of active.disposables) disposable.dispose();
    active.root.removeFromParent();
    this.chunks.delete(key);
    this.lightsDirty = true;
  }

  public setEnvironmentLighting(night: number): void {
    this.night = clamp(night, 0, 1);
    this.applyLightState();
  }

  public updateLightFocus(x: number, z: number): void {
    if (!Number.isFinite(x) || !Number.isFinite(z)) return;
    if (
      !this.lightsDirty &&
      Math.hypot(x - this.lightFocusX, z - this.lightFocusZ) < 1
    ) {
      return;
    }
    this.lightFocusX = x;
    this.lightFocusZ = z;
    this.lightsDirty = false;
    const nearest = [...this.chunks.values()]
      .flatMap((active) => active.lampPositions)
      .map((position) => ({
        ...position,
        distanceSquared:
          (position.x - x) * (position.x - x) +
          (position.z - z) * (position.z - z),
      }))
      .sort((left, right) => left.distanceSquared - right.distanceSquared)
      .slice(0, ACTIVE_TOWN_LIGHT_COUNT);
    this.lightPool.forEach((light, index) => {
      const position = nearest[index];
      light.userData.assigned = position !== undefined;
      if (position) {
        light.position.set(
          position.x,
          BOREALIS_GROUND_HEIGHT + 2.82,
          position.z,
        );
      }
    });
    this.applyLightState();
  }

  public canWalkAt(x: number, z: number): boolean {
    return !this.intersectsBuilding(x, z, 0.18);
  }

  public canDriveAt(x: number, z: number): boolean {
    return !this.intersectsBuilding(x, z, 1.05);
  }

  public canPlaceMachineAt(x: number, z: number, clearanceRadius: number): boolean {
    return !this.intersectsBuilding(x, z, Math.max(0.2, clearanceRadius));
  }

  public getStats(): {
    activeChunks: number;
    visibleBuildings: number;
    drawGroups: number;
    totalBuildings: number;
    emptyLots: number;
    activeLights: number;
  } {
    let visibleBuildings = 0;
    let drawGroups = 0;
    for (const active of this.chunks.values()) {
      visibleBuildings += active.buildings;
      drawGroups += active.drawGroups;
    }
    return {
      activeChunks: this.chunks.size,
      visibleBuildings,
      drawGroups,
      totalBuildings: BOREALIS_TOWN_BUILDINGS.length,
      emptyLots: BOREALIS_TOWN_EMPTY_LOTS.length,
      activeLights: this.lightPool.filter((light) => light.visible).length,
    };
  }

  public writePerformanceTrace(target: {
    townActiveChunks?: number;
    townVisibleBuildings?: number;
    townDrawGroups?: number;
    townActiveLights?: number;
  }): void {
    const stats = this.getStats();
    target.townActiveChunks = stats.activeChunks;
    target.townVisibleBuildings = stats.visibleBuildings;
    target.townDrawGroups = stats.drawGroups;
    target.townActiveLights = stats.activeLights;
  }

  public dispose(): void {
    for (const active of this.chunks.values()) {
      for (const disposable of active.disposables) disposable.dispose();
    }
    this.chunks.clear();
    for (const geometry of this.geometries) geometry.dispose();
    for (const material of this.materials) material.dispose();
    this.root.removeFromParent();
  }

  private createChunk(bounds: {
    minX: number;
    maxX: number;
    minZ: number;
    maxZ: number;
  }): ActiveTownChunk {
    const root = new Group();
    root.name = `Borealis town chunk ${bounds.minX},${bounds.minZ}`;
    const contains = (x: number, z: number): boolean =>
      x >= bounds.minX && x < bounds.maxX && z >= bounds.minZ && z < bounds.maxZ;
    const buildings = BOREALIS_TOWN_BUILDINGS.filter((building) =>
      contains(building.x, building.z),
    );
    let drawGroups = 0;
    const disposables: Array<{ dispose(): void }> = [];
    if (buildings.length > 0) {
      drawGroups += this.addBuildings(root, buildings);
      drawGroups += this.addServiceLabels(root, buildings, disposables);
    }
    if (contains(BOREALIS_FLEET_YARD.centerX, BOREALIS_FLEET_YARD.centerZ)) {
      drawGroups += this.addFleetYard(root);
    }
    const lampPositions: Array<{ x: number; z: number }> = [];
    for (const road of BOREALIS_TOWN_ROADS) {
      if (road.halfWidth > road.halfDepth) {
        for (
          let x = Math.ceil((road.centerX - road.halfWidth) / 16) * 16;
          x <= road.centerX + road.halfWidth;
          x += 16
        ) {
          for (const side of [-1, 1]) {
            const z = road.centerZ + side * (road.halfDepth + 1.15);
            if (contains(x, z)) lampPositions.push({ x, z });
          }
        }
      } else {
        for (
          let z = Math.ceil((road.centerZ - road.halfDepth) / 16) * 16;
          z <= road.centerZ + road.halfDepth;
          z += 16
        ) {
          for (const side of [-1, 1]) {
            const x = road.centerX + side * (road.halfWidth + 1.15);
            if (contains(x, z)) lampPositions.push({ x, z });
          }
        }
      }
    }
    if (lampPositions.length > 0) {
      drawGroups += this.addTownLamps(root, lampPositions);
    }
    const lots = BOREALIS_TOWN_EMPTY_LOTS.filter((lot) => contains(lot.x, lot.z));
    if (lots.length > 0) drawGroups += this.addEmptyLots(root, lots);
    return {
      root,
      lampPositions,
      drawGroups,
      buildings: buildings.length,
      disposables,
    };
  }

  private addServiceLabels(
    root: Group,
    buildings: readonly BorealisTownBuildingLot[],
    disposables: Array<{ dispose(): void }>,
  ): number {
    if (typeof document === 'undefined') return 0;
    let labels = 0;
    for (const building of buildings) {
      if (building.service === 'RESIDENCE' || building.service === 'WAREHOUSE') {
        continue;
      }
      const canvas = document.createElement('canvas');
      canvas.width = 512;
      canvas.height = 96;
      const context = canvas.getContext('2d');
      if (!context) continue;
      context.fillStyle = '#163d45';
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.strokeStyle = '#e5b452';
      context.lineWidth = 8;
      context.strokeRect(4, 4, canvas.width - 8, canvas.height - 8);
      context.fillStyle = '#f3fbf7';
      context.font = '700 30px system-ui, sans-serif';
      context.textAlign = 'center';
      context.textBaseline = 'middle';
      const label = building.displayName
        .replace('Borealis ', '')
        .replace('North Star ', '')
        .toUpperCase();
      context.fillText(label, canvas.width * 0.5, canvas.height * 0.52, 470);
      const texture = new CanvasTexture(canvas);
      texture.colorSpace = SRGBColorSpace;
      const material = new SpriteMaterial({
        map: texture,
        transparent: true,
        depthWrite: false,
      });
      const sprite = new Sprite(material);
      const frontDirection = building.front === 'NORTH' ? 1 : -1;
      sprite.position.set(
        building.x,
        BOREALIS_GROUND_HEIGHT + 2.7,
        building.z + frontDirection * (building.depth * 0.5 + 0.22),
      );
      sprite.scale.set(5.4, 1.02, 1);
      sprite.name = `${building.displayName} readable sign`;
      root.add(sprite);
      disposables.push(texture, material);
      labels += 1;
    }
    return labels;
  }

  private addBuildings(root: Group, buildings: readonly BorealisTownBuildingLot[]): number {
    const walls: TownInstance[] = [];
    const roofs: TownInstance[] = [];
    const roofSnow: TownInstance[] = [];
    const foundations: TownInstance[] = [];
    const windows: TownInstance[] = [];
    const doors: TownInstance[] = [];
    const signs: TownInstance[] = [];
    const details: TownInstance[] = [];
    for (const building of buildings) {
      const height = building.storeys * 2.45 + 0.45;
      foundations.push({
        x: building.x,
        y: BOREALIS_GROUND_HEIGHT + 0.12,
        z: building.z,
        scaleX: building.width + 0.5,
        scaleY: 0.24,
        scaleZ: building.depth + 0.5,
      });
      walls.push({
        x: building.x,
        y: BOREALIS_GROUND_HEIGHT + height * 0.5 + 0.18,
        z: building.z,
        scaleX: building.width,
        scaleY: height,
        scaleZ: building.depth,
        color: building.color,
      });
      const roofY = BOREALIS_GROUND_HEIGHT + height + 0.9;
      roofs.push({
        x: building.x,
        y: roofY,
        z: building.z,
        scaleX: building.width * 0.77,
        scaleY: 1.75,
        scaleZ: building.depth * 0.77,
        rotationY: Math.PI * 0.25,
      });
      roofSnow.push({
        x: building.x,
        y: roofY + 0.15,
        z: building.z,
        scaleX: building.width * 0.7,
        scaleY: 1.52,
        scaleZ: building.depth * 0.7,
        rotationY: Math.PI * 0.25,
      });
      const frontZ = building.front === 'NORTH'
        ? building.z + building.depth * 0.5 + 0.055
        : building.z - building.depth * 0.5 - 0.055;
      const frontRotation = building.front === 'NORTH' ? 0 : Math.PI;
      doors.push({
        x: building.x,
        y: BOREALIS_GROUND_HEIGHT + 1.05,
        z: frontZ,
        scaleX: 0.85,
        scaleY: 1.85,
        scaleZ: 0.12,
        rotationY: frontRotation,
      });
      for (const side of [-1, 1]) {
        windows.push({
          x: building.x + side * Math.min(2.1, building.width * 0.28),
          y: BOREALIS_GROUND_HEIGHT + 1.45,
          z: frontZ + (building.front === 'NORTH' ? 0.02 : -0.02),
          scaleX: 1.05,
          scaleY: 0.92,
          scaleZ: 0.1,
          rotationY: frontRotation,
        });
        if (building.storeys > 1) {
          windows.push({
            x: building.x + side * Math.min(2.1, building.width * 0.28),
            y: BOREALIS_GROUND_HEIGHT + 3.55,
            z: frontZ + (building.front === 'NORTH' ? 0.02 : -0.02),
            scaleX: 1,
            scaleY: 0.86,
            scaleZ: 0.1,
            rotationY: frontRotation,
          });
        }
      }
      if (building.service !== 'RESIDENCE' && building.service !== 'WAREHOUSE') {
        signs.push({
          x: building.x,
          y: BOREALIS_GROUND_HEIGHT + 2.45,
          z: frontZ + (building.front === 'NORTH' ? 0.08 : -0.08),
          scaleX: Math.min(3.2, building.width * 0.52),
          scaleY: 0.48,
          scaleZ: 0.16,
          rotationY: frontRotation,
        });
      }
      if (building.service === 'RADIO_TELEGRAPH') {
        details.push({
          x: building.x,
          y: roofY + 2.4,
          z: building.z,
          scaleX: 0.09,
          scaleY: 4.4,
          scaleZ: 0.09,
        });
      } else if (building.service === 'BAKERY_CAFE') {
        details.push({
          x: building.x - building.width * 0.27,
          y: roofY + 0.7,
          z: building.z,
          scaleX: 0.32,
          scaleY: 1.7,
          scaleZ: 0.32,
        });
      }
      const identity = new Group();
      identity.name = `${building.displayName} (${building.service})`;
      identity.position.set(building.x, BOREALIS_GROUND_HEIGHT, building.z);
      root.add(identity);
    }
    let draws = 0;
    draws += this.addInstances(root, 'Town foundations', this.wallGeometry, this.trimMaterial, foundations);
    draws += this.addInstances(root, 'Town walls', this.wallGeometry, this.wallMaterial, walls);
    draws += this.addInstances(root, 'Town roofs', this.roofGeometry, this.roofMaterial, roofs);
    draws += this.addInstances(root, 'Snow-covered town roofs', this.roofGeometry, this.snowMaterial, roofSnow);
    draws += this.addInstances(root, 'Town windows', this.wallGeometry, this.glassMaterial, windows);
    draws += this.addInstances(root, 'Town doors', this.wallGeometry, this.doorMaterial, doors);
    draws += this.addInstances(root, 'Town service signs', this.wallGeometry, this.signMaterial, signs);
    draws += this.addInstances(root, 'Town chimneys and radio masts', this.cylinderGeometry, this.metalMaterial, details);
    return draws;
  }

  private addTownLamps(
    root: Group,
    positions: readonly { x: number; z: number }[],
  ): number {
    const posts: TownInstance[] = [];
    const globes: TownInstance[] = [];
    positions.forEach((position) => {
      posts.push({
        x: position.x,
        y: BOREALIS_GROUND_HEIGHT + 1.45,
        z: position.z,
        scaleX: 0.075,
        scaleY: 2.9,
        scaleZ: 0.075,
      });
      globes.push({
        x: position.x,
        y: BOREALIS_GROUND_HEIGHT + 2.96,
        z: position.z,
        scaleX: 0.2,
        scaleY: 0.24,
        scaleZ: 0.2,
      });
    });
    return (
      this.addInstances(root, 'Town lamp posts', this.cylinderGeometry, this.metalMaterial, posts) +
      this.addInstances(root, 'Town lamp globes', this.globeGeometry, this.lampMaterial, globes)
    );
  }

  private addEmptyLots(
    root: Group,
    lots: readonly { x: number; z: number; width: number; depth: number }[],
  ): number {
    const trees: TownInstance[] = [];
    const trunks: TownInstance[] = [];
    const shrubs: TownInstance[] = [];
    const fences: TownInstance[] = [];
    for (const lot of lots) {
      for (let index = 0; index < 3; index += 1) {
        const offsetX = (index - 1) * Math.min(2.2, lot.width * 0.22);
        const offsetZ = index % 2 === 0 ? -lot.depth * 0.16 : lot.depth * 0.18;
        trunks.push({
          x: lot.x + offsetX,
          y: BOREALIS_GROUND_HEIGHT + 0.65,
          z: lot.z + offsetZ,
          scaleX: 0.15,
          scaleY: 1.3,
          scaleZ: 0.15,
        });
        trees.push({
          x: lot.x + offsetX,
          y: BOREALIS_GROUND_HEIGHT + 1.65,
          z: lot.z + offsetZ,
          scaleX: 0.72,
          scaleY: 1.7,
          scaleZ: 0.72,
        });
        shrubs.push({
          x: lot.x + offsetX * 0.65,
          y: BOREALIS_GROUND_HEIGHT + 0.38,
          z: lot.z - offsetZ * 1.5,
          scaleX: 0.42,
          scaleY: 0.72,
          scaleZ: 0.42,
        });
      }
      for (const side of [-1, 1]) {
        fences.push({
          x: lot.x,
          y: BOREALIS_GROUND_HEIGHT + 0.52,
          z: lot.z + side * lot.depth * 0.5,
          scaleX: lot.width,
          scaleY: 0.12,
          scaleZ: 0.1,
        });
        fences.push({
          x: lot.x + side * lot.width * 0.5,
          y: BOREALIS_GROUND_HEIGHT + 0.52,
          z: lot.z,
          scaleX: 0.1,
          scaleY: 0.12,
          scaleZ: lot.depth,
        });
      }
    }
    return (
      this.addInstances(root, 'Empty lot tree trunks', this.cylinderGeometry, this.doorMaterial, trunks) +
      this.addInstances(root, 'Empty lot spruce trees', this.treeGeometry, this.foliageMaterial, trees) +
      this.addInstances(root, 'Empty lot shrubs', this.globeGeometry, this.foliageMaterial, shrubs) +
      this.addInstances(root, 'Empty lot fences', this.wallGeometry, this.doorMaterial, fences)
    );
  }

  private addFleetYard(root: Group): number {
    const yard = BOREALIS_FLEET_YARD;
    const identity = new Group();
    identity.name = 'Borealis harbor-side municipal fleet yard';
    identity.position.set(yard.centerX, BOREALIS_GROUND_HEIGHT, yard.centerZ);
    root.add(identity);
    const ground: TownInstance[] = [{
      x: yard.centerX,
      y: BOREALIS_GROUND_HEIGHT + 0.025,
      z: yard.centerZ,
      scaleX: yard.halfWidth * 2,
      scaleY: 0.08,
      scaleZ: yard.halfDepth * 2,
    }];
    const southFenceSegmentWidth = (yard.halfWidth * 2 - 5.2) * 0.5;
    const fences: TownInstance[] = [
      {
        // Split the harbor-facing fence around the north/south street so the
        // yard has an obvious drivable entrance from Borealis harbor.
        x: yard.centerX - (southFenceSegmentWidth + 5.2) * 0.5,
        y: BOREALIS_GROUND_HEIGHT + 0.48,
        z: yard.centerZ - yard.halfDepth,
        scaleX: southFenceSegmentWidth,
        scaleY: 0.85,
        scaleZ: 0.1,
      },
      {
        x: yard.centerX + (southFenceSegmentWidth + 5.2) * 0.5,
        y: BOREALIS_GROUND_HEIGHT + 0.48,
        z: yard.centerZ - yard.halfDepth,
        scaleX: southFenceSegmentWidth,
        scaleY: 0.85,
        scaleZ: 0.1,
      },
      {
        x: yard.centerX,
        y: BOREALIS_GROUND_HEIGHT + 0.48,
        z: yard.centerZ + yard.halfDepth,
        scaleX: yard.halfWidth * 2,
        scaleY: 0.85,
        scaleZ: 0.1,
      },
      {
        x: yard.centerX - yard.halfWidth,
        y: BOREALIS_GROUND_HEIGHT + 0.48,
        z: yard.centerZ,
        scaleX: 0.1,
        scaleY: 0.85,
        scaleZ: yard.halfDepth * 2,
      },
    ];
    const markings: TownInstance[] = [];
    for (const offsetX of [-7.2, -2.65, 2.85, 7.2]) {
      markings.push({
        x: yard.centerX + offsetX,
        y: BOREALIS_GROUND_HEIGHT + 0.075,
        z: yard.centerZ - 7,
        scaleX: 0.08,
        scaleY: 0.025,
        scaleZ: 5.2,
      });
    }
    // A simple H remains visible once the helipad is cleared of snow.
    markings.push(
      {
        x: yard.centerX - 1.3,
        y: BOREALIS_GROUND_HEIGHT + 0.075,
        z: yard.centerZ + 6,
        scaleX: 0.16,
        scaleY: 0.025,
        scaleZ: 3.4,
      },
      {
        x: yard.centerX + 1.3,
        y: BOREALIS_GROUND_HEIGHT + 0.075,
        z: yard.centerZ + 6,
        scaleX: 0.16,
        scaleY: 0.025,
        scaleZ: 3.4,
      },
      {
        x: yard.centerX,
        y: BOREALIS_GROUND_HEIGHT + 0.075,
        z: yard.centerZ + 6,
        scaleX: 2.7,
        scaleY: 0.025,
        scaleZ: 0.16,
      },
    );
    return (
      this.addInstances(root, 'Municipal fleet yard hardstand', this.wallGeometry, this.yardMaterial, ground) +
      this.addInstances(root, 'Municipal fleet yard fence', this.wallGeometry, this.metalMaterial, fences) +
      this.addInstances(root, 'Municipal fleet parking markings', this.wallGeometry, this.trimMaterial, markings)
    );
  }

  private addInstances(
    root: Group,
    name: string,
    geometry: BufferGeometry,
    material: MeshStandardMaterial,
    instances: readonly TownInstance[],
  ): number {
    if (instances.length === 0) return 0;
    const mesh = new InstancedMesh(geometry, material, instances.length);
    mesh.name = name;
    instances.forEach((instance, index) => {
      this.transform.position.set(instance.x, instance.y, instance.z);
      this.transform.rotation.set(0, instance.rotationY ?? 0, 0);
      this.transform.scale.set(instance.scaleX, instance.scaleY, instance.scaleZ);
      this.transform.updateMatrix();
      mesh.setMatrixAt(index, this.transform.matrix);
      if (instance.color !== undefined) {
        mesh.setColorAt(index, new Color(instance.color));
      }
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    root.add(mesh);
    return 1;
  }

  private intersectsBuilding(x: number, z: number, radius: number): boolean {
    return (
      BOREALIS_TOWN_BUILDINGS.some(
        (building) =>
          Math.abs(x - building.x) < building.width * 0.5 + radius &&
          Math.abs(z - building.z) < building.depth * 0.5 + radius,
      ) ||
      BOREALIS_TOWN_EMPTY_LOTS.some(
        (lot) =>
          Math.abs(x - lot.x) < lot.width * 0.5 + radius &&
          Math.abs(z - lot.z) < lot.depth * 0.5 + radius,
      )
    );
  }

  private applyLightState(): void {
    const strength = clamp((this.night - 0.16) / 0.7, 0, 1);
    this.lampMaterial.emissiveIntensity = 0.08 + strength * 1.5;
    for (const light of this.lightPool) {
      light.visible = light.userData.assigned === true && strength > 0.01;
      light.intensity = strength * 2.4;
    }
  }

  private geometry<T extends BufferGeometry>(geometry: T): T {
    this.geometries.add(geometry);
    return geometry;
  }

  private material(color: number, roughness: number, metalness: number): MeshStandardMaterial {
    const material = new MeshStandardMaterial({ color, roughness, metalness });
    this.materials.add(material);
    return material;
  }
}
