import { clamp } from '../utils/math';

export type AmbientEventCategory =
  | 'ice-groan'
  | 'distant-swell'
  | 'wind-gust'
  | 'buoy-surge'
  | 'restored-traffic';

export interface AmbientEventContext {
  running: boolean;
  observable: boolean;
  vesselMoving: boolean;
  activeEffectCount: number;
  floeCount: number;
  maximumFloePressure: number;
  waveScale: number;
  swellStrength: number;
  weatherPhase: string;
  snowIntensity: number;
  fogDensity: number;
  windMultiplier: number;
  night: number;
  cloudCover: number;
  recoveryActive: boolean;
  serviceCraftAvailable: boolean;
}

export interface AmbientEvent {
  id: number;
  category: AmbientEventCategory;
  strength: number;
  duration: number;
}

export interface AmbientEventHistoryEntry {
  category: AmbientEventCategory;
  startedAt: number;
  strength: number;
}

export interface AmbientEventDirectorDebugState {
  enabled: boolean;
  eventBudget: number;
  activeEvents: number;
  cooldownRemaining: number;
  calmDuration: number;
  eligibleCandidates: readonly AmbientEventCategory[];
  history: readonly AmbientEventHistoryEntry[];
  forcedCategory?: AmbientEventCategory;
}

interface EventCandidate {
  category: AmbientEventCategory;
  weight: number;
  strength: number;
  duration: number;
}

interface ActiveEvent {
  id: number;
  remaining: number;
}

const EVENT_ORDER: readonly AmbientEventCategory[] = [
  'ice-groan',
  'distant-swell',
  'wind-gust',
  'buoy-surge',
  'restored-traffic',
];
const MAX_HISTORY = 10;
const DEFAULT_MINIMUM_QUIET_SECONDS = 14;

export class AmbientEventDirector {
  private readonly activeEvents: ActiveEvent[] = [];
  private readonly history: AmbientEventHistoryEntry[] = [];
  private readonly minimumQuietSeconds: number;
  private eligibleCandidates: AmbientEventCategory[] = [];
  private enabled = true;
  private eventBudget = 1;
  private cooldownRemaining: number;
  private calmDuration = 0;
  private elapsedSeconds = 0;
  private nextEventId = 1;
  private randomState: number;
  private lastCategory?: AmbientEventCategory;
  private forcedCategory?: AmbientEventCategory;

  public constructor(
    seed = 0x1cea,
    minimumQuietSeconds = DEFAULT_MINIMUM_QUIET_SECONDS,
  ) {
    this.randomState = seed >>> 0 || 1;
    this.minimumQuietSeconds = Math.max(0, minimumQuietSeconds);
    this.cooldownRemaining = this.minimumQuietSeconds;
  }

  public update(
    deltaSeconds: number,
    context: Readonly<AmbientEventContext>,
  ): AmbientEvent[] {
    const delta = clamp(deltaSeconds, 0, 1);
    this.elapsedSeconds += delta;
    this.updateActiveEvents(delta);
    this.cooldownRemaining = Math.max(
      0,
      this.cooldownRemaining - delta,
    );

    const candidates = this.collectCandidates(context);
    this.eligibleCandidates = candidates.map(
      (candidate) => candidate.category,
    );
    if (
      !this.enabled ||
      !context.running ||
      !context.observable
    ) {
      return [];
    }

    this.calmDuration += delta;
    const occupiedSlots =
      this.activeEvents.length +
      Math.max(0, Math.floor(context.activeEffectCount));
    if (
      occupiedSlots >= this.eventBudget ||
      this.cooldownRemaining > 0 ||
      this.calmDuration < this.minimumQuietSeconds ||
      candidates.length === 0
    ) {
      return [];
    }

    const selected = this.selectCandidate(candidates);
    if (!selected) return [];
    const event: AmbientEvent = {
      id: this.nextEventId++,
      category: selected.category,
      strength: selected.strength,
      duration: selected.duration,
    };
    this.activeEvents.push({
      id: event.id,
      remaining: event.duration,
    });
    this.history.unshift({
      category: event.category,
      startedAt: this.elapsedSeconds,
      strength: event.strength,
    });
    this.history.length = Math.min(this.history.length, MAX_HISTORY);
    this.lastCategory = event.category;
    this.forcedCategory = undefined;
    this.calmDuration = 0;
    this.cooldownRemaining = this.nextCooldown(event.category);
    return [event];
  }

  public toggleEnabled(): boolean {
    this.enabled = !this.enabled;
    return this.enabled;
  }

  public cycleEventBudget(): number {
    this.eventBudget = this.eventBudget >= 2
      ? 0
      : this.eventBudget + 1;
    return this.eventBudget;
  }

  public forceNextEvent(
    category?: AmbientEventCategory,
  ): AmbientEventCategory {
    const currentIndex = this.forcedCategory
      ? EVENT_ORDER.indexOf(this.forcedCategory)
      : -1;
    const requested =
      category ??
      EVENT_ORDER[(currentIndex + 1) % EVENT_ORDER.length] ??
      'ice-groan';
    this.forcedCategory = requested;
    this.cooldownRemaining = 0;
    this.calmDuration = this.minimumQuietSeconds;
    return requested;
  }

  public getDebugState(): AmbientEventDirectorDebugState {
    return {
      enabled: this.enabled,
      eventBudget: this.eventBudget,
      activeEvents: this.activeEvents.length,
      cooldownRemaining: this.cooldownRemaining,
      calmDuration: this.calmDuration,
      eligibleCandidates: [...this.eligibleCandidates],
      history: this.history.map((entry) => ({ ...entry })),
      forcedCategory: this.forcedCategory,
    };
  }

  private collectCandidates(
    context: Readonly<AmbientEventContext>,
  ): EventCandidate[] {
    const candidates: EventCandidate[] = [];
    const pressure = clamp(context.maximumFloePressure, 0, 1);
    if (
      context.floeCount > 0 &&
      (pressure >= 0.08 || context.vesselMoving)
    ) {
      candidates.push({
        category: 'ice-groan',
        weight: 0.8 + pressure * 2.4,
        strength: clamp(0.28 + pressure * 0.72, 0.28, 1),
        duration: 2.4,
      });
    }

    const seaEnergy = context.waveScale * (0.5 + context.swellStrength);
    if (seaEnergy >= 0.48) {
      candidates.push({
        category: 'distant-swell',
        weight: 0.75 + seaEnergy * 0.72,
        strength: clamp(0.28 + seaEnergy * 0.34, 0.35, 0.82),
        duration: 9,
      });
    }

    const weatherActive =
      context.weatherPhase === 'transition' ||
      context.weatherPhase === 'active';
    const windEnergy = Math.max(
      context.snowIntensity,
      context.fogDensity * 28,
      (context.windMultiplier - 0.84) / 0.7,
    );
    if (weatherActive && windEnergy >= 0.2) {
      candidates.push({
        category: 'wind-gust',
        weight: 0.64 + windEnergy,
        strength: clamp(0.32 + windEnergy * 0.48, 0.32, 0.9),
        duration: 6,
      });
    }

    if (context.recoveryActive && seaEnergy >= 0.42) {
      candidates.push({
        category: 'buoy-surge',
        weight: 0.42 + seaEnergy * 0.35,
        strength: clamp(0.3 + seaEnergy * 0.32, 0.34, 0.78),
        duration: 7,
      });
    }

    if (
      context.recoveryActive &&
      context.serviceCraftAvailable &&
      context.fogDensity < 0.024 &&
      context.windMultiplier < 1.38
    ) {
      candidates.push({
        category: 'restored-traffic',
        weight: 0.38 + context.night * 0.08,
        strength: 0.62,
        duration: 44,
      });
    }
    return candidates;
  }

  private selectCandidate(
    candidates: readonly EventCandidate[],
  ): EventCandidate | undefined {
    if (this.forcedCategory) {
      return candidates.find(
        (candidate) => candidate.category === this.forcedCategory,
      );
    }

    let totalWeight = 0;
    for (const candidate of candidates) {
      totalWeight +=
        candidate.weight *
        (candidate.category === this.lastCategory ? 0.18 : 1);
    }
    let cursor = this.random() * totalWeight;
    for (const candidate of candidates) {
      cursor -=
        candidate.weight *
        (candidate.category === this.lastCategory ? 0.18 : 1);
      if (cursor <= 0) return candidate;
    }
    return candidates[candidates.length - 1];
  }

  private updateActiveEvents(deltaSeconds: number): void {
    for (let index = this.activeEvents.length - 1; index >= 0; index -= 1) {
      const event = this.activeEvents[index];
      if (!event) continue;
      event.remaining -= deltaSeconds;
      if (event.remaining <= 0) this.activeEvents.splice(index, 1);
    }
  }

  private nextCooldown(category: AmbientEventCategory): number {
    const base = category === 'restored-traffic' ? 54 : 30;
    const variance = category === 'restored-traffic' ? 28 : 22;
    return base + this.random() * variance;
  }

  private random(): number {
    this.randomState =
      (Math.imul(this.randomState, 1664525) + 1013904223) >>> 0;
    return this.randomState / 0x100000000;
  }
}
