export const CONSTRUCTION_GRID_METRES = 0.25;
export const CONSTRUCTION_BLUEPRINT_VERSION = 1 as const;

export type ConstructionModuleCategory =
  | 'hull-foundation'
  | 'structure'
  | 'foundation'
  | 'hull'
  | 'deck'
  | 'superstructure'
  | 'wall'
  | 'roof'
  | 'machinery'
  | 'utility'
  | 'attachment';

export type ConstructionBlueprintKind =
  | 'vessel'
  | 'fishing-hut'
  | 'resource-platform'
  | 'harbor-facility';

export type ConstructionMaterialId =
  | 'arctic-white'
  | 'ice-blue'
  | 'signal-orange'
  | 'hull-red'
  | 'charcoal';

export type ConstructionSurfaceId =
  | 'painted-steel'
  | 'galvanized-steel'
  | 'weathered-timber'
  | 'marine-plywood'
  | 'industrial-concrete'
  | 'rubber';

export type ConstructionDecalId =
  | 'safety-stripe'
  | 'vessel-number'
  | 'company-mark';

export interface ConstructionDecalLayer {
  id: string;
  decalId: ConstructionDecalId;
  slotId: string;
  color: string;
  rotationDegrees: number;
  scale: number;
}

export interface ConstructionGridPoint {
  x: number;
  y: number;
  z: number;
}

export interface ConstructionDirection {
  x: number;
  y: number;
  z: number;
}

export interface ConstructionSurfaceMount {
  kind: 'surface';
  hostPlacementId: string;
  normal: ConstructionDirection;
}

export interface ConstructionSocketConnection {
  hostPlacementId: string;
  hostSocketId: string;
  sourceSocketId: string;
}

export interface ConstructionGridMount {
  kind: 'grid';
  connection?: ConstructionSocketConnection;
}

export type ConstructionMount =
  | ConstructionGridMount
  | ConstructionSurfaceMount;

export type ConstructionCurveProfile = 'arc' | 'lens';

export interface ConstructionShapeParameters {
  profile: ConstructionCurveProfile;
  horizontalArcDegrees: number;
  verticalArcDegrees: number;
}

export interface ConstructionMachineState {
  enabled: boolean;
  control: number;
}

export interface ConstructionPlacement {
  id: string;
  moduleId: string;
  position: ConstructionGridPoint;
  yawDegrees: number;
  pitchDegrees: number;
  rollDegrees: number;
  flipped: boolean;
  materialId: ConstructionMaterialId;
  surfaceId: ConstructionSurfaceId;
  shape?: ConstructionShapeParameters;
  decals?: ConstructionDecalLayer[];
  machineState?: ConstructionMachineState;
  mount: ConstructionMount;
}

export interface ConstructionPalette {
  'arctic-white': string;
  'ice-blue': string;
  'signal-orange': string;
  'hull-red': string;
  charcoal: string;
}

export interface ConstructionBlueprint {
  version: typeof CONSTRUCTION_BLUEPRINT_VERSION;
  id: string;
  name: string;
  kind: ConstructionBlueprintKind;
  revision: number;
  gridSizeMetres: number;
  createdAt: string;
  updatedAt: string;
  palette: ConstructionPalette;
  placements: ConstructionPlacement[];
}

export const DEFAULT_CONSTRUCTION_PALETTE: ConstructionPalette = {
  'arctic-white': '#dcebee',
  'ice-blue': '#4e9dae',
  'signal-orange': '#ef7d35',
  'hull-red': '#923f3f',
  charcoal: '#26363b',
};

const clonePlacement = (
  placement: Readonly<ConstructionPlacement>,
): ConstructionPlacement => ({
  ...placement,
  position: { ...placement.position },
  shape: placement.shape ? { ...placement.shape } : undefined,
  decals: placement.decals?.map((decal) => ({ ...decal })),
  machineState: placement.machineState
    ? { ...placement.machineState }
    : undefined,
  mount:
    placement.mount.kind === 'surface'
      ? {
          ...placement.mount,
          normal: { ...placement.mount.normal },
        }
      : {
          kind: 'grid',
          connection: placement.mount.connection
            ? { ...placement.mount.connection }
            : undefined,
        },
});

export const cloneConstructionBlueprint = (
  blueprint: Readonly<ConstructionBlueprint>,
): ConstructionBlueprint => ({
  ...blueprint,
  palette: { ...blueprint.palette },
  placements: blueprint.placements.map(clonePlacement),
});

const nextBlueprintId = (kind: ConstructionBlueprintKind): string =>
  `${kind}-${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 8)}`;

export const createConstructionBlueprint = (
  name = 'Prototype icebreaker',
  now = new Date(),
  kind: ConstructionBlueprintKind = 'vessel',
): ConstructionBlueprint => {
  const timestamp = now.toISOString();
  return {
    version: CONSTRUCTION_BLUEPRINT_VERSION,
    id: nextBlueprintId(kind),
    name,
    kind,
    revision: 0,
    gridSizeMetres: CONSTRUCTION_GRID_METRES,
    createdAt: timestamp,
    updatedAt: timestamp,
    palette: { ...DEFAULT_CONSTRUCTION_PALETTE },
    placements: [],
  };
};

const isFiniteCoordinate = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value);

const isGridPoint = (value: unknown): value is ConstructionGridPoint => {
  if (!value || typeof value !== 'object') return false;
  const point = value as Partial<ConstructionGridPoint>;
  return (
    isFiniteCoordinate(point.x) &&
    isFiniteCoordinate(point.y) &&
    isFiniteCoordinate(point.z)
  );
};

const isDirection = (value: unknown): value is ConstructionDirection => {
  if (!value || typeof value !== 'object') return false;
  const direction = value as Partial<ConstructionDirection>;
  return (
    typeof direction.x === 'number' &&
    Number.isFinite(direction.x) &&
    typeof direction.y === 'number' &&
    Number.isFinite(direction.y) &&
    typeof direction.z === 'number' &&
    Number.isFinite(direction.z)
  );
};

const isMaterialId = (value: unknown): value is ConstructionMaterialId =>
  value === 'arctic-white' ||
  value === 'ice-blue' ||
  value === 'signal-orange' ||
  value === 'hull-red' ||
  value === 'charcoal';

const isSurfaceId = (value: unknown): value is ConstructionSurfaceId =>
  value === 'painted-steel' ||
  value === 'galvanized-steel' ||
  value === 'weathered-timber' ||
  value === 'marine-plywood' ||
  value === 'industrial-concrete' ||
  value === 'rubber';

const isDecalId = (value: unknown): value is ConstructionDecalId =>
  value === 'safety-stripe' ||
  value === 'vessel-number' ||
  value === 'company-mark';

const sanitizeDecals = (value: unknown): ConstructionDecalLayer[] | undefined => {
  if (value === undefined) return undefined;
  if (!Array.isArray(value) || value.length > 16) return undefined;
  const decals: ConstructionDecalLayer[] = [];
  for (const raw of value) {
    if (!raw || typeof raw !== 'object') return undefined;
    const decal = raw as Partial<ConstructionDecalLayer>;
    if (
      typeof decal.id !== 'string' ||
      !isDecalId(decal.decalId) ||
      typeof decal.slotId !== 'string' ||
      typeof decal.color !== 'string' ||
      !/^(#[0-9a-f]{6}|#[0-9a-f]{3})$/i.test(decal.color) ||
      typeof decal.rotationDegrees !== 'number' ||
      !Number.isFinite(decal.rotationDegrees) ||
      typeof decal.scale !== 'number' ||
      !Number.isFinite(decal.scale)
    ) {
      return undefined;
    }
    decals.push({
      id: decal.id,
      decalId: decal.decalId,
      slotId: decal.slotId.slice(0, 64),
      color: decal.color,
      rotationDegrees: decal.rotationDegrees,
      scale: Math.max(0.1, Math.min(4, decal.scale)),
    });
  }
  return decals;
};

const isBlueprintKind = (
  value: unknown,
): value is ConstructionBlueprintKind =>
  value === 'vessel' ||
  value === 'fishing-hut' ||
  value === 'resource-platform' ||
  value === 'harbor-facility';

const sanitizeShape = (
  value: unknown,
): ConstructionShapeParameters | undefined => {
  if (value === undefined) return undefined;
  if (!value || typeof value !== 'object') return undefined;
  const shape = value as Partial<ConstructionShapeParameters>;
  if (
    (shape.profile !== 'arc' && shape.profile !== 'lens') ||
    typeof shape.horizontalArcDegrees !== 'number' ||
    !Number.isFinite(shape.horizontalArcDegrees) ||
    typeof shape.verticalArcDegrees !== 'number' ||
    !Number.isFinite(shape.verticalArcDegrees)
  ) {
    return undefined;
  }
  return {
    profile: shape.profile,
    horizontalArcDegrees: Math.max(
      -60,
      Math.min(60, shape.horizontalArcDegrees),
    ),
    verticalArcDegrees: Math.max(
      -60,
      Math.min(60, shape.verticalArcDegrees),
    ),
  };
};

const sanitizeMachineState = (
  value: unknown,
): ConstructionMachineState | undefined => {
  if (value === undefined) return undefined;
  if (!value || typeof value !== 'object') return undefined;
  const state = value as Partial<ConstructionMachineState>;
  if (
    typeof state.enabled !== 'boolean' ||
    typeof state.control !== 'number' ||
    !Number.isFinite(state.control)
  ) {
    return undefined;
  }
  return {
    enabled: state.enabled,
    control: Math.max(0, Math.min(1, state.control)),
  };
};

export const sanitizeConstructionBlueprint = (
  value: unknown,
): ConstructionBlueprint | undefined => {
  if (!value || typeof value !== 'object') return undefined;
  const candidate = value as Partial<ConstructionBlueprint>;
  if (
    candidate.version !== CONSTRUCTION_BLUEPRINT_VERSION ||
    typeof candidate.id !== 'string' ||
    typeof candidate.name !== 'string' ||
    !Array.isArray(candidate.placements)
  ) {
    return undefined;
  }

  const ids = new Set<string>();
  const placements: ConstructionPlacement[] = [];
  for (const raw of candidate.placements) {
    if (!raw || typeof raw !== 'object') return undefined;
    const placement = raw as Partial<ConstructionPlacement>;
    if (
      typeof placement.id !== 'string' ||
      placement.id.length === 0 ||
      ids.has(placement.id) ||
      typeof placement.moduleId !== 'string' ||
      !isGridPoint(placement.position) ||
      typeof placement.yawDegrees !== 'number' ||
      !Number.isFinite(placement.yawDegrees) ||
      typeof placement.pitchDegrees !== 'number' ||
      !Number.isFinite(placement.pitchDegrees) ||
      typeof placement.rollDegrees !== 'number' ||
      !Number.isFinite(placement.rollDegrees) ||
      typeof placement.flipped !== 'boolean' ||
      !isMaterialId(placement.materialId) ||
      !placement.mount ||
      typeof placement.mount !== 'object'
    ) {
      return undefined;
    }
    const rawConnection =
      placement.mount.kind === 'grid'
        ? (placement.mount.connection as unknown)
        : undefined;
    const connectionValid =
      rawConnection === undefined ||
      (rawConnection !== null &&
        typeof rawConnection === 'object' &&
        typeof (rawConnection as ConstructionSocketConnection)
          .hostPlacementId === 'string' &&
        typeof (rawConnection as ConstructionSocketConnection)
          .hostSocketId === 'string' &&
        typeof (rawConnection as ConstructionSocketConnection)
          .sourceSocketId === 'string');
    const gridMountValid =
      placement.mount.kind === 'grid' && connectionValid;
    if (
      !gridMountValid &&
      !(
        placement.mount.kind === 'surface' &&
        typeof placement.mount.hostPlacementId === 'string' &&
        isDirection(placement.mount.normal)
      )
    ) {
      return undefined;
    }
    const shape = sanitizeShape(placement.shape);
    const decals = sanitizeDecals(placement.decals);
    const machineState = sanitizeMachineState(placement.machineState);
    if (placement.shape !== undefined && !shape) return undefined;
    if (placement.decals !== undefined && !decals) return undefined;
    if (placement.machineState !== undefined && !machineState) return undefined;
    ids.add(placement.id);
    placements.push(
      clonePlacement({
        ...(placement as ConstructionPlacement),
        // Legacy Phase 1 blueprints stored only a paint slot.
        surfaceId: isSurfaceId(placement.surfaceId)
          ? placement.surfaceId
          : 'painted-steel',
        shape,
        decals,
        machineState,
      }),
    );
  }

  const timestamp = new Date().toISOString();
  const candidatePalette = candidate.palette as
    | Partial<ConstructionPalette>
    | undefined;
  const palette = { ...DEFAULT_CONSTRUCTION_PALETTE };
  for (const materialId of Object.keys(palette) as Array<
    keyof ConstructionPalette
  >) {
    const color = candidatePalette?.[materialId];
    if (
      typeof color === 'string' &&
      /^(#[0-9a-f]{6}|#[0-9a-f]{3})$/i.test(color)
    ) {
      palette[materialId] = color;
    }
  }
  return {
    version: CONSTRUCTION_BLUEPRINT_VERSION,
    id: candidate.id,
    name: candidate.name.slice(0, 80) || 'Unnamed blueprint',
    // Blueprints saved before the general construction pass were all vessels.
    kind: isBlueprintKind(candidate.kind) ? candidate.kind : 'vessel',
    revision:
      typeof candidate.revision === 'number' &&
      Number.isFinite(candidate.revision)
        ? Math.max(0, Math.floor(candidate.revision))
        : 0,
    gridSizeMetres: CONSTRUCTION_GRID_METRES,
    createdAt:
      typeof candidate.createdAt === 'string'
        ? candidate.createdAt
        : timestamp,
    updatedAt:
      typeof candidate.updatedAt === 'string'
        ? candidate.updatedAt
        : timestamp,
    palette,
    placements,
  };
};

export const touchConstructionBlueprint = (
  blueprint: ConstructionBlueprint,
  now = new Date(),
): void => {
  blueprint.revision += 1;
  blueprint.updatedAt = now.toISOString();
};
