export type RuntimeTraceMode =
  | 'menu'
  | 'sea'
  | 'docked'
  | 'land'
  | 'construction';

export type RuntimeTraceValue = string | number | boolean | null;

export interface RuntimeTraceContext {
  mode: RuntimeTraceMode;
  worldTime: number;
  x: number;
  z: number;
  gpuMs?: number;
  drawCalls?: number;
  triangles?: number;
  activeSnowTiles?: number;
  pendingSnowTiles?: number;
  snowMeshUpdates?: number;
  snowUpdatedVertices?: number;
  parkInstancedProps?: number;
  parkDrawGroups?: number;
  parkCleanRatio?: number;
  townActiveChunks?: number;
  townVisibleBuildings?: number;
  townDrawGroups?: number;
  townActiveLights?: number;
  landProtectionFields?: number;
  landCargoMass?: number;
  landNpcPlowEnabled?: number;
  landNpcRouteProgress?: number;
  landFleetCargoMass?: number;
  landActiveMachineCode?: number;
  landHelicopterAltitude?: number;
  landTrailerAttached?: number;
  emergentRoads?: number;
  emergentNpcs?: number;
  emergentTravellingNpcs?: number;
  emergentStrandedNpcs?: number;
  emergentActiveIncidents?: number;
  emergentOpenServices?: number;
}

export interface RuntimeTraceRecord {
  sequence: number;
  observedAtMs: number;
  kind: 'heartbeat' | 'frame-spike' | 'event';
  name: string;
  mode: RuntimeTraceMode;
  worldTime: number;
  x: number;
  z: number;
  value?: number;
  cause?: string;
  phases?: Readonly<Record<string, number>>;
  data?: Readonly<Record<string, RuntimeTraceValue>>;
}

export interface RuntimeMetricSummary {
  count: number;
  averageMs: number;
  p95Ms: number;
  p99Ms: number;
  maximumMs: number;
}

export interface RuntimePerformanceSnapshot {
  capturedAtMs: number;
  elapsedSeconds: number;
  spikeCount: number;
  worstFrameMs: number;
  lastSpikeMs: number;
  lastSpikeCause: string;
  metrics: Readonly<Record<string, RuntimeMetricSummary>>;
  records: readonly RuntimeTraceRecord[];
  worstSpikes: readonly RuntimeTraceRecord[];
}

export interface RuntimePerformanceTraceStatus {
  records: number;
  spikeCount: number;
  worstFrameMs: number;
  lastSpikeMs: number;
  lastSpikeCause: string;
}

interface MutableMetric {
  samples: Float64Array;
  cursor: number;
  sampleCount: number;
  count: number;
  total: number;
  maximum: number;
}

const percentile = (sorted: readonly number[], ratio: number): number => {
  if (sorted.length === 0) return 0;
  return sorted[
    Math.min(sorted.length - 1, Math.ceil(sorted.length * ratio) - 1)
  ] ?? 0;
};

/**
 * A bounded, low-allocation runtime trace. Every frame contributes numeric
 * samples, while the timeline only allocates one heartbeat per second and
 * records whose frame interval crosses the spike threshold.
 */
export class RuntimePerformanceTrace {
  private readonly records: RuntimeTraceRecord[] = [];
  private readonly worstSpikes: RuntimeTraceRecord[] = [];
  private readonly metrics = new Map<string, MutableMetric>();
  private readonly currentPhases = new Map<string, number>();
  private sequence = 0;
  private startedAtMs = performance.now();
  private frameStartedAtMs = 0;
  private frameIntervalMs = 0;
  private heartbeatStartedAtMs = 0;
  private heartbeatFrameTotalMs = 0;
  private heartbeatMaximumFrameMs = 0;
  private heartbeatFrames = 0;
  private spikeCount = 0;
  private worstFrameMs = 0;
  private lastSpikeMs = 0;
  private lastSpikeCause = 'none';
  private warmupFramesRemaining: number;

  public constructor(
    private readonly spikeThresholdMs = 24,
    private readonly retentionMs = 600_000,
    private readonly maximumRecords = 4_096,
    private readonly sampleCapacity = 2_048,
    private readonly warmupFrameCount = 12,
    private readonly maximumWorstSpikes = 32,
  ) {
    this.warmupFramesRemaining = this.warmupFrameCount;
  }

  public beginFrame(
    frameIntervalMs: number,
    now = performance.now(),
  ): void {
    this.frameStartedAtMs = now;
    this.frameIntervalMs = Math.max(0, frameIntervalMs);
    for (const name of this.currentPhases.keys()) {
      this.currentPhases.set(name, 0);
    }
    this.sample('frame.interval', this.frameIntervalMs);
  }

  public start(now = performance.now()): number {
    return now;
  }

  public endPhase(
    name: string,
    startedAtMs: number,
    now = performance.now(),
  ): number {
    const duration = Math.max(0, now - startedAtMs);
    this.currentPhases.set(
      name,
      (this.currentPhases.get(name) ?? 0) + duration,
    );
    this.sample(name, duration);
    return duration;
  }

  public sample(name: string, milliseconds: number): void {
    if (!Number.isFinite(milliseconds) || milliseconds < 0) return;
    let metric = this.metrics.get(name);
    if (!metric) {
      metric = {
        samples: new Float64Array(this.sampleCapacity),
        cursor: 0,
        sampleCount: 0,
        count: 0,
        total: 0,
        maximum: 0,
      };
      this.metrics.set(name, metric);
    }
    metric.samples[metric.cursor] = milliseconds;
    metric.cursor = (metric.cursor + 1) % metric.samples.length;
    metric.sampleCount = Math.min(
      metric.samples.length,
      metric.sampleCount + 1,
    );
    metric.count += 1;
    metric.total += milliseconds;
    metric.maximum = Math.max(metric.maximum, milliseconds);
  }

  public endFrame(
    context: Readonly<RuntimeTraceContext>,
    now = performance.now(),
  ): void {
    const cpuMs = Math.max(0, now - this.frameStartedAtMs);
    const observedMs = Math.max(cpuMs, this.frameIntervalMs);
    this.sample('frame.cpu', cpuMs);
    this.heartbeatFrameTotalMs += observedMs;
    this.heartbeatMaximumFrameMs = Math.max(
      this.heartbeatMaximumFrameMs,
      observedMs,
    );
    this.heartbeatFrames += 1;
    if (this.heartbeatStartedAtMs <= 0) this.heartbeatStartedAtMs = now;

    const warmingUp = this.warmupFramesRemaining > 0;
    this.warmupFramesRemaining = Math.max(
      0,
      this.warmupFramesRemaining - 1,
    );
    if (!warmingUp && observedMs >= this.spikeThresholdMs) {
      let cause = 'unattributed-main-thread-work';
      let longestPhaseMs = 0;
      for (const [name, duration] of this.currentPhases) {
        if (duration <= longestPhaseMs) continue;
        longestPhaseMs = duration;
        cause = name;
      }
      if (this.frameIntervalMs > cpuMs + 4) {
        cause = 'browser-gpu-or-scheduling-gap';
      }
      this.spikeCount += 1;
      this.lastSpikeMs = observedMs;
      this.worstFrameMs = Math.max(this.worstFrameMs, observedMs);
      this.lastSpikeCause = cause;
      const spike = this.append({
        kind: 'frame-spike',
        name: 'frame-spike',
        context,
        observedAtMs: now,
        value: observedMs,
        cause,
        phases: Object.fromEntries(this.currentPhases),
        data: {
          cpuMs,
          frameIntervalMs: this.frameIntervalMs,
          longestPhaseMs,
          gpuMs: context.gpuMs ?? null,
          drawCalls: context.drawCalls ?? null,
          triangles: context.triangles ?? null,
          activeSnowTiles: context.activeSnowTiles ?? null,
          pendingSnowTiles: context.pendingSnowTiles ?? null,
          snowMeshUpdates: context.snowMeshUpdates ?? null,
          snowUpdatedVertices: context.snowUpdatedVertices ?? null,
          parkInstancedProps: context.parkInstancedProps ?? null,
          parkDrawGroups: context.parkDrawGroups ?? null,
          parkCleanRatio: context.parkCleanRatio ?? null,
          townActiveChunks: context.townActiveChunks ?? null,
          townVisibleBuildings: context.townVisibleBuildings ?? null,
          townDrawGroups: context.townDrawGroups ?? null,
          townActiveLights: context.townActiveLights ?? null,
          landProtectionFields: context.landProtectionFields ?? null,
          landCargoMass: context.landCargoMass ?? null,
          landNpcPlowEnabled: context.landNpcPlowEnabled ?? null,
          landNpcRouteProgress: context.landNpcRouteProgress ?? null,
          landFleetCargoMass: context.landFleetCargoMass ?? null,
          landActiveMachineCode: context.landActiveMachineCode ?? null,
          landHelicopterAltitude: context.landHelicopterAltitude ?? null,
          landTrailerAttached: context.landTrailerAttached ?? null,
          emergentRoads: context.emergentRoads ?? null,
          emergentNpcs: context.emergentNpcs ?? null,
          emergentTravellingNpcs: context.emergentTravellingNpcs ?? null,
          emergentStrandedNpcs: context.emergentStrandedNpcs ?? null,
          emergentActiveIncidents: context.emergentActiveIncidents ?? null,
          emergentOpenServices: context.emergentOpenServices ?? null,
        },
      });
      this.rememberWorstSpike(spike);
    }

    if (now - this.heartbeatStartedAtMs >= 1_000) {
      this.append({
        kind: 'heartbeat',
        name: 'performance-heartbeat',
        context,
        observedAtMs: now,
        value:
          this.heartbeatFrameTotalMs /
          Math.max(1, this.heartbeatFrames),
        data: {
          frames: this.heartbeatFrames,
          maximumFrameMs: this.heartbeatMaximumFrameMs,
          cpuMs,
          gpuMs: context.gpuMs ?? null,
          drawCalls: context.drawCalls ?? null,
          triangles: context.triangles ?? null,
          activeSnowTiles: context.activeSnowTiles ?? null,
          pendingSnowTiles: context.pendingSnowTiles ?? null,
          snowMeshUpdates: context.snowMeshUpdates ?? null,
          snowUpdatedVertices: context.snowUpdatedVertices ?? null,
          parkInstancedProps: context.parkInstancedProps ?? null,
          parkDrawGroups: context.parkDrawGroups ?? null,
          parkCleanRatio: context.parkCleanRatio ?? null,
          townActiveChunks: context.townActiveChunks ?? null,
          townVisibleBuildings: context.townVisibleBuildings ?? null,
          townDrawGroups: context.townDrawGroups ?? null,
          townActiveLights: context.townActiveLights ?? null,
          landProtectionFields: context.landProtectionFields ?? null,
          landCargoMass: context.landCargoMass ?? null,
          landNpcPlowEnabled: context.landNpcPlowEnabled ?? null,
          landNpcRouteProgress: context.landNpcRouteProgress ?? null,
          landFleetCargoMass: context.landFleetCargoMass ?? null,
          landActiveMachineCode: context.landActiveMachineCode ?? null,
          landHelicopterAltitude: context.landHelicopterAltitude ?? null,
          landTrailerAttached: context.landTrailerAttached ?? null,
          emergentRoads: context.emergentRoads ?? null,
          emergentNpcs: context.emergentNpcs ?? null,
          emergentTravellingNpcs: context.emergentTravellingNpcs ?? null,
          emergentStrandedNpcs: context.emergentStrandedNpcs ?? null,
          emergentActiveIncidents: context.emergentActiveIncidents ?? null,
          emergentOpenServices: context.emergentOpenServices ?? null,
        },
      });
      this.heartbeatStartedAtMs = now;
      this.heartbeatFrameTotalMs = 0;
      this.heartbeatMaximumFrameMs = 0;
      this.heartbeatFrames = 0;
    }
  }

  public event(
    name: string,
    context: Readonly<RuntimeTraceContext>,
    data?: Readonly<Record<string, RuntimeTraceValue>>,
    value?: number,
    now = performance.now(),
  ): void {
    this.append({
      kind: 'event',
      name,
      context,
      observedAtMs: now,
      value,
      data,
    });
  }

  public status(): RuntimePerformanceTraceStatus {
    return {
      records: this.records.length,
      spikeCount: this.spikeCount,
      worstFrameMs: this.worstFrameMs,
      lastSpikeMs: this.lastSpikeMs,
      lastSpikeCause: this.lastSpikeCause,
    };
  }

  public inspect(): readonly RuntimeTraceRecord[] {
    return Object.freeze([...this.records]);
  }

  public snapshot(now = performance.now()): RuntimePerformanceSnapshot {
    const metrics: Record<string, RuntimeMetricSummary> = {};
    for (const [name, metric] of this.metrics) {
      const values = Array.from(
        metric.samples.subarray(0, metric.sampleCount),
      ).sort((left, right) => left - right);
      metrics[name] = Object.freeze({
        count: metric.count,
        averageMs:
          metric.count > 0 ? metric.total / metric.count : 0,
        p95Ms: percentile(values, 0.95),
        p99Ms: percentile(values, 0.99),
        maximumMs: metric.maximum,
      });
    }
    return Object.freeze({
      capturedAtMs: now,
      elapsedSeconds: Math.max(0, (now - this.startedAtMs) / 1_000),
      spikeCount: this.spikeCount,
      worstFrameMs: this.worstFrameMs,
      lastSpikeMs: this.lastSpikeMs,
      lastSpikeCause: this.lastSpikeCause,
      metrics: Object.freeze(metrics),
      records: this.inspect(),
      worstSpikes: Object.freeze([...this.worstSpikes]),
    });
  }

  public clear(now = performance.now()): void {
    this.records.length = 0;
    this.worstSpikes.length = 0;
    this.metrics.clear();
    this.currentPhases.clear();
    this.startedAtMs = now;
    this.frameStartedAtMs = 0;
    this.heartbeatStartedAtMs = 0;
    this.heartbeatFrameTotalMs = 0;
    this.heartbeatMaximumFrameMs = 0;
    this.heartbeatFrames = 0;
    this.spikeCount = 0;
    this.worstFrameMs = 0;
    this.lastSpikeMs = 0;
    this.lastSpikeCause = 'none';
    this.warmupFramesRemaining = this.warmupFrameCount;
  }

  private append(input: {
    kind: RuntimeTraceRecord['kind'];
    name: string;
    context: Readonly<RuntimeTraceContext>;
    observedAtMs: number;
    value?: number;
    cause?: string;
    phases?: Readonly<Record<string, number>>;
    data?: Readonly<Record<string, RuntimeTraceValue>>;
  }): RuntimeTraceRecord {
    const record: RuntimeTraceRecord = Object.freeze({
      sequence: ++this.sequence,
      observedAtMs: input.observedAtMs,
      kind: input.kind,
      name: input.name,
      mode: input.context.mode,
      worldTime: input.context.worldTime,
      x: input.context.x,
      z: input.context.z,
      ...(input.value === undefined ? {} : { value: input.value }),
      ...(input.cause === undefined ? {} : { cause: input.cause }),
      ...(input.phases === undefined
        ? {}
        : { phases: Object.freeze({ ...input.phases }) }),
      ...(input.data === undefined
        ? {}
        : { data: Object.freeze({ ...input.data }) }),
    });
    this.records.push(record);
    const cutoff = input.observedAtMs - this.retentionMs;
    let remove = Math.max(0, this.records.length - this.maximumRecords);
    while (
      remove < this.records.length &&
      (this.records[remove]?.observedAtMs ?? 0) < cutoff
    ) {
      remove += 1;
    }
    if (remove > 0) this.records.splice(0, remove);
    return record;
  }

  private rememberWorstSpike(record: RuntimeTraceRecord): void {
    this.worstSpikes.push(record);
    this.worstSpikes.sort(
      (left, right) =>
        (right.value ?? 0) - (left.value ?? 0) ||
        right.sequence - left.sequence,
    );
    if (this.worstSpikes.length > this.maximumWorstSpikes) {
      this.worstSpikes.length = this.maximumWorstSpikes;
    }
  }
}

export interface RuntimePerformanceInspector {
  snapshot(): RuntimePerformanceSnapshot;
  trace(): readonly RuntimeTraceRecord[];
  clear(): void;
  download(): void;
}

export const installRuntimePerformanceInspector = (
  trace: RuntimePerformanceTrace,
): RuntimePerformanceInspector => {
  const inspector: RuntimePerformanceInspector = Object.freeze({
    snapshot: () => trace.snapshot(),
    trace: () => trace.inspect(),
    clear: () => trace.clear(),
    download: () => {
      const snapshot = trace.snapshot();
      const blob = new Blob([JSON.stringify(snapshot, null, 2)], {
        type: 'application/json',
      });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download =
        `iceway-performance-trace-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
      document.body.append(link);
      link.click();
      link.remove();
      window.setTimeout(() => URL.revokeObjectURL(link.href), 0);
    },
  });
  (
    window as Window & {
      __ICEWAY_PERF__?: RuntimePerformanceInspector;
    }
  ).__ICEWAY_PERF__ = inspector;
  return inspector;
};
