  private beginFreeSailing(): void {
    if (this.started) return;
    this.started = true;
    this.gameplay.setPauseReason('GAME_NOT_STARTED', false);
    this.gameplay.acceptMission(INTRO_MISSION_ID);
    this.playerController.setEnabled(true);
    this.world.setCameraMode('follow');
    this.ui.enterDrivingMode();
    void this.audio.unlock().then(() => {
      this.audio.click();
    });
    this.syncProgressionUI();
  }

  private openVesselBuilder(): void {
    if (this.vesselBuilder.isOpen() || this.landExpeditionActive)
      return;
    this.gameplay.setPauseReason('VESSEL_BUILDER', true);
    this.playerController.setEnabled(false);
    this.simulationAccumulator = 0;
    this.steeringIntent = 0;
    this.audio.setVesselEngine(false, 0, 0);
    this.world.setSphericalWorldContext('construction');
    this.vesselBuilder.open();
    void this.audio.unlock().then(() => this.audio.click());
  }

  private closeVesselBuilder(): void {
    this.gameplay.setPauseReason('VESSEL_BUILDER', false);
    this.simulationAccumulator = 0;
    this.clock.getDelta();
    this.playerController.setEnabled(
      this.started && !this.docking.isDocked(),
    );
    this.world.setSphericalWorldContext(
      this.docking.getState().availability === 'OUT_OF_RANGE'
        ? 'sea'
        : 'harbor',
    );
    this.audio.click();
  }

  private resetVessel(): void {
    if (!this.started || this.docking.isDocked()) return;
    this.vesselSimulation.resetToSafePosition();
    this.ui.toast('Returned to the last safe open water.');
    this.audio.click();
  }

  private toggleDocking(): void {
    if (!this.started) return;
    if (this.landExpeditionActive) {
      this.endLandExpedition();
      return;
    }
    if (this.docking.isDocked()) {
      this.dockUI.close();
      this.docking.undock();
      this.gameplay.setPauseReason('DOCK_MENU', false);
      this.playerController.setEnabled(true);
      this.simulationAccumulator = 0;
      this.syncDockingPresentation(
        this.docking.update(
          {
            x: this.vesselSimulation.state.worldPosition.x,
            y: 0,
            z: this.vesselSimulation.state.worldPosition.z,
          },
          this.vesselSimulation.state.speed,
        ),
      );
      this.audio.click();
      return;
    }

    const state = this.docking.update(
      {
        x: this.vesselSimulation.state.worldPosition.x,
        y: 0,
        z: this.vesselSimulation.state.worldPosition.z,
      },
      this.vesselSimulation.state.speed,
    );
    const result = this.docking.requestDock();
    if (!result.success) {
      if (result.reason === 'TOO_FAST') {
        this.ui.toast('Slow below 0.5 kn before mooring.');
      }
      return;
    }
    this.vesselSimulation.stopMotion();
    this.playerController.setEnabled(false);
    this.steeringIntent = 0;
    this.simulationAccumulator = 0;
    this.gameplay.setPauseReason('DOCK_MENU', true);
    this.syncDockingPresentation({
      ...state,
      availability: 'DOCKED',
      distance: 0,
    });
    this.persistWorldState();
    if (result.portId) this.openDockInterface(result.portId);
    this.audio.click();
  }

  private syncDockingPresentation(
    state: Readonly<DockingState>,
  ): void {
    this.world.setSphericalWorldContext(
      state.availability === 'OUT_OF_RANGE' ? 'sea' : 'harbor',
    );
    if (this.landExpeditionActive) {
      this.ui.setDockPrompt();
      this.world.setDockingState(state.portId, true);
      return;
    }
    if (!this.started || state.availability === 'OUT_OF_RANGE') {
      this.ui.setDockPrompt();
      this.world.setDockingState();
      return;
    }
    const portName = state.portName?.toUpperCase() ?? 'PORT';
    if (state.availability === 'DOCKED') {
      this.ui.setDockPrompt({
        label: `F  LEAVE ${portName}`,
        enabled: true,
        docked: true,
      });
      this.world.setDockingState(state.portId, true);
      return;
    }
    if (state.availability === 'TOO_FAST') {
      this.ui.setDockPrompt({
        label: `SLOW TO 0.5 KN · ${portName}`,
        enabled: false,
      });
      this.world.setDockingState(state.portId);
      return;
    }
    this.ui.setDockPrompt({
      label: `F  MOOR AT ${portName}`,
      enabled: true,
    });
    this.world.setDockingState(state.portId);
  }

  private restartFresh(): void {
    const confirmed = window.confirm(
      'Restart with a fresh world? Saved ice, routes and progress will be removed. Audio levels will be kept.',
    );
    if (!confirmed) return;
    if (!this.saveSystem.reset()) {
      this.ui.toast('The saved world could not be removed.');
      return;
    }
    this.freshRestartRequested = true;
    window.location.reload();
  }

  private toggleSeaPreview(): void {
    this.seaPreviewActive = !this.seaPreviewActive;
    this.iceGrid.setPresentationVisible(!this.seaPreviewActive);
    this.icebergSystem.setPresentationVisible(!this.seaPreviewActive);
    this.vesselPresenter.setIceEffectsVisible(!this.seaPreviewActive);
    this.world.setSeaPreview(this.seaPreviewActive);
    this.ui.setSeaPreviewActive(this.seaPreviewActive);
    this.ui.toast(
      this.seaPreviewActive
        ? 'Sea preview: ice presentation hidden.'
        : 'Sea preview: ice presentation restored.',
    );
    this.syncDebugSettings();
  }

