import type { BreakResult, IceWorld } from '../ice/IceWorldTypes';
import { EMPTY_BREAK_RESULT } from '../ice/IceWorldTypes';
import { calculateIceInteractionOutcome } from '../gameplay/simulation/VesselCapability';
import { clamp, damp, saturate } from '../utils/math';
import type { VesselObstacleWorld } from '../world/IcebergTypes';
import type { WorldPoint } from '../world/WorldPoint';
import { copyWorldPoint } from '../world/WorldPoint';
import type { VesselConfig } from './VesselConfig';
import { DEFAULT_VESSEL_CONFIG } from './VesselConfig';
import type { VesselControlCommand } from './VesselController';
import type {
  VesselProgressSaveData,
  VesselState,
} from './VesselState';

export interface VesselStepResult {
  breakResult: BreakResult;
  reset: boolean;
  impact: number;
  bowPosition: Readonly<WorldPoint>;
}

export interface VesselEnvironmentForces {
  currentX: number;
  currentZ: number;
  currentAngularVelocity: number;
  windX: number;
  windZ: number;
  windStrength: number;
}

export interface VesselGameplayCapabilities {
  breakPower: number;
  fuelEfficiency: number;
  hullDurability: number;
  agility: number;
  range: number;
  enginePower: number;
}

interface ObstacleCollisionResult {
  impact: number;
  resistance: number;
}

const approach = (current: number, target: number, maximumDelta: number): number => {
  if (current < target) return Math.min(target, current + maximumDelta);
  return Math.max(target, current - maximumDelta);
};

const normalizeAngle = (angle: number): number => {
  let normalized = angle;
  while (normalized > Math.PI) normalized -= Math.PI * 2;
  while (normalized < -Math.PI) normalized += Math.PI * 2;
  return normalized;
};

export class VesselSimulation {
  public readonly state: VesselState;

  private readonly config: VesselConfig;
  private gameplayCapabilities: VesselGameplayCapabilities = {
    breakPower: 1,
    fuelEfficiency: 1,
    hullDurability: 1,
    agility: 1,
    range: 1,
    enginePower: 1,
  };
  private safePosition: WorldPoint;
  private safeHeading: number;
  private previousBow: WorldPoint;
  private readonly currentBow: WorldPoint;
  private previousStern: WorldPoint;
  private readonly currentStern: WorldPoint;
  private readonly previousPosition = { x: 0, z: 0 };
  private previousHeading: number;
  private worldTick = 0;

  public constructor(
    initialPosition: Readonly<WorldPoint>,
    initialHeading: number,
    config: VesselConfig = DEFAULT_VESSEL_CONFIG,
  ) {
    this.config = config;
    this.safePosition = copyWorldPoint(initialPosition);
    this.safeHeading = initialHeading;
    this.previousHeading = initialHeading;
    this.previousBow = this.bowPosition(initialPosition, initialHeading);
    this.currentBow = copyWorldPoint(this.previousBow);
    this.previousStern = this.sternPosition(
      initialPosition,
      initialHeading,
    );
    this.currentStern = copyWorldPoint(this.previousStern);
    this.state = {
      worldPosition: copyWorldPoint(initialPosition),
      heading: initialHeading,
      velocityX: 0,
      velocityZ: 0,
      angularVelocity: 0,
      throttle: 0,
      steering: 0,
      engineRpm: 0.16,
      engineLoad: 0,
      speed: 0,
      longitudinalSpeed: 0,
      lateralSpeed: 0,
      currentResistance: 0,
      currentIceClass: 'open',
      stuckFactor: 0,
      fuel: config.startingFuel,
      hullCondition: 1,
      currentBreakForce: config.breakingPower,
      iceFuelCostMultiplier: 1,
      hullWearRate: 0,
      boostActive: false,
    };
  }

  public step(
    command: Readonly<VesselControlCommand>,
    deltaSeconds: number,
    iceWorld: IceWorld,
    obstacleWorld?: VesselObstacleWorld,
    environment?: Readonly<VesselEnvironmentForces>,
  ): VesselStepResult {
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (delta <= 0) {
      return {
        breakResult: EMPTY_BREAK_RESULT,
        reset: false,
        impact: 0,
        bowPosition: this.currentBow,
      };
    }

    if (command.requestReset) {
      this.resetToSafePosition();
      return {
        breakResult: EMPTY_BREAK_RESULT,
        reset: true,
        impact: 0,
        bowPosition: this.currentBow,
      };
    }

    this.worldTick += 1;
    const state = this.state;
    const config = this.config;
    state.throttle = approach(
      state.throttle,
      clamp(command.throttleTarget, -1, 1),
      config.throttleResponse * delta,
    );
    state.steering = approach(
      state.steering,
      clamp(command.steeringTarget, -1, 1),
      config.steeringResponse * delta,
    );
    state.boostActive = command.boost && state.fuel > 0.05 && state.throttle > 0.05;

    const reverseContactActive =
      state.longitudinalSpeed < -0.05 ||
      (
        state.longitudinalSpeed < 0.08 &&
        state.throttle < -0.05
      );
    const contact = iceWorld.sampleVesselContact(
      state.worldPosition,
      state.heading + (reverseContactActive ? Math.PI : 0),
      reverseContactActive
        ? {
            length: config.sternCollisionOffset * 2,
            width: config.sternCollisionWidth,
          }
        : {
            length: config.hullLength,
            width: config.hullWidth,
          },
    );
    const reverseCenterBlockingCoverage = reverseContactActive
      ? contact.bowCenterBlockingCoverage
      : 0;
    const reverseShoulderBlockingCoverage = reverseContactActive
      ? contact.bowShoulderBlockingCoverage
      : 0;
    const reverseHardBlock = saturate(
      (reverseCenterBlockingCoverage - 0.06) / 0.66,
    );
    const reverseSoftScrape = saturate(
      (reverseShoulderBlockingCoverage - 0.1) / 0.8,
    );
    const reverseMovementBlock = Math.max(
      reverseHardBlock,
      reverseSoftScrape * 0.28,
    );
    const reverseBraceCoverage = Math.max(
      reverseCenterBlockingCoverage * 0.6,
      reverseShoulderBlockingCoverage * 1.15,
    );
    state.currentResistance = contact.bowResistance;
    state.currentIceClass = contact.bowIceClass;

    const forwardX = Math.sin(state.heading);
    const forwardZ = Math.cos(state.heading);
    const rightX = forwardZ;
    const rightZ = -forwardX;
    const longitudinalSpeed =
      state.velocityX * forwardX + state.velocityZ * forwardZ;
    const lateralSpeed =
      state.velocityX * rightX + state.velocityZ * rightZ;
    const currentX = environment?.currentX ?? 0;
    const currentZ = environment?.currentZ ?? 0;
    const relativeVelocityX = state.velocityX - currentX;
    const relativeVelocityZ = state.velocityZ - currentZ;
    const waterLongitudinalSpeed =
      relativeVelocityX * forwardX +
      relativeVelocityZ * forwardZ;
    const waterLateralSpeed =
      relativeVelocityX * rightX +
      relativeVelocityZ * rightZ;
    state.longitudinalSpeed = longitudinalSpeed;
    state.lateralSpeed = lateralSpeed;
    const iceInteraction = calculateIceInteractionOutcome({
      iceClass: contact.bowIceClass,
      pressure: contact.pressure,
      coverage: contact.bowCoverage,
      resistance: contact.bowResistance,
      forwardSpeed: Math.max(0, longitudinalSpeed),
      throttle: state.throttle,
      engineLoad: state.engineLoad,
      capabilities: {
        breakPower:
          config.breakingPower *
          this.gameplayCapabilities.breakPower,
        fuelEfficiency:
          this.gameplayCapabilities.fuelEfficiency,
        hullDurability:
          this.gameplayCapabilities.hullDurability,
        hullCondition: state.hullCondition,
      },
    });
    state.currentBreakForce =
      iceInteraction.strokeBreakingPower;
    state.iceFuelCostMultiplier =
      iceInteraction.fuelCostMultiplier;
    state.hullWearRate =
      iceInteraction.hullWearPerSecond;

    const thrustScale = state.throttle >= 0 ? config.forwardThrust : config.reverseThrust;
    const boostMultiplier = state.boostActive ? config.boostMultiplier : 1;
    const capabilityAdjustedResistance = clamp(
      contact.resistance *
        iceInteraction.resistanceMultiplier,
      0,
      1,
    );
    const propulsionEfficiency =
      1 - capabilityAdjustedResistance * 0.16;
    const thrust =
      state.throttle *
      thrustScale *
      this.gameplayCapabilities.enginePower *
      boostMultiplier *
      propulsionEfficiency;
    const longitudinalDrag =
      waterLongitudinalSpeed *
      Math.abs(waterLongitudinalSpeed) *
      config.longitudinalDrag;
    const lateralDrag =
      waterLateralSpeed *
      Math.abs(waterLateralSpeed) *
      config.lateralDrag;
    const resistanceDirection =
      Math.abs(longitudinalSpeed) > 0.08
        ? Math.sign(longitudinalSpeed)
        : Math.sign(state.throttle);
    const iceResistance =
      resistanceDirection *
      capabilityAdjustedResistance *
      config.iceResistanceForce *
      (0.28 + contact.bowCoverage * 0.72) *
      saturate(Math.abs(longitudinalSpeed) * 0.65 + Math.abs(state.throttle) * 0.35);

    const contactDirection = reverseContactActive ? -1 : 1;
    const bowAsymmetry =
      (
        contact.bowLeftResistance -
        contact.bowRightResistance
      ) * contactDirection;
    const sideAsymmetry =
      (
        contact.sideLeftCoverage -
        contact.sideRightCoverage
      ) * contactDirection;
    const forceForward = thrust - longitudinalDrag - iceResistance;
    const forceRight =
      -lateralDrag +
      (
        bowAsymmetry * 0.76 +
        sideAsymmetry * 0.24
      ) *
      config.asymmetricIceForce;
    state.velocityX +=
      (forwardX * forceForward + rightX * forceRight) / config.mass * delta;
    state.velocityZ +=
      (forwardZ * forceForward + rightZ * forceRight) / config.mass * delta;
    const flowResponse =
      1 - Math.exp(-config.waterCurrentCoupling * delta);
    state.velocityX +=
      (currentX - state.velocityX) * flowResponse;
    state.velocityZ +=
      (currentZ - state.velocityZ) * flowResponse;
    const windAcceleration =
      (environment?.windStrength ?? 0) *
      config.windLeewayAcceleration;
    state.velocityX +=
      (environment?.windX ?? 0) * windAcceleration * delta;
    state.velocityZ +=
      (environment?.windZ ?? 0) * windAcceleration * delta;

    const movementDirection = reverseContactActive ? -1 : 1;
    const waterFlow = Math.abs(waterLongitudinalSpeed);
    const propWashAuthority =
      Math.abs(state.throttle) *
      config.lowSpeedSteeringAssist *
      saturate(waterFlow / 0.2);
    // Reverse thrust can brace the stern against solid ice and create yaw
    // without granting enough translation to climb onto the ice.
    const sternBraceAuthority =
      reverseBraceCoverage *
      Math.abs(state.throttle) *
      config.lowSpeedSteeringAssist *
      1.5;
    const speedAuthority =
      waterFlow + propWashAuthority + sternBraceAuthority;
    // Packed ice should make the vessel labor, but never remove the player's
    // ability to change approach angle or reverse out of a bad line.
    const iceSteeringMultiplier = clamp(1 - contact.resistance * 0.3, 0.72, 1);
    const rudderTorque =
      state.steering *
      movementDirection *
      speedAuthority *
      config.rudderAuthority *
      this.gameplayCapabilities.agility *
      iceSteeringMultiplier;
    const iceContactTorque =
      (
        bowAsymmetry +
        sideAsymmetry * 0.28
      ) *
      config.asymmetricIceTorque *
      (
        0.28 +
        Math.abs(waterLongitudinalSpeed) * 0.38 +
        Math.abs(state.throttle) * 0.24
      );
    const currentTorque =
      (
        (environment?.currentAngularVelocity ?? 0) -
        state.angularVelocity
      ) *
      config.currentYawCoupling;
    const angularAcceleration =
      (rudderTorque + iceContactTorque) /
        config.momentOfInertia +
      currentTorque -
      state.angularVelocity * config.angularDamping;
    state.angularVelocity = clamp(
      state.angularVelocity + angularAcceleration * delta,
      -config.maximumYawRate *
        this.gameplayCapabilities.agility,
      config.maximumYawRate *
        this.gameplayCapabilities.agility,
    );
    state.heading = normalizeAngle(state.heading + state.angularVelocity * delta);

    this.previousPosition.x = state.worldPosition.x;
    this.previousPosition.z = state.worldPosition.z;
    state.worldPosition.x += state.velocityX * delta;
    state.worldPosition.z += state.velocityZ * delta;
    this.resolveWorldBounds();
    this.resolveObstacleCollisions(this.previousPosition);
    const obstacleCollision = this.resolveDynamicObstacleCollisions(
      this.previousPosition,
      obstacleWorld,
    );
    if (reverseMovementBlock > 0) {
      const reverseBlock = reverseMovementBlock;
      const longitudinalMovement =
        (
          state.worldPosition.x - this.previousPosition.x
        ) * forwardX +
        (
          state.worldPosition.z - this.previousPosition.z
        ) * forwardZ;
      if (longitudinalMovement < 0) {
        state.worldPosition.x +=
          forwardX * -longitudinalMovement * reverseBlock;
        state.worldPosition.z +=
          forwardZ * -longitudinalMovement * reverseBlock;
      }
      const reverseSpeed =
        state.velocityX * forwardX +
        state.velocityZ * forwardZ;
      if (reverseSpeed < 0) {
        const retainedReverseSpeed =
          reverseSpeed *
          Math.exp(
            -config.unbrokenIceMomentumDamping *
            (0.8 + reverseBlock * 2.4) *
            delta,
          ) *
          (1 - reverseBlock * 0.82);
        const removedReverseSpeed =
          retainedReverseSpeed - reverseSpeed;
        state.velocityX += forwardX * removedReverseSpeed;
        state.velocityZ += forwardZ * removedReverseSpeed;
      }
    }
    if (obstacleCollision.resistance > state.currentResistance) {
      state.currentResistance = obstacleCollision.resistance;
      state.currentIceClass =
        obstacleCollision.resistance >= 0.72
          ? 'thick'
          : obstacleCollision.resistance >= 0.45
            ? 'medium'
            : 'thin';
    }

    this.writeBowPosition(this.currentBow, state.worldPosition, state.heading);
    this.writeSternPosition(
      this.currentStern,
      state.worldPosition,
      state.heading,
    );
    const impactSpeed = Math.max(0, longitudinalSpeed);
    const forwardThrottle = Math.max(0, state.throttle);
    const compression = saturate(
      contact.bowCoverage *
      forwardThrottle *
      (
        config.staticIceCompression +
        forwardThrottle * 0.7 +
        (state.boostActive ? 0.12 : 0)
      ),
    );
    const breakingImpact =
      impactSpeed >= config.minimumIceBreakingSpeed;
    let breakResult = EMPTY_BREAK_RESULT;
    if (
      !reverseContactActive &&
      contact.bowCoverage > 0.03 &&
      (breakingImpact || compression > 0.03)
    ) {
      breakResult = iceWorld.applyBreakStroke({
        previousBow: this.previousBow,
        currentBow: this.currentBow,
        previousHeading: this.previousHeading,
        currentHeading: state.heading,
        bowWidth: config.hullWidth * 0.92,
        vesselMass: config.mass,
        impactSpeed,
        compression,
        breakingPower:
          iceInteraction.strokeBreakingPower *
          boostMultiplier,
        canBreakIce: iceInteraction.canBreakIce,
        worldTick: this.worldTick,
      });
    }
    const reverseImpactSpeed = Math.max(0, -longitudinalSpeed);
    if (
      reverseContactActive &&
      contact.bowMovableFloeCoverage > 0.03 &&
      (
        reverseImpactSpeed > 0.03 ||
        state.throttle < -0.05
      )
    ) {
      iceWorld.applyBreakStroke({
        previousBow: this.previousStern,
        currentBow: this.currentStern,
        previousHeading: this.previousHeading + Math.PI,
        currentHeading: state.heading + Math.PI,
        bowWidth: config.sternCollisionWidth * 0.82,
        vesselMass: config.mass,
        impactSpeed: reverseImpactSpeed,
        compression:
          contact.bowMovableFloeCoverage *
          (0.12 + Math.max(0, -state.throttle) * 0.38),
        breakingPower:
          config.breakingPower *
          this.gameplayCapabilities.breakPower,
        canBreakIce: false,
        worldTick: this.worldTick,
      });
    }

    const unbrokenBlocking = saturate(
      (contact.bowResistance - 0.14) / 0.62,
    ) * contact.bowCoverage;
    if (
      breakResult.changedCells === 0 &&
      unbrokenBlocking > 0 &&
      state.longitudinalSpeed > 0
    ) {
      const currentForwardX = Math.sin(state.heading);
      const currentForwardZ = Math.cos(state.heading);
      const forwardSpeed =
        state.velocityX * currentForwardX +
        state.velocityZ * currentForwardZ;
      if (forwardSpeed > 0) {
        const retainedForwardSpeed =
          forwardSpeed *
          Math.exp(
            -config.unbrokenIceMomentumDamping *
            unbrokenBlocking *
            delta,
          );
        const removedSpeed = forwardSpeed - retainedForwardSpeed;
        state.velocityX -= currentForwardX * removedSpeed;
        state.velocityZ -= currentForwardZ * removedSpeed;
      }
    }
    this.previousBow.x = this.currentBow.x;
    this.previousBow.z = this.currentBow.z;
    this.previousStern.x = this.currentStern.x;
    this.previousStern.z = this.currentStern.z;
    this.previousHeading = state.heading;

    const impact = Math.max(
      obstacleCollision.impact,
      saturate(
        breakResult.releasedStress * 0.7 +
        contact.resistance * contact.bowCoverage * impactSpeed * 0.24,
      ),
    );
    if (impact > 0.02) {
      const retainedMomentum = clamp(1 - impact * config.iceMomentumLoss, 0.72, 1);
      state.velocityX *= retainedMomentum;
      state.velocityZ *= retainedMomentum;
    }

    state.speed = Math.hypot(state.velocityX, state.velocityZ);
    state.longitudinalSpeed =
      state.velocityX * Math.sin(state.heading) +
      state.velocityZ * Math.cos(state.heading);
    state.lateralSpeed =
      state.velocityX * Math.cos(state.heading) -
      state.velocityZ * Math.sin(state.heading);
    const pushingForward = Math.max(0, state.throttle);
    const effectiveResistance = Math.max(
      contact.resistance,
      obstacleCollision.resistance,
    );
    const effectiveCoverage = Math.max(
      contact.bowCoverage,
      obstacleCollision.resistance > 0 ? 0.82 : 0,
    );
    const stuckTarget = saturate(
      (effectiveResistance * 1.28 + effectiveCoverage * 0.32) *
      pushingForward -
      Math.abs(state.longitudinalSpeed) * 0.48 -
      Math.max(0, -state.throttle) * 0.18,
    );
    state.stuckFactor = damp(state.stuckFactor, stuckTarget, 3.2, delta);
    state.engineLoad = damp(
      state.engineLoad,
      saturate(
        Math.abs(state.throttle) * (0.24 + effectiveResistance * 0.66) +
        state.stuckFactor * 0.46,
      ),
      5,
      delta,
    );
    const freeRpm =
      0.15 + Math.abs(state.throttle) * 0.72;
    const rpmTarget =
      freeRpm +
      state.engineLoad * 0.07 -
      state.stuckFactor * 0.2;
    state.engineRpm = damp(state.engineRpm, clamp(rpmTarget, 0.12, 1), 3.2, delta);

    const fuelMultiplier = state.boostActive ? config.boostFuelMultiplier : 1;
    state.hullCondition = Math.max(
      0,
      state.hullCondition -
        iceInteraction.hullWearPerSecond * delta,
    );
    state.fuel = Math.max(
      0,
      state.fuel -
        config.baseFuelBurn *
        fuelMultiplier *
        iceInteraction.fuelCostMultiplier *
        (
          1 /
          (
            this.gameplayCapabilities.fuelEfficiency *
            this.gameplayCapabilities.range
          )
        ) *
        (0.18 + Math.abs(state.throttle) * 0.52 + state.engineLoad * 0.5) *
        delta,
    );

    if (
      contact.openness > 0.82 &&
      contact.resistance < 0.12 &&
      obstacleCollision.resistance < 0.12 &&
      state.speed < 3.5
    ) {
      this.safePosition = copyWorldPoint(state.worldPosition);
      this.safeHeading = state.heading;
    }

    return {
      breakResult,
      reset: false,
      impact,
      bowPosition: this.currentBow,
    };
  }

  public resetToSafePosition(): void {
    const state = this.state;
    state.worldPosition = copyWorldPoint(this.safePosition);
    state.heading = this.safeHeading;
    state.velocityX = 0;
    state.velocityZ = 0;
    state.angularVelocity = 0;
    state.throttle = 0;
    state.steering = 0;
    state.speed = 0;
    state.longitudinalSpeed = 0;
    state.lateralSpeed = 0;
    state.stuckFactor = 0;
    this.previousBow = this.bowPosition(state.worldPosition, state.heading);
    this.currentBow.x = this.previousBow.x;
    this.currentBow.z = this.previousBow.z;
    this.previousStern = this.sternPosition(
      state.worldPosition,
      state.heading,
    );
    this.currentStern.x = this.previousStern.x;
    this.currentStern.z = this.previousStern.z;
    this.previousHeading = state.heading;
  }

  public stopMotion(): void {
    const state = this.state;
    state.velocityX = 0;
    state.velocityZ = 0;
    state.angularVelocity = 0;
    state.throttle = 0;
    state.steering = 0;
    state.speed = 0;
    state.longitudinalSpeed = 0;
    state.lateralSpeed = 0;
    state.engineRpm = 0;
    state.engineLoad = 0;
    state.stuckFactor = 0;
  }

  public getSafePosition(): WorldPoint {
    return copyWorldPoint(this.safePosition);
  }

  public setGameplayCapabilities(
    capabilities: Readonly<VesselGameplayCapabilities>,
  ): void {
    this.gameplayCapabilities = {
      breakPower: clamp(capabilities.breakPower, 0.25, 4),
      fuelEfficiency: clamp(
        capabilities.fuelEfficiency,
        0.25,
        4,
      ),
      hullDurability: clamp(
        capabilities.hullDurability,
        0.25,
        4,
      ),
      agility: clamp(capabilities.agility, 0.25, 3),
      range: clamp(capabilities.range, 0.25, 4),
      enginePower: clamp(capabilities.enginePower, 0.25, 4),
    };
    this.state.currentBreakForce =
      this.config.breakingPower *
      this.gameplayCapabilities.breakPower;
  }

  public getGameplayCapabilities(): VesselGameplayCapabilities {
    return { ...this.gameplayCapabilities };
  }

  public exportProgress(): VesselProgressSaveData {
    return {
      version: 1,
      fuel: this.state.fuel,
      hullCondition: this.state.hullCondition,
    };
  }

  public restoreProgress(
    saved?: Readonly<VesselProgressSaveData>,
  ): boolean {
    if (
      saved?.version !== 1 ||
      !Number.isFinite(saved.fuel) ||
      !Number.isFinite(saved.hullCondition)
    ) {
      return false;
    }
    this.state.fuel = clamp(
      saved.fuel,
      0,
      this.config.startingFuel,
    );
    this.state.hullCondition = clamp(
      saved.hullCondition,
      0,
      1,
    );
    return true;
  }

  private bowPosition(position: Readonly<WorldPoint>, heading: number): WorldPoint {
    return {
      x: position.x + Math.sin(heading) * this.config.bowOffset,
      z: position.z + Math.cos(heading) * this.config.bowOffset,
    };
  }

  private sternPosition(
    position: Readonly<WorldPoint>,
    heading: number,
  ): WorldPoint {
    const sternOffset = this.config.sternCollisionOffset;
    return {
      x: position.x - Math.sin(heading) * sternOffset,
      z: position.z - Math.cos(heading) * sternOffset,
    };
  }

  private writeBowPosition(
    target: WorldPoint,
    position: Readonly<WorldPoint>,
    heading: number,
  ): void {
    target.x = position.x + Math.sin(heading) * this.config.bowOffset;
    target.z = position.z + Math.cos(heading) * this.config.bowOffset;
  }

  private writeSternPosition(
    target: WorldPoint,
    position: Readonly<WorldPoint>,
    heading: number,
  ): void {
    const sternOffset = this.config.sternCollisionOffset;
    target.x = position.x - Math.sin(heading) * sternOffset;
    target.z = position.z - Math.cos(heading) * sternOffset;
  }

  private resolveWorldBounds(): void {
    const state = this.state;
    const xLimit = this.config.worldHalfWidth - this.config.boundaryPadding;
    const zLimit = this.config.worldHalfHeight - this.config.boundaryPadding;
    if (state.worldPosition.x < -xLimit || state.worldPosition.x > xLimit) {
      state.worldPosition.x = clamp(state.worldPosition.x, -xLimit, xLimit);
      state.velocityX *= -0.18;
    }
    if (state.worldPosition.z < -zLimit || state.worldPosition.z > zLimit) {
      state.worldPosition.z = clamp(state.worldPosition.z, -zLimit, zLimit);
      state.velocityZ *= -0.18;
    }
  }

  private resolveObstacleCollisions(previousPosition: Readonly<WorldPoint>): void {
    const state = this.state;
    const vesselRadius = this.config.hullWidth * 0.42;
    for (const obstacle of this.config.obstacles) {
      const dx = state.worldPosition.x - obstacle.x;
      const dz = state.worldPosition.z - obstacle.z;
      const minimumDistance = obstacle.radius + vesselRadius;
      const distanceSquared = dx * dx + dz * dz;
      if (distanceSquared >= minimumDistance * minimumDistance) continue;

      const distance = Math.sqrt(distanceSquared);
      const normalX =
        distance > 0.001
          ? dx / distance
          : previousPosition.x >= obstacle.x
            ? 1
            : -1;
      const normalZ =
        distance > 0.001
          ? dz / distance
          : previousPosition.z >= obstacle.z
            ? 1
            : -1;
      state.worldPosition.x = obstacle.x + normalX * minimumDistance;
      state.worldPosition.z = obstacle.z + normalZ * minimumDistance;
      const normalVelocity = state.velocityX * normalX + state.velocityZ * normalZ;
      if (normalVelocity < 0) {
        state.velocityX -= normalVelocity * normalX * 1.25;
        state.velocityZ -= normalVelocity * normalZ * 1.25;
      }
      state.angularVelocity *= 0.7;
    }
  }

  private resolveDynamicObstacleCollisions(
    previousPosition: Readonly<WorldPoint>,
    obstacleWorld?: VesselObstacleWorld,
  ): ObstacleCollisionResult {
    if (!obstacleWorld) return { impact: 0, resistance: 0 };

    const state = this.state;
    const forwardX = Math.sin(state.heading);
    const forwardZ = Math.cos(state.heading);
    const sternOffset = -this.config.hullLength * 0.35;
    const bowOffset = this.config.hullLength * 0.47;
    const vesselRadius = this.config.hullWidth * 0.36;
    let maximumImpact = 0;
    let maximumResistance = 0;

    for (const obstacle of obstacleWorld.getVesselObstacles()) {
      const sternX = state.worldPosition.x + forwardX * sternOffset;
      const sternZ = state.worldPosition.z + forwardZ * sternOffset;
      const segmentX = forwardX * (bowOffset - sternOffset);
      const segmentZ = forwardZ * (bowOffset - sternOffset);
      const segmentLengthSquared =
        segmentX * segmentX + segmentZ * segmentZ;
      const projection = clamp(
        (
          (obstacle.x - sternX) * segmentX +
          (obstacle.z - sternZ) * segmentZ
        ) / Math.max(0.0001, segmentLengthSquared),
        0,
        1,
      );
      const closestX = sternX + segmentX * projection;
      const closestZ = sternZ + segmentZ * projection;
      const dx = closestX - obstacle.x;
      const dz = closestZ - obstacle.z;
      const minimumDistance = obstacle.radius + vesselRadius;
      const distanceSquared = dx * dx + dz * dz;
      if (distanceSquared >= minimumDistance * minimumDistance) continue;

      const distance = Math.sqrt(distanceSquared);
      const previousDx = previousPosition.x - obstacle.x;
      const previousDz = previousPosition.z - obstacle.z;
      const previousDistance = Math.hypot(previousDx, previousDz);
      const normalX =
        distance > 0.001
          ? dx / distance
          : previousDistance > 0.001
            ? previousDx / previousDistance
            : -forwardX;
      const normalZ =
        distance > 0.001
          ? dz / distance
          : previousDistance > 0.001
            ? previousDz / previousDistance
            : -forwardZ;
      const penetration = minimumDistance - distance;
      const pushability = clamp(obstacle.pushability, 0, 0.92);
      const vesselShare = 1 - pushability;
      state.worldPosition.x += normalX * penetration * vesselShare;
      state.worldPosition.z += normalZ * penetration * vesselShare;

      const relativeVelocityX = state.velocityX - obstacle.velocityX;
      const relativeVelocityZ = state.velocityZ - obstacle.velocityZ;
      const normalVelocity =
        relativeVelocityX * normalX + relativeVelocityZ * normalZ;
      const closingSpeed = Math.max(0, -normalVelocity);
      if (normalVelocity < 0) {
        const response = 0.45 + obstacle.resistance * 0.62;
        state.velocityX -= normalVelocity * normalX * response;
        state.velocityZ -= normalVelocity * normalZ * response;
        state.angularVelocity *= 1 - obstacle.resistance * 0.32;
      }

      obstacleWorld.applyVesselContact(obstacle.id, {
        displacementX: -normalX * penetration * pushability,
        displacementZ: -normalZ * penetration * pushability,
        impulseX: -normalX * closingSpeed * pushability * 0.48,
        impulseZ: -normalZ * closingSpeed * pushability * 0.48,
      });
      maximumResistance = Math.max(
        maximumResistance,
        obstacle.resistance,
      );
      maximumImpact = Math.max(
        maximumImpact,
        saturate(
          closingSpeed * obstacle.resistance * 0.42 +
          penetration * 0.3,
        ),
      );
    }

    return {
      impact: maximumImpact,
      resistance: maximumResistance,
    };
  }
}
