import type {
  PortIceAccessProfile,
  PortShorelineShape,
} from '../world/PortIceAccess';
import { clamp } from '../utils/math';

export interface PortClearanceRadii {
  innerRadius: number;
  outerRadius: number;
}

export interface PortClearanceVisualState {
  color: number;
  areaOpacity: number;
  outlineOpacity: number;
}

const shapeRadius = (
  shape: Readonly<PortShorelineShape>,
): number => {
  const offset = Math.hypot(
    shape.offsetX ?? 0,
    shape.offsetZ ?? 0,
  );
  if (shape.kind === 'circle') {
    return offset + shape.radius;
  }
  if (shape.kind === 'ellipse') {
    return offset + Math.max(shape.radiusX, shape.radiusZ);
  }
  if (shape.kind === 'polygon') {
    return (
      offset +
      shape.points.reduce(
        (radius, point) =>
          Math.max(radius, Math.hypot(point.x, point.z)),
        0,
      )
    );
  }
  return (
    offset +
    shape.parts.reduce(
      (radius, part) =>
        Math.max(radius, shapeRadius(part)),
      0,
    )
  );
};

const mixHex = (
  from: number,
  to: number,
  amount: number,
): number => {
  const t = clamp(amount, 0, 1);
  const mixChannel = (shift: number): number =>
    Math.round(
      ((from >> shift) & 0xff) * (1 - t) +
        ((to >> shift) & 0xff) * t,
    );
  return (
    (mixChannel(16) << 16) |
    (mixChannel(8) << 8) |
    mixChannel(0)
  );
};

export const resolvePortClearanceRadii = (
  profile: Readonly<PortIceAccessProfile>,
): PortClearanceRadii => {
  const innerRadius = shapeRadius(profile.shoreline);
  return {
    innerRadius,
    outerRadius: innerRadius + profile.clearanceDistance,
  };
};

export const resolvePortClearanceVisual = (
  progress: number,
): PortClearanceVisualState => {
  const normalized = clamp(progress, 0, 1);
  const color =
    normalized < 0.55
      ? mixHex(0xff5d67, 0xffcf66, normalized / 0.55)
      : mixHex(
          0xffcf66,
          0x62e696,
          (normalized - 0.55) / 0.45,
        );
  return {
    color,
    areaOpacity: 0.065 + normalized * 0.035,
    outlineOpacity: 0.76 + normalized * 0.16,
  };
};
