import { clamp, lerp } from '../utils/math';

export type BorealisTerrainClass = 'WATER' | 'SHORE' | 'LAND';

export interface BorealisCoastRasterSample {
  terrain: BorealisTerrainClass;
  bathymetry: number;
}

export interface BorealisCoastRasterSource {
  width: number;
  height: number;
  metresPerPixel: number;
  minX: number;
  minZ: number;
  terrain: ArrayLike<number>;
  bathymetry: ArrayLike<number>;
}

interface ActiveBorealisCoastRaster {
  width: number;
  height: number;
  metresPerPixel: number;
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
  terrain: Uint8ClampedArray;
  bathymetry: Uint8ClampedArray;
  coastXByRow: Float32Array;
}

interface BorealisCoastManifest {
  schemaVersion: 1;
  metresPerPixel: number;
  widthPixels: number;
  heightPixels: number;
  bounds: {
    minX: number;
    maxX: number;
    minZ: number;
    maxZ: number;
  };
  layers: {
    terrain: string;
    bathymetry: string;
  };
}

const SOURCE_ROOT = 'assets/world/borealis/source/';
const WATER = [16, 69, 104, 255] as const;
const SHORE = [123, 188, 182, 255] as const;
const LAND = [77, 118, 104, 255] as const;
let activeRaster: ActiveBorealisCoastRaster | undefined;

const pixelMatches = (
  data: ArrayLike<number>,
  offset: number,
  color: readonly [number, number, number, number],
): boolean =>
  data[offset] === color[0] &&
  data[offset + 1] === color[1] &&
  data[offset + 2] === color[2] &&
  data[offset + 3] === color[3];

const terrainAtOffset = (
  data: ArrayLike<number>,
  offset: number,
): BorealisTerrainClass | undefined => {
  if (pixelMatches(data, offset, WATER)) return 'WATER';
  if (pixelMatches(data, offset, SHORE)) return 'SHORE';
  if (pixelMatches(data, offset, LAND)) return 'LAND';
  return undefined;
};

const loadPixels = async (url: string): Promise<ImageData> => {
  const image = new Image();
  image.decoding = 'async';
  image.src = url;
  await image.decode();
  const canvas = document.createElement('canvas');
  canvas.width = image.naturalWidth;
  canvas.height = image.naturalHeight;
  const context = canvas.getContext('2d', {
    willReadFrequently: true,
  });
  if (!context) throw new Error('Canvas 2D is unavailable.');
  context.drawImage(image, 0, 0);
  return context.getImageData(0, 0, canvas.width, canvas.height);
};

export const installBorealisCoastRaster = (
  source: Readonly<BorealisCoastRasterSource>,
): void => {
  const width = Math.floor(source.width);
  const height = Math.floor(source.height);
  const expectedBytes = width * height * 4;
  if (
    width < 2 ||
    height < 2 ||
    !Number.isFinite(source.metresPerPixel) ||
    source.metresPerPixel <= 0 ||
    source.terrain.length !== expectedBytes ||
    source.bathymetry.length !== expectedBytes
  ) {
    throw new Error('Borealis coast raster dimensions are invalid.');
  }
  const terrain = new Uint8ClampedArray(source.terrain);
  const bathymetry = new Uint8ClampedArray(source.bathymetry);
  const coastXByRow = new Float32Array(height);
  for (let row = 0; row < height; row += 1) {
    let coastColumn = -1;
    for (let column = 0; column < width; column += 1) {
      const offset = (row * width + column) * 4;
      const terrainClass = terrainAtOffset(terrain, offset);
      if (!terrainClass) {
        throw new Error(
          `Unknown Borealis terrain color at ${column},${row}.`,
        );
      }
      if (
        bathymetry[offset] !== bathymetry[offset + 1] ||
        bathymetry[offset] !== bathymetry[offset + 2] ||
        bathymetry[offset + 3] !== 255
      ) {
        throw new Error(
          `Borealis bathymetry must be opaque grayscale at ${column},${row}.`,
        );
      }
      if (terrainClass !== 'WATER') coastColumn = column;
    }
    if (coastColumn < 0) {
      throw new Error(`Borealis terrain row ${row} contains no coast.`);
    }
    coastXByRow[row] =
      source.minX +
      (coastColumn + 1) * source.metresPerPixel;
  }
  activeRaster = {
    width,
    height,
    metresPerPixel: source.metresPerPixel,
    minX: source.minX,
    maxX: source.minX + width * source.metresPerPixel,
    minZ: source.minZ,
    maxZ: source.minZ + height * source.metresPerPixel,
    terrain,
    bathymetry,
    coastXByRow,
  };
};

export const initializeBorealisCoastRaster = async (): Promise<void> => {
  const rootUrl = new URL(SOURCE_ROOT, document.baseURI);
  const manifestResponse = await fetch(
    new URL('borealis-coast.json', rootUrl),
  );
  if (!manifestResponse.ok) {
    throw new Error(
      `Borealis coast manifest returned ${manifestResponse.status}.`,
    );
  }
  const manifest =
    (await manifestResponse.json()) as BorealisCoastManifest;
  if (
    manifest.schemaVersion !== 1 ||
    manifest.widthPixels < 2 ||
    manifest.heightPixels < 2 ||
    !Number.isFinite(manifest.metresPerPixel)
  ) {
    throw new Error('Borealis coast manifest is invalid.');
  }
  const [terrain, bathymetry] = await Promise.all([
    loadPixels(new URL(manifest.layers.terrain, rootUrl).href),
    loadPixels(new URL(manifest.layers.bathymetry, rootUrl).href),
  ]);
  if (
    terrain.width !== manifest.widthPixels ||
    terrain.height !== manifest.heightPixels ||
    bathymetry.width !== manifest.widthPixels ||
    bathymetry.height !== manifest.heightPixels
  ) {
    throw new Error('Borealis coast PNG dimensions do not match its manifest.');
  }
  const expectedMaxX =
    manifest.bounds.minX +
    manifest.widthPixels * manifest.metresPerPixel;
  const expectedMaxZ =
    manifest.bounds.minZ +
    manifest.heightPixels * manifest.metresPerPixel;
  if (
    Math.abs(expectedMaxX - manifest.bounds.maxX) > 0.001 ||
    Math.abs(expectedMaxZ - manifest.bounds.maxZ) > 0.001
  ) {
    throw new Error('Borealis coast manifest bounds are inconsistent.');
  }
  installBorealisCoastRaster({
    width: manifest.widthPixels,
    height: manifest.heightPixels,
    metresPerPixel: manifest.metresPerPixel,
    minX: manifest.bounds.minX,
    minZ: manifest.bounds.minZ,
    terrain: terrain.data,
    bathymetry: bathymetry.data,
  });
};

export const resetBorealisCoastRaster = (): void => {
  activeRaster = undefined;
};

export const sampleBorealisRasterCoastX = (
  z: number,
): number | undefined => {
  const raster = activeRaster;
  if (!raster || z < raster.minZ || z > raster.maxZ) return undefined;
  const pixelY = (z - raster.minZ) / raster.metresPerPixel - 0.5;
  const baseY = Math.floor(pixelY);
  const y0 = clamp(baseY, 0, raster.height - 1);
  const y1 = clamp(baseY + 1, 0, raster.height - 1);
  return lerp(
    raster.coastXByRow[y0]!,
    raster.coastXByRow[y1]!,
    clamp(pixelY - baseY, 0, 1),
  );
};

export const sampleBorealisCoastRaster = (
  x: number,
  z: number,
): BorealisCoastRasterSample | undefined => {
  const raster = activeRaster;
  if (
    !raster ||
    x < raster.minX ||
    x > raster.maxX ||
    z < raster.minZ ||
    z > raster.maxZ
  ) {
    return undefined;
  }
  const pixelX = (x - raster.minX) / raster.metresPerPixel - 0.5;
  const pixelY = (z - raster.minZ) / raster.metresPerPixel - 0.5;
  const nearestX = clamp(Math.round(pixelX), 0, raster.width - 1);
  const nearestY = clamp(Math.round(pixelY), 0, raster.height - 1);
  const terrain = terrainAtOffset(
    raster.terrain,
    (nearestY * raster.width + nearestX) * 4,
  )!;
  const baseX = Math.floor(pixelX);
  const baseY = Math.floor(pixelY);
  const x0 = clamp(baseX, 0, raster.width - 1);
  const x1 = clamp(baseX + 1, 0, raster.width - 1);
  const y0 = clamp(baseY, 0, raster.height - 1);
  const y1 = clamp(baseY + 1, 0, raster.height - 1);
  const tx = clamp(pixelX - baseX, 0, 1);
  const ty = clamp(pixelY - baseY, 0, 1);
  const depthAt = (column: number, row: number): number =>
    raster.bathymetry[(row * raster.width + column) * 4]! / 255;
  const lower = lerp(depthAt(x0, y0), depthAt(x1, y0), tx);
  const upper = lerp(depthAt(x0, y1), depthAt(x1, y1), tx);
  return {
    terrain,
    bathymetry: lerp(lower, upper, ty),
  };
};

export const isBorealisCoastRasterActive = (): boolean =>
  activeRaster !== undefined;
