import { clamp, hash2D, smoothstep } from '../utils/math';

export interface SnowAccumulationInput {
  columns: number;
  rows: number;
  current: Float32Array;
  next: Float32Array;
  openness: Float32Array;
  thickness?: Float32Array;
  stress?: Float32Array;
  disturbance?: Float32Array;
  shelter?: Float32Array;
  windXField?: Float32Array;
  windZField?: Float32Array;
  surfaceIds?: Int32Array;
  depositionOutput?: Float32Array;
  erosionOutput?: Float32Array;
  snowIntensity: number;
  windMultiplier: number;
  windX: number;
  windZ: number;
  deltaSeconds: number;
}

export interface SnowAccumulationResult {
  maximumChange: number;
  depositedSnow: number;
  erodedSnow: number;
  transportedSnow: number;
  lostSnow: number;
}

export interface SnowShelterInput {
  columns: number;
  rows: number;
  openness: Float32Array;
  thickness: Float32Array;
  stress?: Float32Array;
  obstacleHeight?: Float32Array;
  windXField?: Float32Array;
  windZField?: Float32Array;
  windX: number;
  windZ: number;
  output: Float32Array;
  barrierScratch?: Float32Array;
}

export interface SnowShelterResult {
  maximumShelter: number;
  shelteredCells: number;
}

const OPEN_WATER_START = 0.56;
const OPEN_WATER_END = 0.76;
const MINIMUM_WIND_LENGTH = 0.0001;

const validateField = (
  field: ArrayLike<number> | undefined,
  count: number,
  name: string,
): void => {
  if (field && field.length !== count) {
    throw new Error(`${name} must match the snow grid size.`);
  }
};

const sampleBilinear = (
  field: Float32Array,
  columns: number,
  rows: number,
  x: number,
  y: number,
): number => {
  if (x < 0 || y < 0 || x > columns - 1 || y > rows - 1) {
    return 0;
  }
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const x1 = Math.min(columns - 1, x0 + 1);
  const y1 = Math.min(rows - 1, y0 + 1);
  const tx = x - x0;
  const ty = y - y0;
  const top =
    (field[y0 * columns + x0] ?? 0) * (1 - tx) +
    (field[y0 * columns + x1] ?? 0) * tx;
  const bottom =
    (field[y1 * columns + x0] ?? 0) * (1 - tx) +
    (field[y1 * columns + x1] ?? 0) * tx;
  return top * (1 - ty) + bottom * ty;
};

const sampleNeighborAverage = (
  field: Float32Array,
  columns: number,
  rows: number,
  column: number,
  row: number,
): number => {
  let total = 0;
  let samples = 0;
  for (const [offsetX, offsetY] of [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ] as const) {
    const x = column + offsetX;
    const y = row + offsetY;
    if (x < 0 || y < 0 || x >= columns || y >= rows) continue;
    total += field[y * columns + x] ?? 0;
    samples += 1;
  }
  return samples > 0 ? total / samples : 0;
};

const resolveWind = (
  index: number,
  fallbackX: number,
  fallbackZ: number,
  windXField?: Float32Array,
  windZField?: Float32Array,
): readonly [number, number] => {
  const windX = windXField?.[index] ?? fallbackX;
  const windZ = windZField?.[index] ?? fallbackZ;
  const length = Math.hypot(windX, windZ);
  if (length < MINIMUM_WIND_LENGTH) return [0, 0];
  return [windX / length, windZ / length];
};

export const calculateSnowShelterField = (
  input: Readonly<SnowShelterInput>,
): SnowShelterResult => {
  const {
    columns,
    rows,
    openness,
    thickness,
    output,
  } = input;
  const count = columns * rows;
  validateField(openness, count, 'Snow shelter openness');
  validateField(thickness, count, 'Snow shelter thickness');
  validateField(input.stress, count, 'Snow shelter stress');
  validateField(
    input.obstacleHeight,
    count,
    'Snow shelter obstacle height',
  );
  validateField(input.windXField, count, 'Snow shelter wind X');
  validateField(input.windZField, count, 'Snow shelter wind Z');
  validateField(output, count, 'Snow shelter output');
  validateField(
    input.barrierScratch,
    count,
    'Snow shelter barrier scratch',
  );

  const barrier =
    input.barrierScratch ?? new Float32Array(count);
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const index = row * columns + column;
      const localOpenness = openness[index] ?? 1;
      const localThickness = thickness[index] ?? 0;
      const neighborThickness = sampleNeighborAverage(
        thickness,
        columns,
        rows,
        column,
        row,
      );
      const neighborOpenness = sampleNeighborAverage(
        openness,
        columns,
        rows,
        column,
        row,
      );
      const ridge = smoothstep(
        0.035,
        0.2,
        localThickness - neighborThickness,
      );
      const edgeLip = smoothstep(
        0.08,
        0.48,
        neighborOpenness - localOpenness,
      );
      const fractureLip =
        clamp(input.stress?.[index] ?? 0, 0, 1) *
        (1 - smoothstep(0.5, OPEN_WATER_END, localOpenness));
      barrier[index] = Math.max(
        clamp(input.obstacleHeight?.[index] ?? 0, 0, 1),
        clamp(ridge * 0.62 + edgeLip * 0.34 + fractureLip * 0.18, 0, 1),
      );
    }
  }

  let maximumShelter = 0;
  let shelteredCells = 0;
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const index = row * columns + column;
      const [windX, windZ] = resolveWind(
        index,
        input.windX,
        input.windZ,
        input.windXField,
        input.windZField,
      );
      if (windX === 0 && windZ === 0) {
        output[index] = 0;
        continue;
      }

      const crossX = -windZ;
      const crossZ = windX;
      let shelter = 0;
      for (let distance = 1; distance <= 6; distance += 1) {
        const upwindX = column - windX * distance;
        const upwindY = row - windZ * distance;
        const center = sampleBilinear(
          barrier,
          columns,
          rows,
          upwindX,
          upwindY,
        );
        const left = sampleBilinear(
          barrier,
          columns,
          rows,
          upwindX + crossX * 0.45,
          upwindY + crossZ * 0.45,
        );
        const right = sampleBilinear(
          barrier,
          columns,
          rows,
          upwindX - crossX * 0.45,
          upwindY - crossZ * 0.45,
        );
        const blocker = Math.max(center, (left + right) * 0.44);
        const attenuation = Math.exp(-0.31 * (distance - 1));
        shelter = Math.max(shelter, blocker * attenuation);
      }

      const localShelter = clamp(shelter, 0, 1);
      output[index] = localShelter;
      maximumShelter = Math.max(maximumShelter, localShelter);
      if (localShelter >= 0.08) shelteredCells += 1;
    }
  }

  return {
    maximumShelter,
    shelteredCells,
  };
};

export const simulateSnowAccumulation = (
  input: Readonly<SnowAccumulationInput>,
): SnowAccumulationResult => {
  const {
    columns,
    rows,
    current,
    next,
    openness,
  } = input;
  const count = columns * rows;
  validateField(current, count, 'Current snow');
  validateField(next, count, 'Next snow');
  validateField(openness, count, 'Snow openness');
  validateField(input.thickness, count, 'Snow thickness');
  validateField(input.stress, count, 'Snow stress');
  validateField(input.disturbance, count, 'Snow disturbance');
  validateField(input.shelter, count, 'Snow shelter');
  validateField(input.windXField, count, 'Snow wind X');
  validateField(input.windZField, count, 'Snow wind Z');
  validateField(input.surfaceIds, count, 'Snow surface IDs');
  validateField(
    input.depositionOutput,
    count,
    'Snow deposition output',
  );
  validateField(input.erosionOutput, count, 'Snow erosion output');

  const step = clamp(input.deltaSeconds, 0, 1);
  const snowfall = clamp(input.snowIntensity, 0, 1);
  const wind = clamp(input.windMultiplier, 0.5, 2);
  const erosionRate = Math.max(0, wind - 0.78) * 0.095;
  const transportFraction = clamp((wind - 0.76) * 0.38, 0, 0.46);
  const transportDistance =
    0.72 + smoothstep(0.82, 1.9, wind) * 0.72;

  next.fill(0);
  input.depositionOutput?.fill(0);
  input.erosionOutput?.fill(0);

  let depositedSnow = 0;
  let erodedSnow = 0;
  let transportedSnow = 0;
  let lostSnow = 0;

  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const index = row * columns + column;
      const cellOpenness = openness[index] ?? 1;
      const previous = current[index] ?? 0;
      const solidness =
        1 - smoothstep(OPEN_WATER_START, OPEN_WATER_END, cellOpenness);

      if (solidness <= 0.001) {
        next[index] =
          next[index]! + previous * Math.exp(-step * 1.25);
        lostSnow += Math.max(0, previous - next[index]!);
        continue;
      }

      const thickness = clamp(input.thickness?.[index] ?? 0.7, 0, 1);
      const stress = clamp(input.stress?.[index] ?? 0, 0, 1);
      const disturbance = clamp(
        input.disturbance?.[index] ?? 0,
        0,
        1,
      );
      const shelter = clamp(input.shelter?.[index] ?? 0, 0, 1);
      const grip = clamp(
        0.38 + thickness * 0.42 + stress * 0.14,
        0.35,
        0.94,
      );
      const depositionVariation =
        0.74 + hash2D(column, row, 419) * 0.42;
      const deposited =
        snowfall *
        0.105 *
        depositionVariation *
        solidness *
        (0.72 + shelter * 0.74) *
        (0.72 + grip * 0.28) *
        (1 - disturbance * 0.88) *
        step;
      const withFreshSnow = Math.min(1, previous + deposited);
      const exposure = 1 - shelter;
      const windErosion = Math.min(
        withFreshSnow,
        erosionRate *
          (0.32 + withFreshSnow * 0.68) *
          (0.32 + exposure * 0.92) *
          (1.18 - grip * 0.48) *
          solidness *
          step,
      );
      const disturbanceErosion = Math.min(
        withFreshSnow - windErosion,
        disturbance *
          (0.035 + withFreshSnow * 0.12) *
          (0.65 + cellOpenness * 0.35) *
          step,
      );
      const eroded = windErosion + disturbanceErosion;
      const mobileSnow = eroded * transportFraction;

      next[index] = next[index]! + withFreshSnow - eroded;
      if (input.depositionOutput) {
        input.depositionOutput[index] = deposited;
      }
      if (input.erosionOutput) {
        input.erosionOutput[index] = eroded;
      }
      depositedSnow += deposited;
      erodedSnow += eroded;
      transportedSnow += mobileSnow;
      lostSnow += eroded - mobileSnow;

      if (mobileSnow <= 0) continue;
      const [windX, windZ] = resolveWind(
        index,
        input.windX,
        input.windZ,
        input.windXField,
        input.windZField,
      );
      if (windX === 0 && windZ === 0) {
        lostSnow += mobileSnow;
        continue;
      }

      const gust =
        0.88 + hash2D(column, row, 937) * 0.24;
      const targetX =
        column + windX * transportDistance * gust;
      const targetY =
        row + windZ * transportDistance * gust;
      const x0 = Math.floor(targetX);
      const y0 = Math.floor(targetY);
      const tx = targetX - x0;
      const ty = targetY - y0;
      const sourceSurface = input.surfaceIds?.[index];
      let depositedTransport = 0;

      for (const [targetColumn, targetRow, weight] of [
        [x0, y0, (1 - tx) * (1 - ty)],
        [x0 + 1, y0, tx * (1 - ty)],
        [x0, y0 + 1, (1 - tx) * ty],
        [x0 + 1, y0 + 1, tx * ty],
      ] as const) {
        if (
          weight <= 0 ||
          targetColumn < 0 ||
          targetColumn >= columns ||
          targetRow < 0 ||
          targetRow >= rows
        ) {
          continue;
        }
        const targetIndex = targetRow * columns + targetColumn;
        if (
          sourceSurface !== undefined &&
          input.surfaceIds?.[targetIndex] !== sourceSurface
        ) {
          continue;
        }
        const targetSolidness =
          1 -
          smoothstep(
            OPEN_WATER_START,
            OPEN_WATER_END,
            openness[targetIndex] ?? 1,
          );
        if (targetSolidness <= 0.001) continue;

        const targetShelter = clamp(
          input.shelter?.[targetIndex] ?? 0,
          0,
          1,
        );
        const targetThickness = clamp(
          input.thickness?.[targetIndex] ?? 0.7,
          0,
          1,
        );
        const targetDisturbance = clamp(
          input.disturbance?.[targetIndex] ?? 0,
          0,
          1,
        );
        const capture = clamp(
          0.24 +
            targetShelter * 0.58 +
            targetThickness * 0.18 -
            targetDisturbance * 0.46,
          0.08,
          0.94,
        );
        const amount =
          mobileSnow * weight * targetSolidness * capture;
        next[targetIndex] = next[targetIndex]! + amount;
        if (input.depositionOutput) {
          input.depositionOutput[targetIndex] =
            (input.depositionOutput[targetIndex] ?? 0) + amount;
        }
        depositedTransport += amount;
      }
      lostSnow += Math.max(0, mobileSnow - depositedTransport);
    }
  }

  let maximumChange = 0;
  for (let index = 0; index < count; index += 1) {
    next[index] = clamp(next[index]!, 0, 1);
    maximumChange = Math.max(
      maximumChange,
      Math.abs(next[index]! - current[index]!),
    );
  }
  return {
    maximumChange,
    depositedSnow,
    erodedSnow,
    transportedSnow,
    lostSnow,
  };
};
