import type {
  GameplayUpgradeDefinition,
  GoodType,
  PortState,
  ShipCapabilityDefinition,
  ShipStatId,
} from '../definitions/GameplayTypes';

export interface UpgradeAvailabilityContext {
  discoveredPortIds: ReadonlySet<string>;
  discoveredPoiIds: ReadonlySet<string>;
  activeGoodsFlows: ReadonlySet<GoodType>;
  portStates: readonly PortState[];
}

export interface ComputedShipCapabilities {
  breakPower: number;
  fuelEfficiency: number;
  hullDurability: number;
  agility: number;
  range: number;
  enginePower: number;
  moduleSlots: number;
}

export interface UpgradeInventorySaveData {
  version: 1;
  availableUpgradeIds: string[];
  ownedUpgradeIds: string[];
  installedModuleIds: string[];
}

export type UpgradePurchaseFailure =
  | 'UNKNOWN_UPGRADE'
  | 'NOT_AVAILABLE'
  | 'ALREADY_OWNED'
  | 'INSUFFICIENT_FUNDS';

export interface UpgradePurchaseResult {
  success: boolean;
  cost: number;
  moneyRemaining: number;
  reason?: UpgradePurchaseFailure;
}

export type RefitFailure =
  | 'INVALID_DOCK'
  | 'MODULE_NOT_OWNED'
  | 'NOT_A_MODULE'
  | 'TOO_MANY_MODULES'
  | 'INCOMPATIBLE_MODULES';

export interface RefitResult {
  success: boolean;
  reason?: RefitFailure;
}

const STAT_KEYS: Readonly<
  Record<
    ShipStatId,
    keyof Omit<ComputedShipCapabilities, 'moduleSlots'>
  >
> = {
  BREAK_POWER: 'breakPower',
  FUEL_EFFICIENCY: 'fuelEfficiency',
  HULL_DURABILITY: 'hullDurability',
  AGILITY: 'agility',
  RANGE: 'range',
  ENGINE_POWER: 'enginePower',
};

export class UpgradeInventory {
  private readonly definitions = new Map<
    string,
    GameplayUpgradeDefinition
  >();
  private readonly availableUpgradeIds = new Set<string>();
  private readonly ownedUpgradeIds = new Set<string>();
  private installedModuleIds: string[] = [];

  public constructor(
    definitions: readonly GameplayUpgradeDefinition[],
    saved?: Readonly<UpgradeInventorySaveData>,
  ) {
    for (const definition of definitions) {
      this.definitions.set(definition.id, definition);
    }
    if (saved) this.importState(saved);
  }

  public refreshAvailability(
    context: Readonly<UpgradeAvailabilityContext>,
  ): readonly string[] {
    const newlyAvailable: string[] = [];
    const portStates = new Map(
      context.portStates.map((state) => [
        state.portId,
        state,
      ]),
    );
    for (const definition of this.definitions.values()) {
      if (this.availableUpgradeIds.has(definition.id)) continue;
      if (
        definition.requiredDiscoveryId &&
        !context.discoveredPoiIds.has(
          definition.requiredDiscoveryId,
        )
      ) {
        continue;
      }
      if (definition.requiredPortId) {
        if (
          !context.discoveredPortIds.has(
            definition.requiredPortId,
          )
        ) {
          continue;
        }
        const port = portStates.get(definition.requiredPortId);
        if (
          !port ||
          port.developmentLevel <
            (definition.requiredPortLevel ?? 1) ||
          (
            definition.requiredService &&
            !port.unlockedServices.includes(
              definition.requiredService,
            )
          )
        ) {
          continue;
        }
      }
      if (
        (definition.requiredGoodsFlow ?? []).some(
          (good) => !context.activeGoodsFlows.has(good),
        )
      ) {
        continue;
      }
      this.availableUpgradeIds.add(definition.id);
      newlyAvailable.push(definition.id);
    }
    return newlyAvailable;
  }

  public unlockAvailability(upgradeId: string): boolean {
    if (
      !this.definitions.has(upgradeId) ||
      this.availableUpgradeIds.has(upgradeId)
    ) {
      return false;
    }
    this.availableUpgradeIds.add(upgradeId);
    return true;
  }

  public isAvailable(upgradeId: string): boolean {
    return this.availableUpgradeIds.has(upgradeId);
  }

  public isOwned(upgradeId: string): boolean {
    return this.ownedUpgradeIds.has(upgradeId);
  }

  public isInstalled(upgradeId: string): boolean {
    return this.installedModuleIds.includes(upgradeId);
  }

  public getInstalledModuleIds(): readonly string[] {
    return [...this.installedModuleIds];
  }

  public getOwnedUpgradeIds(): readonly string[] {
    return [...this.ownedUpgradeIds];
  }

  public purchase(
    upgradeId: string,
    availableMoney: number,
  ): UpgradePurchaseResult {
    const definition = this.definitions.get(upgradeId);
    if (!definition) {
      return {
        success: false,
        cost: 0,
        moneyRemaining: availableMoney,
        reason: 'UNKNOWN_UPGRADE',
      };
    }
    if (!this.availableUpgradeIds.has(upgradeId)) {
      return {
        success: false,
        cost: definition.price,
        moneyRemaining: availableMoney,
        reason: 'NOT_AVAILABLE',
      };
    }
    if (this.ownedUpgradeIds.has(upgradeId)) {
      return {
        success: false,
        cost: 0,
        moneyRemaining: availableMoney,
        reason: 'ALREADY_OWNED',
      };
    }
    if (availableMoney < definition.price) {
      return {
        success: false,
        cost: definition.price,
        moneyRemaining: availableMoney,
        reason: 'INSUFFICIENT_FUNDS',
      };
    }
    this.ownedUpgradeIds.add(upgradeId);
    return {
      success: true,
      cost: definition.price,
      moneyRemaining: availableMoney - definition.price,
    };
  }

  public refit(
    moduleIds: readonly string[],
    dock: Readonly<PortState> | undefined,
    ship: Readonly<ShipCapabilityDefinition>,
  ): RefitResult {
    if (
      !dock ||
      !dock.unlockedServices.includes('DOCK_REFIT')
    ) {
      return { success: false, reason: 'INVALID_DOCK' };
    }
    const uniqueIds = [...new Set(moduleIds)];
    if (uniqueIds.length > ship.moduleSlots) {
      return { success: false, reason: 'TOO_MANY_MODULES' };
    }
    const categories = new Set<string>();
    for (const moduleId of uniqueIds) {
      const definition = this.definitions.get(moduleId);
      if (!definition) {
        return {
          success: false,
          reason: 'NOT_A_MODULE',
        };
      }
      if (!this.ownedUpgradeIds.has(moduleId)) {
        return {
          success: false,
          reason: 'MODULE_NOT_OWNED',
        };
      }
      if (definition.ownershipType !== 'MODULE') {
        return {
          success: false,
          reason: 'NOT_A_MODULE',
        };
      }
      if (categories.has(definition.category)) {
        return {
          success: false,
          reason: 'INCOMPATIBLE_MODULES',
        };
      }
      categories.add(definition.category);
    }
    this.installedModuleIds = uniqueIds;
    return { success: true };
  }

  public computeCapabilities(
    ship: Readonly<ShipCapabilityDefinition>,
  ): ComputedShipCapabilities {
    const result: ComputedShipCapabilities = {
      breakPower: ship.breakPower,
      fuelEfficiency: ship.fuelEfficiency,
      hullDurability: ship.hullDurability,
      agility: ship.agility,
      range: ship.range,
      enginePower: ship.enginePower,
      moduleSlots: ship.moduleSlots,
    };
    const activeDefinitions = [
      ...this.ownedUpgradeIds,
    ]
      .map((id) => this.definitions.get(id))
      .filter(
        (
          definition,
        ): definition is GameplayUpgradeDefinition =>
          Boolean(
            definition &&
              (
                definition.ownershipType === 'PERMANENT' ||
                this.installedModuleIds.includes(definition.id)
              ),
          ),
      );
    for (const definition of activeDefinitions) {
      for (const modifier of definition.statModifiers) {
        const key = STAT_KEYS[modifier.stat];
        result[key] =
          modifier.operation === 'ADD'
            ? result[key] + modifier.value
            : result[key] * modifier.value;
      }
    }
    return result;
  }

  public exportState(): UpgradeInventorySaveData {
    return {
      version: 1,
      availableUpgradeIds: [...this.availableUpgradeIds],
      ownedUpgradeIds: [...this.ownedUpgradeIds],
      installedModuleIds: [...this.installedModuleIds],
    };
  }

  public importState(
    saved: Readonly<UpgradeInventorySaveData>,
  ): boolean {
    if (
      saved.version !== 1 ||
      !Array.isArray(saved.availableUpgradeIds) ||
      !Array.isArray(saved.ownedUpgradeIds) ||
      !Array.isArray(saved.installedModuleIds)
    ) {
      return false;
    }
    this.availableUpgradeIds.clear();
    this.ownedUpgradeIds.clear();
    for (const id of saved.availableUpgradeIds) {
      if (this.definitions.has(id)) {
        this.availableUpgradeIds.add(id);
      }
    }
    for (const id of saved.ownedUpgradeIds) {
      if (this.definitions.has(id)) {
        this.ownedUpgradeIds.add(id);
        this.availableUpgradeIds.add(id);
      }
    }
    const installedCategories = new Set<string>();
    this.installedModuleIds = [];
    for (const id of saved.installedModuleIds) {
      const definition = this.definitions.get(id);
      if (
        !definition ||
        definition.ownershipType !== 'MODULE' ||
        !this.ownedUpgradeIds.has(id) ||
        installedCategories.has(definition.category)
      ) {
        continue;
      }
      installedCategories.add(definition.category);
      this.installedModuleIds.push(id);
    }
    return true;
  }
}
