import { Vector3 } from 'three';

export const clamp = (value: number, min: number, max: number): number =>
  Math.max(min, Math.min(max, value));

export const saturate = (value: number): number => clamp(value, 0, 1);

export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

export const inverseLerp = (a: number, b: number, value: number): number =>
  a === b ? 0 : saturate((value - a) / (b - a));

export const smoothstep = (edge0: number, edge1: number, value: number): number => {
  const t = inverseLerp(edge0, edge1, value);
  return t * t * (3 - 2 * t);
};

export const damp = (current: number, target: number, lambda: number, dt: number): number =>
  lerp(current, target, 1 - Math.exp(-lambda * dt));

export const dampVector3 = (
  current: Vector3,
  target: Vector3,
  lambda: number,
  dt: number,
): Vector3 => current.lerp(target, 1 - Math.exp(-lambda * dt));

export const formatMoney = (value: number): string =>
  new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'EUR',
    maximumFractionDigits: 0,
  }).format(value);

export const formatDuration = (seconds: number): string => {
  const safe = Math.max(0, Math.round(seconds));
  const minutes = Math.floor(safe / 60);
  const rest = safe % 60;
  return minutes > 0 ? `${minutes}:${rest.toString().padStart(2, '0')}` : `${rest}s`;
};

export const hash2D = (x: number, y: number, seed = 0): number => {
  let h = Math.imul(x + seed * 374761393, 668265263) ^ Math.imul(y + seed * 69069, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
};

export const valueNoise2D = (x: number, y: number, seed = 0): number => {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const tx = x - x0;
  const ty = y - y0;
  const sx = tx * tx * (3 - 2 * tx);
  const sy = ty * ty * (3 - 2 * ty);

  const n00 = hash2D(x0, y0, seed);
  const n10 = hash2D(x0 + 1, y0, seed);
  const n01 = hash2D(x0, y0 + 1, seed);
  const n11 = hash2D(x0 + 1, y0 + 1, seed);

  return lerp(lerp(n00, n10, sx), lerp(n01, n11, sx), sy);
};

export const distancePointToSegment = (
  px: number,
  py: number,
  ax: number,
  ay: number,
  bx: number,
  by: number,
): number => {
  const abx = bx - ax;
  const aby = by - ay;
  const apx = px - ax;
  const apy = py - ay;
  const denominator = abx * abx + aby * aby;
  const t = denominator > 0 ? clamp((apx * abx + apy * aby) / denominator, 0, 1) : 0;
  const dx = px - (ax + abx * t);
  const dy = py - (ay + aby * t);
  return Math.hypot(dx, dy);
};

export const polylineLength = (points: Vector3[]): number => {
  let length = 0;
  for (let index = 1; index < points.length; index += 1) {
    const previous = points[index - 1];
    const current = points[index];
    if (previous && current) length += previous.distanceTo(current);
  }
  return length;
};

export const seededPick = <T>(items: T[], seed: number): T => {
  const index = Math.abs(Math.floor(seed * 9973)) % items.length;
  const item = items[index];
  if (item === undefined) throw new Error('Cannot pick from an empty array.');
  return item;
};
