import {
  Color,
  Group,
  Matrix4,
  Mesh,
  MeshStandardMaterial,
  Quaternion,
  Vector3,
  type Material,
  type Object3D,
} from 'three';
import type {
  ConstructionPalette,
  ConstructionSurfaceId,
} from '../ConstructionBlueprint';
import { getConstructionSurface } from '../ConstructionSurfaceCatalog';
import {
  CONSTRUCTION_ASSET_SCHEMA_VERSION,
  constructionUnitsToMetres,
  type ConstructionAssetAxis,
  type ConstructionAssetManifest,
  type ConstructionAssetManifestEntry,
} from './ConstructionAssetContract';

interface LoadedConstructionAsset {
  descriptor: ConstructionAssetManifestEntry;
  object: Group;
}

const axisVector = (axis: ConstructionAssetAxis): Vector3 => {
  const sign = axis.startsWith('-') ? -1 : 1;
  if (axis.endsWith('X')) return new Vector3(sign, 0, 0);
  if (axis.endsWith('Y')) return new Vector3(0, sign, 0);
  return new Vector3(0, 0, sign);
};

export const constructionAxisQuaternion = (
  upAxis: ConstructionAssetAxis,
  forwardAxis: ConstructionAssetAxis,
): Quaternion => {
  const up = axisVector(upAxis);
  const forward = axisVector(forwardAxis);
  const right = new Vector3().crossVectors(up, forward).normalize();
  const sourceBasis = new Matrix4().makeBasis(right, up, forward);
  return new Quaternion().setFromRotationMatrix(sourceBasis.invert());
};

const cloneMaterial = (material: Material): Material => material.clone();

const deepCloneAsset = (source: Readonly<Group>): Group => {
  const clone = source.clone(true);
  clone.traverse((object) => {
    const mesh = object as Mesh;
    if (!mesh.isMesh) return;
    mesh.geometry = mesh.geometry.clone();
    mesh.material = Array.isArray(mesh.material)
      ? mesh.material.map(cloneMaterial)
      : cloneMaterial(mesh.material);
  });
  return clone;
};

export class ConstructionAssetRegistry {
  private readonly assets = new Map<string, LoadedConstructionAsset>();
  private loading?: Promise<number>;

  public preload(manifestUrl: string): Promise<number> {
    this.loading ??= this.load(manifestUrl);
    return this.loading;
  }

  public has(moduleId: string): boolean {
    return this.assets.has(moduleId);
  }

  public create(
    moduleId: string,
    palette: Readonly<ConstructionPalette>,
    colorSlot: keyof ConstructionPalette,
    surfaceId: ConstructionSurfaceId,
    preview: boolean,
  ): Group | undefined {
    const loaded = this.assets.get(moduleId);
    if (!loaded || !loaded.descriptor.replaceProcedural) return undefined;
    const clone = deepCloneAsset(loaded.object);
    const materialModes = new Map(
      (loaded.descriptor.materials ?? []).map((material) => [
        material.sourceMaterial,
        material.mode,
      ]),
    );
    const surface = getConstructionSurface(surfaceId);
    clone.traverse((object) => {
      const mesh = object as Mesh;
      if (!mesh.isMesh) return;
      const materials = Array.isArray(mesh.material)
        ? mesh.material
        : [mesh.material];
      for (const material of materials) {
        const standard = material as MeshStandardMaterial;
        if (
          materialModes.get(material.name) === 'paint' &&
          standard.color instanceof Color
        ) {
          standard.color.set(palette[colorSlot]);
          standard.roughness = surface.roughness;
          standard.metalness = surface.metalness;
        }
        if (preview) {
          standard.transparent = true;
          standard.opacity = 0.52;
          standard.depthWrite = false;
        }
      }
    });
    return clone;
  }

  private async load(manifestUrl: string): Promise<number> {
    const response = await fetch(manifestUrl);
    if (!response.ok) return 0;
    const manifest = (await response.json()) as Partial<ConstructionAssetManifest>;
    if (
      manifest.version !== CONSTRUCTION_ASSET_SCHEMA_VERSION ||
      !Array.isArray(manifest.assets)
    ) {
      console.warn('ICE-A-WAY construction asset manifest is invalid.');
      return 0;
    }
    if (manifest.assets.length === 0) return 0;
    const { ColladaLoader } = await import(
      'three/examples/jsm/loaders/ColladaLoader.js'
    );
    const loader = new ColladaLoader();
    const results = await Promise.allSettled(
      manifest.assets.map(async (descriptor) => {
        const collada = await loader.loadAsync(descriptor.assetUrl);
        const object = new Group();
        object.name = `External construction asset: ${descriptor.moduleId}`;
        const content = collada.scene;
        if (descriptor.normalization === 'sidecar') {
          content.scale.setScalar(constructionUnitsToMetres(descriptor.units));
          content.quaternion.copy(
            constructionAxisQuaternion(
              descriptor.upAxis,
              descriptor.forwardAxis,
            ),
          );
        }
        object.add(content);
        object.updateMatrixWorld(true);
        if (descriptor.pivotNode) {
          const pivot = object.getObjectByName(descriptor.pivotNode);
          if (!pivot) {
            throw new Error(
              `${descriptor.moduleId} is missing pivot node ${descriptor.pivotNode}.`,
            );
          }
          const pivotPosition = pivot.getWorldPosition(new Vector3());
          content.position.sub(pivotPosition);
        }
        for (const nodeName of descriptor.collisionNodes ?? []) {
          const collider = object.getObjectByName(nodeName);
          if (collider) collider.visible = false;
        }
        for (const animation of descriptor.animations ?? []) {
          const node = object.getObjectByName(animation.node);
          if (node) {
            node.userData.constructionAnimation = {
              axis: animation.axis,
              speed: animation.speed,
            };
          }
        }
        this.assets.set(descriptor.moduleId, { descriptor, object });
      }),
    );
    for (const result of results) {
      if (result.status === 'rejected') {
        console.warn('Construction DAE asset could not be loaded.', result.reason);
      }
    }
    return this.assets.size;
  }
}
