import {
  CanvasTexture,
  DoubleSide,
  LinearFilter,
  MeshBasicMaterial,
  NormalBlending,
  OrthographicCamera,
  Scene,
  SRGBColorSpace,
} from 'three';
import {
  BatchedRenderer,
  ColorOverLife,
  ColorRange,
  ConstantValue,
  ForceOverLife,
  Gradient,
  IntervalValue,
  ParticleSystem,
  RectangleEmitter,
  RenderMode,
  Vector4 as ParticleColor,
} from 'three.quarks';
import { clamp, smoothstep } from '../utils/math';
import { calculateWeatherCoverage } from './WeatherCoverage';

interface FogLayer {
  system: ParticleSystem;
  emission: ConstantValue;
  forceX: ConstantValue;
  forceZ: ConstantValue;
  shape: RectangleEmitter;
}

const createFogTexture = (): CanvasTexture => {
  const size = 128;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext('2d');
  if (context) {
    const image = context.createImageData(size, size);
    for (let y = 0; y < size; y += 1) {
      for (let x = 0; x < size; x += 1) {
        const nx = (x + 0.5) / size * 2 - 1;
        const ny = (y + 0.5) / size * 2 - 1;
        const radial = clamp(1 - Math.hypot(nx, ny), 0, 1);
        const cloudNoise =
          0.5 +
          Math.sin(x * 0.12 + Math.sin(y * 0.07) * 2.1) * 0.2 +
          Math.sin(y * 0.18 - x * 0.045) * 0.16 +
          Math.sin((x + y) * 0.31) * 0.08;
        const alpha =
          Math.pow(radial, 0.72) *
          smoothstep(0.18, 0.78, cloudNoise);
        const index = (y * size + x) * 4;
        image.data[index] = 216;
        image.data[index + 1] = 235;
        image.data[index + 2] = 240;
        image.data[index + 3] = Math.round(alpha * 255);
      }
    }
    context.putImageData(image, 0, 0);
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  return texture;
};

export class FogBankSystem {
  private readonly scene: Scene;
  private readonly renderer = new BatchedRenderer();
  private readonly texture = createFogTexture();
  private readonly material = new MeshBasicMaterial({
    color: 0xd9edf0,
    map: this.texture,
    transparent: true,
    opacity: 0.92,
    depthWrite: false,
    depthTest: true,
    alphaTest: 0.004,
    blending: NormalBlending,
    side: DoubleSide,
  });
  private readonly low: FogLayer;
  private readonly high: FogLayer;
  private intensity = 0;

  public constructor(scene: Scene) {
    this.scene = scene;
    this.renderer.name = 'Quarks spatial fog batch';
    this.renderer.renderOrder = 6;
    this.scene.add(this.renderer);
    this.low = this.createLayer({
      height: 3.8,
      lifeMin: 13,
      lifeMax: 20,
      sizeMin: 13,
      sizeMax: 23,
      alphaMin: 0.07,
      alphaMax: 0.13,
    });
    this.high = this.createLayer({
      height: 9,
      lifeMin: 16,
      lifeMax: 24,
      sizeMin: 19,
      sizeMax: 32,
      alphaMin: 0.045,
      alphaMax: 0.09,
    });
  }

  public setIntensity(intensity: number): void {
    const nextIntensity = smoothstep(
      0.18,
      0.78,
      clamp(intensity, 0, 1),
    );
    this.intensity = nextIntensity;
    this.low.emission.value = this.intensity * 4.2;
    this.high.emission.value = this.intensity * 2.1;
  }

  public update(
    deltaSeconds: number,
    camera: OrthographicCamera,
    windX: number,
    windZ: number,
    windStrength: number,
  ): void {
    const coverage = calculateWeatherCoverage(camera);
    const acceleration =
      (0.018 + clamp(windStrength, 0, 2) * 0.045) *
      (0.35 + this.intensity * 0.65);
    for (const layer of [this.low, this.high]) {
      layer.system.emitter.position.x = coverage.centerX;
      layer.system.emitter.position.z = coverage.centerZ;
      layer.shape.width = coverage.width;
      layer.shape.height = coverage.depth;
      layer.forceX.value = windX * acceleration;
      layer.forceZ.value = windZ * acceleration;
    }
    this.renderer.update(clamp(deltaSeconds, 0, 0.1));
  }

  public getActiveParticleCount(): number {
    return this.low.system.particleNum + this.high.system.particleNum;
  }

  public dispose(): void {
    for (const layer of [this.low, this.high]) {
      this.renderer.deleteSystem(layer.system);
      this.scene.remove(layer.system.emitter);
      layer.system.dispose();
    }
    this.scene.remove(this.renderer);
    for (const batch of this.renderer.batches) batch.dispose();
    this.material.dispose();
    this.texture.dispose();
  }

  private createLayer(options: {
    height: number;
    lifeMin: number;
    lifeMax: number;
    sizeMin: number;
    sizeMax: number;
    alphaMin: number;
    alphaMax: number;
  }): FogLayer {
    const emission = new ConstantValue(0);
    const forceX = new ConstantValue(0);
    const forceZ = new ConstantValue(0);
    const shape = new RectangleEmitter({
      width: 100,
      height: 80,
      thickness: 1,
    });
    const system = new ParticleSystem({
      looping: true,
      prewarm: true,
      duration: 18,
      worldSpace: true,
      shape,
      startLife: new IntervalValue(options.lifeMin, options.lifeMax),
      startSpeed: new IntervalValue(0.005, 0.025),
      startRotation: new IntervalValue(0, Math.PI * 2),
      startSize: new IntervalValue(options.sizeMin, options.sizeMax),
      startColor: new ColorRange(
        new ParticleColor(0.82, 0.91, 0.94, options.alphaMin),
        new ParticleColor(0.94, 0.98, 1, options.alphaMax),
      ),
      emissionOverTime: emission,
      behaviors: [
        new ForceOverLife(
          forceX,
          new ConstantValue(0),
          forceZ,
        ),
        new ColorOverLife(
          new Gradient(
            undefined,
            [
              [0, 0],
              [1, 0.18],
              [1, 0.76],
              [0, 1],
            ],
          ),
        ),
      ],
      material: this.material,
      renderMode: RenderMode.BillBoard,
      renderOrder: 6,
    });
    system.emitter.name = 'Spatial fog bank emitter';
    system.emitter.position.y = options.height;
    system.emitter.rotation.x = -Math.PI / 2;
    this.scene.add(system.emitter);
    this.renderer.addSystem(system);
    return {
      system,
      emission,
      forceX,
      forceZ,
      shape,
    };
  }
}
