export interface HarborControlBroadcastDefinition {
  id: string;
  eventType: WorldDomainEvent['type'];
  routeStatus?: 'OPEN' | 'NARROW' | 'CRITICAL' | 'BLOCKED';
  incidentStatus?: 'REPORTED' | 'RESOLVED';
  copyKey: HarborControlCopyKey;
  stationId: string;
  channelType: RadioChannelType;
  frequencyId: string;
  category: RadioCategory;
  priority: number;
  lifetimeSeconds: number;
  cooldownSeconds: number;
}

const HARBOR_STATION_ID = 'borealis-harbor-control';
