const HARBOR_CHANNEL: RadioChannelType = 'HARBOR_CONTROL';

const harborDefinition = (
  definition: Omit<
    HarborControlBroadcastDefinition,
    'stationId' | 'channelType' | 'frequencyId'
  >,
): HarborControlBroadcastDefinition => ({
  ...definition,
  stationId: HARBOR_STATION_ID,
  channelType: HARBOR_CHANNEL,
  frequencyId: HARBOR_FREQUENCY_ID,
});

