const definitionsById = new Map(
  HARBOR_CONTROL_BROADCAST_DEFINITIONS.map(
    (definition) => [definition.id, definition],
  ),
);

export const getHarborControlBroadcastDefinition = (
  definitionId: string,
): HarborControlBroadcastDefinition | undefined =>
  definitionsById.get(definitionId);

const definitionForEvent = (
  event: Readonly<WorldDomainEvent>,
): HarborControlBroadcastDefinition | undefined =>
  HARBOR_CONTROL_BROADCAST_DEFINITIONS.find(
    (definition) =>
      definition.eventType === event.type &&
      (definition.routeStatus === undefined ||
        (event.type === 'ROUTE_CONDITION_CHANGED' &&
          event.status === definition.routeStatus)) &&
      (definition.incidentStatus === undefined ||
        (event.type === 'WORLD_INCIDENT_CHANGED' &&
          event.status === definition.incidentStatus)),
  );

const draftFromDefinition = (
  definition: Readonly<HarborControlBroadcastDefinition>,
  dedupeKey: string,
  context: RadioBroadcastContext,
  supersessionKey?: string,
): HarborControlBroadcastDraft => ({
  definitionId: definition.id,
  copyKey: definition.copyKey,
  stationId: definition.stationId,
  channelType: definition.channelType,
  frequencyId: definition.frequencyId,
  category: definition.category,
  priority: definition.priority,
  lifetimeSeconds: definition.lifetimeSeconds,
  dedupeKey,
  cooldownSeconds: definition.cooldownSeconds,
  ...(supersessionKey ? { supersessionKey } : {}),
  context,
});

export const createHarborControlBroadcastDraft = (
  event: Readonly<WorldDomainEvent>,
): HarborControlBroadcastDraft | undefined => {
  if (event.type === 'ROUTE_CONDITION_CHANGED') {
    if (event.status === 'NARROW') return undefined;
    if (
      event.status === 'CRITICAL' &&
      ['CRITICAL', 'BLOCKED'].includes(event.previousStatus)
    ) {
      return undefined;
    }
    if (
      event.status === 'BLOCKED' &&
      event.previousStatus === 'CRITICAL'
    ) {
      return undefined;
    }
  }
  const definition = definitionForEvent(event);
  if (!definition) return undefined;

  switch (event.type) {
    case 'ROUTE_CONDITION_CHANGED':
      if (event.status === 'UNKNOWN') return undefined;
      return draftFromDefinition(
        definition,
        `route:${event.routeId}:condition:${event.status}`,
        {
          routeId: event.routeId,
          routeStatus: event.status,
        },
        `route:${event.routeId}:condition`,
      );
    case 'ROUTE_CAPACITY_CHANGED':
      return draftFromDefinition(
        definition,
        `route:${event.routeId}:capacity:${event.widthClass}`,
        {
          routeId: event.routeId,
          previousWidthClass: event.previousWidthClass,
          widthClass: event.widthClass,
        },
        `route:${event.routeId}:capacity`,
      );
    case 'SHIP_DEPARTED':
      return draftFromDefinition(
        definition,
        `trip:${event.tripId}:departed`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          originPortId: event.originPortId,
          destinationPortId: event.destinationPortId,
          tripId: event.tripId,
        },
        `ship:${event.shipId}:navigation`,
      );
    case 'SHIP_WAITING':
      return draftFromDefinition(
        definition,
        `ship:${event.shipId}:route:${event.routeId}:waiting`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          incidentId: event.incidentId,
        },
        `ship:${event.shipId}:navigation`,
      );
    case 'SHIP_STUCK':
      return draftFromDefinition(
        definition,
        `incident:${event.incidentId}:stuck`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          incidentId: event.incidentId,
        },
        `incident:${event.incidentId}:assistance`,
      );
    case 'SHIP_RESUMED':
      return draftFromDefinition(
        definition,
        `incident:${event.incidentId}:resumed`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          incidentId: event.incidentId,
        },
        `ship:${event.shipId}:navigation`,
      );
    case 'SHIP_ESCORT_STARTED':
      return draftFromDefinition(
        definition,
        `escort:${event.escortId}:started`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          incidentId: event.incidentId,
          escortId: event.escortId,
        },
        `incident:${event.incidentId}:assistance`,
      );
    case 'SHIP_ESCORT_PAUSED':
      return draftFromDefinition(
        definition,
        `escort:${event.escortId}:paused:${event.eventId}`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          incidentId: event.incidentId,
          escortId: event.escortId,
          escortPauseReason: event.reason,
        },
        `incident:${event.incidentId}:assistance`,
      );
    case 'SHIP_ESCORT_RESUMED':
      return draftFromDefinition(
        definition,
        `escort:${event.escortId}:resumed:${event.eventId}`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          incidentId: event.incidentId,
          escortId: event.escortId,
        },
        `incident:${event.incidentId}:assistance`,
      );
    case 'SHIP_RESCUED':
      if (!event.routeId || !event.incidentId) {
        return undefined;
      }
      return draftFromDefinition(
        definition,
        `incident:${event.incidentId}:resolved`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          incidentId: event.incidentId,
        },
        `incident:${event.incidentId}:assistance`,
      );
    case 'SHIP_ARRIVED':
      return draftFromDefinition(
        definition,
        `trip:${event.tripId}:arrived`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          portId: event.portId,
          tripId: event.tripId,
        },
        `ship:${event.shipId}:navigation`,
      );
    case 'PORT_CARGO_DELIVERED':
      return draftFromDefinition(
        definition,
        `trip:${event.tripId}:delivery`,
        {
          shipId: event.shipId,
          portId: event.portId,
          tripId: event.tripId,
          goodType: event.goodType,
          amount: event.amount,
        },
      );
    case 'WEATHER_REPORT_UPDATED':
      return draftFromDefinition(
        definition,
        `weather:${event.regionId}:${event.weatherKind}`,
        {
          weatherKind: event.weatherKind,
          windMultiplier: event.windMultiplier,
          fogDensity: event.fogDensity,
          snowIntensity: event.snowIntensity,
          refreezeMultiplier: event.refreezeMultiplier,
        },
        `weather:${event.regionId}`,
      );
    case 'LOCAL_PORT_NOTICE':
      return draftFromDefinition(
        definition,
        `port:${event.portId}:notice:${event.noticeCode}`,
        {
          portId: event.portId,
          noticeCode: event.noticeCode,
          supplySatisfaction: event.supplySatisfaction,
          traffic: event.traffic,
          developmentProgress: event.developmentProgress,
        },
        `port:${event.portId}:local-notice`,
      );
    case 'OPEN_BAND_TRAFFIC':
      return draftFromDefinition(
        definition,
        `open-band:${event.shipId}:${event.navigationStatus}`,
        {
          shipId: event.shipId,
          routeId: event.routeId,
          destinationPortId: event.destinationPortId,
          navigationStatus: event.navigationStatus,
        },
        `open-band:${event.shipId}:navigation`,
      );
    case 'MYSTERY_BROADCAST_AVAILABLE':
      return draftFromDefinition(
        definition,
        `mystery:${event.broadcastId}`,
        {
          mysteryBroadcastId: event.broadcastId,
          clueCode: event.clueCode,
          musicTrackId: event.musicTrackId,
        },
      );
    case 'WORLD_INCIDENT_CHANGED':
      if (event.status !== 'REPORTED' && event.status !== 'RESOLVED') return undefined;
      return draftFromDefinition(
        definition,
        `incident:${event.incidentId}:${event.status.toLowerCase()}`,
        {
          incidentId: event.incidentId,
          npcId: event.subjectId,
          incidentStatus: event.status,
        },
        `incident:${event.incidentId}:land-assistance`,
      );
    default:
      return undefined;
  }
};

const nonEmpty = (value: unknown): value is string =>
  typeof value === 'string' && value.trim().length > 0;

const ROUTE_BROADCAST_STATUSES = new Set([
  'OPEN',
  'NARROW',
  'CRITICAL',
  'BLOCKED',
]);

export const isValidHarborBroadcastContext = (
  copyKey: HarborControlCopyKey,
  context: Readonly<RadioBroadcastContext>,
): boolean => {
  switch (copyKey) {
    case 'ROUTE_CONDITION':
      return (
        nonEmpty(context.routeId) &&
        ROUTE_BROADCAST_STATUSES.has(
          String(context.routeStatus),
        )
      );
    case 'ROUTE_CAPACITY':
      return (
        nonEmpty(context.routeId) &&
        ['SMALL', 'STANDARD', 'HEAVY'].includes(
          String(context.previousWidthClass),
        ) &&
        ['SMALL', 'STANDARD', 'HEAVY'].includes(
          String(context.widthClass),
        )
      );
    case 'SHIP_DEPARTED':
      return (
        nonEmpty(context.shipId) &&
        nonEmpty(context.routeId) &&
        nonEmpty(context.originPortId) &&
        nonEmpty(context.destinationPortId) &&
        nonEmpty(context.tripId)
      );
    case 'SHIP_WAITING':
    case 'SHIP_RESUMED':
    case 'SHIP_STUCK':
    case 'INCIDENT_RESOLVED':
      return (
        nonEmpty(context.shipId) &&
        nonEmpty(context.routeId) &&
        nonEmpty(context.incidentId)
      );
    case 'ESCORT_STARTED':
    case 'ESCORT_RESUMED':
      return (
        nonEmpty(context.shipId) &&
        nonEmpty(context.routeId) &&
        nonEmpty(context.incidentId) &&
        nonEmpty(context.escortId)
      );
    case 'ESCORT_PAUSED':
      return (
        nonEmpty(context.shipId) &&
        nonEmpty(context.routeId) &&
        nonEmpty(context.incidentId) &&
        nonEmpty(context.escortId) &&
        [
          'UNSAFE_ROUTE',
          'PLAYER_TOO_FAR',
          'PLAYER_OFF_CORRIDOR',
          'WAITING_FOR_LEAD',
        ].includes(String(context.escortPauseReason))
      );
    case 'SHIP_ARRIVED':
      return (
        nonEmpty(context.shipId) &&
        nonEmpty(context.routeId) &&
        nonEmpty(context.portId) &&
        nonEmpty(context.tripId)
      );
    case 'PORT_CARGO_DELIVERED':
      return (
        nonEmpty(context.shipId) &&
        nonEmpty(context.portId) &&
        nonEmpty(context.tripId) &&
        nonEmpty(context.goodType) &&
        Number.isFinite(context.amount) &&
        (context.amount ?? 0) > 0
      );
    case 'WEATHER_REPORT':
      return (
        nonEmpty(context.weatherKind) &&
        Number.isFinite(context.windMultiplier) &&
        Number.isFinite(context.fogDensity) &&
        Number.isFinite(context.snowIntensity) &&
        Number.isFinite(context.refreezeMultiplier)
      );
    case 'LOCAL_PORT_NOTICE':
      return (
        nonEmpty(context.portId) &&
        nonEmpty(context.noticeCode) &&
        Number.isFinite(context.supplySatisfaction) &&
        Number.isFinite(context.traffic) &&
        Number.isFinite(context.developmentProgress)
      );
    case 'OPEN_BAND_TRAFFIC':
      return (
        nonEmpty(context.shipId) &&
        nonEmpty(context.routeId) &&
        nonEmpty(context.destinationPortId) &&
        nonEmpty(context.navigationStatus)
      );
    case 'MYSTERY_BROADCAST':
      return (
        nonEmpty(context.mysteryBroadcastId) &&
        nonEmpty(context.clueCode) &&
        nonEmpty(context.musicTrackId)
      );
    case 'NPC_DISTRESS':
    case 'NPC_INCIDENT_RESOLVED':
      return (
        nonEmpty(context.incidentId) &&
        nonEmpty(context.npcId) &&
        nonEmpty(context.incidentStatus)
      );
  }
};
