import {
  DEFAULT_VISUAL_PROFILE_ID,
  type VisualProfileId,
} from './VisualProfile';
import { OCEAN_V3_FEATURES } from './OceanV3';

export type OceanDebugLayerId =
  | 'cloudPatches'
  | 'depthColor'
  | 'voronoi'
  | 'surfaceWaves'
  | 'microRipples'
  | 'waveHighlights'
  | 'currentRibbons'
  | 'edgeFoam'
  | 'windShimmer'
  | 'skyReflection'
  | 'celestialGlint';

export type OceanDebugLayerState = Record<
  OceanDebugLayerId,
  boolean
>;

export const LEGACY_OCEAN_DEBUG_DEFAULTS: Readonly<OceanDebugLayerState> =
  Object.freeze({
    cloudPatches: false,
    depthColor: true,
    voronoi: false,
    surfaceWaves: true,
    microRipples: false,
    waveHighlights: false,
    currentRibbons: true,
    edgeFoam: true,
    windShimmer: true,
    skyReflection: true,
    celestialGlint: false,
  });

export const OCEAN_V3_DEBUG_DEFAULTS: Readonly<OceanDebugLayerState> =
  Object.freeze({
    cloudPatches: false,
    depthColor: OCEAN_V3_FEATURES.bathymetry,
    voronoi: false,
    surfaceWaves: OCEAN_V3_FEATURES.dynamics,
    microRipples: false,
    waveHighlights: false,
    currentRibbons: false,
    edgeFoam: OCEAN_V3_FEATURES.interactions,
    windShimmer: false,
    skyReflection: OCEAN_V3_FEATURES.skyReflection,
    celestialGlint: false,
  });

const copyState = (
  source: Readonly<OceanDebugLayerState>,
): OceanDebugLayerState => ({ ...source });

export class OceanDebugStateController {
  private readonly state: OceanDebugLayerState;
  private readonly legacyState =
    copyState(LEGACY_OCEAN_DEBUG_DEFAULTS);
  private profile: VisualProfileId;

  public constructor(
    initialProfile: VisualProfileId = DEFAULT_VISUAL_PROFILE_ID,
  ) {
    this.profile = initialProfile;
    this.state = copyState(
      initialProfile === 'ocean-v3'
        ? OCEAN_V3_DEBUG_DEFAULTS
        : LEGACY_OCEAN_DEBUG_DEFAULTS,
    );
  }

  public setProfile(profile: VisualProfileId): void {
    const previous = this.profile;
    if (profile === 'ocean-v3') {
      if (previous !== 'ocean-v3') {
        Object.assign(this.legacyState, this.state);
      }
      Object.assign(this.state, OCEAN_V3_DEBUG_DEFAULTS);
    } else if (previous === 'ocean-v3') {
      Object.assign(this.state, this.legacyState);
    }
    this.profile = profile;
  }

  public toggle(layer: OceanDebugLayerId): boolean {
    const enabled = !this.state[layer];
    this.state[layer] = enabled;
    return enabled;
  }

  public getState(): Readonly<OceanDebugLayerState> {
    return this.state;
  }
}
