import {
  AnimationAction,
  AnimationClip,
  AnimationMixer,
  Box3,
  BoxGeometry,
  BufferAttribute,
  BufferGeometry,
  Color,
  ConeGeometry,
  DataTexture,
  Group,
  LinearFilter,
  LoopOnce,
  LoopRepeat,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  Points,
  PointsMaterial,
  RGBAFormat,
  SphereGeometry,
  Texture,
  UnsignedByteType,
  Vector3,
  type Camera,
  type Scene,
  type WebGLRenderer,
} from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { clamp, damp, hash2D } from '../utils/math';
import type { PenguinState } from './PenguinSimulation';

const penguinModelUrl = './assets/models/low-poly-penguin.glb';

interface BlowerParticle {
  x: number;
  y: number;
  z: number;
  velocityX: number;
  velocityY: number;
  velocityZ: number;
  life: number;
}

const PENGUIN_HEIGHT = 1.18;
const PARTICLE_COUNT = 112;
const BLOWER_FORWARD_OFFSET = 0.82;
const BLOWER_RIGHT_OFFSET = 0.3;

interface PenguinAnimationActions {
  idle: AnimationAction;
  walk: AnimationAction;
  blower: AnimationAction;
}

export const writePenguinBlowerOrigin = (
  state: Readonly<Pick<PenguinState, 'x' | 'z' | 'heading'>>,
  target: { x: number; z: number },
): void => {
  const forwardX = Math.sin(state.heading);
  const forwardZ = Math.cos(state.heading);
  const rightX = Math.cos(state.heading);
  const rightZ = -Math.sin(state.heading);
  target.x =
    state.x +
    forwardX * BLOWER_FORWARD_OFFSET +
    rightX * BLOWER_RIGHT_OFFSET;
  target.z =
    state.z +
    forwardZ * BLOWER_FORWARD_OFFSET +
    rightZ * BLOWER_RIGHT_OFFSET;
};

const createSnowParticleTexture = (): DataTexture => {
  const size = 24;
  const data = new Uint8Array(size * size * 4);
  for (let row = 0; row < size; row += 1) {
    for (let column = 0; column < size; column += 1) {
      const x = ((column + 0.5) / size) * 2 - 1;
      const y = ((row + 0.5) / size) * 2 - 1;
      const alpha = Math.round(
        clamp(1 - Math.hypot(x, y), 0, 1) ** 1.6 * 255,
      );
      const offset = (row * size + column) * 4;
      data[offset] = 238;
      data[offset + 1] = 250;
      data[offset + 2] = 252;
      data[offset + 3] = alpha;
    }
  }
  const texture = new DataTexture(
    data,
    size,
    size,
    RGBAFormat,
    UnsignedByteType,
  );
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.needsUpdate = true;
  return texture;
};

const stripRootMotion = (clip: AnimationClip): AnimationClip => {
  const filtered = clip.tracks.filter(
    (track) => {
      const name = track.name.replace(/^.*\//, '');
      return (
        !/^(Root|Hip|Armature)\.position$/.test(name) &&
        name !== 'Root.quaternion'
      );
    },
  );
  return new AnimationClip(clip.name, clip.duration, filtered, clip.blendMode);
};

export class PenguinPresenter {
  private readonly group = new Group();
  private readonly modelRoot = new Group();
  private readonly blower = new Group();
  private readonly blowerOrigin = { x: 0, z: 0 };
  private readonly handWorldPosition = new Vector3();
  private readonly materials: MeshStandardMaterial[] = [];
  private readonly particleTexture = createSnowParticleTexture();
  private readonly particles: BlowerParticle[] = Array.from(
    { length: PARTICLE_COUNT },
    () => ({
      x: 0,
      y: -10,
      z: 0,
      velocityX: 0,
      velocityY: 0,
      velocityZ: 0,
      life: 0,
    }),
  );
  private readonly particlePositions = new Float32Array(PARTICLE_COUNT * 3);
  private readonly particleGeometry = new BufferGeometry();
  private readonly particleMaterial = new PointsMaterial({
    color: new Color(0xbadfe6),
    size: 4.6,
    map: this.particleTexture,
    transparent: true,
    opacity: 0.9,
    alphaTest: 0.02,
    depthWrite: false,
  });
  private readonly particlePoints: Points;
  private mixer?: AnimationMixer;
  private readonly actions: AnimationAction[] = [];
  private animationActions?: PenguinAnimationActions;
  private activeAction?: AnimationAction;
  private visible = false;
  private loaded = false;
  private surfaceY = 0;
  private particleCursor = 0;
  private animationNames: string[] = [];
  private modelLoadFailed = false;
  private rightHand?: Object3D;

  public constructor(
    private readonly scene: Scene,
    private readonly renderer?: WebGLRenderer,
    private readonly camera?: Camera,
  ) {
    this.group.name = 'Player penguin character';
    this.group.add(this.modelRoot);
    this.createLeafBlower();
    this.createFallbackPenguin();
    this.particleGeometry.setAttribute(
      'position',
      new BufferAttribute(this.particlePositions, 3),
    );
    this.particlePoints = new Points(
      this.particleGeometry,
      this.particleMaterial,
    );
    this.particlePoints.name = 'Leaf blower snow plume';
    this.particlePoints.frustumCulled = false;
    this.scene.add(this.group, this.particlePoints);
    this.setVisible(false);
    void this.loadModel();
  }

  public setVisible(visible: boolean): void {
    this.visible = visible;
    this.group.visible = visible;
    this.particlePoints.visible = visible;
  }

  public update(
    state: Readonly<PenguinState>,
    deltaSeconds: number,
    targetSurfaceY: number,
  ): void {
    const delta = clamp(deltaSeconds, 0, 0.05);
    this.surfaceY = deltaSeconds <= 0
      ? targetSurfaceY
      : damp(this.surfaceY, targetSurfaceY, 9, delta);
    this.group.position.set(state.x, this.surfaceY, state.z);
    this.group.rotation.y = state.heading;
    this.blower.visible = true;
    this.selectAnimation(state);
    this.mixer?.update(delta);
    this.syncBlowerToHand();
    if (state.blowerActive && this.visible) this.emitBlowerSnow(state);
    this.updateParticles(delta);
  }

  public getStats(): {
    loaded: boolean;
    modelLoadFailed: boolean;
    animationNames: readonly string[];
    triangles: number;
  } {
    return {
      loaded: this.loaded,
      modelLoadFailed: this.modelLoadFailed,
      animationNames: this.animationNames,
      triangles: 482,
    };
  }

  public dispose(): void {
    this.group.traverse((object) => {
      if (object instanceof Mesh) object.geometry.dispose();
    });
    for (const material of this.materials) material.dispose();
    this.particleGeometry.dispose();
    this.particleMaterial.dispose();
    this.particleTexture.dispose();
    this.group.removeFromParent();
    this.particlePoints.removeFromParent();
  }

  private async loadModel(): Promise<void> {
    try {
      const gltf = await new GLTFLoader().loadAsync(penguinModelUrl);
      const bounds = new Box3().setFromObject(gltf.scene);
      const size = bounds.getSize(new Vector3());
      const scale = PENGUIN_HEIGHT / Math.max(0.001, size.y);
      gltf.scene.scale.setScalar(scale);
      gltf.scene.position.y = -bounds.min.y * scale;
      gltf.scene.name = 'Animated low-poly penguin';
      gltf.scene.traverse((object) => {
        if (!(object instanceof Mesh)) return;
        object.castShadow = true;
        object.receiveShadow = true;
      });
      for (const child of [...this.modelRoot.children]) {
        if (child === this.blower) continue;
        child.traverse((object) => {
          if (object instanceof Mesh) object.geometry.dispose();
        });
        child.removeFromParent();
      }
      this.modelRoot.add(gltf.scene);
      this.rightHand = gltf.scene.getObjectByName('R_Hand');
      this.mixer = new AnimationMixer(gltf.scene);
      const clips = gltf.animations.map(stripRootMotion);
      this.animationNames = clips.map((clip) => clip.name);
      this.actions.push(...clips.map((clip) => this.mixer!.clipAction(clip)));
      this.actions.forEach((action) => action.setEffectiveWeight(1));
      // The source GLB exports generic NlaTrack names. Its stable order is
      // idle, walk, long character action and stationary work pose.
      const idle = this.actions[0];
      const walk = this.actions[1] ?? idle;
      const blower = this.actions[3] ?? idle;
      if (idle && walk && blower) {
        walk.setLoop(LoopRepeat, Number.POSITIVE_INFINITY);
        this.animationActions = { idle, walk, blower };
      }
      this.loaded = true;
      if (this.animationActions) {
        this.selectAction(this.animationActions.idle, true);
      }
      this.prewarmGpuResources(this.scene, gltf.scene);
    } catch (error) {
      this.modelLoadFailed = true;
      console.warn('ICEWAY penguin model could not be loaded.', error);
    }
  }

  private selectAnimation(state: Readonly<PenguinState>): void {
    if (!this.animationActions) return;
    const speed = Math.abs(state.speed);
    const requested = speed > 0.08
      ? this.animationActions.walk
      : state.blowerActive
        ? this.animationActions.blower
        : this.animationActions.idle;
    this.selectAction(requested);
    const timeScale = state.blowerActive
      ? 1
      : speed > 0.08
        ? clamp(speed / 1.15, 0.4, 1.65)
        : 1;
    this.activeAction?.setEffectiveTimeScale(timeScale);
  }

  private selectAction(action: AnimationAction, immediate = false): void {
    if (action === this.activeAction) return;
    action.reset().play();
    if (action.getClip().duration < 1) action.setLoop(LoopOnce, 1);
    if (this.activeAction && !immediate) {
      action.crossFadeFrom(this.activeAction, 0.18, true);
    } else {
      action.fadeIn(immediate ? 0 : 0.18);
    }
    this.activeAction = action;
  }

  private createFallbackPenguin(): void {
    const black = this.material(0x26383d, 0.82, 0.02);
    const white = this.material(0xe7f1ee, 0.88, 0);
    const orange = this.material(0xeaa03d, 0.74, 0.02);
    const body = new Mesh(new SphereGeometry(0.42, 12, 9), black);
    body.scale.y = 1.25;
    body.position.y = 0.56;
    const belly = new Mesh(new SphereGeometry(0.3, 12, 8), white);
    belly.scale.set(0.78, 1.2, 0.3);
    belly.position.set(0, 0.55, 0.33);
    const beak = new Mesh(new ConeGeometry(0.12, 0.3, 6), orange);
    beak.rotation.x = Math.PI / 2;
    beak.position.set(0, 0.88, 0.38);
    for (const mesh of [body, belly, beak]) {
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      this.modelRoot.add(mesh);
    }
    this.blower.position.set(0.37, 0.58, 0.04);
    this.modelRoot.add(this.blower);
  }

  private createLeafBlower(): void {
    const orange = this.material(0xf2a13d, 0.64, 0.05);
    const dark = this.material(0x34464a, 0.76, 0.16);
    const body = new Mesh(new BoxGeometry(0.33, 0.28, 0.42), orange);
    body.position.set(0, -0.08, 0);
    const handle = new Mesh(new BoxGeometry(0.12, 0.2, 0.16), dark);
    handle.position.set(0, 0.12, -0.02);
    const tube = new Mesh(new ConeGeometry(0.12, 0.82, 9, 1, true), dark);
    tube.rotation.x = Math.PI / 2;
    tube.position.set(0, -0.12, 0.47);
    for (const mesh of [body, handle, tube]) {
      mesh.castShadow = true;
      this.blower.add(mesh);
    }
    this.blower.name = 'Penguin handheld leaf blower';
    this.modelRoot.add(this.blower);
  }

  private emitBlowerSnow(state: Readonly<PenguinState>): void {
    const forwardX = Math.sin(state.heading);
    const forwardZ = Math.cos(state.heading);
    const rightX = Math.cos(state.heading);
    const rightZ = -Math.sin(state.heading);
    writePenguinBlowerOrigin(state, this.blowerOrigin);
    for (let index = 0; index < 4; index += 1) {
      const particle = this.particles[this.particleCursor]!;
      this.particleCursor = (this.particleCursor + 1) % PARTICLE_COUNT;
      const random = hash2D(this.particleCursor, index, 614);
      const side = random * 2 - 1;
      particle.x =
        this.blowerOrigin.x + forwardX * random * 0.1 + rightX * side * 0.035;
      particle.y = this.surfaceY + 0.42 + random * 0.08;
      particle.z =
        this.blowerOrigin.z + forwardZ * random * 0.1 + rightZ * side * 0.035;
      particle.velocityX =
        forwardX * (3.2 + random * 2.1) + rightX * side * 0.48;
      particle.velocityY = 0.18 + random * 0.52;
      particle.velocityZ =
        forwardZ * (3.2 + random * 2.1) + rightZ * side * 0.48;
      particle.life = 0.42 + random * 0.48;
    }
  }

  private syncBlowerToHand(): void {
    if (!this.rightHand) return;
    this.group.updateMatrixWorld(true);
    this.rightHand.getWorldPosition(this.handWorldPosition);
    this.modelRoot.worldToLocal(this.handWorldPosition);
    this.blower.position.copy(this.handWorldPosition);
  }

  private prewarmGpuResources(scene: Scene, model: Object3D): void {
    if (!this.renderer || !this.camera) return;
    model.traverse((object) => {
      if (!(object instanceof Mesh)) return;
      const materials = Array.isArray(object.material)
        ? object.material
        : [object.material];
      for (const material of materials) {
        for (const value of Object.values(material)) {
          if (value instanceof Texture) this.renderer!.initTexture(value);
        }
      }
    });
    const groupWasVisible = this.group.visible;
    const particlesWereVisible = this.particlePoints.visible;
    this.group.visible = true;
    this.particlePoints.visible = true;
    const compilation = this.renderer.compileAsync(scene, this.camera);
    this.group.visible = groupWasVisible;
    this.particlePoints.visible = particlesWereVisible;
    void compilation.catch((error) => {
      console.warn('ICEWAY penguin shader prewarm failed.', error);
    });
  }

  private updateParticles(deltaSeconds: number): void {
    for (let index = 0; index < this.particles.length; index += 1) {
      const particle = this.particles[index]!;
      if (particle.life > 0) {
        particle.life -= deltaSeconds;
        particle.x += particle.velocityX * deltaSeconds;
        particle.y += particle.velocityY * deltaSeconds;
        particle.z += particle.velocityZ * deltaSeconds;
        particle.velocityY -= 2.2 * deltaSeconds;
        particle.velocityX *= 1 - deltaSeconds * 0.9;
        particle.velocityZ *= 1 - deltaSeconds * 0.9;
      } else {
        particle.y = -10;
      }
      this.particlePositions[index * 3] = particle.x;
      this.particlePositions[index * 3 + 1] = particle.y;
      this.particlePositions[index * 3 + 2] = particle.z;
    }
    this.particleGeometry.getAttribute('position').needsUpdate = true;
  }

  private material(
    color: number,
    roughness: number,
    metalness: number,
  ): MeshStandardMaterial {
    const material = new MeshStandardMaterial({ color, roughness, metalness });
    this.materials.push(material);
    return material;
  }
}
