import {
  BufferAttribute,
  BufferGeometry,
  Color,
  ConeGeometry,
  CylinderGeometry,
  IcosahedronGeometry,
  InstancedMesh,
  Matrix4,
  MeshStandardMaterial,
  Object3D,
  Scene,
} from 'three';
import {
  OCEAN_SEA_LEVEL,
  type OceanCurrentSample,
  type OceanEnvironmentSample,
  OceanField,
  type OceanSurfaceSample,
} from '../ocean/OceanField';
import { clamp, lerp } from '../utils/math';
import type {
  IcebergDefinition,
  IcebergPlacementExclusion,
  IcebergShape,
  IcebergSize,
  IcebergStats,
  VesselCollisionObstacle,
  VesselObstacleContact,
  VesselObstacleWorld,
} from '../world/IcebergTypes';

interface IcebergWorldBounds {
  halfWidth: number;
  halfHeight: number;
  padding: number;
}

interface IcebergMotionProfile {
  currentResponse: number;
  windResponse: number;
  velocityResponse: number;
  angularResponse: number;
  waveResponse: number;
  pushability: number;
  resistance: number;
  maximumSpeed: number;
}

interface RuntimeIceberg extends VesselCollisionObstacle {
  size: IcebergSize;
  shape: IcebergShape;
  visualRadius: number;
  height: number;
  yaw: number;
  angularVelocity: number;
  grounded: boolean;
  colorMix: number;
  phase: number;
  instanceIndex: number;
  capIndex: number;
}

const SHAPES: readonly IcebergShape[] = [
  'dome',
  'pinnacle',
  'tabular',
  'wedge',
];

const MOTION_PROFILES: Record<IcebergSize, IcebergMotionProfile> = {
  growler: {
    currentResponse: 0.68,
    windResponse: 0.006,
    velocityResponse: 0.9,
    angularResponse: 0.7,
    waveResponse: 0.95,
    pushability: 0.78,
    resistance: 0.3,
    maximumSpeed: 0.12,
  },
  small: {
    currentResponse: 0.5,
    windResponse: 0.004,
    velocityResponse: 0.62,
    angularResponse: 0.48,
    waveResponse: 0.72,
    pushability: 0.52,
    resistance: 0.5,
    maximumSpeed: 0.085,
  },
  medium: {
    currentResponse: 0.3,
    windResponse: 0.002,
    velocityResponse: 0.38,
    angularResponse: 0.28,
    waveResponse: 0.48,
    pushability: 0.12,
    resistance: 0.82,
    maximumSpeed: 0.052,
  },
  large: {
    currentResponse: 0.15,
    windResponse: 0.0008,
    velocityResponse: 0.2,
    angularResponse: 0.12,
    waveResponse: 0.28,
    pushability: 0.025,
    resistance: 0.98,
    maximumSpeed: 0.028,
  },
};

const ICEBERG_COLORS: Record<IcebergSize, number> = {
  growler: 0xe0faf7,
  small: 0xcdf3f2,
  medium: 0xb9ebef,
  large: 0xa8e0ea,
};

const createIcebergGeometry = (shape: IcebergShape): BufferGeometry => {
  if (shape === 'dome') {
    const geometry = new IcosahedronGeometry(1, 1);
    geometry.scale(1, 0.5, 0.92);
    geometry.translate(0, 0.5, 0);
    return geometry;
  }

  if (shape === 'pinnacle') {
    const geometry = new ConeGeometry(1, 1, 7, 2);
    geometry.translate(0, 0.5, 0);
    return geometry;
  }

  if (shape === 'tabular') {
    const geometry = new CylinderGeometry(0.88, 1, 1, 8, 2);
    geometry.translate(0, 0.5, 0);
    return geometry;
  }

  const geometry = new ConeGeometry(1, 1, 7, 2);
  const positions = geometry.getAttribute('position') as BufferAttribute;
  for (let index = 0; index < positions.count; index += 1) {
    const y = positions.getY(index) + 0.5;
    positions.setXYZ(
      index,
      positions.getX(index) + y * 0.46,
      y,
      positions.getZ(index) * lerp(1, 0.72, y),
    );
  }
  positions.needsUpdate = true;
  geometry.computeVertexNormals();
  return geometry;
};

const countByShape = (
  definitions: readonly IcebergDefinition[],
  shape: IcebergShape,
): number => definitions.filter((definition) => definition.shape === shape).length;

export class IcebergSystem implements VesselObstacleWorld {
  private readonly scene: Scene;
  private readonly oceanField: OceanField;
  private readonly landObstacles: readonly IcebergPlacementExclusion[];
  private readonly bounds: IcebergWorldBounds;
  private readonly material = new MeshStandardMaterial({
    color: 0xffffff,
    emissive: 0x174552,
    emissiveIntensity: 0.24,
    roughness: 0.72,
    metalness: 0.02,
    flatShading: true,
    vertexColors: true,
  });
  private readonly capMaterial = new MeshStandardMaterial({
    color: 0xf2fcf8,
    emissive: 0x5f8583,
    emissiveIntensity: 0.18,
    roughness: 0.88,
    flatShading: true,
  });
  private readonly meshes = new Map<IcebergShape, InstancedMesh>();
  private readonly capMesh?: InstancedMesh;
  private readonly icebergs: RuntimeIceberg[] = [];
  private readonly icebergsById = new Map<string, RuntimeIceberg>();
  private readonly dummy = new Object3D();
  private readonly capDummy = new Object3D();
  private readonly identity = new Matrix4();
  private readonly color = new Color();
  private readonly colorHighlight = new Color(0xe9fbf7);
  private readonly current: OceanCurrentSample = {
    x: 0,
    z: 0,
    angularVelocity: 0,
  };
  private readonly environment: OceanEnvironmentSample = {
    depth: 0.5,
    seaState: 0.5,
    windX: 1,
    windZ: 0,
    windStrength: 0.5,
    waveExposure: 1,
  };
  private readonly surface: OceanSurfaceSample = {
    height: OCEAN_SEA_LEVEL,
    normalX: 0,
    normalY: 1,
    normalZ: 0,
  };

  private simulationTime = 0;
  private vesselContacts = 0;

  public constructor(
    scene: Scene,
    oceanField: OceanField,
    definitions: readonly IcebergDefinition[],
    landObstacles: readonly IcebergPlacementExclusion[],
    bounds: Readonly<IcebergWorldBounds>,
  ) {
    this.scene = scene;
    this.oceanField = oceanField;
    this.landObstacles = landObstacles;
    this.bounds = bounds;

    for (const shape of SHAPES) {
      const count = countByShape(definitions, shape);
      if (count === 0) continue;
      const mesh = new InstancedMesh(
        createIcebergGeometry(shape),
        this.material,
        count,
      );
      mesh.name = `Icebergs ${shape}`;
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      mesh.frustumCulled = false;
      this.meshes.set(shape, mesh);
      this.scene.add(mesh);
    }

    const shapeCounts = new Map<IcebergShape, number>();
    const capCount = definitions.filter(
      (definition) =>
        definition.size === 'medium' || definition.size === 'large',
    ).length;
    if (capCount > 0) {
      const capGeometry = new IcosahedronGeometry(1, 1);
      capGeometry.scale(1, 0.18, 0.82);
      this.capMesh = new InstancedMesh(
        capGeometry,
        this.capMaterial,
        capCount,
      );
      this.capMesh.name = 'Iceberg snow caps';
      this.capMesh.castShadow = true;
      this.capMesh.receiveShadow = true;
      this.capMesh.frustumCulled = false;
      this.scene.add(this.capMesh);
    }
    let capIndex = 0;
    for (const definition of definitions) {
      const profile = MOTION_PROFILES[definition.size];
      const instanceIndex = shapeCounts.get(definition.shape) ?? 0;
      shapeCounts.set(definition.shape, instanceIndex + 1);
      const iceberg: RuntimeIceberg = {
        id: definition.id,
        x: definition.x,
        z: definition.z,
        size: definition.size,
        shape: definition.shape,
        visualRadius: definition.visualRadius,
        radius: definition.collisionRadius,
        height: definition.height,
        yaw: definition.yaw,
        angularVelocity: 0,
        velocityX: 0,
        velocityZ: 0,
        grounded: definition.grounded,
        colorMix: definition.colorMix,
        phase: definition.phase,
        instanceIndex,
        capIndex:
          definition.size === 'medium' || definition.size === 'large'
            ? capIndex++
            : -1,
        pushability: definition.grounded ? 0 : profile.pushability,
        resistance: profile.resistance,
      };
      this.icebergs.push(iceberg);
      this.icebergsById.set(iceberg.id, iceberg);

      const mesh = this.meshes.get(iceberg.shape);
      if (!mesh) continue;
      this.color
        .setHex(ICEBERG_COLORS[iceberg.size])
        .lerp(this.colorHighlight, iceberg.colorMix * 0.32);
      mesh.setColorAt(iceberg.instanceIndex, this.color);
      mesh.setMatrixAt(iceberg.instanceIndex, this.identity);
      if (iceberg.capIndex >= 0) {
        this.capMesh?.setMatrixAt(iceberg.capIndex, this.identity);
      }
    }

    for (const mesh of this.meshes.values()) {
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    }
    this.updateVisuals(0);
  }

  public update(
    deltaSeconds: number,
    elapsedSeconds: number,
    timeScale: number,
  ): void {
    const scaledDelta = Math.min(deltaSeconds, 0.1) * timeScale;
    this.simulationTime += scaledDelta;
    if (scaledDelta > 0) {
      for (const iceberg of this.icebergs) {
        this.updateMotion(iceberg, scaledDelta);
      }
    }
    this.updateVisuals(elapsedSeconds);
  }

  public getVesselObstacles(): readonly VesselCollisionObstacle[] {
    return this.icebergs;
  }

  public applyVesselContact(
    id: string,
    contact: Readonly<VesselObstacleContact>,
  ): void {
    const iceberg = this.icebergsById.get(id);
    if (!iceberg) return;
    iceberg.x += contact.displacementX;
    iceberg.z += contact.displacementZ;
    iceberg.velocityX += contact.impulseX;
    iceberg.velocityZ += contact.impulseZ;
    const maximumSpeed = MOTION_PROFILES[iceberg.size].maximumSpeed * 2.4;
    const speed = Math.hypot(iceberg.velocityX, iceberg.velocityZ);
    if (speed > maximumSpeed) {
      const scale = maximumSpeed / speed;
      iceberg.velocityX *= scale;
      iceberg.velocityZ *= scale;
    }
    this.resolveLandAndBounds(iceberg);
    this.vesselContacts += 1;
  }

  public getStats(): IcebergStats {
    const stats: IcebergStats = {
      total: this.icebergs.length,
      growlers: 0,
      small: 0,
      medium: 0,
      large: 0,
      moving: 0,
      vesselContacts: this.vesselContacts,
    };
    for (const iceberg of this.icebergs) {
      if (iceberg.size === 'growler') stats.growlers += 1;
      else if (iceberg.size === 'small') stats.small += 1;
      else if (iceberg.size === 'medium') stats.medium += 1;
      else stats.large += 1;
      if (Math.hypot(iceberg.velocityX, iceberg.velocityZ) > 0.003) {
        stats.moving += 1;
      }
    }
    return stats;
  }

  public dispose(): void {
    for (const mesh of this.meshes.values()) {
      this.scene.remove(mesh);
      mesh.geometry.dispose();
    }
    if (this.capMesh) {
      this.scene.remove(this.capMesh);
      this.capMesh.geometry.dispose();
    }
    this.meshes.clear();
    this.material.dispose();
    this.capMaterial.dispose();
  }

  private updateMotion(iceberg: RuntimeIceberg, deltaSeconds: number): void {
    const profile = MOTION_PROFILES[iceberg.size];
    if (iceberg.grounded) {
      iceberg.velocityX = 0;
      iceberg.velocityZ = 0;
      iceberg.angularVelocity = 0;
      return;
    }

    this.oceanField.sampleCurrent(
      iceberg.x,
      iceberg.z,
      this.simulationTime,
      this.current,
    );
    this.oceanField.sampleEnvironment(
      iceberg.x,
      iceberg.z,
      this.simulationTime,
      this.environment,
    );
    const targetVelocityX =
      this.current.x * profile.currentResponse +
      this.environment.windX *
        this.environment.windStrength *
        profile.windResponse;
    const targetVelocityZ =
      this.current.z * profile.currentResponse +
      this.environment.windZ *
        this.environment.windStrength *
        profile.windResponse;
    const velocityBlend =
      1 - Math.exp(-profile.velocityResponse * deltaSeconds);
    iceberg.velocityX = lerp(
      iceberg.velocityX,
      targetVelocityX,
      velocityBlend,
    );
    iceberg.velocityZ = lerp(
      iceberg.velocityZ,
      targetVelocityZ,
      velocityBlend,
    );

    const speed = Math.hypot(iceberg.velocityX, iceberg.velocityZ);
    if (speed > profile.maximumSpeed) {
      const scale = profile.maximumSpeed / speed;
      iceberg.velocityX *= scale;
      iceberg.velocityZ *= scale;
    }
    iceberg.x += iceberg.velocityX * deltaSeconds;
    iceberg.z += iceberg.velocityZ * deltaSeconds;

    const targetAngularVelocity =
      this.current.angularVelocity *
      profile.angularResponse *
      (0.65 + Math.sin(iceberg.phase) * 0.2);
    iceberg.angularVelocity = lerp(
      iceberg.angularVelocity,
      targetAngularVelocity,
      velocityBlend * 0.55,
    );
    iceberg.yaw += iceberg.angularVelocity * deltaSeconds;
    this.resolveLandAndBounds(iceberg);
  }

  private resolveLandAndBounds(iceberg: RuntimeIceberg): void {
    for (const obstacle of this.landObstacles) {
      const dx = iceberg.x - obstacle.x;
      const dz = iceberg.z - obstacle.z;
      const minimumDistance = obstacle.radius + iceberg.radius * 0.72;
      const distanceSquared = dx * dx + dz * dz;
      if (distanceSquared >= minimumDistance * minimumDistance) continue;
      const distance = Math.sqrt(distanceSquared);
      const normalX = distance > 0.001 ? dx / distance : 1;
      const normalZ = distance > 0.001 ? dz / distance : 0;
      iceberg.x = obstacle.x + normalX * minimumDistance;
      iceberg.z = obstacle.z + normalZ * minimumDistance;
      const normalVelocity =
        iceberg.velocityX * normalX + iceberg.velocityZ * normalZ;
      if (normalVelocity < 0) {
        iceberg.velocityX -= normalVelocity * normalX;
        iceberg.velocityZ -= normalVelocity * normalZ;
      }
      iceberg.angularVelocity *= 0.65;
    }

    const xLimit =
      this.bounds.halfWidth - this.bounds.padding - iceberg.radius;
    const zLimit =
      this.bounds.halfHeight - this.bounds.padding - iceberg.radius;
    if (iceberg.x < -xLimit || iceberg.x > xLimit) {
      iceberg.x = clamp(iceberg.x, -xLimit, xLimit);
      iceberg.velocityX =
        iceberg.x < 0
          ? Math.max(0, iceberg.velocityX)
          : Math.min(0, iceberg.velocityX);
      iceberg.angularVelocity *= 0.75;
    }
    if (iceberg.z < -zLimit || iceberg.z > zLimit) {
      iceberg.z = clamp(iceberg.z, -zLimit, zLimit);
      iceberg.velocityZ =
        iceberg.z < 0
          ? Math.max(0, iceberg.velocityZ)
          : Math.min(0, iceberg.velocityZ);
      iceberg.angularVelocity *= 0.75;
    }
  }

  public setPresentationVisible(visible: boolean): void {
    for (const mesh of this.meshes.values()) {
      mesh.visible = visible;
    }
    if (this.capMesh) this.capMesh.visible = visible;
  }

  private updateVisuals(elapsedSeconds: number): void {
    for (const iceberg of this.icebergs) {
      const profile = MOTION_PROFILES[iceberg.size];
      const waveResponse = iceberg.grounded
        ? profile.waveResponse * 0.12
        : profile.waveResponse;
      this.oceanField.sampleSurface(
        iceberg.x,
        iceberg.z,
        elapsedSeconds,
        waveResponse,
        this.surface,
      );
      const pitch =
        Math.atan2(this.surface.normalZ, this.surface.normalY) * waveResponse;
      const roll =
        -Math.atan2(this.surface.normalX, this.surface.normalY) * waveResponse;
      const stretch =
        0.88 + (Math.sin(iceberg.phase * 1.7) * 0.5 + 0.5) * 0.22;
      const baseSubmersion =
        iceberg.height * (iceberg.shape === 'tabular' ? 0.13 : 0.09);

      this.dummy.position.set(
        iceberg.x,
        this.surface.height - baseSubmersion,
        iceberg.z,
      );
      this.dummy.rotation.order = 'YXZ';
      this.dummy.rotation.set(
        pitch,
        iceberg.yaw,
        roll + Math.sin(elapsedSeconds * 0.24 + iceberg.phase) * 0.008 * waveResponse,
      );
      this.dummy.scale.set(
        iceberg.visualRadius * stretch,
        iceberg.height,
        iceberg.visualRadius / stretch,
      );
      this.dummy.updateMatrix();
      const mesh = this.meshes.get(iceberg.shape);
      mesh?.setMatrixAt(iceberg.instanceIndex, this.dummy.matrix);

      if (iceberg.capIndex >= 0 && this.capMesh) {
        const capRadius =
          iceberg.visualRadius *
          (iceberg.shape === 'tabular' ? 0.78 : 0.68);
        const capHeight =
          iceberg.shape === 'tabular'
            ? 0.84
            : iceberg.shape === 'dome'
              ? 0.8
              : iceberg.shape === 'pinnacle'
                ? 0.68
                : 0.74;
        this.capDummy.position.set(
          iceberg.x,
          this.surface.height + iceberg.height * capHeight,
          iceberg.z,
        );
        this.capDummy.rotation.copy(this.dummy.rotation);
        this.capDummy.scale.set(
          capRadius * stretch,
          iceberg.height * 0.58,
          capRadius / stretch,
        );
        this.capDummy.updateMatrix();
        this.capMesh.setMatrixAt(iceberg.capIndex, this.capDummy.matrix);
      }
    }

    for (const mesh of this.meshes.values()) {
      mesh.instanceMatrix.needsUpdate = true;
    }
    if (this.capMesh) this.capMesh.instanceMatrix.needsUpdate = true;
  }
}
