import {
  LinearFilter,
  RGBAFormat,
  ShaderMaterial,
  UnsignedByteType,
  Vector2,
  WebGLRenderTarget,
  type Camera,
  type Scene,
  type WebGLRenderer,
} from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';
import { damp } from '../utils/math';

export type SphericalWorldContext =
  | 'sea'
  | 'harbor'
  | 'construction';

export const SPHERICAL_WORLD_STRENGTH = Object.freeze({
  sea: 0.14,
  harbor: 0.3,
  construction: 0,
} satisfies Record<SphericalWorldContext, number>);

const SPHERICAL_WORLD_SHADER = {
  uniforms: {
    tDiffuse: { value: null },
    uStrength: { value: 0 },
    uAspect: { value: 1 },
    uFocus: { value: new Vector2() },
  },
  vertexShader: `
    varying vec2 vUv;

    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform sampler2D tDiffuse;
    uniform float uStrength;
    uniform float uAspect;
    uniform vec2 uFocus;
    varying vec2 vUv;

    void main() {
      vec2 point = vUv * 2.0 - 1.0;
      vec2 localPoint = point - uFocus;
      vec2 sphericalPoint = vec2(
        localPoint.x * uAspect,
        localPoint.y
      );
      float sphereRadius = 1.08;
      float normalizedRadius = min(
        length(sphericalPoint) / sphereRadius,
        0.97
      );
      float radiusSquared = normalizedRadius * normalizedRadius;

      // Lower distant screen regions around the focal point instead of
      // magnifying the centre. The sphere sagitta gives this projection an
      // actual round profile rather than an arbitrary lens distortion.
      float sphereSagitta =
        1.0 - sqrt(max(0.0, 1.0 - radiusSquared));
      float domeDrop = uStrength * sphereSagitta * 0.95;
      vec2 samplePoint = vec2(point.x, point.y + domeDrop);
      vec2 sampleUv = samplePoint * 0.5 + 0.5;
      vec4 sceneColor = texture2D(tDiffuse, sampleUv);

      // A very small cool falloff helps the corners recede without drawing a
      // visible vignette over the arctic palette.
      float edgeFalloff =
        smoothstep(0.48, 1.0, radiusSquared) * uStrength * 0.12;
      sceneColor.rgb = mix(
        sceneColor.rgb,
        sceneColor.rgb * 0.965 + vec3(0.012, 0.022, 0.026),
        edgeFalloff
      );
      gl_FragColor = sceneColor;
    }
  `,
};

/**
 * Presentation-only spherical lens for evaluating a rounder world language.
 * The scene, physics, raycasts, construction grid and persistence remain flat.
 */
export class SphericalWorldOverlay {
  private readonly renderer: WebGLRenderer;
  private readonly scene: Scene;
  private readonly camera: Camera;
  private composer?: EffectComposer;
  private sphericalPass?: ShaderPass;
  private width = 1;
  private height = 1;
  private enabled = false;
  private context: SphericalWorldContext = 'sea';
  private currentStrength = 0;
  private readonly focus = new Vector2();

  public constructor(
    renderer: WebGLRenderer,
    scene: Scene,
    camera: Camera,
  ) {
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
  }

  public dispose(): void {
    this.releaseComposer();
  }

  public setSize(width: number, height: number): void {
    this.width = Math.max(1, width);
    this.height = Math.max(1, height);
    if (!this.composer) return;
    this.composer.setPixelRatio(this.renderer.getPixelRatio());
    this.composer.setSize(this.width, this.height);
    this.updateAspect();
  }

  public setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    if (enabled) this.ensureComposer();
  }

  public toggle(): boolean {
    this.setEnabled(!this.enabled);
    return this.enabled;
  }

  public isEnabled(): boolean {
    return this.enabled;
  }

  public setContext(context: SphericalWorldContext): void {
    this.context = context;
  }

  public getContext(): SphericalWorldContext {
    return this.context;
  }

  public setFocus(x: number, y: number): void {
    this.focus.set(x, y);
    if (!this.sphericalPass) return;
    const focus = this.sphericalPass.uniforms.uFocus;
    if (focus) (focus.value as Vector2).copy(this.focus);
  }

  public update(deltaSeconds: number): void {
    const target = this.enabled
      ? SPHERICAL_WORLD_STRENGTH[this.context]
      : 0;
    this.currentStrength = damp(
      this.currentStrength,
      target,
      this.enabled ? 5.2 : 7.5,
      deltaSeconds,
    );
    if (this.sphericalPass) {
      const strength = this.sphericalPass.uniforms.uStrength;
      if (strength) strength.value = this.currentStrength;
    }
    if (!this.enabled && this.currentStrength <= 0.0005) {
      this.currentStrength = 0;
      this.releaseComposer();
    }
  }

  /**
   * Converts a pointer position from the curved output back into the flat
   * scene projection. This keeps world interaction aligned with the visual
   * dome while the simulation remains planar.
   */
  public mapScreenNdcToSceneNdc(
    x: number,
    y: number,
    target: Vector2,
  ): Vector2 {
    if (this.currentStrength <= 0.0005) return target.set(x, y);
    const aspect = this.width / this.height;
    const localX = x - this.focus.x;
    const localY = y - this.focus.y;
    const normalizedRadius = Math.min(
      0.97,
      Math.hypot(localX * aspect, localY) / 1.08,
    );
    const radiusSquared = normalizedRadius * normalizedRadius;
    const sphereSagitta =
      1 - Math.sqrt(Math.max(0, 1 - radiusSquared));
    const domeDrop = this.currentStrength * sphereSagitta * 0.95;
    return target.set(x, y + domeDrop);
  }

  public render(deltaSeconds: number): void {
    if (this.currentStrength <= 0.0005 || !this.composer) {
      this.renderer.render(this.scene, this.camera);
      return;
    }
    this.composer.render(deltaSeconds);
  }

  public getRenderPassCount(): number {
    return this.currentStrength > 0.0005 && this.composer ? 3 : 1;
  }

  public getRenderTargetCount(): number {
    return this.currentStrength > 0.0005 && this.composer ? 2 : 0;
  }

  private ensureComposer(): void {
    if (this.composer) return;
    const renderTarget = new WebGLRenderTarget(1, 1, {
      minFilter: LinearFilter,
      magFilter: LinearFilter,
      format: RGBAFormat,
      type: UnsignedByteType,
      depthBuffer: true,
      stencilBuffer: false,
    });
    renderTarget.texture.name = 'Spherical world overlay scene';
    const composer = new EffectComposer(this.renderer, renderTarget);
    composer.addPass(new RenderPass(this.scene, this.camera));
    const sphericalMaterial = new ShaderMaterial(
      SPHERICAL_WORLD_SHADER,
    );
    sphericalMaterial.name = 'Spherical world overlay';
    sphericalMaterial.toneMapped = false;
    const sphericalPass = new ShaderPass(sphericalMaterial);
    composer.addPass(sphericalPass);
    composer.addPass(new OutputPass());
    this.composer = composer;
    this.sphericalPass = sphericalPass;
    const focus = sphericalPass.uniforms.uFocus;
    if (focus) (focus.value as Vector2).copy(this.focus);
    composer.setPixelRatio(this.renderer.getPixelRatio());
    composer.setSize(this.width, this.height);
    this.updateAspect();
  }

  private updateAspect(): void {
    if (!this.sphericalPass) return;
    const aspect = this.sphericalPass.uniforms.uAspect;
    if (aspect) aspect.value = this.width / this.height;
  }

  private releaseComposer(): void {
    this.composer?.dispose();
    this.sphericalPass?.material.dispose();
    this.composer = undefined;
    this.sphericalPass = undefined;
  }
}
