import {
  isGlobalPositionInPartition,
  type GlobalPosition,
} from '../../world/GlobalPosition';
import {
  ICEAWAY_TARGET_WORLD_PARTITION,
  isValidWorldPartition,
  type WorldPartitionDefinition,
} from '../../world/WorldPartitionTypes';
import type {
  RadioChannelType,
  RadioCoverageProfileDefinition,
  RadioNetworkDefinitionSet,
  RadioRegionDefinition,
  RadioStationDefinition,
  RadioTowerDefinition,
  RadioTowerState,
  RadioTransmitterDefinition,
  RadioVoiceProfileDefinition,
  RegionalFrequencyDefinition,
} from './RadioNetworkTypes';

export interface RadioNetworkRegistryIssue {
  path: string;
  message: string;
}

export class RadioNetworkRegistryValidationError extends Error {
  public constructor(
    public readonly issues: readonly RadioNetworkRegistryIssue[],
  ) {
    super(
      `Invalid radio network definitions:\n${issues
        .map((issue) => `- ${issue.path}: ${issue.message}`)
        .join('\n')}`,
    );
    this.name = 'RadioNetworkRegistryValidationError';
  }
}

const RADIO_CHANNEL_TYPES = new Set<RadioChannelType>([
  'HARBOR_CONTROL',
  'EMERGENCY',
  'LOCAL',
  'OPEN_BAND',
  'WEATHER_AND_ICE',
  'UNKNOWN',
]);

const RADIO_TOWER_STATES = new Set<RadioTowerState>([
  'OFFLINE',
  'DAMAGED',
  'WEAK',
  'ONLINE',
  'UPGRADED',
]);

const deepFreeze = <T>(value: T): T => {
  if (
    value === null ||
    typeof value !== 'object' ||
    Object.isFrozen(value)
  ) {
    return value;
  }
  for (const nested of Object.values(
    value as Record<string, unknown>,
  )) {
    deepFreeze(nested);
  }
  return Object.freeze(value);
};

const cloneDefinitions = (
  source: RadioNetworkDefinitionSet,
): RadioNetworkDefinitionSet =>
  deepFreeze(structuredClone(source));

const collectIds = <T extends { id: string }>(
  values: readonly T[],
  path: string,
  issues: RadioNetworkRegistryIssue[],
): Set<string> => {
  const result = new Set<string>();
  for (const [index, value] of values.entries()) {
    const id = value?.id.trim() ?? '';
    if (!id) {
      issues.push({
        path: `${path}[${index}].id`,
        message: 'ID must be a non-empty string',
      });
      continue;
    }
    if (result.has(id)) {
      issues.push({
        path: `${path}[${index}].id`,
        message: `Duplicate ID "${id}"`,
      });
    }
    result.add(id);
  }
  return result;
};

const requireNonEmptyString = (
  value: string,
  path: string,
  issues: RadioNetworkRegistryIssue[],
): void => {
  if (!value.trim()) {
    issues.push({
      path,
      message: 'Value must be a non-empty string',
    });
  }
};

const requireGlobalPosition = (
  position: Readonly<GlobalPosition>,
  partition: Readonly<WorldPartitionDefinition>,
  path: string,
  issues: RadioNetworkRegistryIssue[],
): void => {
  if (!isGlobalPositionInPartition(partition, position)) {
    issues.push({
      path,
      message:
        'Position must be normalized and inside the world partition',
    });
  }
};

export const validateRadioNetworkDefinitions = (
  definitions: RadioNetworkDefinitionSet,
  partition: Readonly<WorldPartitionDefinition> =
    ICEAWAY_TARGET_WORLD_PARTITION,
): readonly RadioNetworkRegistryIssue[] => {
  const issues: RadioNetworkRegistryIssue[] = [];
  if (!isValidWorldPartition(partition)) {
    issues.push({
      path: 'partition',
      message: 'World partition is invalid',
    });
    return issues;
  }

  const regionIds = collectIds(
    definitions.regions,
    'regions',
    issues,
  );
  const coverageProfileIds = collectIds(
    definitions.coverageProfiles,
    'coverageProfiles',
    issues,
  );
  const voiceProfileIds = collectIds(
    definitions.voiceProfiles,
    'voiceProfiles',
    issues,
  );
  const stationIds = collectIds(
    definitions.stations,
    'stations',
    issues,
  );
  const frequencyIds = collectIds(
    definitions.frequencies,
    'frequencies',
    issues,
  );
  const towerIds = collectIds(
    definitions.towers,
    'towers',
    issues,
  );
  collectIds(
    definitions.transmitters,
    'transmitters',
    issues,
  );

  for (const [index, region] of definitions.regions.entries()) {
    requireNonEmptyString(
      region.displayNameKey,
      `regions[${index}].displayNameKey`,
      issues,
    );
  }

  for (const [
    index,
    profile,
  ] of definitions.coverageProfiles.entries()) {
    if (
      !Number.isFinite(profile.clearRadiusMetres) ||
      !Number.isFinite(profile.usableRadiusMetres) ||
      !Number.isFinite(profile.maximumRadiusMetres) ||
      profile.clearRadiusMetres < 0 ||
      profile.usableRadiusMetres <
        profile.clearRadiusMetres ||
      profile.maximumRadiusMetres <
        profile.usableRadiusMetres
    ) {
      issues.push({
        path: `coverageProfiles[${index}]`,
        message:
          'Coverage radii must be finite, non-negative and ordered clear <= usable <= maximum',
      });
    }
    if (
      !Number.isFinite(profile.falloffExponent) ||
      profile.falloffExponent <= 0
    ) {
      issues.push({
        path: `coverageProfiles[${index}].falloffExponent`,
        message: 'Falloff exponent must be positive',
      });
    }
  }

  for (const [
    index,
    profile,
  ] of definitions.voiceProfiles.entries()) {
    if (
      profile.baseVoiceAssetId !== undefined &&
      !profile.baseVoiceAssetId.trim()
    ) {
      issues.push({
        path: `voiceProfiles[${index}].baseVoiceAssetId`,
        message: 'Asset ID must be non-empty when provided',
      });
    }
    if (
      !Number.isFinite(profile.pitchSemitones) ||
      profile.pitchSemitones < -24 ||
      profile.pitchSemitones > 24
    ) {
      issues.push({
        path: `voiceProfiles[${index}].pitchSemitones`,
        message: 'Pitch must be between -24 and 24 semitones',
      });
    }
    if (
      !Number.isFinite(profile.playbackRate) ||
      profile.playbackRate < 0.5 ||
      profile.playbackRate > 2
    ) {
      issues.push({
        path: `voiceProfiles[${index}].playbackRate`,
        message: 'Playback rate must be between 0.5 and 2',
      });
    }
    for (const key of [
      'eqProfileId',
      'radioNoiseProfileId',
      'compressionProfileId',
    ] as const) {
      requireNonEmptyString(
        profile[key],
        `voiceProfiles[${index}].${key}`,
        issues,
      );
    }
  }

  for (const [
    index,
    station,
  ] of definitions.stations.entries()) {
    requireNonEmptyString(
      station.displayNameKey,
      `stations[${index}].displayNameKey`,
      issues,
    );
    if (station.regionIds.length === 0) {
      issues.push({
        path: `stations[${index}].regionIds`,
        message: 'Station must serve at least one region',
      });
    }
    for (const regionId of station.regionIds) {
      if (!regionIds.has(regionId)) {
        issues.push({
          path: `stations[${index}].regionIds`,
          message: `Missing region "${regionId}"`,
        });
      }
    }
    if (station.channelTypes.length === 0) {
      issues.push({
        path: `stations[${index}].channelTypes`,
        message: 'Station must support at least one channel',
      });
    }
    for (const channel of station.channelTypes) {
      if (!RADIO_CHANNEL_TYPES.has(channel)) {
        issues.push({
          path: `stations[${index}].channelTypes`,
          message: `Unknown channel "${channel}"`,
        });
      }
    }
    if (
      station.voiceProfileId !== undefined &&
      !voiceProfileIds.has(station.voiceProfileId)
    ) {
      issues.push({
        path: `stations[${index}].voiceProfileId`,
        message: `Missing voice profile "${station.voiceProfileId}"`,
      });
    }
  }

  for (const [
    index,
    frequency,
  ] of definitions.frequencies.entries()) {
    requireNonEmptyString(
      frequency.displayNameKey,
      `frequencies[${index}].displayNameKey`,
      issues,
    );
    if (!regionIds.has(frequency.regionId)) {
      issues.push({
        path: `frequencies[${index}].regionId`,
        message: `Missing region "${frequency.regionId}"`,
      });
    }
    if (!RADIO_CHANNEL_TYPES.has(frequency.channelType)) {
      issues.push({
        path: `frequencies[${index}].channelType`,
        message: `Unknown channel "${frequency.channelType}"`,
      });
    }
    if (
      !Number.isFinite(frequency.frequencyMhz) ||
      frequency.frequencyMhz <= 0
    ) {
      issues.push({
        path: `frequencies[${index}].frequencyMhz`,
        message: 'Frequency must be positive',
      });
    }
  }

  for (const [index, tower] of definitions.towers.entries()) {
    requireNonEmptyString(
      tower.displayNameKey,
      `towers[${index}].displayNameKey`,
      issues,
    );
    if (!regionIds.has(tower.regionId)) {
      issues.push({
        path: `towers[${index}].regionId`,
        message: `Missing region "${tower.regionId}"`,
      });
    }
    if (!coverageProfileIds.has(tower.coverageProfileId)) {
      issues.push({
        path: `towers[${index}].coverageProfileId`,
        message: `Missing coverage profile "${tower.coverageProfileId}"`,
      });
    }
    if (!RADIO_TOWER_STATES.has(tower.initialState)) {
      issues.push({
        path: `towers[${index}].initialState`,
        message: `Unknown tower state "${tower.initialState}"`,
      });
    }
    requireGlobalPosition(
      tower.worldPosition,
      partition,
      `towers[${index}].worldPosition`,
      issues,
    );
  }

  const stationsById = new Map(
    definitions.stations.map((station) => [
      station.id,
      station,
    ]),
  );
  const frequenciesById = new Map(
    definitions.frequencies.map((frequency) => [
      frequency.id,
      frequency,
    ]),
  );
  const towersById = new Map(
    definitions.towers.map((tower) => [tower.id, tower]),
  );

  for (const [
    index,
    transmitter,
  ] of definitions.transmitters.entries()) {
    const path = `transmitters[${index}]`;
    const station = stationsById.get(transmitter.stationId);
    const frequency = frequenciesById.get(
      transmitter.frequencyId,
    );
    if (!stationIds.has(transmitter.stationId)) {
      issues.push({
        path: `${path}.stationId`,
        message: `Missing station "${transmitter.stationId}"`,
      });
    }
    if (!regionIds.has(transmitter.regionId)) {
      issues.push({
        path: `${path}.regionId`,
        message: `Missing region "${transmitter.regionId}"`,
      });
    }
    if (!frequencyIds.has(transmitter.frequencyId)) {
      issues.push({
        path: `${path}.frequencyId`,
        message: `Missing frequency "${transmitter.frequencyId}"`,
      });
    }
    if (
      station &&
      !station.regionIds.includes(transmitter.regionId)
    ) {
      issues.push({
        path: `${path}.regionId`,
        message: 'Station does not serve transmitter region',
      });
    }
    if (
      frequency &&
      frequency.regionId !== transmitter.regionId
    ) {
      issues.push({
        path: `${path}.frequencyId`,
        message:
          'Frequency and transmitter must belong to the same region',
      });
    }
    if (
      station &&
      frequency &&
      !station.channelTypes.includes(
        frequency.channelType,
      )
    ) {
      issues.push({
        path: `${path}.frequencyId`,
        message:
          'Station does not support the frequency channel',
      });
    }

    if (transmitter.source.kind === 'TOWER') {
      const tower = towersById.get(
        transmitter.source.towerId,
      );
      if (!towerIds.has(transmitter.source.towerId)) {
        issues.push({
          path: `${path}.source.towerId`,
          message: `Missing tower "${transmitter.source.towerId}"`,
        });
      } else if (
        tower?.regionId !== transmitter.regionId
      ) {
        issues.push({
          path: `${path}.source.towerId`,
          message:
            'Tower and transmitter must belong to the same region',
        });
      }
    } else {
      if (
        !coverageProfileIds.has(
          transmitter.source.coverageProfileId,
        )
      ) {
        issues.push({
          path: `${path}.source.coverageProfileId`,
          message:
            `Missing coverage profile "${transmitter.source.coverageProfileId}"`,
        });
      }
      requireGlobalPosition(
        transmitter.source.worldPosition,
        partition,
        `${path}.source.worldPosition`,
        issues,
      );
    }
  }

  return issues;
};

export class RadioNetworkRegistry {
  public readonly definitions: RadioNetworkDefinitionSet;
  public readonly partition: WorldPartitionDefinition;

  private readonly regionsById: Map<
    string,
    RadioRegionDefinition
  >;
  private readonly coverageProfilesById: Map<
    string,
    RadioCoverageProfileDefinition
  >;
  private readonly voiceProfilesById: Map<
    string,
    RadioVoiceProfileDefinition
  >;
  private readonly stationsById: Map<
    string,
    RadioStationDefinition
  >;
  private readonly frequenciesById: Map<
    string,
    RegionalFrequencyDefinition
  >;
  private readonly towersById: Map<
    string,
    RadioTowerDefinition
  >;
  private readonly transmittersById: Map<
    string,
    RadioTransmitterDefinition
  >;

  public constructor(
    definitions: RadioNetworkDefinitionSet,
    partition: Readonly<WorldPartitionDefinition> =
      ICEAWAY_TARGET_WORLD_PARTITION,
  ) {
    const issues = validateRadioNetworkDefinitions(
      definitions,
      partition,
    );
    if (issues.length > 0) {
      throw new RadioNetworkRegistryValidationError(issues);
    }

    this.definitions = cloneDefinitions(definitions);
    this.partition = deepFreeze(structuredClone(partition));
    this.regionsById = new Map(
      this.definitions.regions.map((value) => [
        value.id,
        value,
      ]),
    );
    this.coverageProfilesById = new Map(
      this.definitions.coverageProfiles.map((value) => [
        value.id,
        value,
      ]),
    );
    this.voiceProfilesById = new Map(
      this.definitions.voiceProfiles.map((value) => [
        value.id,
        value,
      ]),
    );
    this.stationsById = new Map(
      this.definitions.stations.map((value) => [
        value.id,
        value,
      ]),
    );
    this.frequenciesById = new Map(
      this.definitions.frequencies.map((value) => [
        value.id,
        value,
      ]),
    );
    this.towersById = new Map(
      this.definitions.towers.map((value) => [
        value.id,
        value,
      ]),
    );
    this.transmittersById = new Map(
      this.definitions.transmitters.map((value) => [
        value.id,
        value,
      ]),
    );
  }

  public getRegion(
    id: string,
  ): RadioRegionDefinition | undefined {
    return this.regionsById.get(id);
  }

  public getCoverageProfile(
    id: string,
  ): RadioCoverageProfileDefinition | undefined {
    return this.coverageProfilesById.get(id);
  }

  public getVoiceProfile(
    id: string,
  ): RadioVoiceProfileDefinition | undefined {
    return this.voiceProfilesById.get(id);
  }

  public getStation(
    id: string,
  ): RadioStationDefinition | undefined {
    return this.stationsById.get(id);
  }

  public getFrequency(
    id: string,
  ): RegionalFrequencyDefinition | undefined {
    return this.frequenciesById.get(id);
  }

  public getTower(
    id: string,
  ): RadioTowerDefinition | undefined {
    return this.towersById.get(id);
  }

  public getTransmitter(
    id: string,
  ): RadioTransmitterDefinition | undefined {
    return this.transmittersById.get(id);
  }

  public listRegionalFrequencies(
    regionId: string,
  ): readonly RegionalFrequencyDefinition[] {
    return this.definitions.frequencies.filter(
      (frequency) => frequency.regionId === regionId,
    );
  }

  public listRegionalTransmitters(
    regionId: string,
  ): readonly RadioTransmitterDefinition[] {
    return this.definitions.transmitters.filter(
      (transmitter) =>
        transmitter.regionId === regionId,
    );
  }
}
