const nextPlacementId = (): string =>
  `part-${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 7)}`;

const downloadTextFile = (
  filename: string,
  contents: string,
): void => {
  const blob = new Blob([contents], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
};

const closestPlacementId = (object: Object3D | null): string | undefined => {
  let current: Object3D | null = object;
  while (current) {
    if (typeof current.userData.placementId === 'string') {
      return current.userData.placementId;
    }
    current = current.parent;
  }
  return undefined;
};

const surfaceNormal = (
  normal: Readonly<Vector3>,
): ConstructionDirection | undefined => {
  if (Math.abs(normal.y) > 0.55) return undefined;
  const horizontalLength = Math.hypot(normal.x, normal.z);
  if (horizontalLength < 0.5) return undefined;
  return {
    x: Number((normal.x / horizontalLength).toFixed(4)),
    y: 0,
    z: Number((normal.z / horizontalLength).toFixed(4)),
  };
};

const yawForNormal = (normal: Readonly<ConstructionDirection>): number =>
  MathUtils.radToDeg(Math.atan2(normal.x, normal.z));

const angularDistance = (left: number, right: number): number =>
  Math.abs(((left - right + 180) % 360 + 360) % 360 - 180);

