import { clamp } from '../utils/math';
import {
  gamepadAxis,
  gamepadButtonPressed,
  gamepadButtonValue,
  getPrimaryGamepad,
} from './GamepadInput';

export interface BulldozerControlCommand {
  throttle: number;
  steering: number;
  bladeMotion: -1 | 0 | 1;
  bucketTiltMotion: -1 | 0 | 1;
  cycleBladeMode: boolean;
  toggleBeacon: boolean;
  toggleLights: boolean;
  horn: boolean;
  requestExitVehicle: boolean;
  requestReturn: boolean;
}

const CONTROL_KEYS = new Set([
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'KeyW',
  'KeyA',
  'KeyS',
  'KeyD',
  'KeyQ',
  'KeyE',
  'KeyC',
  'KeyZ',
  'KeyB',
  'KeyG',
  'Space',
]);

export class PlayerBulldozerController {
  private readonly pressed = new Set<string>();
  private enabled = false;
  private bladeModeCycleRequested = false;
  private beaconToggleRequested = false;
  private lightsToggleRequested = false;
  private hornRequested = false;
  private exitVehicleRequested = false;
  private virtualBladeMotion: -1 | 0 | 1 = 0;
  private gamepadBladeModePressed = false;
  private gamepadBeaconPressed = false;
  private gamepadLightsPressed = false;
  private gamepadHornPressed = false;

  public constructor() {
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', this.onBlur);
  }

  public setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    this.pressed.clear();
    this.bladeModeCycleRequested = false;
    this.beaconToggleRequested = false;
    this.lightsToggleRequested = false;
    this.hornRequested = false;
    this.exitVehicleRequested = false;
    this.virtualBladeMotion = 0;
    this.gamepadBladeModePressed = false;
    this.gamepadBeaconPressed = false;
    this.gamepadLightsPressed = false;
    this.gamepadHornPressed = false;
  }

  public setBladeMotionInput(motion: -1 | 0 | 1): void {
    this.virtualBladeMotion = motion;
  }

  public sampleControls(
    deltaSeconds = 1 / 60,
  ): BulldozerControlCommand {
    if (!this.enabled) {
      return {
        throttle: 0,
        steering: 0,
        bladeMotion: 0,
        bucketTiltMotion: 0,
        cycleBladeMode: false,
        toggleBeacon: false,
        toggleLights: false,
        horn: false,
        requestExitVehicle: false,
        requestReturn: false,
      };
    }
    const forward = this.isPressed('KeyW', 'ArrowUp') ? 1 : 0;
    const reverse = this.isPressed('KeyS', 'ArrowDown') ? 1 : 0;
    const left = this.isPressed('KeyA', 'ArrowLeft') ? 1 : 0;
    const right = this.isPressed('KeyD', 'ArrowRight') ? 1 : 0;
    const lowerBlade = this.pressed.has('KeyQ');
    const raiseBlade = this.pressed.has('KeyE');
    const curlBucket = this.pressed.has('KeyZ');
    const dumpBucket = this.pressed.has('KeyC');
    const gamepad = getPrimaryGamepad();
    const gamepadThrottle =
      gamepadButtonValue(gamepad, 7) - gamepadButtonValue(gamepad, 6);
    const gamepadSteering = -gamepadAxis(gamepad, 0);
    const gamepadLowerBlade = gamepadButtonPressed(gamepad, 4);
    const gamepadRaiseBlade = gamepadButtonPressed(gamepad, 5);
    const gamepadBladeMode = gamepadButtonPressed(gamepad, 3);
    if (gamepadBladeMode && !this.gamepadBladeModePressed) {
      this.bladeModeCycleRequested = true;
    }
    this.gamepadBladeModePressed = gamepadBladeMode;
    const gamepadBeacon = gamepadButtonPressed(gamepad, 1);
    if (gamepadBeacon && !this.gamepadBeaconPressed) {
      this.beaconToggleRequested = true;
    }
    this.gamepadBeaconPressed = gamepadBeacon;
    const gamepadLights = gamepadButtonPressed(gamepad, 12);
    if (gamepadLights && !this.gamepadLightsPressed) {
      this.lightsToggleRequested = true;
    }
    this.gamepadLightsPressed = gamepadLights;
    const gamepadHorn = gamepadButtonPressed(gamepad, 0);
    if (gamepadHorn && !this.gamepadHornPressed) {
      this.hornRequested = true;
    }
    this.gamepadHornPressed = gamepadHorn;
    const keyboardBladeMotion =
      lowerBlade === raiseBlade ? 0 : lowerBlade ? 1 : -1;
    const gamepadBladeMotion =
      gamepadLowerBlade === gamepadRaiseBlade
        ? 0
        : gamepadLowerBlade
          ? 1
          : -1;
    const keyboardThrottle = clamp(forward - reverse, -1, 1);
    const keyboardSteering = clamp(left - right, -1, 1);
    const command = {
      throttle:
        Math.abs(keyboardThrottle) > 0.01
          ? keyboardThrottle
          : gamepadThrottle,
      // Negative heading rotation is a visible right turn in Three.js.
      steering:
        Math.abs(keyboardSteering) > 0.01
          ? keyboardSteering
          : gamepadSteering,
      bladeMotion:
        this.virtualBladeMotion !== 0
          ? this.virtualBladeMotion
          : keyboardBladeMotion !== 0
            ? keyboardBladeMotion
            : gamepadBladeMotion,
      bucketTiltMotion:
        curlBucket === dumpBucket ? 0 : curlBucket ? 1 : -1,
      cycleBladeMode: this.bladeModeCycleRequested,
      toggleBeacon: this.beaconToggleRequested,
      toggleLights: this.lightsToggleRequested,
      horn: this.hornRequested,
      requestExitVehicle: this.exitVehicleRequested,
      requestReturn: false,
    };
    this.bladeModeCycleRequested = false;
    this.beaconToggleRequested = false;
    this.lightsToggleRequested = false;
    this.hornRequested = false;
    this.exitVehicleRequested = false;
    return command as BulldozerControlCommand;
  }

  public dispose(): void {
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
    window.removeEventListener('blur', this.onBlur);
  }

  private isPressed(...codes: string[]): boolean {
    return codes.some((code) => this.pressed.has(code));
  }

  private onKeyDown = (event: KeyboardEvent): void => {
    if (!this.enabled) return;
    if (CONTROL_KEYS.has(event.code)) event.preventDefault();
    this.pressed.add(event.code);
    if (!event.repeat && event.code === 'KeyC') {
      this.bladeModeCycleRequested = true;
    }
    if (!event.repeat && event.code === 'KeyB') {
      this.beaconToggleRequested = true;
    }
    if (!event.repeat && event.code === 'KeyG') {
      this.lightsToggleRequested = true;
    }
    if (!event.repeat && event.code === 'Space') {
      this.hornRequested = true;
    }
  };

  private onKeyUp = (event: KeyboardEvent): void => {
    this.pressed.delete(event.code);
  };

  private onBlur = (): void => {
    this.pressed.clear();
    this.virtualBladeMotion = 0;
    this.gamepadBladeModePressed = false;
    this.gamepadBeaconPressed = false;
    this.gamepadLightsPressed = false;
    this.gamepadHornPressed = false;
  };
}
