import { clamp, damp, hash2D } from '../utils/math';

export type WeatherKind =
  | 'clear'
  | 'overcast'
  | 'light-snow'
  | 'fog'
  | 'strong-wind'
  | 'snowstorm';
export type WeatherMode = 'auto' | WeatherKind;
export type WeatherPhase =
  | 'calm'
  | 'transition'
  | 'active'
  | 'recovery'
  | 'forced';
export type WeatherTimeScale = 1 | 4 | 12;

export interface WeatherProfile {
  cloudCover: number;
  fogDensity: number;
  snowIntensity: number;
  windMultiplier: number;
  waveMultiplier: number;
  refreezeMultiplier: number;
  iceContrast: number;
}

export interface WeatherState extends WeatherProfile {
  mode: WeatherMode;
  current: WeatherKind;
  target: WeatherKind;
  phase: WeatherPhase;
  phaseProgress: number;
  frozen: boolean;
  timeScale: WeatherTimeScale;
  weatherTime: number;
  updates: number;
}

export interface WeatherForecast {
  snowExpected: boolean;
  kind: WeatherKind;
  minutesUntil: number;
  expectedIntensity: number;
}

export interface WeatherSystemSaveData {
  version: 1;
  state: WeatherState;
  accumulator: number;
  phaseElapsed: number;
  eventIndex: number;
  activeWeather: WeatherKind;
}

const WEATHER_STEP = 0.25;
const TRANSITION_SECONDS = 38;
const RECOVERY_SECONDS = 42;
const WEATHER_MODES: readonly WeatherMode[] = [
  'auto',
  'overcast',
  'light-snow',
  'fog',
  'strong-wind',
  'snowstorm',
  'clear',
];
const WEATHER_TIME_SCALES: readonly WeatherTimeScale[] = [1, 4, 12];
const WEATHER_TRANSITIONS: Readonly<
  Record<WeatherKind, readonly WeatherKind[]>
> = {
  clear: ['clear', 'overcast', 'overcast', 'strong-wind'],
  overcast: ['clear', 'light-snow', 'fog', 'strong-wind'],
  'light-snow': ['clear', 'overcast', 'snowstorm'],
  fog: ['clear', 'clear', 'overcast'],
  'strong-wind': ['clear', 'overcast', 'snowstorm'],
  snowstorm: ['light-snow', 'overcast', 'clear'],
};

export const WEATHER_PROFILES: Readonly<
  Record<WeatherKind, Readonly<WeatherProfile>>
> = {
  clear: Object.freeze({
    cloudCover: 0.08,
    fogDensity: 0.0105,
    snowIntensity: 0,
    windMultiplier: 0.82,
    waveMultiplier: 0.9,
    refreezeMultiplier: 0.92,
    iceContrast: 1,
  }),
  overcast: Object.freeze({
    cloudCover: 0.72,
    fogDensity: 0.014,
    snowIntensity: 0,
    windMultiplier: 0.96,
    waveMultiplier: 1,
    refreezeMultiplier: 1.04,
    iceContrast: 0.94,
  }),
  'light-snow': Object.freeze({
    cloudCover: 0.88,
    fogDensity: 0.017,
    snowIntensity: 0.42,
    windMultiplier: 1.02,
    waveMultiplier: 1.02,
    refreezeMultiplier: 1.14,
    iceContrast: 0.9,
  }),
  fog: Object.freeze({
    cloudCover: 0.82,
    fogDensity: 0.023,
    snowIntensity: 0.04,
    windMultiplier: 0.68,
    waveMultiplier: 0.82,
    refreezeMultiplier: 1.08,
    iceContrast: 0.88,
  }),
  'strong-wind': Object.freeze({
    cloudCover: 0.54,
    fogDensity: 0.0135,
    snowIntensity: 0.03,
    windMultiplier: 1.38,
    waveMultiplier: 1.24,
    refreezeMultiplier: 0.94,
    iceContrast: 0.96,
  }),
  snowstorm: Object.freeze({
    cloudCover: 1,
    fogDensity: 0.027,
    snowIntensity: 1,
    windMultiplier: 1.55,
    waveMultiplier: 1.32,
    refreezeMultiplier: 1.22,
    iceContrast: 0.84,
  }),
};

const cycleValue = <T>(values: readonly T[], current: T): T => {
  const index = values.indexOf(current);
  return values[(index + 1) % values.length] ?? values[0]!;
};

export class WeatherSystem {
  private readonly state: WeatherState = {
    mode: 'auto',
    current: 'clear',
    target: 'overcast',
    phase: 'transition',
    phaseProgress: 0,
    frozen: false,
    timeScale: 1,
    weatherTime: 0,
    updates: 0,
    ...WEATHER_PROFILES.clear,
  };
  private accumulator = 0;
  private phaseElapsed = 0;
  private eventIndex = 0;
  private activeWeather: WeatherKind = 'overcast';

  public update(deltaSeconds: number): void {
    if (this.state.frozen) return;
    const realStep = clamp(deltaSeconds, 0, 0.1);
    this.accumulator += realStep;

    while (this.accumulator >= WEATHER_STEP) {
      const step = WEATHER_STEP * this.state.timeScale;
      this.state.weatherTime += step;
      if (this.state.mode === 'auto') this.advanceAutomaticCycle(step);
      else this.advanceForcedPreview();
      this.state.updates += 1;
      this.accumulator -= WEATHER_STEP;
    }

    this.approachTargetProfile(realStep * this.state.timeScale);
  }

  public getState(): Readonly<WeatherState> {
    return this.state;
  }

  public getForecast(): WeatherForecast {
    const currentSnow = WEATHER_PROFILES[this.state.current].snowIntensity;
    if (this.state.snowIntensity >= 0.12 || currentSnow >= 0.2) {
      return {
        snowExpected: true,
        kind: this.state.current,
        minutesUntil: 0,
        expectedIntensity: Math.max(this.state.snowIntensity, currentSnow),
      };
    }
    const targetSnow = WEATHER_PROFILES[this.state.target].snowIntensity;
    if (targetSnow >= 0.2) {
      const remaining = this.state.phase === 'transition'
        ? Math.max(0, TRANSITION_SECONDS - this.phaseElapsed)
        : 0;
      return {
        snowExpected: true,
        kind: this.state.target,
        minutesUntil: remaining / 60,
        expectedIntensity: targetSnow,
      };
    }
    if (this.state.mode === 'auto' && this.state.phase === 'calm') {
      const next = this.selectNextWeather();
      const nextSnow = WEATHER_PROFILES[next].snowIntensity;
      if (nextSnow >= 0.2) {
        const calmDuration = 82 + (this.eventIndex % 3) * 14;
        return {
          snowExpected: true,
          kind: next,
          minutesUntil:
            (Math.max(0, calmDuration - this.phaseElapsed) +
              TRANSITION_SECONDS) /
            60,
          expectedIntensity: nextSnow,
        };
      }
    }
    return {
      snowExpected: false,
      kind: this.state.target,
      minutesUntil: Number.POSITIVE_INFINITY,
      expectedIntensity: targetSnow,
    };
  }

  public setMode(mode: WeatherMode): WeatherMode {
    if (!WEATHER_MODES.includes(mode)) return this.state.mode;
    this.state.mode = mode;
    this.phaseElapsed = 0;
    if (mode === 'auto') {
      this.state.phase = 'recovery';
      this.state.target = 'clear';
      this.state.phaseProgress = 0;
    } else {
      this.advanceForcedPreview();
    }
    return this.state.mode;
  }

  public exportState(): WeatherSystemSaveData {
    return {
      version: 1,
      state: { ...this.state },
      accumulator: this.accumulator,
      phaseElapsed: this.phaseElapsed,
      eventIndex: this.eventIndex,
      activeWeather: this.activeWeather,
    };
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<WeatherSystemSaveData>;
    const state = candidate.state as Partial<WeatherState> | undefined;
    if (
      candidate.version !== 1 ||
      !state ||
      !WEATHER_MODES.includes(state.mode as WeatherMode) ||
      !Object.hasOwn(WEATHER_PROFILES, state.current ?? '') ||
      !Object.hasOwn(WEATHER_PROFILES, state.target ?? '') ||
      !['calm', 'transition', 'active', 'recovery', 'forced']
        .includes(state.phase ?? '') ||
      !WEATHER_TIME_SCALES.includes(
        state.timeScale as WeatherTimeScale,
      ) ||
      !Object.hasOwn(
        WEATHER_PROFILES,
        candidate.activeWeather ?? '',
      )
    ) {
      return false;
    }
    const numericState = [
      state.phaseProgress,
      state.weatherTime,
      state.updates,
      state.cloudCover,
      state.fogDensity,
      state.snowIntensity,
      state.windMultiplier,
      state.waveMultiplier,
      state.refreezeMultiplier,
      state.iceContrast,
      candidate.accumulator,
      candidate.phaseElapsed,
      candidate.eventIndex,
    ];
    if (!numericState.every((value) => Number.isFinite(value))) {
      return false;
    }

    Object.assign(this.state, {
      mode: state.mode,
      current: state.current,
      target: state.target,
      phase: state.phase,
      phaseProgress: clamp(state.phaseProgress ?? 0, 0, 1),
      frozen: state.frozen === true,
      timeScale: state.timeScale,
      weatherTime: Math.max(0, state.weatherTime ?? 0),
      updates: Math.max(0, Math.floor(state.updates ?? 0)),
      cloudCover: clamp(state.cloudCover ?? 0.08, 0, 1),
      fogDensity: clamp(state.fogDensity ?? 0.0105, 0, 0.08),
      snowIntensity: clamp(state.snowIntensity ?? 0, 0, 1),
      windMultiplier: clamp(state.windMultiplier ?? 1, 0.5, 1.7),
      waveMultiplier: clamp(state.waveMultiplier ?? 1, 0.7, 1.5),
      refreezeMultiplier: clamp(
        state.refreezeMultiplier ?? 1,
        0.5,
        2,
      ),
      iceContrast: clamp(state.iceContrast ?? 1, 0.5, 1.5),
    });
    this.accumulator = clamp(
      candidate.accumulator ?? 0,
      0,
      WEATHER_STEP,
    );
    this.phaseElapsed = Math.max(0, candidate.phaseElapsed ?? 0);
    this.eventIndex = Math.max(
      0,
      Math.floor(candidate.eventIndex ?? 0),
    );
    this.activeWeather = candidate.activeWeather as WeatherKind;
    return true;
  }

  public cycleMode(): WeatherMode {
    return this.setMode(cycleValue(WEATHER_MODES, this.state.mode));
  }

  public toggleFrozen(): boolean {
    this.state.frozen = !this.state.frozen;
    return this.state.frozen;
  }

  public cycleTimeScale(): WeatherTimeScale {
    this.state.timeScale = cycleValue(
      WEATHER_TIME_SCALES,
      this.state.timeScale,
    );
    return this.state.timeScale;
  }

  private advanceForcedPreview(): void {
    const forced = this.state.mode === 'auto'
      ? 'clear'
      : this.state.mode;
    this.state.phase = 'forced';
    this.state.target = forced;
    this.state.current = forced;
    this.state.phaseProgress = 1;
  }

  private advanceAutomaticCycle(step: number): void {
    this.phaseElapsed += step;
    const calmDuration = 82 + (this.eventIndex % 3) * 14;
    const activeDuration = 72 + (this.eventIndex % 4) * 11;

    if (this.state.phase === 'calm') {
      this.state.current = 'clear';
      this.state.target = 'clear';
      this.state.phaseProgress = clamp(
        this.phaseElapsed / calmDuration,
        0,
        1,
      );
      if (this.phaseElapsed >= calmDuration) {
        this.phaseElapsed = 0;
        this.activeWeather = this.selectNextWeather();
        this.state.phase = 'transition';
        this.state.target = this.activeWeather;
        this.state.phaseProgress = 0;
      }
      return;
    }

    if (this.state.phase === 'transition') {
      this.state.target = this.activeWeather;
      this.state.phaseProgress = clamp(
        this.phaseElapsed / TRANSITION_SECONDS,
        0,
        1,
      );
      this.state.current =
        this.state.phaseProgress < 0.5 ? 'clear' : this.activeWeather;
      if (this.phaseElapsed >= TRANSITION_SECONDS) {
        this.phaseElapsed = 0;
        this.state.phase = 'active';
        this.state.current = this.activeWeather;
        this.state.phaseProgress = 0;
      }
      return;
    }

    if (this.state.phase === 'active') {
      this.state.current = this.activeWeather;
      this.state.target = this.activeWeather;
      this.state.phaseProgress = clamp(
        this.phaseElapsed / activeDuration,
        0,
        1,
      );
      if (this.phaseElapsed >= activeDuration) {
        this.phaseElapsed = 0;
        this.state.phase = 'recovery';
        this.state.target = 'clear';
        this.state.phaseProgress = 0;
      }
      return;
    }

    this.state.target = 'clear';
    this.state.phaseProgress = clamp(
      this.phaseElapsed / RECOVERY_SECONDS,
      0,
      1,
    );
    this.state.current =
      this.state.phaseProgress < 0.5 ? this.activeWeather : 'clear';
    if (this.phaseElapsed >= RECOVERY_SECONDS) {
      this.phaseElapsed = 0;
      this.eventIndex += 1;
      this.state.phase = 'calm';
      this.state.current = 'clear';
      this.state.target = 'clear';
      this.state.phaseProgress = 0;
    }
  }

  private approachTargetProfile(step: number): void {
    const target = WEATHER_PROFILES[this.state.target];
    const response = this.state.phase === 'forced' ? 2.4 : 0.11;
    this.state.cloudCover = damp(
      this.state.cloudCover,
      target.cloudCover,
      response,
      step,
    );
    this.state.fogDensity = damp(
      this.state.fogDensity,
      target.fogDensity,
      response,
      step,
    );
    this.state.snowIntensity = damp(
      this.state.snowIntensity,
      target.snowIntensity,
      response,
      step,
    );
    this.state.windMultiplier = damp(
      this.state.windMultiplier,
      target.windMultiplier,
      response,
      step,
    );
    this.state.waveMultiplier = damp(
      this.state.waveMultiplier,
      target.waveMultiplier,
      response,
      step,
    );
    this.state.refreezeMultiplier = damp(
      this.state.refreezeMultiplier,
      target.refreezeMultiplier,
      response,
      step,
    );
    this.state.iceContrast = damp(
      this.state.iceContrast,
      target.iceContrast,
      response,
      step,
    );
  }

  private selectNextWeather(): WeatherKind {
    const options = WEATHER_TRANSITIONS[this.activeWeather];
    const random = hash2D(
      this.eventIndex,
      Math.floor(this.state.weatherTime / 17),
      2027,
    );
    return options[
      Math.min(
        options.length - 1,
        Math.floor(random * options.length),
      )
    ] ?? 'overcast';
  }
}
