  public resize = (): void => {
    if (this.disposed) return;
    const width = Math.max(1, this.host.clientWidth);
    const height = Math.max(1, this.host.clientHeight);
    const aspect = width / height;
    const minimumWorldWidth = WORLD.gridColumns * WORLD.cellSize + 8;
    const minimumWorldHeight = WORLD.gridRows * WORLD.cellSize + 7;
    const viewHeight = Math.max(minimumWorldHeight, minimumWorldWidth / aspect);
    const viewWidth = viewHeight * aspect;

    this.camera.left = -viewWidth * 0.5;
    this.camera.right = viewWidth * 0.5;
    this.camera.top = viewHeight * 0.5;
    this.camera.bottom = -viewHeight * 0.5;
    this.followCamera.setFollowFramingScale(
      viewHeight / REFERENCE_FOLLOW_VIEW_HEIGHT,
    );
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(width, height, false);
    this.sphericalWorldOverlay.setSize(width, height);
  };

  public update(
    deltaSeconds: number,
    elapsedSeconds: number,
    followTarget?: Readonly<FollowCameraTarget>,
  ): void {
    this.followCamera.update(this.camera, deltaSeconds, followTarget);
    updateViewToCameraDirection(
      this.camera,
      this.viewToCameraDirection,
    );
    const cameraGroundDistance =
      (this.camera.position.y - OCEAN_SEA_LEVEL) /
      Math.max(0.001, this.viewToCameraDirection.y);
    this.cameraGroundPoint.set(
      this.camera.position.x -
        this.viewToCameraDirection.x * cameraGroundDistance,
      this.camera.position.z -
        this.viewToCameraDirection.z * cameraGroundDistance,
    );
    this.sphericalWorldFocus
      .set(
        followTarget?.position.x ?? this.cameraGroundPoint.x,
        OCEAN_SEA_LEVEL,
        followTarget?.position.z ?? this.cameraGroundPoint.y,
      )
      .project(this.camera);
    this.sphericalWorldOverlay.setFocus(
      this.sphericalWorldFocus.x,
      this.sphericalWorldFocus.y,
    );
    this.requestedCelestialFocus.set(
      followTarget?.position.x ?? this.cameraGroundPoint.x,
      0,
      followTarget?.position.z ?? this.cameraGroundPoint.y,
    );
    stabilizeIceShadowFocus(
      this.requestedCelestialFocus,
      this.sunDirection,
      ICE_SHADOW_QUALITY_SETTINGS[this.iceShadowQuality],
      this.celestialFocus,
    );
    this.updateCelestialWorldPositions();
    this.recoveryStrength = damp(
      this.recoveryStrength,
      this.recoveryTarget,
      1.8,
      deltaSeconds,
    );
    this.seaUniforms.uRecoveryStrength.value =
      this.recoveryStrength;
    if (this.ambientSwellRemaining > 0) {
      this.ambientSwellRemaining = Math.max(
        0,
        this.ambientSwellRemaining - deltaSeconds,
      );
    } else {
      this.ambientSwellTarget = 0;
    }
    this.ambientSwellStrength = damp(
      this.ambientSwellStrength,
      this.ambientSwellTarget,
      this.ambientSwellRemaining > 0 ? 1.15 : 0.72,
      deltaSeconds,
    );
    this.oceanField.setTransientSwellStrength(
      this.ambientSwellStrength,
    );
    this.windGustRemaining = Math.max(
      0,
      this.windGustRemaining - deltaSeconds,
    );
    this.seaUniforms.uSwellStrength.value =
      this.oceanField.resolveSwellStrength(
        this.baseSwellStrength,
      );
    const snowCenterX = followTarget?.position.x ?? 0;
    const snowCenterZ = followTarget?.position.z ?? 0;
    const snowEnvironment = this.environmentSystem.sampleLocal(
      snowCenterX,
      snowCenterZ,
      this.localEnvironment,
    );
    const oceanCloudWindLength = Math.max(
      0.0001,
      Math.hypot(snowEnvironment.windX, snowEnvironment.windZ),
    );
    this.oceanCloudOffset.x +=
      snowEnvironment.windX /
      oceanCloudWindLength *
      this.oceanCloudSpeed *
      deltaSeconds;
    this.oceanCloudOffset.y +=
      snowEnvironment.windZ /
      oceanCloudWindLength *
      this.oceanCloudSpeed *
      deltaSeconds;
    this.seaUniforms.uOceanCloudOffset.value
      .copy(this.oceanCloudOffset);
    const windX = snowEnvironment.windX / oceanCloudWindLength;
    const windZ = snowEnvironment.windZ / oceanCloudWindLength;
    this.oceanSurfaceOffset.x +=
      (
        snowEnvironment.currentX * 0.12 +
        windX * snowEnvironment.windStrength * 0.008
      ) *
      deltaSeconds;
    this.oceanSurfaceOffset.y +=
      (
        snowEnvironment.currentZ * 0.12 +
        windZ * snowEnvironment.windStrength * 0.008
      ) *
      deltaSeconds;
    this.seaUniforms.uOceanSurfaceOffset.value
      .copy(this.oceanSurfaceOffset);
    this.fogBanks.update(
      deltaSeconds,
      this.camera,
      snowEnvironment.windX,
      snowEnvironment.windZ,
      snowEnvironment.windStrength,
    );
    this.snowfall.update(
      deltaSeconds,
      this.camera,
      snowEnvironment.windX,
      snowEnvironment.windZ,
      snowEnvironment.windStrength,
    );
    this.recoveryActivity.update(deltaSeconds, elapsedSeconds);
    this.updatePortBeacons(elapsedSeconds);
    this.updateRadioTowerVisuals(elapsedSeconds);
    this.sphericalWorldOverlay.update(deltaSeconds);
    this.pollGpuTimer();
    const gpuQueryStarted = this.beginGpuTimer();
    const previousAutoReset = this.renderer.info.autoReset;
    this.renderer.info.autoReset = false;
    this.renderer.info.reset();
    this.sphericalWorldOverlay.render(deltaSeconds);
    if (gpuQueryStarted) {
      this.gpuTimerContext!.endQuery(
        this.gpuTimerExtension!.TIME_ELAPSED_EXT,
      );
    }
    this.lastDrawCalls = this.renderer.info.render.calls;
    this.lastTriangles = this.renderer.info.render.triangles;
    this.renderer.info.autoReset = previousAutoReset;
  }

