      ocean.weatherWindMultiplier;
    this.weatherCloudCover = clamp(weather.cloudCover, 0, 1);
    this.weatherSnowIntensity = clamp(weather.snowIntensity, 0, 1);
    this.weatherFogFactor = clamp(
      (weather.fogDensity - 0.0105) / 0.0165,
      0,
      1,
    );
    this.seaUniforms.uCloudCover.value =
      this.weatherCloudCover;
    this.seaUniforms.uVisibility.value =
      1 - this.weatherFogFactor;

    this.snowfall.setIntensity(this.weatherSnowIntensity);
    this.snowfall.setBlowingSnowIntensity(
      weather.windMultiplier,
    );
    this.fogBanks.setIntensity(this.weatherFogFactor);

    this.seaUniforms.uDaylight.value = day.daylight;
    this.seaUniforms.uWarmth.value = day.warmth;
    this.seaUniforms.uNight.value = day.night;
    this.environmentArtificialLight = day.artificialLight;
