  public screenToWorld(clientX: number, clientY: number): Vector3 | null {
    const bounds = this.canvas.getBoundingClientRect();
    this.sphericalWorldOverlay.mapScreenNdcToSceneNdc(
      ((clientX - bounds.left) / bounds.width) * 2 - 1,
      -((clientY - bounds.top) / bounds.height) * 2 + 1,
      this.pointer,
    );
    this.raycaster.setFromCamera(this.pointer, this.camera);
    const result = new Vector3();
    return this.raycaster.ray.intersectPlane(this.interactionPlane, result);
  }

  public writeCameraRelativeMovement(
    right: number,
    forward: number,
    target: { moveX: number; moveZ: number },
  ): void {
    this.camera.getWorldDirection(this.cameraMovementForward);
    this.cameraMovementForward.y = 0;
    this.cameraMovementForward.normalize();
    this.cameraMovementRight.setFromMatrixColumn(this.camera.matrixWorld, 0);
    this.cameraMovementRight.y = 0;
    this.cameraMovementRight.normalize();
    target.moveX =
      this.cameraMovementForward.x * forward +
      this.cameraMovementRight.x * right;
    target.moveZ =
      this.cameraMovementForward.z * forward +
      this.cameraMovementRight.z * right;
    const magnitude = Math.hypot(target.moveX, target.moveZ);
    if (magnitude > 1) {
      target.moveX /= magnitude;
      target.moveZ /= magnitude;
    }
  }

  public setRoute(points: Vector3[], mode: 'planned' | 'active'): void {
    this.clearRoute();
    if (points.length < 2) return;
    this.routeMode = mode;

    const lifted = points.map((point) => new Vector3(point.x, mode === 'active' ? 0.205 : 0.235, point.z));
    const curve = new CatmullRomCurve3(lifted, false, 'centripetal', 0.25);
    const segments = Math.max(24, Math.min(220, points.length * 14));
    const color = mode === 'active' ? 0xffbb68 : 0x6ce5ec;

    const glowGeometry = new TubeGeometry(curve, segments, mode === 'active' ? 0.24 : 0.21, 7, false);
    const glowMaterial = new MeshBasicMaterial({
      color,
      transparent: true,
      opacity: mode === 'active' ? 0.18 : 0.2,
      depthWrite: false,
      blending: AdditiveBlending,
    });
    const glow = new Mesh(glowGeometry, glowMaterial);
    glow.renderOrder = 3;
    this.routeGroup.add(glow);

    const coreGeometry = new TubeGeometry(curve, segments, mode === 'active' ? 0.075 : 0.065, 7, false);
    const coreMaterial = new MeshBasicMaterial({
      color,
      transparent: true,
      opacity: mode === 'active' ? 0.82 : 0.88,
      depthWrite: false,
    });
    const core = new Mesh(coreGeometry, coreMaterial);
    core.renderOrder = 4;
    this.routeGroup.add(core);

    if (mode === 'planned') {
      for (let index = 1; index < lifted.length - 1; index += 1) {
        const point = lifted[index];
        if (!point) continue;
        const marker = new Mesh(
          new TorusGeometry(0.23, 0.045, 7, 20),
          new MeshBasicMaterial({ color: 0xc4ffff, transparent: true, opacity: 0.8 }),
        );
        marker.rotation.x = Math.PI / 2;
        marker.position.copy(point).setY(0.27);
        this.routeGroup.add(marker);
      }
    }
  }

  public clearRoute(): void {
    for (const child of [...this.routeGroup.children]) {
      this.routeGroup.remove(child);
      this.disposeObject(child);
    }
  }

  public setPortSelection(originId?: string, destinationId?: string): void {
    this.selectedDestinationId = destinationId;
    const harborWeights = this.seaUniforms.uHarborWeights.value;
    for (let index = 0; index < PORTS.length; index += 1) {
      const id = PORTS[index]?.id;
      harborWeights[index] =
        id === destinationId
          ? 1.2
          : id === originId
            ? 0.86
            : 0.62;
    }
    for (const [id, visual] of this.portVisuals) {
      const isOrigin = id === originId;
      const isDestination = id === destinationId;
      visual.ring.material.color.setHex(isDestination ? 0xffc36a : isOrigin ? 0x77e5ee : 0x79aeb8);
      visual.ring.material.opacity = isDestination ? 0.78 : isOrigin ? 0.56 : 0.24;
      visual.ringBaseScale = isDestination ? 1.18 : isOrigin ? 1.03 : 0.9;
      visual.ring.scale.setScalar(visual.ringBaseScale);
      visual.baseBeaconIntensity = isDestination
        ? 2.2
        : isOrigin
          ? 1.45
          : 0.75;
    }
  }

  public setPortClearanceObjective(
    portId?: string,
    progress = 0,
  ): void {
    const state = resolvePortClearanceVisual(progress);
    for (const [id, visual] of this.portVisuals) {
      const active = id === portId;
      visual.clearanceArea.visible = active;
      visual.clearanceRing.visible = active;
      if (!active) continue;
      visual.clearanceArea.material.color.setHex(state.color);
      visual.clearanceRing.material.color.setHex(state.color);
      visual.clearanceAreaOpacity = state.areaOpacity;
      visual.clearanceRingOpacity = state.outlineOpacity;
      visual.clearanceArea.material.opacity = state.areaOpacity;
      visual.clearanceRing.material.opacity =
        state.outlineOpacity;
    }
  }

