  public setRadioTowerPresentationStates(
    states: readonly Readonly<RadioTowerPresentationState>[],
  ): void {
    const activeIds = new Set(
      states.map((state) => state.towerId),
    );
    for (const [towerId, visual] of (
      this.radioTowerVisuals
    )) {
      if (activeIds.has(towerId)) continue;
      visual.group.removeFromParent();
      this.disposeObject(visual.group);
      this.radioTowerVisuals.delete(towerId);
    }
    for (const state of states) {
      let visual = this.radioTowerVisuals.get(
        state.towerId,
      );
      if (!visual) {
        visual = this.createRadioTowerVisual(state);
        this.radioTowerVisuals.set(state.towerId, visual);
        this.scene.add(visual.group);
      }
      visual.group.position.set(
        state.position.x,
        0.32,
        state.position.z,
      );
      this.applyRadioTowerVisualState(
        visual,
        state.state,
      );
    }
  }

