  public triggerAmbientEvent(event: Readonly<AmbientEvent>): void {
    this.lastAmbientCategory = event.category;
    if (event.category === 'distant-swell') {
      this.ambientSwellTarget = Math.max(
        this.ambientSwellTarget,
        event.strength,
      );
      this.ambientSwellRemaining = Math.max(
        this.ambientSwellRemaining,
        event.duration,
      );
    } else if (event.category === 'wind-gust') {
      this.windGustRemaining = Math.max(
        this.windGustRemaining,
        event.duration,
      );
      this.snowfall.triggerGust(event.strength, event.duration);
    } else if (event.category === 'buoy-surge') {
      this.recoveryActivity.triggerBuoySurge(
        event.strength,
        event.duration,
      );
    } else if (event.category === 'restored-traffic') {
      this.recoveryActivity.launchServiceCraft();
    }
  }

