  public dispose(): void {
    this.disposed = true;
    this.resizeObserver.disconnect();
    window.removeEventListener('resize', this.resize);
    if (this.pendingGpuQuery && this.gpuTimerContext) {
      this.gpuTimerContext.deleteQuery(this.pendingGpuQuery);
      this.pendingGpuQuery = undefined;
    }
    this.snowfall.dispose();
    this.fogBanks.dispose();
    this.recoveryActivity.dispose();
    this.atmosphere.dispose();
    this.sphericalWorldOverlay.dispose();
    this.scene.traverse((object: Object3D) => this.disposeObject(object, false));
    this.fallbackIceOpennessTexture.dispose();
    this.fallbackIceCoverageTexture.dispose();
    this.fallbackIceLifecycleTexture.dispose();
    this.oceanVoronoiTexture.dispose();
    this.oceanBathymetryTexture.dispose();
    this.renderer.dispose();
    this.canvas.remove();
  }

  private pollGpuTimer(): void {
    const context = this.gpuTimerContext;
    const extension = this.gpuTimerExtension;
    const query = this.pendingGpuQuery;
    if (!context || !extension) return;
    if (!query) {
      this.gpuTimerCooldownFrames = Math.max(
        0,
        this.gpuTimerCooldownFrames - 1,
      );
      return;
    }
    const available = context.getQueryParameter(
      query,
      context.QUERY_RESULT_AVAILABLE,
    ) as boolean;
    if (!available) return;
    const disjoint = context.getParameter(
      extension.GPU_DISJOINT_EXT,
    ) as boolean;
    if (!disjoint) {
      const elapsedNanoseconds = Number(
        context.getQueryParameter(
          query,
          context.QUERY_RESULT,
        ),
      );
      if (Number.isFinite(elapsedNanoseconds)) {
        this.lastGpuRenderMs = elapsedNanoseconds / 1_000_000;
      }
    }
    context.deleteQuery(query);
    this.pendingGpuQuery = undefined;
    this.gpuTimerCooldownFrames = 15;
  }

  private beginGpuTimer(): boolean {
    const context = this.gpuTimerContext;
    const extension = this.gpuTimerExtension;
    if (
      !context ||
      !extension ||
      this.pendingGpuQuery ||
      this.gpuTimerCooldownFrames > 0
    ) {
      return false;
    }
    const query = context.createQuery();
    if (!query) return false;
    context.beginQuery(extension.TIME_ELAPSED_EXT, query);
    this.pendingGpuQuery = query;
    return true;
  }

  private setupLighting(): void {
    this.hemisphere = new HemisphereLight(
      0xe6fbff,
      0x244d5c,
      2.15,
    );
    this.scene.add(this.hemisphere);

    this.sun = new DirectionalLight(0xfff5db, 3.25);
    this.sun.position.set(-18, 35, 14);
    this.sun.castShadow = true;
    this.sun.shadow.mapSize.set(2048, 2048);
    this.sun.shadow.camera.left = -34;
    this.sun.shadow.camera.right = 34;
    this.sun.shadow.camera.top = 28;
    this.sun.shadow.camera.bottom = -28;
    this.sun.shadow.camera.near = 2;
    this.sun.shadow.camera.far = 90;
    this.sun.shadow.bias = -0.0001;
    this.sun.shadow.normalBias = 0.012;
    this.sun.target.name = 'Sun shadow focus';
    this.scene.add(this.sun, this.sun.target);

    this.moon = new DirectionalLight(0x9bcfff, 0);
    this.moon.position.set(18, 28, -14);
    this.moon.target.name = 'Moon light focus';
    this.scene.add(this.moon, this.moon.target);

    this.fill = new DirectionalLight(0x82cfe2, 1.1);
    this.fill.position.set(22, 14, -22);
    this.scene.add(this.fill);

    this.ambient = new AmbientLight(0xc2e8ed, 0.35);
    this.scene.add(this.ambient);
  }

