import { EMPTY_UPGRADE_LEVELS } from '../data/config';
import type { SaveData, UpgradeLevels } from '../data/types';

const STORAGE_KEY = 'iceway-save-v1';
const SAVE_VERSION = 6;

const cloneLevels = (levels: UpgradeLevels): UpgradeLevels => ({
  ...levels,
});

export class SaveSystem {
  public load(): SaveData {
    const fallback: SaveData = {
      version: SAVE_VERSION,
      money: 520,
      currentPortId: 'borealis',
      completedMissions: 0,
      upgradeLevels: cloneLevels(EMPTY_UPGRADE_LEVELS),
    };

    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      if (!raw) return fallback;

      const parsed = JSON.parse(raw) as Partial<SaveData>;
      if (
        parsed.version !== 1 &&
        parsed.version !== 2 &&
        parsed.version !== 3 &&
        parsed.version !== 4 &&
        parsed.version !== 5 &&
        parsed.version !== SAVE_VERSION
      ) {
        return fallback;
      }

      return {
        version: SAVE_VERSION,
        money: Number.isFinite(parsed.money)
          ? Math.max(0, parsed.money ?? fallback.money)
          : fallback.money,
        currentPortId:
          typeof parsed.currentPortId === 'string'
            ? parsed.currentPortId
            : fallback.currentPortId,
        completedMissions: Number.isFinite(parsed.completedMissions)
          ? Math.max(0, Math.floor(parsed.completedMissions ?? 0))
          : 0,
        upgradeLevels: {
          ...EMPTY_UPGRADE_LEVELS,
          ...(parsed.upgradeLevels ?? {}),
        },
        iceWorld:
          (parsed.version === 2 ||
            parsed.version === 3 ||
            parsed.version === 4 ||
            parsed.version === 5 ||
            parsed.version === SAVE_VERSION) &&
          parsed.iceWorld &&
          typeof parsed.iceWorld === 'object'
            ? parsed.iceWorld
            : undefined,
        environment:
          (parsed.version === 3 ||
            parsed.version === 4 ||
            parsed.version === 5 ||
            parsed.version === SAVE_VERSION) &&
          parsed.environment &&
          typeof parsed.environment === 'object'
            ? parsed.environment
            : undefined,
        recovery:
          (parsed.version === 4 ||
            parsed.version === 5 ||
            parsed.version === SAVE_VERSION) &&
          parsed.recovery?.version === 1 &&
          typeof parsed.recovery.channelRestored === 'boolean' &&
          Number.isFinite(parsed.recovery.restoredAtWorldTime) &&
          Number.isFinite(parsed.recovery.serviceTripsCompleted)
            ? {
                version: 1,
                channelRestored: parsed.recovery.channelRestored,
                restoredAtWorldTime: Math.max(
                  0,
                  parsed.recovery.restoredAtWorldTime,
                ),
                serviceTripsCompleted: Math.max(
                  0,
                  Math.floor(parsed.recovery.serviceTripsCompleted),
                ),
              }
            : undefined,
        gameplay:
          (parsed.version === 5 || parsed.version === SAVE_VERSION) &&
          parsed.gameplay?.version === 1
            ? parsed.gameplay
            : undefined,
        vessel:
          (parsed.version === 5 || parsed.version === SAVE_VERSION) &&
          parsed.vessel?.version === 1 &&
          Number.isFinite(parsed.vessel.fuel) &&
          Number.isFinite(parsed.vessel.hullCondition)
            ? {
                version: 1,
                fuel: Math.max(0, parsed.vessel.fuel),
                hullCondition: Math.max(
                  0,
                  Math.min(1, parsed.vessel.hullCondition),
                ),
              }
            : undefined,
        achievements:
          (parsed.version === 5 || parsed.version === SAVE_VERSION) &&
          parsed.achievements?.version === 1
            ? parsed.achievements
            : undefined,
        landExpedition:
          parsed.version === SAVE_VERSION &&
          parsed.landExpedition?.version === 1 &&
          (parsed.landExpedition.bulldozer?.version === 1 ||
            parsed.landExpedition.bulldozer?.version === 2 ||
            parsed.landExpedition.bulldozer?.version === 3 ||
            parsed.landExpedition.bulldozer?.version === 4) &&
          (parsed.landExpedition.snow?.version === 1 ||
            parsed.landExpedition.snow?.version === 2)
            ? parsed.landExpedition
            : undefined,
      };
    } catch (error) {
      console.warn(
        'ICEWAY save could not be loaded. Starting a fresh shift.',
        error,
      );
      return fallback;
    }
  }

  public save(data: SaveData): void {
    try {
      window.localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({
          ...data,
          version: SAVE_VERSION,
          money: Math.round(data.money),
          completedMissions: Math.floor(data.completedMissions),
          upgradeLevels: cloneLevels(data.upgradeLevels),
        }),
      );
    } catch (error) {
      console.warn('ICEWAY progress could not be saved.', error);
    }
  }

  public reset(): boolean {
    try {
      window.localStorage.removeItem(STORAGE_KEY);
      return true;
    } catch (error) {
      console.warn('ICEWAY progress could not be reset.', error);
      return false;
    }
  }
}
