  public toast(
    message: string,
    tone: 'info' | 'achievement' = 'info',
  ): void {
    window.clearTimeout(this.toastTimer);
    this.toastElement.textContent = message;
    this.toastElement.classList.toggle(
      'is-achievement',
      tone === 'achievement',
    );
    this.toastElement.classList.add('is-visible');
    this.toastTimer = window.setTimeout(() => {
      this.toastElement.classList.remove('is-visible');
    }, 2400);
  }

  public dispose(): void {
    window.clearTimeout(this.toastTimer);
  }

  private bindEvents(): void {
    this.root.addEventListener('click', (event) => {
      const target = event.target as HTMLElement;
      const action = target.closest<HTMLElement>('[data-drive-action]')?.dataset.driveAction;
      if (action === 'begin') this.actions.onBegin();
      if (action === 'vessel-builder') {
        this.actions.onOpenVesselBuilder();
      }
      if (action === 'reset') this.actions.onReset();
      if (action === 'restart-fresh') {
        this.actions.onRestartFresh();
      }
      if (action === 'dock') this.actions.onDock();
      if (action === 'lights') this.actions.onToggleLights();
      if (action === 'sea-preview') {
        this.actions.onToggleSeaPreview();
      }
      if (action === 'audio-settings') {
        this.setDebugPanelOpen(false);
        this.setAchievementPanelOpen(false);
        this.setAudioPanelOpen(
          this.audioSettingsPanel.classList.contains('is-hidden'),
        );
      }
      if (action === 'achievements') {
        this.setAchievementPanelOpen(
          this.achievementPanel.classList.contains('is-hidden'),
        );
      }
      if (action === 'radio') {
        this.setRadioPanelOpen(
          this.radioPanel.classList.contains('is-hidden'),
        );
      }
      if (action === 'debug-settings') {
        this.setDebugPanelOpen(
          this.debugSettingsPanel.classList.contains('is-hidden'),
        );
      }
      if (action === 'close-audio-settings') {
        this.setAudioPanelOpen(false);
      }
      if (action === 'toggle-realistic-steering') {
        this.actions.onSetRealisticSteering(
          this.realisticSteeringButton.getAttribute(
            'aria-pressed',
          ) !== 'true',
        );
      }
      if (action === 'toggle-penguin-control-mode') {
        const current =
          this.penguinControlModeButton.dataset.controlMode ?? 'WASD';
        this.actions.onSetPenguinControlMode(
          current === 'WASD'
            ? 'MOUSE_STEERING'
            : current === 'MOUSE_STEERING'
              ? 'WASD_ONLY'
              : 'WASD',
        );
      }
      if (action === 'music-previous') {
        this.actions.onPreviousMusicTrack();
      }
      if (action === 'music-playback') {
        this.actions.onToggleMusicPlayback();
      }
      if (action === 'music-next') {
        this.actions.onNextMusicTrack();
      }
      if (action === 'music-repeat') {
        this.actions.onToggleMusicRepeat();
      }
      if (action === 'close-achievements') {
        this.setAchievementPanelOpen(false);
      }
      if (action === 'close-radio') {
        this.setRadioPanelOpen(false);
      }
      if (action === 'acknowledge-all-radio') {
        this.actions.onAcknowledgeAllRadioMessages();
      }
      if (action === 'toggle-radio-auto') {
        this.actions.onToggleRadioAutoTune();
      }
      const radioCategory =
        target.closest<HTMLElement>(
          '[data-radio-category]',
        )?.dataset.radioCategory;
      if (radioCategory) {
        this.actions.onToggleRadioCategory(radioCategory);
      }
      if (action === 'close-debug-settings') {
        this.setDebugPanelOpen(false);
      }
      const debugCommand =
        target.closest<HTMLElement>('[data-debug-command]')
          ?.dataset.debugCommand as DrivingDebugCommand | undefined;
      if (debugCommand) {
        this.actions.onDebugCommand(debugCommand);
      }
      const radioMessageId =
        target.closest<HTMLElement>(
          '[data-radio-message-id]',
        )?.dataset.radioMessageId;
      if (radioMessageId) {
        this.actions.onAcknowledgeRadioMessage(
          radioMessageId,
        );
      }
      const radioTuneStep = Number(
        target.closest<HTMLElement>(
          '[data-radio-tune-step]',
        )?.dataset.radioTuneStep,
      );
      if (radioTuneStep === -1 || radioTuneStep === 1) {
        this.actions.onNudgeRadioFrequency(
          radioTuneStep,
        );
      }
      if (
        !action &&
        !this.audioSettingsPanel.classList.contains('is-hidden') &&
        !target.closest('#drive-audio-panel')
      ) {
        this.setAudioPanelOpen(false);
      }
      if (
        !action &&
        !this.achievementPanel.classList.contains('is-hidden') &&
        !target.closest('#drive-achievements-panel')
      ) {
        this.setAchievementPanelOpen(false);
      }
      if (
        !action &&
        !radioMessageId &&
        !this.radioPanel.classList.contains('is-hidden') &&
        !target.closest('#drive-radio-panel')
      ) {
        this.setRadioPanelOpen(false);
      }
    });
    this.root.addEventListener('input', (event) => {
      const input = event.target as HTMLInputElement;
      if (input.dataset.radioFrequency === 'dial') {
        const frequencyMhz = Number(input.value);
        if (!Number.isFinite(frequencyMhz)) return;
        this.radioFrequencyOutput.value =
          `${frequencyMhz.toFixed(3)} MHz`;
        this.actions.onSetRadioFrequency(frequencyMhz);
        return;
      }
      const iceTuning = input.dataset.iceTuning;
      if (
        iceTuning === 'drift-strength' ||
        iceTuning === 'refreeze-speed'
      ) {
        const value = Number(input.value);
        if (!Number.isFinite(value)) return;
        const output =
          this.debugSettingsPanel.querySelector<HTMLOutputElement>(
            `[data-ice-tuning-output="${iceTuning}"]`,
          );
        if (output) output.textContent = `${value.toFixed(2)}x`;
        if (iceTuning === 'drift-strength') {
          this.actions.onSetDriftStrength(value);
        } else {
          this.actions.onSetRefreezeSpeed(value);
        }
        return;
      }
      const bus = input.dataset.audioVolume;
      if (bus !== 'effects' && bus !== 'music') return;
      const volume = Number(input.value);
      if (!Number.isFinite(volume)) return;
      if (bus === 'effects') {
        this.updateVolumeControl(
          this.effectsVolumeInput,
          this.effectsVolumeOutput,
          volume,
        );
        this.actions.onSetEffectsVolume(volume);
      } else {
        this.updateVolumeControl(
          this.musicVolumeInput,
          this.musicVolumeOutput,
          volume,
        );
        this.actions.onSetMusicVolume(volume);
      }
    });
    this.root.addEventListener('change', (event) => {
      const select = event.target as HTMLSelectElement;
      if (select.dataset.audioTrack !== 'music') return;
      this.actions.onSetMusicTrack(select.value);
    });
  }

