  private requireElement<T extends HTMLElement = HTMLElement>(selector: string): T {
    const element = this.root.querySelector<T>(selector);
    if (!element) throw new Error(`ICE-A-WAY driving UI element not found: ${selector}`);
    return element;
  }

  private updateWorldPosition(x: number, z: number, altitude?: number): void {
    this.positionValue.textContent = altitude === undefined
      ? `X ${x.toFixed(1)} · Z ${z.toFixed(1)}`
      : `X ${x.toFixed(1)} · Z ${z.toFixed(1)} · Y ${altitude.toFixed(1)}`;
  }

  private setAudioPanelOpen(open: boolean): void {
    if (open) {
      this.setAchievementPanelOpen(false);
      this.setRadioPanelOpen(false);
    }
    this.audioSettingsPanel.classList.toggle('is-hidden', !open);
    this.audioSettingsButton.classList.toggle('is-active', open);
    this.audioSettingsButton.setAttribute('aria-expanded', String(open));
  }

  private setDebugPanelOpen(open: boolean): void {
    if (open) {
      this.setAudioPanelOpen(false);
      this.setAchievementPanelOpen(false);
      this.setRadioPanelOpen(false);
    }
    this.debugSettingsPanel.classList.toggle('is-hidden', !open);
    this.debugSettingsButton.classList.toggle('is-active', open);
    this.debugSettingsButton.setAttribute(
      'aria-expanded',
      String(open),
    );
  }

  private setAchievementPanelOpen(open: boolean): void {
    if (open) {
      this.setAudioPanelOpen(false);
      this.setDebugPanelOpen(false);
      this.setRadioPanelOpen(false);
    }
    this.achievementPanel.classList.toggle('is-hidden', !open);
    this.achievementButton.classList.toggle('is-active', open);
    this.achievementButton.setAttribute(
      'aria-expanded',
      String(open),
    );
  }

  private setRadioPanelOpen(open: boolean): void {
    if (open) {
      this.setAudioPanelOpen(false);
      this.setDebugPanelOpen(false);
      this.setAchievementPanelOpen(false);
    }
    this.radioPanel.classList.toggle('is-hidden', !open);
    this.radioButton.classList.toggle('is-active', open);
    this.radioButton.setAttribute(
      'aria-expanded',
      String(open),
    );
  }

  private formatRadioTime(seconds: number): string {
    const totalMinutes = Math.max(
      0,
      Math.floor(seconds / 60),
    );
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    return `T+${String(hours).padStart(2, '0')}:${String(
      minutes,
    ).padStart(2, '0')}`;
  }

  private updateMusicPlayerControls(state: Readonly<{
    trackTitle: string;
    paused: boolean;
    repeat: boolean;
  }>): void {
    this.musicTrackTitle.textContent = state.trackTitle;
    this.musicPlaybackButton.textContent = state.paused
      ? 'PLAY'
      : 'PAUSE';
    this.musicPlaybackButton.setAttribute(
      'aria-label',
      state.paused ? 'Play music' : 'Pause music',
    );
    this.musicPlaybackButton.setAttribute(
      'aria-pressed',
      String(state.paused),
    );
    this.musicRepeatButton.classList.toggle(
      'is-active',
      state.repeat,
    );
    this.musicRepeatButton.setAttribute(
      'aria-pressed',
      String(state.repeat),
    );
  }

  private updateVolumeControl(
    input: HTMLInputElement,
    output: HTMLOutputElement,
    volume: number,
  ): void {
    const normalized = Math.max(0, Math.min(1, volume));
    input.value = normalized.toFixed(2);
    input.style.setProperty(
      '--range-progress',
      `${Math.round(normalized * 100)}%`,
    );
    output.value = `${Math.round(normalized * 100)}%`;
  }
