import {
  BoxGeometry,
  BufferGeometry,
  CylinderGeometry,
  Group,
  Mesh,
  MeshStandardMaterial,
  SphereGeometry,
  TorusGeometry,
  Float32BufferAttribute,
  type Material,
  type Object3D,
} from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import type {
  ConstructionPalette,
  ConstructionSurfaceId,
} from './ConstructionBlueprint';
import { getConstructionSurface } from './ConstructionSurfaceCatalog';
import type {
  ConstructionLoftSection,
  ConstructionModuleDefinition,
} from './ConstructionModuleCatalog';

const curvedOffset = (
  coordinate: number,
  span: number,
  degrees: number,
  profile: 'arc' | 'lens' = 'arc',
): number => {
  if (Math.abs(degrees) < 0.001) return 0;
  const angle = (Math.abs(degrees) * Math.PI) / 180;
  const radius = span / (2 * Math.sin(angle * 0.5));
  const edgeHeight = Math.sqrt(
    Math.max(0, radius * radius - span * span * 0.25),
  );
  if (profile === 'lens') {
    const sag = radius - edgeHeight;
    const normalized = Math.max(-1, Math.min(1, coordinate / (span * 0.5)));
    const lens = Math.pow(Math.max(0, Math.cos(normalized * Math.PI * 0.5)), 1.65);
    return (degrees < 0 ? -1 : 1) * sag * lens;
  }
  const offset = Math.sqrt(
    Math.max(0, radius * radius - coordinate * coordinate),
  ) - edgeHeight;
  return degrees < 0 ? -offset : offset;
};

export const createCurvedPanelGeometry = (
  width: number,
  height: number,
  thickness: number,
  horizontalArcDegrees: number,
  verticalArcDegrees: number,
  profile: 'arc' | 'lens' = 'arc',
): BufferGeometry => {
  const xSegments = Math.max(2, Math.ceil(Math.abs(horizontalArcDegrees) / 5));
  const ySegments = Math.max(2, Math.ceil(Math.abs(verticalArcDegrees) / 5));
  const columns = xSegments + 1;
  const rows = ySegments + 1;
  const vertices: number[] = [];
  const uvs: number[] = [];
  const indices: number[] = [];

  for (let side = 0; side < 2; side += 1) {
    const sideOffset = side === 0 ? thickness * 0.5 : -thickness * 0.5;
    for (let yIndex = 0; yIndex <= ySegments; yIndex += 1) {
      const v = yIndex / ySegments;
      const y = v * height - height * 0.5;
      for (let xIndex = 0; xIndex <= xSegments; xIndex += 1) {
        const u = xIndex / xSegments;
        const x = u * width - width * 0.5;
        const z =
          curvedOffset(x, width, horizontalArcDegrees, profile) +
          curvedOffset(y, height, verticalArcDegrees, profile) +
          sideOffset;
        vertices.push(x, y + height * 0.5, z);
        uvs.push(u, v);
      }
    }
  }

  const sideVertexCount = columns * rows;
  for (let yIndex = 0; yIndex < ySegments; yIndex += 1) {
    for (let xIndex = 0; xIndex < xSegments; xIndex += 1) {
      const a = yIndex * columns + xIndex;
      const b = a + 1;
      const c = a + columns;
      const d = c + 1;
      indices.push(a, c, b, b, c, d);
      const back = sideVertexCount;
      indices.push(
        back + a,
        back + b,
        back + c,
        back + b,
        back + d,
        back + c,
      );
    }
  }

  const connectEdge = (frontA: number, frontB: number): void => {
    const backA = frontA + sideVertexCount;
    const backB = frontB + sideVertexCount;
    indices.push(frontA, frontB, backA, frontB, backB, backA);
  };
  for (let xIndex = 0; xIndex < xSegments; xIndex += 1) {
    connectEdge(xIndex, xIndex + 1);
    const top = ySegments * columns;
    connectEdge(top + xIndex + 1, top + xIndex);
  }
  for (let yIndex = 0; yIndex < ySegments; yIndex += 1) {
    connectEdge((yIndex + 1) * columns, yIndex * columns);
    connectEdge(
      yIndex * columns + xSegments,
      (yIndex + 1) * columns + xSegments,
    );
  }

  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new Float32BufferAttribute(vertices, 3));
  geometry.setAttribute('uv', new Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  return geometry;
};

/**
 * Builds a closed hull volume by joining ordered X/Y cross-sections along Z.
 * Every section uses the same consistently ordered point topology, allowing
 * one primitive to describe parallel V-bottoms, rounded transoms, rising bows
 * and later asymmetric hull courses.
 */
export const createLoftedHullGeometry = (
  sourceSections: readonly ConstructionLoftSection[],
  capStart = true,
  capEnd = true,
): BufferGeometry => {
  if (sourceSections.length < 2) {
    throw new Error('A lofted hull needs at least two cross-sections.');
  }
  const sections = [...sourceSections].sort((left, right) => left.z - right.z);
  const pointCount = sections[0]?.points.length ?? 0;
  if (pointCount < 3) {
    throw new Error('A lofted hull cross-section needs at least three points.');
  }
  for (let index = 0; index < sections.length; index += 1) {
    const section = sections[index]!;
    if (
      !Number.isFinite(section.z) ||
      section.points.length !== pointCount ||
      section.points.some(
        (point) => !Number.isFinite(point.x) || !Number.isFinite(point.y),
      )
    ) {
      throw new Error('Lofted hull sections must use matching finite profiles.');
    }
    if (index > 0 && section.z <= sections[index - 1]!.z) {
      throw new Error('Lofted hull sections must occupy unique Z stations.');
    }
  }

  const vertices: number[] = [];
  const uvs: number[] = [];
  const indices: number[] = [];
  const zStart = sections[0]!.z;
  const zSpan = sections[sections.length - 1]!.z - zStart;

  for (const section of sections) {
    const v = (section.z - zStart) / zSpan;
    for (let pointIndex = 0; pointIndex < pointCount; pointIndex += 1) {
      const point = section.points[pointIndex]!;
      vertices.push(point.x, point.y, section.z);
      uvs.push(pointIndex / pointCount, v);
    }
  }

  for (let sectionIndex = 0; sectionIndex < sections.length - 1; sectionIndex += 1) {
    const current = sectionIndex * pointCount;
    const next = (sectionIndex + 1) * pointCount;
    for (let pointIndex = 0; pointIndex < pointCount; pointIndex += 1) {
      const following = (pointIndex + 1) % pointCount;
      const a = current + pointIndex;
      const b = current + following;
      const c = next + following;
      const d = next + pointIndex;
      indices.push(a, b, d, b, c, d);
    }
  }

  const addCap = (section: ConstructionLoftSection, start: boolean): void => {
    const centre = section.points.reduce(
      (result, point) => ({
        x: result.x + point.x / pointCount,
        y: result.y + point.y / pointCount,
      }),
      { x: 0, y: 0 },
    );
    const xs = section.points.map((point) => point.x);
    const ys = section.points.map((point) => point.y);
    const minX = Math.min(...xs);
    const maxX = Math.max(...xs);
    const minY = Math.min(...ys);
    const maxY = Math.max(...ys);
    const width = Math.max(0.001, maxX - minX);
    const height = Math.max(0.001, maxY - minY);
    const centreIndex = vertices.length / 3;
    vertices.push(centre.x, centre.y, section.z);
    uvs.push((centre.x - minX) / width, (centre.y - minY) / height);
    const ringStart = vertices.length / 3;
    for (const point of section.points) {
      vertices.push(point.x, point.y, section.z);
      uvs.push((point.x - minX) / width, (point.y - minY) / height);
    }
    for (let pointIndex = 0; pointIndex < pointCount; pointIndex += 1) {
      const following = (pointIndex + 1) % pointCount;
      if (start) {
        indices.push(
          centreIndex,
          ringStart + following,
          ringStart + pointIndex,
        );
      } else {
        indices.push(
          centreIndex,
          ringStart + pointIndex,
          ringStart + following,
        );
      }
    }
  };

  if (capStart) addCap(sections[0]!, true);
  if (capEnd) addCap(sections[sections.length - 1]!, false);

  const geometry = new BufferGeometry();
  geometry.name = 'Construction lofted hull';
  geometry.setAttribute('position', new Float32BufferAttribute(vertices, 3));
  geometry.setAttribute('uv', new Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  return geometry;
};

const createBox = (
  width: number,
  height: number,
  length: number,
  bevel = 0,
): BufferGeometry => {
  const geometry =
    bevel > 0
      ? new RoundedBoxGeometry(width, height, length, 2, bevel)
      : new BoxGeometry(width, height, length);
  geometry.translate(0, height * 0.5, 0);
  return geometry;
};

const materialFor = (
  color: string,
  preview: boolean,
  surfaceId: ConstructionSurfaceId = 'painted-steel',
  metalnessOverride?: number,
): MeshStandardMaterial => {
  const surface = getConstructionSurface(surfaceId);
  return new MeshStandardMaterial({
    color,
    roughness: surface.roughness,
    metalness: metalnessOverride ?? surface.metalness,
    transparent: preview,
    opacity: preview ? 0.52 : 1,
    depthWrite: !preview,
  });
};

const addMesh = (
  root: Group,
  geometry: BufferGeometry,
  material: Material,
): Mesh => {
  const mesh = new Mesh(geometry, material);
  root.add(mesh);
  return mesh;
};

export const createConstructionModuleObject = (
  definition: Readonly<ConstructionModuleDefinition>,
  palette: Readonly<ConstructionPalette>,
  materialId: keyof ConstructionPalette,
  preview = false,
  surfaceId: ConstructionSurfaceId = definition.defaultSurface,
): Group => {
  const root = new Group();
  root.name = definition.label;
  const color = palette[materialId];
  const mainMaterial = materialFor(color, preview, surfaceId);
  const geometry = definition.geometry;

  if (geometry.kind === 'box') {
    addMesh(
      root,
      createBox(
        geometry.width,
        geometry.height,
        geometry.length,
        geometry.bevel,
      ),
      mainMaterial,
    );
  } else if (geometry.kind === 'curved-panel') {
    addMesh(
      root,
      createCurvedPanelGeometry(
        geometry.width,
        geometry.height,
        geometry.thickness,
        geometry.horizontalArcDegrees,
        geometry.verticalArcDegrees,
        geometry.profile,
      ),
      mainMaterial,
    );
  } else if (geometry.kind === 'round-transition') {
    const rounded = new SphereGeometry(1, 20, 12);
    rounded.scale(
      geometry.width * 0.5,
      geometry.height * 0.5,
      geometry.length * 0.5,
    );
    rounded.translate(0, geometry.height * 0.5, 0);
    addMesh(root, rounded, mainMaterial);
  } else if (geometry.kind === 'lofted-hull') {
    addMesh(
      root,
      createLoftedHullGeometry(
        geometry.sections,
        geometry.capStart ?? true,
        geometry.capEnd ?? true,
      ),
      mainMaterial,
    );
  } else if (geometry.kind === 'window') {
    const frameMaterial = materialFor(color, preview, surfaceId, 0.55);
    const glassMaterial = materialFor(
      '#173f50',
      preview,
      'painted-steel',
      0.45,
    );
    glassMaterial.roughness = 0.18;
    if (geometry.round) {
      const frame = new TorusGeometry(
        geometry.width * 0.39,
        geometry.width * 0.11,
        8,
        24,
      );
      addMesh(root, frame, frameMaterial);
      const glass = new CylinderGeometry(
        geometry.width * 0.34,
        geometry.width * 0.34,
        geometry.depth * 0.55,
        24,
      );
      glass.rotateX(Math.PI * 0.5);
      addMesh(root, glass, glassMaterial);
    } else {
      const outer = createBox(
        geometry.width,
        geometry.height,
        geometry.depth,
        0.08,
      );
      outer.translate(0, -geometry.height * 0.5, 0);
      addMesh(root, outer, frameMaterial);
      const pane = createBox(
        geometry.width * 0.78,
        geometry.height * 0.7,
        geometry.depth * 1.12,
        0.055,
      );
      pane.translate(0, -geometry.height * 0.5, 0.006);
      addMesh(root, pane, glassMaterial);
    }
  } else if (geometry.kind === 'fender') {
    const body = new CylinderGeometry(
      geometry.radius,
      geometry.radius,
      geometry.height,
      12,
    );
    addMesh(root, body, mainMaterial);
    const capMaterial = materialFor('#152226', preview, 'rubber', 0.08);
    for (const y of [-geometry.height * 0.51, geometry.height * 0.51]) {
      const cap = new Mesh(
        new TorusGeometry(geometry.radius * 0.82, geometry.radius * 0.13, 6, 14),
        capMaterial,
      );
      cap.rotation.x = Math.PI * 0.5;
      cap.position.y = y;
      root.add(cap);
    }
  } else if (geometry.kind === 'railing') {
    const railMaterial = materialFor(color, preview, surfaceId, 0.7);
    const vertical = new CylinderGeometry(0.035, 0.035, geometry.height, 8);
    for (const x of [-geometry.width * 0.45, geometry.width * 0.45]) {
      const post = addMesh(root, vertical.clone(), railMaterial);
      post.position.x = x;
    }
    const horizontal = new CylinderGeometry(
      0.045,
      0.045,
      geometry.width,
      8,
    );
    horizontal.rotateZ(Math.PI * 0.5);
    for (const y of [-geometry.height * 0.4, geometry.height * 0.4]) {
      const rail = addMesh(root, horizontal.clone(), railMaterial);
      rail.position.y = y;
      rail.position.z = geometry.depth * 0.25;
    }
  } else if (geometry.kind === 'mechanism') {
    const darkMaterial = materialFor(
      '#203238',
      preview,
      'galvanized-steel',
    );
    const animated = new Group();
    const mechanism = definition.mechanism;
    if (mechanism) {
      animated.userData.constructionAnimation = {
        axis: mechanism.animationAxis,
        speed: mechanism.animationSpeed,
      };
    }
    if (geometry.mechanism === 'generator') {
      addMesh(
        root,
        createBox(geometry.width, 0.18, geometry.length, 0.05),
        darkMaterial,
      );
      const body = addMesh(
        root,
        createBox(0.78, 0.62, 1.1, 0.12),
        mainMaterial,
      );
      body.position.y = 0.18;
      const flywheel = new CylinderGeometry(0.31, 0.31, 0.18, 18);
      flywheel.rotateX(Math.PI * 0.5);
      addMesh(animated, flywheel, darkMaterial);
      animated.position.set(0, 0.53, 0.64);
      root.add(animated);
    } else if (geometry.mechanism === 'winch') {
      addMesh(
        root,
        createBox(geometry.width, 0.16, geometry.length, 0.05),
        darkMaterial,
      );
      const drum = new CylinderGeometry(0.3, 0.3, 0.62, 18);
      drum.rotateX(Math.PI * 0.5);
      addMesh(animated, drum, mainMaterial);
      animated.position.y = 0.58;
      root.add(animated);
      for (const x of [-0.4, 0.4]) {
        const support = addMesh(
          root,
          createBox(0.12, 0.62, 0.18, 0.025),
          darkMaterial,
        );
        support.position.set(x, 0.16, 0);
      }
    } else if (geometry.mechanism === 'resource-drill') {
      addMesh(
        root,
        createBox(geometry.width, 0.2, geometry.length, 0.06),
        darkMaterial,
      );
      for (const x of [-0.55, 0.55]) {
        const mast = addMesh(
          root,
          createBox(0.14, geometry.height * 0.86, 0.14, 0.025),
          mainMaterial,
        );
        mast.position.set(x, 0.2, 0);
      }
      const drill = new CylinderGeometry(0.12, 0.24, geometry.height * 0.78, 12);
      addMesh(animated, drill, darkMaterial);
      animated.position.y = geometry.height * 0.52;
      root.add(animated);
    } else {
      const pedestal = addMesh(
        root,
        new CylinderGeometry(0.3, 0.42, 0.72, 16),
        darkMaterial,
      );
      pedestal.position.y = 0.36;
      const tower = addMesh(
        animated,
        createBox(0.34, geometry.height * 0.68, 0.34, 0.04),
        mainMaterial,
      );
      tower.position.y = 0.68;
      const boom = addMesh(
        animated,
        createBox(0.24, 0.24, geometry.length * 1.2, 0.04),
        mainMaterial,
      );
      boom.position.set(0, geometry.height * 0.72, geometry.length * 0.42);
      boom.rotation.x = -0.22;
      animated.position.y = 0.72;
      root.add(animated);
    }
  } else {
    const badge = new CylinderGeometry(
      geometry.radius,
      geometry.radius,
      geometry.depth,
      6,
    );
    badge.rotateX(Math.PI * 0.5);
    addMesh(root, badge, mainMaterial);
  }

  return root;
};

export const disposeConstructionObject = (object: Object3D): void => {
  const geometries = new Set<BufferGeometry>();
  const materials = new Set<Material>();
  object.traverse((child) => {
    const mesh = child as Mesh;
    if (mesh.geometry) geometries.add(mesh.geometry);
    if (Array.isArray(mesh.material)) {
      for (const material of mesh.material) materials.add(material);
    } else if (mesh.material) {
      materials.add(mesh.material);
    }
  });
  for (const geometry of geometries) geometry.dispose();
  for (const material of materials) material.dispose();
};
