import {
  BoxGeometry,
  BufferGeometry,
  Color,
  Float32BufferAttribute,
  Group,
  InstancedMesh,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  Shape,
  ShapeGeometry,
  type Scene,
} from 'three';
import {
  ICEAWAY_PROTOTYPE_WORLD_ORIGIN,
} from '../world/PrototypeWorldPositionAdapter';
import type {
  RuntimeWorldChunkDescriptor,
  RuntimeWorldChunkListener,
} from '../world/RuntimeWorldChunks';
import { ICEAWAY_TARGET_WORLD_PARTITION } from '../world/WorldPartitionTypes';
import {
  BOREALIS_GROUND_HEIGHT,
  BOREALIS_WORKSHOP_SNOWFIELD,
  borealisCoastX,
} from './BorealisLand';

interface PrototypeChunkBounds {
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
}

const chunkKey = (x: number, z: number): string => `${x},${z}`;

export const prototypeBoundsForChunk = (
  chunkX: number,
  chunkZ: number,
): PrototypeChunkBounds => {
  const size = ICEAWAY_TARGET_WORLD_PARTITION.chunkSizeMetres;
  const minX =
    (chunkX - ICEAWAY_PROTOTYPE_WORLD_ORIGIN.chunk.x) * size -
    ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.xMetres;
  const minZ =
    (chunkZ - ICEAWAY_PROTOTYPE_WORLD_ORIGIN.chunk.z) * size -
    ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.zMetres;
  return {
    minX,
    maxX: minX + size,
    minZ,
    maxZ: minZ + size,
  };
};

export class BorealisMainlandRenderer
  implements RuntimeWorldChunkListener
{
  private readonly root = new Group();
  private readonly chunks = new Map<string, Group>();
  private readonly groundMaterial = new MeshStandardMaterial({
    color: new Color(0xdbe9e7),
    roughness: 0.97,
    metalness: 0,
  });
  private readonly coastMaterial = new MeshStandardMaterial({
    color: new Color(0xffffff),
    vertexColors: true,
    roughness: 0.9,
    metalness: 0,
  });
  private readonly markerMaterial = new MeshStandardMaterial({
    color: new Color(0xf0b84e),
    emissive: new Color(0x5e3608),
    emissiveIntensity: 0.32,
    roughness: 0.68,
    metalness: 0.05,
  });
  private workshopMarker?: Group;

  public constructor(scene: Scene) {
    this.root.name = 'Borealis western mainland chunks';
    scene.add(this.root);
  }

  public onChunkActivated(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void {
    if (
      chunk.kind !== 'WESTERN_MAINLAND' &&
      chunk.kind !== 'BOREALIS_COAST'
    ) {
      return;
    }
    const key = chunkKey(chunk.address.x, chunk.address.z);
    if (this.chunks.has(key)) return;
    const group = this.createChunk(chunk);
    this.chunks.set(key, group);
    this.root.add(group);
  }

  public onChunkDeactivated(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void {
    const key = chunkKey(chunk.address.x, chunk.address.z);
    const group = this.chunks.get(key);
    if (!group) return;
    this.chunks.delete(key);
    this.root.remove(group);
    group.traverse((object) => {
      if (object instanceof Mesh) object.geometry.dispose();
    });
  }

  public getActiveChunkCount(): number {
    return this.chunks.size;
  }

  public setExpeditionActive(active: boolean): void {
    if (this.workshopMarker) this.workshopMarker.visible = active;
  }

  public dispose(): void {
    for (const group of this.chunks.values()) {
      this.root.remove(group);
      group.traverse((object) => {
        if (object instanceof Mesh) object.geometry.dispose();
      });
    }
    this.chunks.clear();
    this.groundMaterial.dispose();
    this.coastMaterial.dispose();
    this.markerMaterial.dispose();
    this.root.removeFromParent();
  }

  private createChunk(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): Group {
    const chunkBounds = prototypeBoundsForChunk(
      chunk.address.x,
      chunk.address.z,
    );
    const bounds = chunkBounds;
    const group = new Group();
    group.name = `World chunk ${chunk.address.x},${chunk.address.z} ${chunk.kind}`;
    const top = new Mesh(
      this.createTopGeometry(bounds),
      this.groundMaterial,
    );
    top.position.y = BOREALIS_GROUND_HEIGHT - 0.035;
    top.receiveShadow = true;
    top.castShadow = true;
    group.add(top);

    if (chunk.kind === 'BOREALIS_COAST') {
      const coast = new Mesh(
        this.createCoastGeometry(bounds),
        this.coastMaterial,
      );
      coast.receiveShadow = true;
      coast.castShadow = true;
      group.add(coast);
    }
    this.addLandmarks(group, bounds);
    return group;
  }

  private createTopGeometry(bounds: PrototypeChunkBounds): BufferGeometry {
    const shape = new Shape();
    shape.moveTo(bounds.minX, -bounds.minZ);
    shape.lineTo(bounds.minX, -bounds.maxZ);
    const samples = 128;
    for (let index = samples; index >= 0; index -= 1) {
      const z =
        bounds.minZ +
        (bounds.maxZ - bounds.minZ) * (index / samples);
      const coast = Math.min(
        bounds.maxX,
        borealisCoastX(z) - 0.9,
      );
      shape.lineTo(Math.max(bounds.minX, coast), -z);
    }
    shape.closePath();
    const geometry = new ShapeGeometry(shape, 12);
    geometry.rotateX(-Math.PI / 2);
    geometry.computeVertexNormals();
    return geometry;
  }

  private createCoastGeometry(bounds: PrototypeChunkBounds): BufferGeometry {
    const positions: number[] = [];
    const colors: number[] = [];
    const indices: number[] = [];
    const samples = 128;
    const crossSection = [
      {
        x: -0.9,
        y: BOREALIS_GROUND_HEIGHT - 0.035,
        color: new Color(0xd8e5df),
      },
      { x: -0.15, y: 0.12, color: new Color(0xb7c5b5) },
      { x: 0.72, y: -0.075, color: new Color(0x7da8a2) },
      { x: 2.8, y: -0.28, color: new Color(0x477b7a) },
    ] as const;
    for (let index = 0; index <= samples; index += 1) {
      const z =
        bounds.minZ +
        (bounds.maxZ - bounds.minZ) * (index / samples);
      const x = borealisCoastX(z);
      for (const point of crossSection) {
        positions.push(x + point.x, point.y, z);
        colors.push(point.color.r, point.color.g, point.color.b);
      }
      if (index >= samples) continue;
      const base = index * crossSection.length;
      const next = base + crossSection.length;
      for (
        let strip = 0;
        strip < crossSection.length - 1;
        strip += 1
      ) {
        indices.push(
          base + strip,
          base + strip + 1,
          next + strip,
          next + strip,
          base + strip + 1,
          next + strip + 1,
        );
      }
    }
    const geometry = new BufferGeometry();
    geometry.setAttribute(
      'position',
      new Float32BufferAttribute(positions, 3),
    );
    geometry.setAttribute(
      'color',
      new Float32BufferAttribute(colors, 3),
    );
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    return geometry;
  }

  private addLandmarks(
    group: Group,
    bounds: PrototypeChunkBounds,
  ): void {
    this.addWorkshopMarker(group, bounds);
  }

  private addWorkshopMarker(
    group: Group,
    bounds: PrototypeChunkBounds,
  ): void {
    const field = BOREALIS_WORKSHOP_SNOWFIELD;
    if (
      field.centerX < bounds.minX ||
      field.centerX > bounds.maxX ||
      field.centerZ < bounds.minZ ||
      field.centerZ > bounds.maxZ
    ) {
      return;
    }
    const marker = new Group();
    marker.name = 'Borealis workshop snowfield marker';
    marker.position.set(field.centerX, 0, field.centerZ);
    marker.visible = false;
    this.workshopMarker = marker;
    const boxes = new InstancedMesh(
      new BoxGeometry(1, 1, 1),
      this.markerMaterial,
      8,
    );
    const transform = new Object3D();
    let index = 0;
    const setBox = (
      x: number,
      y: number,
      z: number,
      width: number,
      height: number,
      depth: number,
    ): void => {
      transform.position.set(x, y, z);
      transform.rotation.set(0, 0, 0);
      transform.scale.set(width, height, depth);
      transform.updateMatrix();
      boxes.setMatrixAt(index, transform.matrix);
      index += 1;
    };
    for (const x of [-field.halfWidth, field.halfWidth]) {
      for (const z of [-field.halfHeight, field.halfHeight]) {
        setBox(x, BOREALIS_GROUND_HEIGHT + 0.72, z, 0.13, 1.45, 0.13);
      }
    }
    for (const z of [-field.halfHeight, field.halfHeight]) {
      setBox(0, BOREALIS_GROUND_HEIGHT + 0.55, z, field.halfWidth * 2, 0.09, 0.09);
    }
    for (const x of [-field.halfWidth, field.halfWidth]) {
      setBox(x, BOREALIS_GROUND_HEIGHT + 0.55, 0, 0.09, 0.09, field.halfHeight * 2);
    }
    boxes.instanceMatrix.needsUpdate = true;
    boxes.castShadow = true;
    marker.add(boxes);
    group.add(marker);
  }
}
