import {
  type DefinitionId,
  type PersistentEntityId,
  controlSlotId,
  definitionId,
  persistentEntityId,
} from '../../netcode/core/NetworkPrimitives';
import type {
  SharedEntityDefinition,
  SharedEntityRegistration,
} from './SharedEntityRegistry';

export const ICEWAY_CONTROL_SLOTS = Object.freeze({
  body: controlSlotId('body'),
  driver: controlSlotId('driver'),
  pilot: controlSlotId('pilot'),
});

export const ICEWAY_ENTITY_DEFINITIONS = Object.freeze({
  penguin: definitionId('character:penguin'),
  starterDozer: definitionId('vehicle:starter-dozer'),
  heavyDozer: definitionId('vehicle:heavy-dozer'),
  wheelLoader: definitionId('vehicle:wheel-loader'),
  snowTruck: definitionId('vehicle:snow-truck'),
  helicopter: definitionId('vehicle:utility-helicopter'),
  smallSnowTrailer: definitionId('trailer:small-snow-conveyor'),
  playerIcebreaker: definitionId('vessel:player-icebreaker'),
} satisfies Readonly<Record<string, DefinitionId>>);

export const ICEWAY_PERSISTENT_ENTITY_IDS = Object.freeze({
  starterDozer: persistentEntityId('vehicle:borealis:starter-dozer'),
  heavyDozer: persistentEntityId('vehicle:borealis:heavy-dozer:1'),
  wheelLoader: persistentEntityId('vehicle:borealis:wheel-loader:1'),
  snowTruck: persistentEntityId('vehicle:borealis:snow-truck:1'),
  helicopter: persistentEntityId('vehicle:borealis:helicopter:1'),
  smallSnowTrailer: persistentEntityId('trailer:borealis:small-snow:1'),
  playerIcebreaker: persistentEntityId('vessel:borealis:player-icebreaker'),
} satisfies Readonly<Record<string, PersistentEntityId>>);

export const LAND_MACHINE_ENTITY_ID_BY_TYPE = Object.freeze({
  HEAVY_DOZER: ICEWAY_PERSISTENT_ENTITY_IDS.heavyDozer,
  WHEEL_LOADER: ICEWAY_PERSISTENT_ENTITY_IDS.wheelLoader,
  SNOW_TRUCK: ICEWAY_PERSISTENT_ENTITY_IDS.snowTruck,
  HELICOPTER: ICEWAY_PERSISTENT_ENTITY_IDS.helicopter,
});

export type ManifestLandMachineType = keyof typeof LAND_MACHINE_ENTITY_ID_BY_TYPE;

/** Migration seam for v6 land saves that identify the one parked machine by type. */
export const persistentEntityIdForLandMachine = (
  type: ManifestLandMachineType,
): PersistentEntityId => LAND_MACHINE_ENTITY_ID_BY_TYPE[type];

