import {
  ICEAWAY_TARGET_WORLD_PARTITION,
  isChunkInWorldPartition,
  type WorldChunkAddress,
  type WorldPartitionDefinition,
} from './WorldPartitionTypes';
import type { GlobalPosition } from './GlobalPosition';

export type RuntimeWorldChunkKind =
  | 'LEGACY_PROTOTYPE'
  | 'SEA'
  | 'BOREALIS_COAST'
  | 'WESTERN_MAINLAND';

export interface RuntimeWorldChunkDescriptor {
  readonly address: WorldChunkAddress;
  readonly kind: RuntimeWorldChunkKind;
  readonly seed: number;
}

export interface WorldDataProvider {
  readonly id: string;
  readonly partition: Readonly<WorldPartitionDefinition>;
  getChunk(
    address: Readonly<WorldChunkAddress>,
  ): Readonly<RuntimeWorldChunkDescriptor> | undefined;
}

export interface RuntimeWorldChunkListener {
  onChunkActivated(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void;
  onChunkDeactivated(
    chunk: Readonly<RuntimeWorldChunkDescriptor>,
  ): void;
}

export interface RuntimeWorldChunkStats {
  activeChunks: number;
  activatedChunks: number;
  deactivatedChunks: number;
  centerChunk?: WorldChunkAddress;
}

const chunkKey = (address: Readonly<WorldChunkAddress>): string =>
  `${address.x},${address.z}`;

const chunkSeed = (
  address: Readonly<WorldChunkAddress>,
  salt: number,
): number => {
  let value = Math.imul(address.x ^ salt, 0x45d9f3b);
  value = Math.imul(value ^ address.z, 0x45d9f3b);
  return (value ^ (value >>> 16)) >>> 0;
};

export class LegacyPrototypeWorldProvider implements WorldDataProvider {
  public readonly id = 'legacy-prototype-world';
  public readonly partition = ICEAWAY_TARGET_WORLD_PARTITION;

  public getChunk(
    address: Readonly<WorldChunkAddress>,
  ): Readonly<RuntimeWorldChunkDescriptor> | undefined {
    if (address.x !== 12 || address.z !== 16) return undefined;
    return {
      address: { ...address },
      kind: 'LEGACY_PROTOTYPE',
      seed: chunkSeed(address, 34711),
    };
  }
}

/**
 * Runtime bridge used while the compiled raster provider remains opt-in.
 * It keeps the current prototype in its authored centre chunk and exposes
 * deterministic neighbouring terrain without growing the legacy ice grid.
 */
export class BorealisMainlandWorldProvider implements WorldDataProvider {
  public readonly id = 'borealis-mainland-runtime-bridge';
  public readonly partition = ICEAWAY_TARGET_WORLD_PARTITION;

  public constructor(
    private readonly legacy: WorldDataProvider =
      new LegacyPrototypeWorldProvider(),
  ) {}

  public getChunk(
    address: Readonly<WorldChunkAddress>,
  ): Readonly<RuntimeWorldChunkDescriptor> | undefined {
    if (!isChunkInWorldPartition(this.partition, address)) {
      return undefined;
    }
    const legacyChunk = this.legacy.getChunk(address);
    if (legacyChunk) {
      return {
        ...legacyChunk,
        kind: 'BOREALIS_COAST',
      };
    }
    return {
      address: { ...address },
      kind: address.x < 12 ? 'WESTERN_MAINLAND' : 'SEA',
      seed: chunkSeed(address, 91373),
    };
  }
}

export class RuntimeWorldChunkManager {
  private readonly active = new Map<
    string,
    Readonly<RuntimeWorldChunkDescriptor>
  >();
  private readonly listeners = new Set<RuntimeWorldChunkListener>();
  private centerChunk?: WorldChunkAddress;
  private activatedChunks = 0;
  private deactivatedChunks = 0;

  public constructor(
    public readonly provider: WorldDataProvider,
    private readonly activeRadius = 1,
  ) {}

  public addListener(listener: RuntimeWorldChunkListener): void {
    this.listeners.add(listener);
    for (const chunk of this.active.values()) {
      listener.onChunkActivated(chunk);
    }
  }

  public removeListener(listener: RuntimeWorldChunkListener): void {
    this.listeners.delete(listener);
  }

  public update(position: Readonly<GlobalPosition>): boolean {
    const center = position.chunk;
    if (
      this.centerChunk?.x === center.x &&
      this.centerChunk.z === center.z
    ) {
      return false;
    }
    this.centerChunk = { ...center };
    const requested = new Map<
      string,
      Readonly<RuntimeWorldChunkDescriptor>
    >();
    for (
      let z = center.z - this.activeRadius;
      z <= center.z + this.activeRadius;
      z += 1
    ) {
      for (
        let x = center.x - this.activeRadius;
        x <= center.x + this.activeRadius;
        x += 1
      ) {
        const chunk = this.provider.getChunk({ x, z });
        if (chunk) requested.set(chunkKey(chunk.address), chunk);
      }
    }

    let changed = false;
    for (const [key, chunk] of this.active) {
      if (requested.has(key)) continue;
      this.active.delete(key);
      this.deactivatedChunks += 1;
      changed = true;
      for (const listener of this.listeners) {
        listener.onChunkDeactivated(chunk);
      }
    }
    for (const [key, chunk] of requested) {
      if (this.active.has(key)) continue;
      this.active.set(key, chunk);
      this.activatedChunks += 1;
      changed = true;
      for (const listener of this.listeners) {
        listener.onChunkActivated(chunk);
      }
    }
    return changed;
  }

  public getActiveChunks(): readonly Readonly<RuntimeWorldChunkDescriptor>[] {
    return [...this.active.values()];
  }

  public getStats(): RuntimeWorldChunkStats {
    return {
      activeChunks: this.active.size,
      activatedChunks: this.activatedChunks,
      deactivatedChunks: this.deactivatedChunks,
      ...(this.centerChunk
        ? { centerChunk: { ...this.centerChunk } }
        : {}),
    };
  }

  public dispose(): void {
    for (const chunk of this.active.values()) {
      for (const listener of this.listeners) {
        listener.onChunkDeactivated(chunk);
      }
    }
    this.active.clear();
    this.listeners.clear();
  }
}
