import { clamp } from '../utils/math';

export interface PortIcePoint {
  readonly x: number;
  readonly z: number;
}

interface PortShorelineBase {
  readonly offsetX?: number;
  readonly offsetZ?: number;
}

export interface CircularPortShoreline extends PortShorelineBase {
  readonly kind: 'circle';
  readonly radius: number;
}

export interface EllipticalPortShoreline extends PortShorelineBase {
  readonly kind: 'ellipse';
  readonly radiusX: number;
  readonly radiusZ: number;
  readonly rotation?: number;
}

export interface PolygonPortShoreline extends PortShorelineBase {
  readonly kind: 'polygon';
  readonly points: readonly PortIcePoint[];
  readonly rotation?: number;
}

export interface CompoundPortShoreline extends PortShorelineBase {
  readonly kind: 'compound';
  readonly parts: readonly PortShorelineShape[];
}

export type PortShorelineShape =
  | CircularPortShoreline
  | EllipticalPortShoreline
  | PolygonPortShoreline
  | CompoundPortShoreline;

export interface PortIceAccessProfile {
  readonly shoreline: PortShorelineShape;
  readonly clearanceDistance: number;
  readonly minimumCellOpenness: number;
  readonly requiredOpenRatio: number;
  readonly requireDockConnection: boolean;
  readonly startingBerthClearRadius?: number;
}

export interface PortIceAccessDefinition {
  readonly id: string;
  readonly worldPosition: PortIcePoint;
  readonly dock: {
    readonly worldPosition: PortIcePoint;
    readonly radius: number;
  };
  readonly iceAccess: PortIceAccessProfile;
}

const rotateIntoLocalSpace = (
  x: number,
  z: number,
  rotation = 0,
): PortIcePoint => {
  const cosine = Math.cos(rotation);
  const sine = Math.sin(rotation);
  return {
    x: x * cosine + z * sine,
    z: -x * sine + z * cosine,
  };
};

const pointSegmentDistance = (
  point: Readonly<PortIcePoint>,
  start: Readonly<PortIcePoint>,
  end: Readonly<PortIcePoint>,
): number => {
  const deltaX = end.x - start.x;
  const deltaZ = end.z - start.z;
  const lengthSquared = deltaX * deltaX + deltaZ * deltaZ;
  if (lengthSquared <= 0.000001) {
    return Math.hypot(point.x - start.x, point.z - start.z);
  }
  const t = clamp(
    (
      (point.x - start.x) * deltaX +
      (point.z - start.z) * deltaZ
    ) / lengthSquared,
    0,
    1,
  );
  return Math.hypot(
    point.x - (start.x + deltaX * t),
    point.z - (start.z + deltaZ * t),
  );
};

const polygonContainsPoint = (
  point: Readonly<PortIcePoint>,
  points: readonly PortIcePoint[],
): boolean => {
  let inside = false;
  for (
    let current = 0, previous = points.length - 1;
    current < points.length;
    previous = current, current += 1
  ) {
    const a = points[current];
    const b = points[previous];
    if (!a || !b) continue;
    const intersects =
      (a.z > point.z) !== (b.z > point.z) &&
      point.x <
        (
          (b.x - a.x) * (point.z - a.z) /
          (b.z - a.z)
        ) +
          a.x;
    if (intersects) inside = !inside;
  }
  return inside;
};

const localSignedDistance = (
  x: number,
  z: number,
  shape: Readonly<PortShorelineShape>,
): number => {
  const shiftedX = x - (shape.offsetX ?? 0);
  const shiftedZ = z - (shape.offsetZ ?? 0);

  if (shape.kind === 'circle') {
    return Math.hypot(shiftedX, shiftedZ) - shape.radius;
  }
  if (shape.kind === 'ellipse') {
    const point = rotateIntoLocalSpace(
      shiftedX,
      shiftedZ,
      shape.rotation,
    );
    const angle = Math.atan2(point.z, point.x);
    const cosine = Math.cos(angle);
    const sine = Math.sin(angle);
    const boundaryRadius =
      1 /
      Math.sqrt(
        cosine * cosine / (shape.radiusX * shape.radiusX) +
          sine * sine / (shape.radiusZ * shape.radiusZ),
      );
    return Math.hypot(point.x, point.z) - boundaryRadius;
  }
  if (shape.kind === 'compound') {
    let distance = Number.POSITIVE_INFINITY;
    for (const part of shape.parts) {
      distance = Math.min(
        distance,
        localSignedDistance(shiftedX, shiftedZ, part),
      );
    }
    return distance;
  }

  if (shape.points.length < 3) {
    return Number.POSITIVE_INFINITY;
  }
  const point = rotateIntoLocalSpace(
    shiftedX,
    shiftedZ,
    shape.rotation,
  );
  let edgeDistance = Number.POSITIVE_INFINITY;
  for (let index = 0; index < shape.points.length; index += 1) {
    const start = shape.points[index];
    const end = shape.points[(index + 1) % shape.points.length];
    if (!start || !end) continue;
    edgeDistance = Math.min(
      edgeDistance,
      pointSegmentDistance(point, start, end),
    );
  }
  return polygonContainsPoint(point, shape.points)
    ? -edgeDistance
    : edgeDistance;
};

export const signedDistanceToPortShoreline = (
  point: Readonly<PortIcePoint>,
  portPosition: Readonly<PortIcePoint>,
  shoreline: Readonly<PortShorelineShape>,
): number =>
  localSignedDistance(
    point.x - portPosition.x,
    point.z - portPosition.z,
    shoreline,
  );

export const isInsidePortLand = (
  point: Readonly<PortIcePoint>,
  definition: Readonly<PortIceAccessDefinition>,
): boolean =>
  signedDistanceToPortShoreline(
    point,
    definition.worldPosition,
    definition.iceAccess.shoreline,
  ) <= 0;

export const isInsidePortClearanceArea = (
  point: Readonly<PortIcePoint>,
  definition: Readonly<PortIceAccessDefinition>,
): boolean => {
  const distance = signedDistanceToPortShoreline(
    point,
    definition.worldPosition,
    definition.iceAccess.shoreline,
  );
  return (
    distance > 0 &&
    distance <= definition.iceAccess.clearanceDistance
  );
};

export const portClearanceOuterDistance = (
  point: Readonly<PortIcePoint>,
  definition: Readonly<PortIceAccessDefinition>,
): number =>
  definition.iceAccess.clearanceDistance -
  signedDistanceToPortShoreline(
    point,
    definition.worldPosition,
    definition.iceAccess.shoreline,
  );
