import type {
  UpgradeCategory,
  UpgradeOwnershipType,
} from '../gameplay/definitions/GameplayTypes';
import { ObjectInspectionViewport } from '../rendering/ObjectInspectionViewport';
import { PLAYER_VESSEL_MODEL_TUNING } from '../vessels/PlayerVesselModelTuning';

export interface DockUpgradeViewModel {
  id: string;
  displayName: string;
  description: string;
  category: UpgradeCategory;
  ownershipType: UpgradeOwnershipType;
  price: number;
  available: boolean;
  owned: boolean;
  installed: boolean;
  canPurchase: boolean;
  canInstall: boolean;
  canRemove: boolean;
  status: string;
}

export interface DockMissionOfferViewModel {
  id: string;
  displayName: string;
  description: string;
  rewardMoney: number;
  status: 'OFFERED' | 'ACTIVE';
  action?: {
    id: string;
    label: string;
    status: string;
    enabled: boolean;
  };
}

export interface DockViewModel {
  portId: string;
  portName: string;
  portDescription: string;
  accent: number;
  money: number;
  moduleSlots: number;
  installedModules: number;
  breakPower: number;
  enginePower: number;
  agility: number;
  fuelEfficiency: number;
  missionOffers: readonly DockMissionOfferViewModel[];
  upgrades: readonly DockUpgradeViewModel[];
  canExploreSurroundings: boolean;
  canUsePlaytestCredits: boolean;
}

export interface DockUIActions {
  onUndock: () => void;
  onExploreSurroundings: () => void;
  onPurchase: (upgradeId: string) => void;
  onToggleModule: (upgradeId: string) => void;
  onAcceptMission: (missionId: string) => void;
  onPerformMissionAction: (actionId: string) => void;
  onAddPlaytestCredits: () => void;
}

type DockServiceTab = 'jobs' | 'refit';

const PLAYER_VESSEL_MODEL_URL =
  './assets/models/player-icebreaker.glb';

const escapeHtml = (value: string): string =>
  value.replace(/[&<>"']/g, (character) => {
    const entities: Record<string, string> = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#039;',
    };
    return entities[character] ?? character;
  });

const accentHex = (accent: number): string =>
  `#${Math.max(0, accent).toString(16).padStart(6, '0').slice(-6)}`;

export class DockUI {
  private readonly host: HTMLElement;
  private readonly actions: DockUIActions;
  private readonly overlay: HTMLElement;
  private readonly portName: HTMLElement;
  private readonly portDescription: HTMLElement;
  private readonly exploreButton: HTMLButtonElement;
  private readonly money: HTMLElement;
  private readonly playtestCreditsButton: HTMLButtonElement;
  private readonly slotState: HTMLElement;
  private readonly stats: HTMLElement;
  private readonly upgradeList: HTMLElement;
  private readonly missionOffice: HTMLElement;
  private readonly jobsCount: HTMLElement;
  private readonly tabButtons: Readonly<
    Record<DockServiceTab, HTMLButtonElement>
  >;
  private readonly tabPanels: Readonly<
    Record<DockServiceTab, HTMLElement>
  >;
  private readonly inspectorHost: HTMLElement;
  private readonly inspectorStatus: HTMLElement;
  private inspector?: ObjectInspectionViewport;
  private inspectorLoaded = false;
  private openState = false;
  private activeTab: DockServiceTab = 'refit';

  public constructor(host: HTMLElement, actions: DockUIActions) {
    this.host = host;
    this.actions = actions;
    this.host.innerHTML = this.template();
    this.overlay = this.requireElement('#dock-overlay');
    this.portName = this.requireElement('#dock-port-name');
    this.portDescription = this.requireElement(
      '#dock-port-description',
    );
    this.exploreButton = this.requireElement<HTMLButtonElement>(
      '#dock-explore-surroundings',
    );
    this.money = this.requireElement('#dock-money');
    this.playtestCreditsButton =
      this.requireElement<HTMLButtonElement>('#dock-playtest-credits');
    this.slotState = this.requireElement('#dock-module-slots');
    this.stats = this.requireElement('#dock-vessel-stats');
    this.upgradeList = this.requireElement('#dock-upgrade-list');
    this.missionOffice = this.requireElement(
      '#dock-mission-office',
    );
    this.jobsCount = this.requireElement('#dock-jobs-count');
    this.tabButtons = {
      jobs: this.requireElement<HTMLButtonElement>(
        '#dock-tab-jobs',
      ),
      refit: this.requireElement<HTMLButtonElement>(
        '#dock-tab-refit',
      ),
    };
    this.tabPanels = {
      jobs: this.requireElement('#dock-panel-jobs'),
      refit: this.requireElement('#dock-panel-refit'),
    };
    this.inspectorHost = this.requireElement('#dock-inspector');
    this.inspectorStatus = this.requireElement(
      '#dock-inspector-status',
    );
    this.bindEvents();
  }

  public open(state: Readonly<DockViewModel>): void {
    const wasOpen = this.openState;
    this.openState = true;
    this.overlay.classList.remove('is-hidden');
    this.overlay.setAttribute('aria-hidden', 'false');
    this.render(state);
    if (!wasOpen) {
      this.setActiveTab(
        state.missionOffers.length > 0 ? 'jobs' : 'refit',
      );
    }
    this.ensureInspector();
  }

  public render(state: Readonly<DockViewModel>): void {
    this.overlay.style.setProperty(
      '--dock-accent',
      accentHex(state.accent),
    );
    this.portName.textContent = state.portName;
    this.portDescription.textContent = state.portDescription;
    this.exploreButton.classList.toggle(
      'is-hidden',
      !state.canExploreSurroundings,
    );
    this.exploreButton.disabled = !state.canExploreSurroundings;
    this.money.textContent = `${Math.floor(state.money)} cr`;
    this.playtestCreditsButton.classList.toggle(
      'is-hidden',
      !state.canUsePlaytestCredits,
    );
    this.playtestCreditsButton.disabled = !state.canUsePlaytestCredits;
    this.slotState.textContent =
      `${state.installedModules} / ${state.moduleSlots} modules`;
    this.stats.innerHTML = [
      ['BREAK POWER', state.breakPower],
      ['ENGINE', state.enginePower],
      ['AGILITY', state.agility],
      ['FUEL ECONOMY', state.fuelEfficiency],
    ]
      .map(
        ([label, value]) =>
          `<div><span>${label}</span><strong>${Number(value).toFixed(2)}x</strong></div>`,
      )
      .join('');
    this.renderMissionOffers(state.missionOffers);

    if (state.upgrades.length === 0) {
      this.upgradeList.innerHTML =
        '<p class="dock-empty">No refits are offered at this port yet.</p>';
      return;
    }
    this.upgradeList.innerHTML = state.upgrades
      .map((upgrade) => this.upgradeTemplate(upgrade))
      .join('');
  }

  public close(): void {
    this.openState = false;
    this.overlay.classList.add('is-hidden');
    this.overlay.setAttribute('aria-hidden', 'true');
    this.inspector?.setActive(false);
  }

  public update(): void {
    if (this.openState) this.inspector?.update();
  }

  public dispose(): void {
    this.inspector?.dispose();
    this.host.replaceChildren();
  }

  private ensureInspector(): void {
    if (!this.inspector) {
      this.inspector = new ObjectInspectionViewport(
        this.inspectorHost,
      );
    }
    this.inspector.setActive(true);
    if (this.inspectorLoaded) return;
    this.inspectorLoaded = true;
    this.inspectorStatus.textContent = 'LOADING VESSEL';
    void this.inspector
      .loadAsset({
        url: PLAYER_VESSEL_MODEL_URL,
        targetSize: 3.4,
        yawRadians:
          PLAYER_VESSEL_MODEL_TUNING.yawCorrectionDegrees *
          Math.PI /
          180,
      })
      .then((loaded) => {
        if (loaded) {
          this.inspectorStatus.textContent =
            'DRAG TO ROTATE · WHEEL TO ZOOM';
        }
      })
      .catch(() => {
        this.inspectorStatus.textContent =
          'VESSEL PREVIEW UNAVAILABLE';
      });
  }

  private bindEvents(): void {
    this.overlay.addEventListener('click', (event) => {
      const target = event.target as HTMLElement;
      const tab = target.closest<HTMLButtonElement>(
        '[data-dock-tab]',
      )?.dataset.dockTab;
      if (tab === 'jobs' || tab === 'refit') {
        this.setActiveTab(tab, true);
        return;
      }
      const action = target.closest<HTMLElement>(
        '[data-dock-action]',
      )?.dataset.dockAction;
      if (action === 'undock') {
        this.actions.onUndock();
        return;
      }
      if (action === 'explore-surroundings') {
        this.actions.onExploreSurroundings();
        return;
      }
      if (action === 'add-playtest-credits') {
        this.actions.onAddPlaytestCredits();
        return;
      }
      const upgradeButton = target.closest<HTMLButtonElement>(
        '[data-dock-upgrade]',
      );
      const missionButton = target.closest<HTMLButtonElement>(
        '[data-dock-mission]',
      );
      const missionActionButton =
        target.closest<HTMLButtonElement>(
          '[data-dock-mission-action]',
        );
      const missionActionId =
        missionActionButton?.dataset.dockMissionAction;
      if (
        action === 'perform-mission-action' &&
        missionActionId &&
        !missionActionButton.disabled
      ) {
        this.actions.onPerformMissionAction(
          missionActionId,
        );
        return;
      }
      const missionId = missionButton?.dataset.dockMission;
      if (
        action === 'accept-mission' &&
        missionId &&
        !missionButton.disabled
      ) {
        this.actions.onAcceptMission(missionId);
        return;
      }
      const upgradeId = upgradeButton?.dataset.dockUpgrade;
      if (!upgradeId || upgradeButton?.disabled) return;
      if (action === 'purchase') {
        this.actions.onPurchase(upgradeId);
      } else if (action === 'toggle-module') {
        this.actions.onToggleModule(upgradeId);
      }
    });
    this.overlay.addEventListener('keydown', (event) => {
      if (
        event.key !== 'ArrowLeft' &&
        event.key !== 'ArrowRight'
      ) {
        return;
      }
      const target = event.target as HTMLElement;
      if (!target.closest('[data-dock-tab]')) return;
      event.preventDefault();
      this.setActiveTab(
        this.activeTab === 'jobs' ? 'refit' : 'jobs',
        true,
      );
    });
  }

  private setActiveTab(
    tab: DockServiceTab,
    focus = false,
  ): void {
    this.activeTab = tab;
    for (const candidate of ['jobs', 'refit'] as const) {
      const active = candidate === tab;
      const button = this.tabButtons[candidate];
      const panel = this.tabPanels[candidate];
      button.setAttribute(
        'aria-selected',
        active ? 'true' : 'false',
      );
      button.tabIndex = active ? 0 : -1;
      panel.classList.toggle('is-hidden', !active);
      panel.setAttribute('aria-hidden', active ? 'false' : 'true');
    }
    if (focus) this.tabButtons[tab].focus();
  }

  private upgradeTemplate(
    upgrade: Readonly<DockUpgradeViewModel>,
  ): string {
    let action = 'purchase';
    let actionLabel =
      `BUY ${upgrade.displayName} · ${upgrade.price} cr`;
    let disabled = !upgrade.canPurchase;
    if (upgrade.ownershipType === 'PERMANENT' && upgrade.owned) {
      actionLabel = 'FITTED';
      disabled = true;
    } else if (upgrade.ownershipType === 'MODULE' && upgrade.owned) {
      action = 'toggle-module';
      actionLabel = upgrade.installed ? 'REMOVE' : 'INSTALL';
      disabled = upgrade.installed
        ? !upgrade.canRemove
        : !upgrade.canInstall;
    }
    const classes = [
      'dock-upgrade',
      upgrade.owned ? 'is-owned' : '',
      upgrade.installed ? 'is-installed' : '',
      !upgrade.available ? 'is-locked' : '',
    ]
      .filter(Boolean)
      .join(' ');
    return `
      <article class="${classes}">
        <div class="dock-upgrade-copy">
          <small>${escapeHtml(upgrade.category)} · ${escapeHtml(upgrade.ownershipType)}</small>
          <strong>${escapeHtml(upgrade.displayName)}</strong>
          <p>${escapeHtml(upgrade.description)}</p>
        </div>
        <div class="dock-upgrade-action">
          <span>${escapeHtml(upgrade.status)}</span>
          <button
            data-dock-action="${action}"
            data-dock-upgrade="${escapeHtml(upgrade.id)}"
            aria-label="${escapeHtml(actionLabel)}"
            ${disabled ? 'disabled' : ''}
          >${escapeHtml(actionLabel)}</button>
        </div>
      </article>
    `;
  }

  private renderMissionOffers(
    offers: readonly DockMissionOfferViewModel[],
  ): void {
    this.jobsCount.textContent = String(offers.length);
    this.jobsCount.classList.toggle(
      'is-hidden',
      offers.length === 0,
    );
    if (offers.length === 0) {
      this.missionOffice.innerHTML =
        '<p class="dock-empty">No jobs are offered at this port right now.</p>';
      return;
    }
    this.missionOffice.classList.toggle(
      'is-hidden',
      false,
    );
    this.missionOffice.innerHTML = offers
      .map((offer) => {
        const active = offer.status === 'ACTIVE';
        const action = active ? offer.action : undefined;
        const actionLabel =
          action?.label ?? (active ? 'ACTIVE JOB' : 'ACCEPT JOB');
        const ariaLabel = action
          ? `${actionLabel} for ${offer.displayName}`
          : active
            ? `${offer.displayName} is active`
            : `Accept ${offer.displayName}`;
        return `
          <article class="dock-mission-offer">
            <div>
              <small>${escapeHtml(action?.status ?? (active ? 'ACTIVE JOB' : 'HARBOUR OFFICE'))} · ${Math.floor(offer.rewardMoney)} cr</small>
              <strong>${escapeHtml(offer.displayName)}</strong>
              <p>${escapeHtml(offer.description)}</p>
            </div>
            <button
              data-dock-action="${action ? 'perform-mission-action' : 'accept-mission'}"
              ${action ? `data-dock-mission-action="${escapeHtml(action.id)}"` : `data-dock-mission="${escapeHtml(offer.id)}"`}
              aria-label="${escapeHtml(ariaLabel)}"
              ${(action ? !action.enabled : active) ? 'disabled' : ''}
            >${escapeHtml(actionLabel)}</button>
          </article>
        `;
      })
      .join('');
  }

  private template(): string {
    return `
      <section id="dock-overlay" class="dock-overlay is-hidden" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="dock-port-name">
        <div class="dock-window">
          <header class="dock-header">
            <div>
              <small>MOORED AT</small>
              <h1 id="dock-port-name">PORT</h1>
              <p id="dock-port-description"></p>
            </div>
            <div class="dock-balance">
              <small>AVAILABLE FUNDS</small>
              <strong id="dock-money">0 cr</strong>
              <button
                id="dock-playtest-credits"
                class="is-hidden"
                data-dock-action="add-playtest-credits"
              >DEV · +1000 CR</button>
              <button data-dock-action="undock">UNDOCK</button>
              <button
                id="dock-explore-surroundings"
                class="dock-explore-surroundings is-hidden"
                data-dock-action="explore-surroundings"
              >EXPLORE HARBOR AND ITS SURROUNDINGS</button>
            </div>
          </header>
          <div class="dock-content">
            <section class="dock-refit">
              <nav class="dock-tabs" role="tablist" aria-label="Harbour services">
                <button
                  id="dock-tab-jobs"
                  type="button"
                  role="tab"
                  data-dock-tab="jobs"
                  aria-controls="dock-panel-jobs"
                  aria-selected="false"
                  tabindex="-1"
                >
                  JOB OFFERS
                  <span id="dock-jobs-count" class="dock-tab-count is-hidden">0</span>
                </button>
                <button
                  id="dock-tab-refit"
                  type="button"
                  role="tab"
                  data-dock-tab="refit"
                  aria-controls="dock-panel-refit"
                  aria-selected="true"
                >UPGRADES &amp; REFITS</button>
              </nav>
              <section
                id="dock-panel-jobs"
                class="dock-tab-panel is-hidden"
                role="tabpanel"
                aria-labelledby="dock-tab-jobs"
                aria-hidden="true"
              >
                <header>
                  <div>
                    <small>HARBOUR OFFICE</small>
                    <h2>JOB OFFERS</h2>
                  </div>
                </header>
                <div id="dock-mission-office" class="dock-mission-office"></div>
              </section>
              <section
                id="dock-panel-refit"
                class="dock-tab-panel"
                role="tabpanel"
                aria-labelledby="dock-tab-refit"
                aria-hidden="false"
              >
                <header>
                  <div>
                    <small>WORKSHOP</small>
                    <h2>UPGRADES &amp; REFITS</h2>
                  </div>
                  <strong id="dock-module-slots">0 / 0 modules</strong>
                </header>
                <div id="dock-upgrade-list" class="dock-upgrade-list"></div>
              </section>
            </section>
            <section class="dock-vessel">
              <div id="dock-inspector" class="dock-inspector"></div>
              <div id="dock-inspector-status" class="dock-inspector-status">VESSEL PREVIEW</div>
              <div id="dock-vessel-stats" class="dock-vessel-stats"></div>
            </section>
          </div>
        </div>
      </section>
    `;
  }

  private requireElement<T extends HTMLElement = HTMLElement>(
    selector: string,
  ): T {
    const element = this.host.querySelector<T>(selector);
    if (!element) {
      throw new Error(`ICE-A-WAY dock UI element not found: ${selector}`);
    }
    return element;
  }
}
