import { hash2D } from '../utils/math';

export interface BorealisTownRoad {
  id: string;
  centerX: number;
  centerZ: number;
  halfWidth: number;
  halfDepth: number;
}

export type BorealisTownService =
  | 'GENERAL_STORE'
  | 'ARCHIVES'
  | 'BARBER'
  | 'TAILOR'
  | 'CHARTMAKER'
  | 'RADIO_TELEGRAPH'
  | 'BAKERY_CAFE'
  | 'REPAIR_GARAGE'
  | 'RESIDENCE'
  | 'WAREHOUSE';

export interface BorealisTownBuildingLot {
  id: string;
  displayName: string;
  service: BorealisTownService;
  x: number;
  z: number;
  width: number;
  depth: number;
  storeys: number;
  color: number;
  front: 'NORTH' | 'SOUTH' | 'EAST' | 'WEST';
}

export interface BorealisTownEmptyLot {
  id: string;
  x: number;
  z: number;
  width: number;
  depth: number;
}

export const BOREALIS_TOWN_BOUNDS = Object.freeze({
  minX: -340,
  maxX: -27,
  minZ: -122,
  maxZ: 142,
});

/** Authored non-building spaces shared with park and fleet systems. */
