const insideReservedArea = (
  x: number,
  z: number,
  area: Readonly<{
    centerX: number;
    centerZ: number;
    halfWidth: number;
    halfDepth: number;
  }>,
): boolean =>
  Math.abs(x - area.centerX) <= area.halfWidth &&
  Math.abs(z - area.centerZ) <= area.halfDepth;

const withinProtectedCore = (x: number, z: number): boolean =>
  (x > -49 && x < -37 && z > 3 && z < 14) ||
  insideReservedArea(x, z, BOREALIS_PARK_RESERVED_AREA) ||
  insideReservedArea(x, z, BOREALIS_FLEET_YARD);

const nearServiceBuilding = (x: number, z: number): boolean =>
  serviceBuildings.some(
    (building) => Math.hypot(x - building.x, z - building.z) < 9,
  );

const proceduralBuildings: BorealisTownBuildingLot[] = [];
const emptyLots: BorealisTownEmptyLot[] = [];
for (let column = 0; column < northSouthStreetX.length - 1; column += 1) {
  const rightStreet = northSouthStreetX[column]!;
  const leftStreet = northSouthStreetX[column + 1]!;
  const centerX = (rightStreet + leftStreet) * 0.5;
  for (let row = 0; row < eastWestStreetZ.length - 1; row += 1) {
    const nearStreet = eastWestStreetZ[row]!;
    const farStreet = eastWestStreetZ[row + 1]!;
    const centerZ = (nearStreet + farStreet) * 0.5;
    const candidates = [
      { x: centerX - 6.2, z: centerZ - 6.1, front: 'NORTH' as const },
      { x: centerX + 6.2, z: centerZ - 6.1, front: 'NORTH' as const },
      { x: centerX - 6.2, z: centerZ + 6.1, front: 'SOUTH' as const },
      { x: centerX + 6.2, z: centerZ + 6.1, front: 'SOUTH' as const },
    ];
    for (let slot = 0; slot < candidates.length; slot += 1) {
      const candidate = candidates[slot]!;
      if (
        withinProtectedCore(candidate.x, candidate.z) ||
        nearServiceBuilding(candidate.x, candidate.z)
      ) {
        continue;
      }
      const lotNoise = hash2D(column * 11 + slot, row * 13, 7219);
      const id = `town-${column}-${row}-${slot}`;
      if (lotNoise < 0.16) {
        emptyLots.push({
          id: `${id}-empty-lot`,
          x: candidate.x,
          z: candidate.z,
          width: 9.5,
          depth: 8.8,
        });
        continue;
      }
      const warehouseDistrict = column >= 7 && row <= 3;
      const storeys = warehouseDistrict
        ? 1
        : hash2D(column, row * 7 + slot, 9337) > 0.7
          ? 2
          : 1;
      const palette = [0x89a9a3, 0xb48c72, 0x7893aa, 0xb5a06d, 0x8f819c];
      proceduralBuildings.push({
        id,
        displayName: warehouseDistrict
          ? `West yard warehouse ${column}-${row}-${slot}`
          : `Borealis residence ${column}-${row}-${slot}`,
        service: warehouseDistrict ? 'WAREHOUSE' : 'RESIDENCE',
        x: candidate.x,
        z: candidate.z,
        width: 7.1 + hash2D(column, row, slot + 411) * 2.3,
        depth: 6.8 + hash2D(row, slot, column + 907) * 2,
        storeys,
        color: palette[Math.floor(lotNoise * palette.length) % palette.length]!,
        front: candidate.front,
      });
    }
  }
}

export const BOREALIS_TOWN_BUILDINGS: readonly BorealisTownBuildingLot[] =
  Object.freeze([...serviceBuildings, ...proceduralBuildings]);

export const BOREALIS_TOWN_EMPTY_LOTS: readonly BorealisTownEmptyLot[] =
  Object.freeze(emptyLots);

export const isBorealisTownRoad = (x: number, z: number): boolean =>
  x >= BOREALIS_TOWN_BOUNDS.minX &&
  x <= BOREALIS_TOWN_BOUNDS.maxX &&
  z >= BOREALIS_TOWN_BOUNDS.minZ &&
  z <= BOREALIS_TOWN_BOUNDS.maxZ &&
  (eastWestStreetZ.some(
    (streetZ) => Math.abs(z - streetZ) <= STREET_HALF_WIDTH,
  ) ||
    northSouthStreetX.some(
      (streetX) => Math.abs(x - streetX) <= STREET_HALF_WIDTH,
    ));
