import type {
  GameplayDefinitionSet,
  GameplayUpgradeDefinition,
  GoodDefinition,
  GoodType,
  IceFieldDefinition,
  IceType,
  MissionDefinition,
  PoiDefinition,
  PortGameplayDefinition,
  PortServiceType,
  RouteDefinition,
  ShipCapabilityDefinition,
} from './GameplayTypes';
import type { PortShorelineShape } from '../../world/PortIceAccess';

export interface GameplayRegistryIssue {
  path: string;
  message: string;
}

export class GameplayRegistryValidationError extends Error {
  public constructor(
    public readonly issues: readonly GameplayRegistryIssue[],
  ) {
    super(
      `Invalid gameplay definitions:\n${issues
        .map((issue) => `- ${issue.path}: ${issue.message}`)
        .join('\n')}`,
    );
    this.name = 'GameplayRegistryValidationError';
  }
}

const GOOD_TYPES = new Set<GoodType>([
  'FOOD',
  'FUEL',
  'WOOD',
  'METAL',
  'MACHINERY',
]);
const ICE_TYPES = new Set<IceType>([
  'THIN',
  'MEDIUM',
  'THICK',
  'PRESSURE_ICE',
]);
const PORT_SERVICES = new Set<PortServiceType>([
  'REFUEL',
  'REPAIR',
  'DOCK_REFIT',
  'RESEARCH',
]);

const deepFreeze = <T>(value: T): T => {
  if (
    value === null ||
    typeof value !== 'object' ||
    Object.isFrozen(value)
  ) {
    return value;
  }
  for (const nested of Object.values(
    value as Record<string, unknown>,
  )) {
    deepFreeze(nested);
  }
  return Object.freeze(value);
};

const cloneDefinitions = (
  source: GameplayDefinitionSet,
): GameplayDefinitionSet =>
  deepFreeze(structuredClone(source));

const collectIds = <T extends { id: string }>(
  values: readonly T[],
  path: string,
  issues: GameplayRegistryIssue[],
): Set<string> => {
  const result = new Set<string>();
  for (let index = 0; index < values.length; index += 1) {
    const id = values[index]?.id.trim() ?? '';
    if (!id) {
      issues.push({
        path: `${path}[${index}].id`,
        message: 'ID must be a non-empty string',
      });
      continue;
    }
    if (result.has(id)) {
      issues.push({
        path: `${path}[${index}].id`,
        message: `Duplicate ID "${id}"`,
      });
    }
    result.add(id);
  }
  return result;
};

const validUnitValue = (value: number): boolean =>
  Number.isFinite(value) && value >= 0 && value <= 1;

const validateShoreline = (
  shoreline: Readonly<PortShorelineShape>,
  path: string,
  issues: GameplayRegistryIssue[],
): void => {
  if (shoreline.kind === 'circle') {
    if (!Number.isFinite(shoreline.radius) || shoreline.radius <= 0) {
      issues.push({
        path: `${path}.radius`,
        message: 'Circle radius must be positive',
      });
    }
    return;
  }
  if (shoreline.kind === 'ellipse') {
    if (
      !Number.isFinite(shoreline.radiusX) ||
      shoreline.radiusX <= 0 ||
      !Number.isFinite(shoreline.radiusZ) ||
      shoreline.radiusZ <= 0
    ) {
      issues.push({
        path,
        message: 'Ellipse radii must be positive',
      });
    }
    return;
  }
  if (shoreline.kind === 'polygon') {
    if (
      shoreline.points.length < 3 ||
      shoreline.points.some(
        (point) =>
          !Number.isFinite(point.x) ||
          !Number.isFinite(point.z),
      )
    ) {
      issues.push({
        path: `${path}.points`,
        message:
          'Polygon requires at least three finite points',
      });
    }
    return;
  }
  if (shoreline.parts.length === 0) {
    issues.push({
      path: `${path}.parts`,
      message: 'Compound shoreline requires at least one part',
    });
  }
  shoreline.parts.forEach((part, index) =>
    validateShoreline(
      part,
      `${path}.parts[${index}]`,
      issues,
    ),
  );
};

export const validateGameplayDefinitions = (
  definitions: GameplayDefinitionSet,
): readonly GameplayRegistryIssue[] => {
  const issues: GameplayRegistryIssue[] = [];
  const goodIds = collectIds(definitions.goods, 'goods', issues);
  const iceIds = collectIds(
    definitions.iceFields,
    'iceFields',
    issues,
  );
  const portIds = collectIds(definitions.ports, 'ports', issues);
  collectIds(definitions.routes, 'routes', issues);
  const poiIds = collectIds(definitions.pois, 'pois', issues);
  collectIds(definitions.ships, 'ships', issues);
  const upgradeIds = collectIds(
    definitions.upgrades,
    'upgrades',
    issues,
  );
  const missionIds = collectIds(
    definitions.missions,
    'missions',
    issues,
  );

  for (const [index, good] of definitions.goods.entries()) {
    if (!GOOD_TYPES.has(good.id)) {
      issues.push({
        path: `goods[${index}].id`,
        message: `Unknown good type "${good.id}"`,
      });
    }
  }
  for (const [index, ice] of definitions.iceFields.entries()) {
    if (!ICE_TYPES.has(ice.id)) {
      issues.push({
        path: `iceFields[${index}].id`,
        message: `Unknown ice type "${ice.id}"`,
      });
    }
    for (const key of [
      'baseResistance',
      'navigationDifficulty',
    ] as const) {
      if (!validUnitValue(ice[key])) {
        issues.push({
          path: `iceFields[${index}].${key}`,
          message: 'Value must be between 0 and 1',
        });
      }
    }
    for (const key of [
      'hullWearMultiplier',
      'refreezeRate',
    ] as const) {
      if (!Number.isFinite(ice[key]) || ice[key] < 0) {
        issues.push({
          path: `iceFields[${index}].${key}`,
          message: 'Multiplier must be non-negative',
        });
      }
    }
    if (
      !Number.isFinite(ice.fuelCostMultiplier) ||
      ice.fuelCostMultiplier < 1
    ) {
      issues.push({
        path: `iceFields[${index}].fuelCostMultiplier`,
        message: 'Fuel multiplier must be at least 1',
      });
    }
  }
  for (const [index, port] of definitions.ports.entries()) {
    if (!goodIds.has(port.producedGood)) {
      issues.push({
        path: `ports[${index}].producedGood`,
        message: `Missing good "${port.producedGood}"`,
      });
    }
    for (const good of port.requiredGoods) {
      if (!goodIds.has(good)) {
        issues.push({
          path: `ports[${index}].requiredGoods`,
          message: `Missing good "${good}"`,
        });
      }
    }
    for (const service of port.services) {
      if (!PORT_SERVICES.has(service)) {
        issues.push({
          path: `ports[${index}].services`,
          message: `Unknown service "${service}"`,
        });
      }
    }
    const position = port.worldPosition;
    if (
      !Number.isFinite(position.x) ||
      !Number.isFinite(position.y) ||
      !Number.isFinite(position.z)
    ) {
      issues.push({
        path: `ports[${index}].worldPosition`,
        message: 'Position components must be finite',
      });
    }
    const dockPosition = port.dock.worldPosition;
    if (
      !Number.isFinite(dockPosition.x) ||
      !Number.isFinite(dockPosition.y) ||
      !Number.isFinite(dockPosition.z)
    ) {
      issues.push({
        path: `ports[${index}].dock.worldPosition`,
        message: 'Dock position components must be finite',
      });
    }
    if (
      !Number.isFinite(port.dock.radius) ||
      port.dock.radius <= 0
    ) {
      issues.push({
        path: `ports[${index}].dock.radius`,
        message: 'Dock radius must be positive',
      });
    }
    if (
      !Number.isFinite(port.dock.maximumSpeed) ||
      port.dock.maximumSpeed < 0
    ) {
      issues.push({
        path: `ports[${index}].dock.maximumSpeed`,
        message: 'Dock maximum speed must be non-negative',
      });
    }
    if (
      !Number.isFinite(port.iceAccess.clearanceDistance) ||
      port.iceAccess.clearanceDistance <= 0
    ) {
      issues.push({
        path: `ports[${index}].iceAccess.clearanceDistance`,
        message: 'Clearance distance must be positive',
      });
    }
    if (
      !validUnitValue(port.iceAccess.minimumCellOpenness) ||
      !validUnitValue(port.iceAccess.requiredOpenRatio)
    ) {
      issues.push({
        path: `ports[${index}].iceAccess`,
        message: 'Clearance thresholds must be between 0 and 1',
      });
    }
    validateShoreline(
      port.iceAccess.shoreline,
      `ports[${index}].iceAccess.shoreline`,
      issues,
    );
  }
  for (const [index, route] of definitions.routes.entries()) {
    if (!portIds.has(route.fromPortId)) {
      issues.push({
        path: `routes[${index}].fromPortId`,
        message: `Missing port "${route.fromPortId}"`,
      });
    }
    if (!portIds.has(route.toPortId)) {
      issues.push({
        path: `routes[${index}].toPortId`,
        message: `Missing port "${route.toPortId}"`,
      });
    }
    if (route.fromPortId === route.toPortId) {
      issues.push({
        path: `routes[${index}]`,
        message: 'Route endpoints must differ',
      });
    }
    if (
      !Number.isFinite(route.sampleHalfWidth) ||
      route.sampleHalfWidth <= 0
    ) {
      issues.push({
        path: `routes[${index}].sampleHalfWidth`,
        message: 'Sample half-width must be positive',
      });
    }
    if (
      route.nominalWidth !== undefined &&
      (
        !Number.isFinite(route.nominalWidth) ||
        route.nominalWidth <= 0 ||
        route.nominalWidth >
          route.sampleHalfWidth * 2
      )
    ) {
      issues.push({
        path: `routes[${index}].nominalWidth`,
        message:
          'Nominal width must be positive and fit inside the sampled corridor',
      });
    }
    for (const [pointIndex, point] of (
      route.waitingPoints ?? []
    ).entries()) {
      if (
        !Number.isFinite(point.x) ||
        !Number.isFinite(point.y) ||
        !Number.isFinite(point.z)
      ) {
        issues.push({
          path:
            `routes[${index}].waitingPoints` +
            `[${pointIndex}]`,
          message:
            'Waiting point components must be finite',
        });
      }
    }
    if (!validUnitValue(route.baseRefreezeRate)) {
      issues.push({
        path: `routes[${index}].baseRefreezeRate`,
        message: 'Refreeze rate must be between 0 and 1',
      });
    }
  }
  for (const [index, poi] of definitions.pois.entries()) {
    if (
      poi.rewardUpgradeId &&
      !upgradeIds.has(poi.rewardUpgradeId)
    ) {
      issues.push({
        path: `pois[${index}].rewardUpgradeId`,
        message: `Missing upgrade "${poi.rewardUpgradeId}"`,
      });
    }
    if (
      poi.linkedMissionId &&
      !missionIds.has(poi.linkedMissionId)
    ) {
      issues.push({
        path: `pois[${index}].linkedMissionId`,
        message: `Missing mission "${poi.linkedMissionId}"`,
      });
    }
    if (
      !Number.isFinite(poi.discoveryRadius) ||
      poi.discoveryRadius <= 0
    ) {
      issues.push({
        path: `pois[${index}].discoveryRadius`,
        message: 'Discovery radius must be positive',
      });
    }
  }
  for (const [index, ship] of definitions.ships.entries()) {
    for (const key of [
      'breakPower',
      'fuelEfficiency',
      'hullDurability',
      'agility',
      'range',
      'enginePower',
    ] as const) {
      if (!Number.isFinite(ship[key]) || ship[key] <= 0) {
        issues.push({
          path: `ships[${index}].${key}`,
          message: 'Capability must be positive',
        });
      }
    }
    if (
      !Number.isInteger(ship.moduleSlots) ||
      ship.moduleSlots < 0
    ) {
      issues.push({
        path: `ships[${index}].moduleSlots`,
        message: 'Module slots must be a non-negative integer',
      });
    }
  }
  for (const [index, upgrade] of definitions.upgrades.entries()) {
    if (
      upgrade.requiredPortId &&
      !portIds.has(upgrade.requiredPortId)
    ) {
      issues.push({
        path: `upgrades[${index}].requiredPortId`,
        message: `Missing port "${upgrade.requiredPortId}"`,
      });
    }
    if (
      upgrade.requiredDiscoveryId &&
      !poiIds.has(upgrade.requiredDiscoveryId)
    ) {
      issues.push({
        path: `upgrades[${index}].requiredDiscoveryId`,
        message: `Missing POI "${upgrade.requiredDiscoveryId}"`,
      });
    }
    for (const good of upgrade.requiredGoodsFlow ?? []) {
      if (!goodIds.has(good)) {
        issues.push({
          path: `upgrades[${index}].requiredGoodsFlow`,
          message: `Missing good "${good}"`,
        });
      }
    }
    if (
      upgrade.requiredService &&
      !PORT_SERVICES.has(upgrade.requiredService)
    ) {
      issues.push({
        path: `upgrades[${index}].requiredService`,
        message: `Unknown service "${upgrade.requiredService}"`,
      });
    }
    if (!Number.isFinite(upgrade.price) || upgrade.price < 0) {
      issues.push({
        path: `upgrades[${index}].price`,
        message: 'Price must be non-negative',
      });
    }
  }
  for (const [index, mission] of definitions.missions.entries()) {
    if (
      mission.linkedRouteId &&
      !definitions.routes.some(
        (route) => route.id === mission.linkedRouteId,
      )
    ) {
      issues.push({
        path: `missions[${index}].linkedRouteId`,
        message: `Missing route "${mission.linkedRouteId}"`,
      });
    }
    for (const [routeIndex, routeId] of (
      mission.linkedRouteIds ?? []
    ).entries()) {
      if (
        !definitions.routes.some(
          (route) => route.id === routeId,
        )
      ) {
        issues.push({
          path:
            `missions[${index}].linkedRouteIds` +
            `[${routeIndex}]`,
          message: `Missing route "${routeId}"`,
        });
      }
    }
    if (
      mission.linkedPortId &&
      !portIds.has(mission.linkedPortId)
    ) {
      issues.push({
        path: `missions[${index}].linkedPortId`,
        message: `Missing port "${mission.linkedPortId}"`,
      });
    }
    if (
      mission.linkedPoiId &&
      !poiIds.has(mission.linkedPoiId)
    ) {
      issues.push({
        path: `missions[${index}].linkedPoiId`,
        message: `Missing POI "${mission.linkedPoiId}"`,
      });
    }
    if (
      mission.linkedShipId !== undefined &&
      !mission.linkedShipId.trim()
    ) {
      issues.push({
        path: `missions[${index}].linkedShipId`,
        message: 'Linked runtime ship ID must be non-empty',
      });
    }
    if (
      mission.rewardUpgradeId &&
      !upgradeIds.has(mission.rewardUpgradeId)
    ) {
      issues.push({
        path: `missions[${index}].rewardUpgradeId`,
        message: `Missing upgrade "${mission.rewardUpgradeId}"`,
      });
    }
    for (const [offerIndex, portId] of (
      mission.offerAtPortIds ?? []
    ).entries()) {
      if (!portIds.has(portId)) {
        issues.push({
          path:
            `missions[${index}].offerAtPortIds` +
            `[${offerIndex}]`,
          message: `Missing port "${portId}"`,
        });
      }
    }
    for (const [prerequisiteIndex, prerequisite] of (
      mission.prerequisites ?? []
    ).entries()) {
      const path =
        `missions[${index}].prerequisites` +
        `[${prerequisiteIndex}]`;
      if (prerequisite.type === 'MISSION_COMPLETED') {
        if (!missionIds.has(prerequisite.missionId)) {
          issues.push({
            path: `${path}.missionId`,
            message:
              `Missing mission "${prerequisite.missionId}"`,
          });
        } else if (prerequisite.missionId === mission.id) {
          issues.push({
            path: `${path}.missionId`,
            message: 'Mission cannot require itself',
          });
        }
      } else if (prerequisite.type === 'PORT_CLEARED') {
        if (!portIds.has(prerequisite.portId)) {
          issues.push({
            path: `${path}.portId`,
            message:
              `Missing port "${prerequisite.portId}"`,
          });
        }
      } else if (
        prerequisite.type === 'POI_DISCOVERED'
      ) {
        if (!poiIds.has(prerequisite.poiId)) {
          issues.push({
            path: `${path}.poiId`,
            message: `Missing POI "${prerequisite.poiId}"`,
          });
        }
      } else if (
        prerequisite.type === 'UPGRADE_OWNED' &&
        !upgradeIds.has(prerequisite.upgradeId)
      ) {
        issues.push({
          path: `${path}.upgradeId`,
          message:
            `Missing upgrade "${prerequisite.upgradeId}"`,
        });
      }
    }
    if (
      mission.offerExpiresAfterSeconds !== undefined &&
      (
        !Number.isFinite(
          mission.offerExpiresAfterSeconds,
        ) ||
        mission.offerExpiresAfterSeconds <= 0
      )
    ) {
      issues.push({
        path:
          `missions[${index}].offerExpiresAfterSeconds`,
        message: 'Offer expiry must be positive',
      });
    }
    if (
      mission.requiredComponentId !== undefined &&
      !mission.requiredComponentId.trim()
    ) {
      issues.push({
        path: `missions[${index}].requiredComponentId`,
        message: 'Required component ID must be non-empty',
      });
    }
    if (
      !Number.isFinite(mission.rewardMoney) ||
      mission.rewardMoney < 0
    ) {
      issues.push({
        path: `missions[${index}].rewardMoney`,
        message: 'Reward must be non-negative',
      });
    }
  }

  const missionById = new Map(
    definitions.missions.map((mission) => [
      mission.id,
      mission,
    ]),
  );
  const visiting = new Set<string>();
  const visited = new Set<string>();
  const visitMission = (
    missionId: string,
    chain: readonly string[],
  ): void => {
    if (visited.has(missionId)) return;
    if (visiting.has(missionId)) {
      issues.push({
        path: 'missions',
        message:
          `Mission prerequisite cycle: ` +
          [...chain, missionId].join(' -> '),
      });
      return;
    }
    visiting.add(missionId);
    const mission = missionById.get(missionId);
    for (const prerequisite of mission?.prerequisites ?? []) {
      if (
        prerequisite.type === 'MISSION_COMPLETED' &&
        missionById.has(prerequisite.missionId)
      ) {
        visitMission(prerequisite.missionId, [
          ...chain,
          missionId,
        ]);
      }
    }
    visiting.delete(missionId);
    visited.add(missionId);
  };
  for (const missionId of missionIds) {
    visitMission(missionId, []);
  }

  if (goodIds.size !== GOOD_TYPES.size) {
    issues.push({
      path: 'goods',
      message: 'V1 requires exactly the five supported good types',
    });
  }
  if (iceIds.size !== ICE_TYPES.size) {
    issues.push({
      path: 'iceFields',
      message: 'V1 requires thin, medium, thick and pressure ice',
    });
  }
  return issues;
};

export class GameplayRegistry {
  public readonly definitions: GameplayDefinitionSet;

  private readonly goods = new Map<string, GoodDefinition>();
  private readonly iceFields =
    new Map<string, IceFieldDefinition>();
  private readonly ports =
    new Map<string, PortGameplayDefinition>();
  private readonly routes = new Map<string, RouteDefinition>();
  private readonly pois = new Map<string, PoiDefinition>();
  private readonly ships =
    new Map<string, ShipCapabilityDefinition>();
  private readonly upgrades =
    new Map<string, GameplayUpgradeDefinition>();
  private readonly missions =
    new Map<string, MissionDefinition>();

  public constructor(source: GameplayDefinitionSet) {
    const issues = validateGameplayDefinitions(source);
    if (issues.length > 0) {
      throw new GameplayRegistryValidationError(issues);
    }
    this.definitions = cloneDefinitions(source);
    this.index(this.definitions.goods, this.goods);
    this.index(this.definitions.iceFields, this.iceFields);
    this.index(this.definitions.ports, this.ports);
    this.index(this.definitions.routes, this.routes);
    this.index(this.definitions.pois, this.pois);
    this.index(this.definitions.ships, this.ships);
    this.index(this.definitions.upgrades, this.upgrades);
    this.index(this.definitions.missions, this.missions);
  }

  public getGood(id: string): GoodDefinition | undefined {
    return this.goods.get(id);
  }

  public getIceField(
    id: string,
  ): IceFieldDefinition | undefined {
    return this.iceFields.get(id);
  }

  public getPort(
    id: string,
  ): PortGameplayDefinition | undefined {
    return this.ports.get(id);
  }

  public getRoute(id: string): RouteDefinition | undefined {
    return this.routes.get(id);
  }

  public getPoi(id: string): PoiDefinition | undefined {
    return this.pois.get(id);
  }

  public getShip(
    id: string,
  ): ShipCapabilityDefinition | undefined {
    return this.ships.get(id);
  }

  public getUpgrade(
    id: string,
  ): GameplayUpgradeDefinition | undefined {
    return this.upgrades.get(id);
  }

  public getMission(
    id: string,
  ): MissionDefinition | undefined {
    return this.missions.get(id);
  }

  private index<T extends { id: string }>(
    definitions: readonly T[],
    target: Map<string, T>,
  ): void {
    for (const definition of definitions) {
      target.set(definition.id, definition);
    }
  }
}
