import type { GlobalPosition } from '../../world/GlobalPosition';
import { prototypeLocalToGlobalPosition } from '../../world/PrototypeWorldPositionAdapter';
import type { GameplayRegistry } from '../definitions/GameplayRegistry';
import type { MissionStatus } from '../definitions/GameplayTypes';
import { worldTarget } from '../world/WorldTarget';
import type {
  WorldOutcomeDefinition,
  WorldOutcomeRuntimeState,
} from '../simulation/WorldOutcomeSystem';

export interface LighthouseChartRoute {
  routeId: string;
  centreline: readonly GlobalPosition[];
  safeWaitingPoints: readonly GlobalPosition[];
}

export interface LighthouseChartShallow {
  id: string;
  centre: GlobalPosition;
  radiusMetres: number;
}

export interface LighthouseRestorationDefinition {
  id: string;
  displayName: string;
  poiId: string;
  missionId: string;
  servicePortId: string;
  componentId: string;
  componentDisplayName: string;
  outcomeId: string;
  revealId: string;
  sectorId: string;
  sectorCentre: GlobalPosition;
  sectorRadiusMetres: number;
  chartRoutes: readonly LighthouseChartRoute[];
  chartShallows: readonly LighthouseChartShallow[];
  hintedPoiIds: readonly string[];
}

export type LighthouseRestorationStatus =
  | 'LOCKED'
  | 'AVAILABLE'
  | 'READY'
  | 'LIT';

export interface LighthouseRestorationView {
  id: string;
  displayName: string;
  poiId: string;
  missionId: string;
  servicePortId: string;
  componentDisplayName: string;
  outcomeId: string;
  status: LighthouseRestorationStatus;
  statusLabel: string;
  actionLabel: string;
  canRestore: boolean;
}

export interface NavigationChartRevealView {
  id: string;
  sectorId: string;
  sourcePoiId: string;
  revealed: boolean;
  sectorCentre?: GlobalPosition;
  sectorRadiusMetres?: number;
  routes: readonly LighthouseChartRoute[];
  shallows: readonly LighthouseChartShallow[];
  hintedPoiIds: readonly string[];
}

export type LighthouseRestorationFailure =
  | 'UNKNOWN_RESTORATION'
  | 'WRONG_PORT'
  | 'MISSION_NOT_ACTIVE'
  | 'ALREADY_RESTORED';

const routeChart = (
  routeId: string,
  points: readonly { x: number; y: number; z: number }[],
  waitingPoints: readonly { x: number; y: number; z: number }[] = [],
): LighthouseChartRoute =>
  Object.freeze({
    routeId,
    centreline: Object.freeze(
      points.map((point) =>
        prototypeLocalToGlobalPosition(point),
      ),
    ),
    safeWaitingPoints: Object.freeze(
      waitingPoints.map((point) =>
        prototypeLocalToGlobalPosition(point),
      ),
    ),
  });

