const clonePosition = (
  position: Readonly<GlobalPosition>,
): GlobalPosition => structuredClone(position);

const cloneRoute = (
  route: Readonly<LighthouseChartRoute>,
): LighthouseChartRoute => ({
  routeId: route.routeId,
  centreline: route.centreline.map(clonePosition),
  safeWaitingPoints: route.safeWaitingPoints.map(clonePosition),
});

export class LighthouseRestorationSystem {
  private readonly definitions = new Map<
    string,
    Readonly<LighthouseRestorationDefinition>
  >();

  public constructor(
    definitions: readonly LighthouseRestorationDefinition[],
    gameplay: GameplayRegistry,
  ) {
    for (const definition of definitions) {
      if (this.definitions.has(definition.id)) {
        throw new Error(
          `Duplicate lighthouse restoration "${definition.id}"`,
        );
      }
      const mission = gameplay.getMission(definition.missionId);
      const poi = gameplay.getPoi(definition.poiId);
      if (
        !mission ||
        mission.type !== 'DELIVER_SPECIAL_COMPONENT' ||
        mission.linkedPortId !== definition.servicePortId ||
        mission.linkedPoiId !== definition.poiId ||
        mission.requiredComponentId !== definition.componentId
      ) {
        throw new Error(
          `Invalid lighthouse mission "${definition.missionId}"`,
        );
      }
      if (!poi || poi.category !== 'NAVIGATION') {
        throw new Error(
          `Invalid lighthouse POI "${definition.poiId}"`,
        );
      }
      if (!gameplay.getPort(definition.servicePortId)) {
        throw new Error(
          `Missing lighthouse port "${definition.servicePortId}"`,
        );
      }
      for (const route of definition.chartRoutes) {
        if (!gameplay.getRoute(route.routeId)) {
          throw new Error(
            `Missing chart route "${route.routeId}"`,
          );
        }
      }
      for (const hintedPoiId of definition.hintedPoiIds) {
        if (!gameplay.getPoi(hintedPoiId)) {
          throw new Error(
            `Missing chart POI "${hintedPoiId}"`,
          );
        }
      }
      this.definitions.set(
        definition.id,
        Object.freeze({ ...definition }),
      );
    }
  }

  public getDefinition(
    restorationId: string,
  ): Readonly<LighthouseRestorationDefinition> | undefined {
    return this.definitions.get(restorationId);
  }

  public getDefinitions():
    readonly Readonly<LighthouseRestorationDefinition>[] {
    return [...this.definitions.values()];
  }

  public checkRestoration(
    restorationId: string,
    portId: string,
    missionStatus: MissionStatus | undefined,
    outcomeState: string | undefined,
  ): {
    accepted: boolean;
    definition?: Readonly<LighthouseRestorationDefinition>;
    reason?: LighthouseRestorationFailure;
  } {
    const definition = this.definitions.get(restorationId);
    if (!definition) {
      return {
        accepted: false,
        reason: 'UNKNOWN_RESTORATION',
      };
    }
    if (outcomeState === 'LIT') {
      return {
        accepted: false,
        definition,
        reason: 'ALREADY_RESTORED',
      };
    }
    if (definition.servicePortId !== portId) {
      return {
        accepted: false,
        definition,
        reason: 'WRONG_PORT',
      };
    }
    if (missionStatus !== 'ACTIVE') {
      return {
        accepted: false,
        definition,
        reason: 'MISSION_NOT_ACTIVE',
      };
    }
    return { accepted: true, definition };
  }

  public createView(
    definition: Readonly<LighthouseRestorationDefinition>,
    missionStatus: MissionStatus | undefined,
    outcome: Readonly<WorldOutcomeRuntimeState> | undefined,
  ): LighthouseRestorationView {
    const lit = outcome?.state === 'LIT';
    const status: LighthouseRestorationStatus = lit
      ? 'LIT'
      : missionStatus === 'ACTIVE'
        ? 'READY'
        : missionStatus === 'OFFERED'
          ? 'AVAILABLE'
          : 'LOCKED';
    return {
      id: definition.id,
      displayName: definition.displayName,
      poiId: definition.poiId,
      missionId: definition.missionId,
      servicePortId: definition.servicePortId,
      componentDisplayName: definition.componentDisplayName,
      outcomeId: definition.outcomeId,
      status,
      statusLabel:
        status === 'LIT'
          ? 'LIGHTHOUSE LIT'
          : status === 'READY'
            ? `${definition.componentDisplayName.toUpperCase()} READY`
            : status === 'AVAILABLE'
              ? 'JOB AVAILABLE'
              : 'LIGHTHOUSE DARK',
      actionLabel:
        `INSTALL ${definition.componentDisplayName.toUpperCase()} & LIGHT`,
      canRestore: status === 'READY',
    };
  }

  public createChartView(
    definition: Readonly<LighthouseRestorationDefinition>,
    outcome: Readonly<WorldOutcomeRuntimeState> | undefined,
  ): NavigationChartRevealView {
    const revealed = outcome?.state === 'LIT';
    return {
      id: definition.revealId,
      sectorId: definition.sectorId,
      sourcePoiId: definition.poiId,
      revealed,
      ...(revealed
        ? {
            sectorCentre: clonePosition(
              definition.sectorCentre,
            ),
            sectorRadiusMetres:
              definition.sectorRadiusMetres,
          }
        : {}),
      routes: revealed
        ? definition.chartRoutes.map(cloneRoute)
        : [],
      shallows: revealed
        ? definition.chartShallows.map((shallow) => ({
            ...shallow,
            centre: clonePosition(shallow.centre),
          }))
        : [],
      hintedPoiIds: revealed
        ? [...definition.hintedPoiIds]
        : [],
    };
  }
}
