import type { IceClass } from '../../ice/IceWorldTypes';
import { clamp, saturate } from '../../utils/math';
import { V1_GAMEPLAY_DEFINITIONS } from '../definitions/GameplayDefinitions';
import type {
  IceFieldDefinition,
  IceType,
} from '../definitions/GameplayTypes';

export interface VesselIceCapabilities {
  breakPower: number;
  fuelEfficiency: number;
  hullDurability: number;
  hullCondition: number;
}

export interface IceInteractionInput {
  iceClass: IceClass;
  pressure: number;
  coverage: number;
  resistance: number;
  forwardSpeed: number;
  throttle: number;
  engineLoad: number;
  capabilities: Readonly<VesselIceCapabilities>;
}

export interface IceInteractionOutcome {
  iceType?: IceType;
  strokeBreakingPower: number;
  resistanceMultiplier: number;
  fuelCostMultiplier: number;
  hullWearPerSecond: number;
  capabilityRatio: number;
  canBreakIce: boolean;
}

const ICE_BY_TYPE = new Map<IceType, IceFieldDefinition>(
  V1_GAMEPLAY_DEFINITIONS.iceFields.map((definition) => [
    definition.id,
    definition,
  ]),
);

const classifyCapabilityIce = (
  iceClass: IceClass,
  pressure: number,
): IceType | undefined => {
  if (iceClass === 'open' || iceClass === 'channel') {
    return undefined;
  }
  if (
    pressure >= 0.82 &&
    (iceClass === 'medium' || iceClass === 'thick')
  ) {
    return 'PRESSURE_ICE';
  }
  if (iceClass === 'thin') return 'THIN';
  if (iceClass === 'medium') return 'MEDIUM';
  return 'THICK';
};

export const calculateIceInteractionOutcome = (
  input: Readonly<IceInteractionInput>,
): IceInteractionOutcome => {
  const iceType = classifyCapabilityIce(
    input.iceClass,
    clamp(input.pressure, 0, 1),
  );
  const breakPower = Math.max(
    0.05,
    input.capabilities.breakPower,
  );
  const hullCondition = clamp(
    input.capabilities.hullCondition,
    0,
    1,
  );
  if (!iceType) {
    return {
      iceType,
      strokeBreakingPower: breakPower,
      resistanceMultiplier: 1,
      fuelCostMultiplier: 1,
      hullWearPerSecond: 0,
      capabilityRatio: 1,
      canBreakIce: false,
    };
  }

  const definition = ICE_BY_TYPE.get(iceType)!;
  const coverage = saturate(input.coverage);
  const pressureLoad =
    iceType === 'PRESSURE_ICE'
      ? 0.24 + saturate(input.pressure) * 0.18
      : saturate(input.pressure - 0.55) * 0.12;
  const difficultyDemand =
    1 +
    definition.baseResistance * 0.75 +
    saturate(input.resistance) * 0.08 +
    pressureLoad;
  const conditionFactor = 0.68 + hullCondition * 0.32;
  const capabilityRatio =
    breakPower * conditionFactor / difficultyDemand;
  const breakingEfficiency = clamp(
    0.45 + capabilityRatio * 0.65,
    0.45,
    1.28,
  );
  const strokeBreakingPower =
    breakPower * breakingEfficiency;
  const resistanceMultiplier = clamp(
    1 +
      Math.max(0, difficultyDemand - breakPower) * 0.18 -
      Math.max(0, breakPower - difficultyDemand) * 0.1,
    0.82,
    1.22,
  );
  const fuelEfficiency = Math.max(
    0.25,
    input.capabilities.fuelEfficiency,
  );
  const workLoad = saturate(
    0.22 +
      Math.abs(input.throttle) * 0.42 +
      saturate(input.engineLoad) * 0.36,
  );
  const fuelCostMultiplier =
    1 +
    (
      definition.fuelCostMultiplier / fuelEfficiency -
      1
    ) *
      coverage *
      workLoad;
  const impactLoad = saturate(
    (Math.max(0, input.forwardSpeed) - 0.08) / 1.15,
  );
  const compressionLoad =
    saturate((Math.abs(input.throttle) - 0.35) / 0.65) *
    coverage *
    0.18;
  const hullDurability = Math.max(
    0.25,
    input.capabilities.hullDurability,
  );
  const hullWearPerSecond =
    (
      impactLoad * impactLoad +
      compressionLoad
    ) *
    coverage *
    definition.hullWearMultiplier *
    (0.000025 / hullDurability);

  return {
    iceType,
    strokeBreakingPower,
    resistanceMultiplier,
    fuelCostMultiplier: Math.max(1, fuelCostMultiplier),
    hullWearPerSecond,
    capabilityRatio,
    canBreakIce:
      coverage > 0.02 &&
      capabilityRatio >= 0.42 &&
      (
        input.forwardSpeed >= 0.08 ||
        input.throttle > 0.12
      ),
  };
};
