import type { GameplayRegistry } from '../definitions/GameplayRegistry';
import type {
  RouteState,
  Vec3Like,
} from '../definitions/GameplayTypes';
import {
  MerchantShippingSystem,
  V1_MERCHANT_SERVICE_DEFINITIONS,
  type MerchantShipPresentationState,
  type MerchantShipRuntimeState,
  type MerchantShippingSaveData,
  type MerchantShippingStats,
  type MerchantShippingUpdateResult,
} from './MerchantShippingSystem';

const emptyStats = (): MerchantShippingStats => ({
  farSimulatedShips: 0,
  activePhysicalShips: 0,
  waitingShips: 0,
  stuckShips: 0,
  pathfindingCalls: 0,
  completedTrips: 0,
  deliveredCargo: 0,
  nearTransitions: 0,
  escortingShips: 0,
});

export class MerchantFleetSystem {
  private readonly ships = new Map<
    string,
    MerchantShippingSystem
  >();

  public constructor(
    registry: GameplayRegistry,
    saved?: Readonly<MerchantShippingSaveData>,
  ) {
    const primaryShipId =
      V1_MERCHANT_SERVICE_DEFINITIONS[0].shipId;
    for (const service of V1_MERCHANT_SERVICE_DEFINITIONS) {
      const savedShip =
        service.shipId === primaryShipId && saved?.ship
          ? saved.ship
          : saved?.ships?.find(
              (ship) => ship.shipId === service.shipId,
            );
      const shippingSave = savedShip
        ? {
            version: saved?.version ?? 3,
            ship: savedShip,
          } as const
        : undefined;
      this.ships.set(
        service.shipId,
        new MerchantShippingSystem(
          registry,
          shippingSave,
          service,
        ),
      );
    }
  }

  public update(
    deltaSeconds: number,
    simulationTime: number,
    routeStates: readonly RouteState[],
    clearedPortIds: ReadonlySet<string>,
    playerPosition?: Readonly<Vec3Like>,
  ): MerchantShippingUpdateResult {
    const result: MerchantShippingUpdateResult = {
      domainEvents: [],
      deliveries: [],
    };
    for (const shipping of this.ships.values()) {
      const update = shipping.update(
        deltaSeconds,
        simulationTime,
        routeStates,
        clearedPortIds,
        playerPosition,
      );
      result.domainEvents.push(...update.domainEvents);
      result.deliveries.push(...update.deliveries);
    }
    return result;
  }

  public getState(): MerchantShipRuntimeState {
    return this.requirePrimary().getState();
  }

  public getStates(): readonly MerchantShipRuntimeState[] {
    return [...this.ships.values()].map((shipping) =>
      shipping.getState(),
    );
  }

  public getPresentationState(): MerchantShipPresentationState {
    return this.requirePrimary().getPresentationState();
  }

  public getPresentationStates():
    readonly MerchantShipPresentationState[] {
    return [...this.ships.values()].map((shipping) =>
      shipping.getPresentationState(),
    );
  }

  public getStats(): MerchantShippingStats {
    const total = emptyStats();
    for (const shipping of this.ships.values()) {
      const stats = shipping.getStats();
      total.farSimulatedShips += stats.farSimulatedShips;
      total.activePhysicalShips += stats.activePhysicalShips;
      total.waitingShips += stats.waitingShips;
      total.stuckShips += stats.stuckShips;
      total.pathfindingCalls += stats.pathfindingCalls;
      total.completedTrips += stats.completedTrips;
      total.deliveredCargo += stats.deliveredCargo;
      total.nearTransitions += stats.nearTransitions;
      total.escortingShips += stats.escortingShips;
    }
    return total;
  }

  public exportState(): MerchantShippingSaveData {
    const states = this.getStates();
    return {
      version: 3,
      ship: states[0]!,
      ships: [...states],
    };
  }

  private requirePrimary(): MerchantShippingSystem {
    const primary = this.ships.get(
      V1_MERCHANT_SERVICE_DEFINITIONS[0].shipId,
    );
    if (!primary) {
      throw new Error('Primary merchant service is unavailable');
    }
    return primary;
  }
}
